(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,571621,(a,n,g)=>{n.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Madilim na Anino","nameplate.Eerie Voice":"Nakakikilabot na Boses","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Boses ng Lalaki","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Misteryosong Lalaki","nameplate.Mysterious Woman":"Misteryosong Babae","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Boses ng Babae","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Tahimik na Boses ng Lalaki","story.map1-dungeon0-1end.001":"Makakakuha ka na ng mga materyal mula sa <color=00FF00>Bukid</color> sa Village of the Venturer!","story.map1-dungeon0-2end.001":"Makakakuha ka na ng mga materyal mula sa <color=00FF00>Bundok</color> sa Village of the Venturer!","story.map1-dungeon0-3end.001":"Mapupuntahan mo na ang <color=00FF00>Sphere House</color> sa Village of the Venturer!","story.map1-dungeon0-3end.002":"Sa Sphere House, puwede kang gumamit ng mga materyal para mag-forge ng <color=00FFFF>Sphere</color> na maipapa-equip mo sa iyong mga Unit.","story.map1-dungeon0-3end.003":"Mag-forge ng malalakas na Sphere para palakasin ang iyong mga Unit!","story.map1-dungeon1.001":"<size=13>Ang init-init! <wait=40>Gusto ko nang umuwi! <wait=40>Hindi ko na kaya \'to...","story.map1-dungeon1.002":"<size=20>Oh! <wait=20><rep_handlename>!","story.map1-dungeon1.003":"Hoy, late ka! <wait=40>Saan ka ba nagpunta?!","story.map1-dungeon1.004":"Ang lakas ng loob mong paghintayin ako sa napakainit na kuwebang \'to!","story.map1-dungeon1.005":"Nag-aalala na tuloy ako sa paglalakbay natin...","story.map1-dungeon1.006":"Well, <wait=40>nangako nga pala akong ipapaliwanag sa\'yo kung ano talaga ang nangyayari...","story.map1-dungeon1.007":"Seryoso \'to, kaya makinig kang mabuti, OK?","story.map1-dungeon1.008":"Nasa gitna ng matinding krisis ang Grand Gaia...","story.map1-dungeon1.009":"Kasi, ang ilan sa makapangyarihang mga diyos na nagbabantay sa amin ay nilamon na ng kasamaan.","story.map1-dungeon1.010":"Sinusuway nila ang Banal na Emperador na si Karna Masta, <wait=19>at naghahasik sila ngayon ng gulo.","story.map1-dungeon1.011":"Sa mga puwersang ito ng kasamaan, <wait=40>ang iilang may pinakapambihirang kapangyarihan ay kilala bilang...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>ang Apat na Nahulog na Diyos.","story.map1-dungeon1.013":"Dati silang mga diyos na mataas ang ranggo...","story.map1-dungeon1.014":"...<wait=20>Pero ngayon, gusto nilang angkinin ang Grand Gaia para sa sarili nila.","story.map1-dungeon1.015":"Hindi lang ginawang alipin ng Apat na Nahulog na Diyos ang mga halimaw at espiritu,","story.map1-dungeon1.016":"...ginamit din nila ang kapangyarihan nila para ipatawag at kontrolin ang mga maalamat na bayani ng Grand Gaia.","story.map1-dungeon1.017":"Kung hindi natin sila mapipigilan, <wait=40>mawawasak ang Grand Gaia...","story.map1-dungeon1.018":"Kahit ang Banal na Emperador na si Karna Masta at ang iba pang mga diyos...","story.map1-dungeon1.019":"...<wait=20>ay hindi sila kayang pigilan nang matagal.","story.map1-dungeon1.020":"Kaya binuksan ni Lord Lucius ang Pintuan patungo sa mundong ito.","story.map1-dungeon1.021":"Gusto niyang hiramin ang kapangyarihan mo.","story.map1-dungeon1.022":"Kaya ang mga pinili lang ang nakakakita sa pintuan.","story.map1-dungeon1.023":"Malaki ang inaasahan ni Lord Lucius sa\'yo.","story.map1-dungeon1.024":"Kaya umaasa akong hindi mo kami bibiguin, <wait=20><rep_handlename>!","story.map1-dungeon1.025":"Ngayon, <wait=40>ang una mong target ay isa sa Apat na Nahulog na Diyos...","story.map1-dungeon1.026":"Ang Diyosa ng Paglikha, <wait=20>si Maxwell!","story.map1-dungeon1.027":"Si Maxwell <wait=20>ang sumakop sa St. Lamia. Dati itong banal na lupain, pero ngayon ay kuta na niya.","story.map1-dungeon1.028":"Mula rito sa Mistral, <wait=40>kailangan mong lumampas sa Morgan para makarating doon.","story.map1-dungeon1.029":"Malayo-layo ang lalakbayin, <wait=40>pero sigurado akong kaya mo \'yan!","story.map1-dungeon1.030":"Dahan-dahan lang tayo hanggang matutunan mo ang pagiging Summoner!","story.map1-dungeon1.031":"Una, para makarating sa Morgan, kailangan nating pumunta sa Tore ng Mistral.","story.map1-dungeon1.032":"Para roon, <wait=20>kailangan nating malampasan ang Kuweba ng Apoy.","story.map1-dungeon1.033":"Sabi-sabi, <wait=20>punong-puno raw ng mababangis na hayop ang kuwebang ito.","story.map1-dungeon1.034":"Pero kahit ganoon, <wait=20>kaya mo \'yan!","story.map1-dungeon1.035":"<size=20>Argh! <wait=40>Hindi ko na matiis ang init na \'to!","story.map1-dungeon1.036":"Babalik muna ako para maligo. Mag-ingat ka at mauna ka na!","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.002":"<size=36>Achoo!!","story.map1-dungeon2.003":"...Naku,<wait=30> ang lamig-lamig!","story.map1-dungeon2.004":"Hoy! <wait=40>Ang lakas ng loob mong paghintayin ang isang babae sa ganito kalamig na lugar!","story.map1-dungeon2.005":"Brr... <wait=30>ang lamig talaga!!","story.map1-dungeon2.006":"So, <wait=20>para makarating sa Tore ng Mistral <wait=40>kailangan mong tawirin ang Niyebeng Parang ng Egor at dumaan sa gubat...","story.map1-dungeon2.007":"Tapos dumaan sa latian, <wait=30>at saka sa mga guho...","story.map1-dungeon2.008":"Ang layo na kahit iniisip pa lang, <wait=40>at hindi pa kasama riyan kung gaano katindi ang panahon!","story.map1-dungeon2.009":"Anyway, <wait=20>malayo pa ang lalakbayin mo papunta sa tore.","story.map1-dungeon2.010":"Pero mag-ingat ka. <wait=20>Lumalakas ang mga kalaban habang papalapit ka roon.","story.map1-dungeon2.011":"Kung may kalabang hindi mo matalo, <wait=20>magandang bumalik muna sa naunang dungeon at mag-training nang kaunti.","story.map1-dungeon2.012":"Ay oo nga pala, <wait=20>panahon na rin para ayusin mo ang squad mo nang isinasaalang-alang ang kanilang Element.","story.map1-dungeon2.013":"Halos lahat ng kalaban sa kuweba ay apoy ang Element, kaya kung puro Unit na tubig ang Element ng squad mo, malaki sana ang naging bentahe mo!","story.map1-dungeon2.014":"Ngayon, nasa niyebeng parang tayo. <wait=40>Sa tingin ko, maraming kalabang tubig ang Element dito.","story.map1-dungeon2.015":"Kaya... <wait=20>pop quiz! <wait=40>Aling Element ang malakas laban sa tubig?","story.map1-dungeon2.016":"Oo, <wait=40>tama \'yan!","story.map1-dungeon2.017":"Mukhang nag-aral ka, ah. <wait=40>Yup, talo ng kidlat ang tubig.","story.map1-dungeon2.018":"Sa kabilang banda, dehado ang mga Unit na apoy ang Element laban sa mga kalaban sa niyebeng parang, kaya mag-ingat ka.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.020":"<size=36>Achoo!!","story.map1-dungeon2.021":"Hay naku, <wait=20>hindi ko na kaya. <wait=40>Uuwi na ako!","story.map1-dungeon2.022":"...Ah, <wait=20>muntik ko nang makalimutan.","story.map1-dungeon2.023":"Mukhang may kabalyerong ipinatawag ni Maxwell na nanggugulo sa may dulo ng niyebeng parang na \'to.","story.map1-dungeon2.024":"Mukhang malakas siya. Mag-ingat ka!","story.map1-dungeon3.001":"Oh, <wait=20><rep_handlename>! <wait=40>Magaling at natawid mo ang niyebeng parang.","story.map1-dungeon3.002":"Hmm, <wait=40>masasabi kong mas kagalang-galang ka na ngayon kumpara noong una tayong magkita.","story.map1-dungeon3.003":"Sige, <wait=20>oras na para tawirin ang Gubat ng mga Halimaw!","story.map1-dungeon3.004":"Gaya ng ipinahihiwatig ng pangalan, puno ng mababangis na hayop ang gubat na \'to...","story.map1-dungeon3.005":"Pero ang tunay mong kalaban <wait=20>ay ang nangangaso sa kanila.","story.map1-dungeon3.006":"Ay, <wait=40>nag-equip ka na ba ng Sphere?","story.map1-dungeon3.007":"Mapapalakas mo ang kakayahan ng iyong mga Unit kapag in-equip mo sila ng Sphere.","story.map1-dungeon3.008":"Bilang Summoner, kailangan mong malaman \'to kung gusto mong tumagal.","story.map1-dungeon3.009":"Puwedeng mag-forge ng Sphere sa Sphere House sa mundo mo.","story.map1-dungeon3.010":"Mag-equip ng Sphere sa iyong mga Unit para bumuo ng mas malakas na Squad!","story.map1-dungeon3.011":"Para makagawa ng Sphere, kailangan ng ilang materyal na kailangan mo munang kolektahin.","story.map1-dungeon3.012":"Anyway, <wait=20>good luck at lumaban ka nang husto!<br>","story.map1-dungeon4.001":"<size=18>Argh, <wait=20>grabe \'to!! Ano ba \'tong nakakabaliw na alinsangan?!","story.map1-dungeon4.002":"Ang lagkit-lagkit ng buhok at damit ko, nakakadiri!!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Nakalabas ka sa gubat. Buti naman at hindi nasayang ang oras ko sa pagtuturo sa\'yo.","story.map1-dungeon4.005":"Ay, <wait=20>oo nga. <wait=40>Nagagamit mo ba nang maayos ang Spark?","story.map1-dungeon4.006":"Kapag sabay-sabay umatake ang iyong mga Unit at naka-Spark ka, malaki ang itinataas ng damage mo.","story.map1-dungeon4.007":"Napakahalagang technique \'yan. Lalo itong nakakatulong laban sa mahihirap na kalaban.","story.map1-dungeon4.008":"Magpraktis ka hanggang makuha mo ang tamang timing at maka-Spark ka nang marami!","story.map1-dungeon4.009":"<wait=20>Sige na, bilisan nating tawirin ang Latian ng Magutagal! Nakakadiri rito...","story.map1-dungeon4.010":"Argh, <wait=20>kinakagat na ako ng mga insekto. Mapupuno ng kagat ang makinis kong binti kapag nagtagal pa ako rito.","story.map1-dungeon4.011":"Ayoko na! <wait=40>Hihintayin na lang kita sa mga guho!","story.map1-dungeon5.001":"Oh, <wait=20><rep_handlename>! <wait=40>Sa wakas, nakarating ka rin sa mga guho!","story.map1-dungeon5.002":"Sa totoo lang, <wait=20>noong una tayong magkita, mukha kang hindi maaasahan, <wait=20>walang alam, <wait=20>at walang kamalay-malay sa nangyayari sa paligid mo...","story.map1-dungeon5.003":"Talagang napaisip ako... <wait=40>Summoner ba talaga \'tong taong \'to?","story.map1-dungeon5.004":"Pero mukhang tama si Lord Lucius. <wait=20>May potensyal ka nga!","story.map1-dungeon5.005":"Siya nga pala, <wait=20>alam mo na siguro ang tungkol sa Leader Skill, \'di ba?","story.map1-dungeon5.006":"Para makalamang sa kalaban o matakpan ang mga kahinaan ng Squad mo...","story.map1-dungeon5.007":"mahalagang subukang magpalit ng Leader para masubukan ang iba\'t ibang Leader Skill.","story.map1-dungeon5.008":"At saka, <wait=40>kapag may ibang Summoner na tumutulong sa\'yo...","story.map1-dungeon5.009":"...gumagana rin ang Leader Skill nila.","story.map1-dungeon5.010":"Mahalaga \'to, kaya tandaan mo!","story.map1-dungeon5.011":"Tara na, <wait=20>ilang hakbang na lang tayo sa Tore ng Mistral!","story.map1-dungeon5.012":"Itong Labi ng Mirza, <wait=40>ay mga natira sa isang gusaling itinayo libu-libong taon na ang nakararaan...","story.map1-dungeon5.013":"Pero kamakailan, wala akong nababalitaang mga nilalang na nag-aabang dito.","story.map1-dungeon5.014":"Baka, <wait=20>baka lang, <wait=20>makalusot ka nang walang aberya!","story.map1-dungeon5.015":"Well... <wait=20>hindi natin malalaman hangga\'t hindi mo sinusubukan.","story.map1-dungeon5.016":"Pero sa dami ng nagawa mo na, <wait=20>duda akong may makakaharang pa sa\'yo!","story.map1-dungeon5.017":"Magtiwala ka sa sarili mo! Good luck!","story.map1-dungeon6.001":"Oh, <wait=20><rep_handlename>.<br><wait=40>Nakalabas ka nang buhay sa mga guho...","story.map1-dungeon6.002":"Brr... <wait=20>Ang lamig at nakakakilabot dito. <wait=40>Tingnan mo \'yung kahina-hinalang gusali roon.","story.map1-dungeon6.003":"Narinig kong kilala raw \'yon bilang Pugad ng Halimaw...","story.map1-dungeon6.004":"Kinikilabutan ako sa lugar na \'yon!","story.map1-dungeon6.005":"At kamakailan, may mga ulat tungkol sa isang misteryosong eskrimador na gumagala sa lugar.","story.map1-dungeon6.006":"<size=20>H-<wait=10>Hindi <size=19>sa <size=18>s-<size=17>sinasabi <size=16>kong <size=15>ako\'y <size=14>n-<size=13>na-<size=12>natatakot, <size=11>OK<size=9>?!","story.map1-dungeon6.007":"A-Anyway, <wait=20>kakaiba raw ang suot niya at kakaibang espada ang hawak niya. <wait=20>Pero hindi dapat maliitin ang tunay niyang lakas.","story.map1-dungeon6.008":"Siguraduhin mong alerto ka palagi...","story.map1-dungeon6.009":"<size=20>Eek!!<br><wait=20><size=18>M-<size=20>May <size=16>kung <size=19>anong <size=17>dumapo <size=18>s-<size=15>sa <size=17>braso <size=19>ko...","story.map1-dungeon6.010":"Oh, <wait=20>dahon lang?<br><wait=60>Ano... <wait=20>ano \'yang tingin mo?","story.map1-dungeon6.011":"A-Anyway, <wait=20>mag-ingat ka!","story.map1-dungeon6.012":"Kapag nalampasan natin \'to, <wait=20>nasa paanan na tayo ng Tore ng Mistral!","story.map1-dungeon6.013":"Good luck, <wait=20><rep_handlename>!","story.map1-dungeon7.001":"Sa wakas, nakarating na tayo sa Tore ng Mistral.","story.map1-dungeon7.002":"Kahit nasa loob pa ng Mistral ang tore, nasakop na ito ni Maxwell.","story.map1-dungeon7.003":"Sa totoo lang, <wait=20>walang-wala ang mga kalabang nakaharap natin kumpara sa mga tauhan ni Maxwell.","story.map1-dungeon7.004":"Kailangan nating maging handang-handa para manalo at mapalaya ang tore mula sa kontrol ni Maxwell.","story.map1-dungeon7.005":"Sa pinakamataas na palapag <wait=20>naghihintay ang halimaw na sinasabing nilikha mismo ni Maxwell.","story.map1-dungeon7.006":"Pero hindi puwedeng madurog ka rito.","story.map1-dungeon7.007":"Malayo pa tayo sa St. Lamia, kung saan nag-aabang si Maxwell.","story.map1-dungeon7.008":"Sigurado akong kaya mo \'yan. <wait=40>Nirerespeto na nga kita ngayon. <wait=20>Magtiwala ka sa sarili mo!","story.map1-dungeon7.009":"Tara na, <wait=40><rep_handlename>!","story.map1-dungeon7.010":"Ilabas mo ang iyong lakas <wait=20>at palayain ang Mistral mula sa kamay ng kasamaan!","story.map1-dungeon_ex_clear.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>Ayan ka pala!</size>","story.map1-dungeon_ex_clear.003":"<rep_handlename>! <wait=40>Nagawa mo!","story.map1-dungeon_ex_clear.004":"Natukoy naming naglaho na ang isang napakalakas na kapangyarihan.","story.map1-dungeon_ex_clear.005":"Mukhang natalo mo si Skramya.","story.map1-dungeon_ex_clear.006":"Alam kong kung may makakagawa nito, ikaw \'yon!","story.map1-dungeon_ex_clear.007":"Ay, <wait=20>hindi ka naman nasugatan, \'di ba?","story.map1-dungeon_ex_clear.008":"Aalagaan kita pagbalik natin!","story.map1-dungeon_ex_clear.009":"Hehe, joke lang.","story.map1-dungeon_ex_clear.010":"Umm, <wait=20>dahil natalo mo ito, marami kaming nakuhang bagong impormasyon.","story.map1-dungeon_ex_clear.011":"Mukhang noong unang panahon, may isang maliit na bansa sa Rehiyon ng Mystral na sinubukang gamitin ang kapangyarihan ni Skramya.","story.map1-dungeon_ex_clear.012":"Pumalpak ang plano nila, at winasak ito ni Skramya sa galit.","story.map1-dungeon_ex_clear.013":"Hindi humupa ang galit ni Skramya at sumugod ito sa iba pang mga bansa.","story.map1-dungeon_ex_clear.014":"Pero may isang bayaning lumitaw, at buong-gilas na ikinulong si Skramya.","story.map1-dungeon_ex_clear.015":"Pagkatapos noon, mukhang namahinga si Skramya sa Kabundukan ng Egor nang walang gumagambala.","story.map1-dungeon_ex_clear.016":"Gusto ko sanang malaman kung anong klaseng bayani \'yon, pero wala na kaming ibang impormasyon.","story.map1-dungeon_ex_clear.017":"Sana balang araw ay may makuha pa kaming impormasyon tungkol sa taong \'yon.","story.map1-dungeon_ex_clear.018":"Sige, <wait=40>sasabihan kita kapag may bago kaming impormasyon!","story.map1-dungeon_ex_clear.019":"Good luck sa patuloy mong pag-iimbestiga sa Grand Gaia!","story.map1-dungeon_ex_open.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"H-<wait=20>Hello...","story.map1-dungeon_ex_open.003":"May nakakarinig ba sa akin?","story.map1-dungeon_ex_open.004":"Naririnig mo ba ako, <wait=40>sir?","story.map1-dungeon_ex_open.005":"Ah! <wait=40>Nakakonekta rin ako sa\'yo!","story.map1-dungeon_ex_open.006":"<rep_handlename>!","story.map1-dungeon_ex_open.007":"Nakarating ka na pala sa Kabundukan ng Egor!","story.map1-dungeon_ex_open.008":"Alam kong kaya mo!","story.map1-dungeon_ex_open.009":"Ay, <wait=20>hayaan mong ipakilala ko ulit ang sarili ko.","story.map1-dungeon_ex_open.010":"Ako si Lin Merylham mula sa Logistics Support...","story.map1-dungeon_ex_open.011":"...ng Grand Gaia Survey Office Bureau of Investigation, handang maglingkod sa inyo.","story.map1-dungeon_ex_open.012":"Para sa araw na ito...","story.map1-dungeon_ex_open.013":"...<rep_handlename>, bilang miyembro ng Summoner Army ng Akras Summoners\' Hall...","story.map1-dungeon_ex_open.014":"...hinihiling naming imbestigahan mo ang Kabundukan ng Egor!","story.map1-dungeon_ex_open.015":"Kahit nasa Rehiyon ng Mystral ito, naantala ang imbestigasyon dito dahil nasa kontrol ito ni Maxwell...","story.map1-dungeon_ex_open.016":"...pero dahil natalo na siya, maiimbestigahan na namin ito nang mas masusi!","story.map1-dungeon_ex_open.017":"Ang galing talaga ng ilang Summoner diyan, \'no?","story.map1-dungeon_ex_open.018":"Galingan mo rin, ha!","story.map1-dungeon_ex_open.019":"Ay, <wait=20>balik tayo sa sinasabi ko.","story.map1-dungeon_ex_open.020":"Tungkol sa Kabundukan ng Egor...","story.map1-dungeon_ex_open.021":"Ayon sa imbestigasyon namin, may natutulog doon na napakalakas na demonyo.","story.map1-dungeon_ex_open.022":"Hindi pa kami lubos na sigurado, pero...","story.map1-dungeon_ex_open.023":"...malaki ang posibilidad na ito ang demonyo ng yelo na sinasabing nasa Rehiyon ng Mystral.","story.map1-dungeon_ex_open.024":"Ha?","story.map1-dungeon_ex_open.025":"Hindi mo kilala si Skramya, ang demonyo ng yelo?","story.map1-dungeon_ex_open.026":"Nagulat talaga ako diyan...","story.map1-dungeon_ex_open.027":"Sige! <wait=40>Ipapaliwanag ko sa\'yo!","story.map1-dungeon_ex_open.028":"Noong unang panahon, sa Rehiyon ng Mystral...","story.map1-dungeon_ex_open.029":"...mukhang may ilan pang maliliit na bansa bukod sa lumang kaharian ng St. Lamia.","story.map1-dungeon_ex_open.030":"Sinasabing winasak silang lahat ng mga diyos nang sumalakay ang mga ito.","story.map1-dungeon_ex_open.031":"Pero sinasabi ring may isa sa mga iyon na hindi diyos ang wumasak, kundi si Skramya.","story.map1-dungeon_ex_open.032":"Gaano man kaliit, para mapabagsak ng iisang demonyo ang isang kaharian...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Umm, <wait=20>\'yon lang ang impormasyong alam ko.","story.map1-dungeon_ex_open.036":"\'Yon lang naman ang kailangan mong malaman!","story.map1-dungeon_ex_open.037":"Kaya nitong wasakin ang mga kaharian!","story.map1-dungeon_ex_open.038":"Sobrang delikado nito!","story.map1-dungeon_ex_open.039":"Bilang Summoner, hindi mo ito puwedeng pabayaan!","story.map1-dungeon_ex_open.040":"Wow, mukhang hindi ka man lang nag-aalala kung gaano ito kadelikado.","story.map1-dungeon_ex_open.041":"Pero talagang malupit ang demonyong ito, <wait=20>kaya huwag mong pilitin ang sarili mo!","story.map1-dungeon_ex_open.042":"Sige, aasahan ko ang magandang ulat mula sa\'yo!","story.map1-ending.001":"<size=24><rep_handlename>!!<br>Nagawa mo!!</size>","story.map1-ending.002":"Ang laban mo sa Juggernaut ay talagang <wait=40>astig!","story.map1-ending.003":"Puwede mo nang ipagmalaking magaling kang Summoner.","story.map1-ending.004":"Siguro... <wait=40>Ikaw ang itinadhanang kalaban ni Maxwell...","story.map1-ending.005":"Hindi, <wait=40>wala nang siguro-siguro!","story.map1-ending.006":"Ikaw talaga ang Summoner na itinadhanang magligtas sa Grand Gaia!","story.map1-ending.007":"...<wait=20>Hoy! <wait=40>Puwede ka namang magpakita ng kaunting pasasalamat sa taong pumupuri sa\'yo, \'di ba!","story.map1-ending.008":"Hindi ka ba puwedeng ma-excite nang kaunti? <wait=40>Nakakahiya na ako lang ang hyped dito.","story.map1-ending.009":"Oh! <wait=40>Tinatawag tayo ni Lord Lucius!","story.map1-ending.010":"<speed=12>Sa wakas, makakapunta na tayo sa Morgan<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ako si Lucius...<br><wait=40>Diyos ng Pintuang ito...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Tagapagligtas ng St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang aking kapangyarihan <wait=40>at maglakbay sa mga bagong lupain...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Humayo ka <wait=20>at gamitin ang iyong lakas upang magdala ng kapayapaan sa mundong ito...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...Gumising ka!","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...Naririnig mo ba ako?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40><rep_handlename>, gumising ka!!","story.map1-ending.018":"Hay naku, <wait=40>sobra ka namang matulog!!","story.map1-ending.019":"Ano? <wait=40>Nasaan tayo? Ito ang Morgan... <wait=20>Morgan!","story.map1-ending.020":"Ang ganda, \'di ba! <wait=20>Bukas na rin sa wakas ang mga pintuan papuntang Morgan.","story.map1-ending.021":"Sa wakas, ha... <wait=20>Morgan...","story.map1-ending.022":"Dati, kilala ang lugar na \'to sa napakagandang tanawin...","story.map1-ending.023":"Pero maraming taon na ang lumipas, <wait=20> at napunta na ito sa kamay ni Maxwell.","story.map1-ending.024":"Mas malalakas ang mga halimaw dito kaysa sa Mistral...","story.map1-ending.025":"Hindi natin alam ang naghihintay sa atin, <wait=40>kaya mas mabuti siguro kung babalik ka muna sa nayon mo para maghanda.","story.map1-ending.026":"Hihintayin kita rito.","story.map1-ending.027":"Pagbalik mo, pumunta tayo sa Tore ng Morgan, <wait=19>at doon natin palalayain ang lupaing ito!","story.map1-ending.028":"Sige, <wait=20>kita tayo mamaya!","story.map10-dungeon1.001":"<size=20>Late ka! <wait=40>Saan ka ba nagpunta, <rep_handlename>!</size>","story.map10-dungeon1.002":"Nagpapakahirap ako para iligtas ang kaibigan mo, tapos paghihintayin mo pa ako!","story.map10-dungeon1.003":"Ikaw <size=20>bagal-bagal </size>na tanga!","story.map10-dungeon1.004":"Alam kong utos \'to ng mga Elder Summoner, pero bakit ako pa ang hahabol sa kanya?","story.map10-dungeon1.005":"Hoy, ano\'ng mukha \'yan?","story.map10-dungeon1.006":"Hindi mo naman iniisip na tatakasan ko ang misyong \'to, \'di ba?","story.map10-dungeon1.007":"<size=20>Huwag mo akong pagbibiruin!</size>","story.map10-dungeon1.008":"Kapag perpekto kong natapos ang tungkulin ko, ang huwad na Karl na \'yon ang magmumukhang tanga.","story.map10-dungeon1.009":"Hindi na ako makakakuha ng maraming pagkakataong tulad nito.","story.map10-dungeon1.010":"Kaya umayos ka na at tulungan mo ako!","story.map10-dungeon1.011":"Kung gagawin mo \'yan, baka mabilis nating matapos ang imbestigasyon dito.","story.map10-dungeon1.012":"Hindi ako sigurado kung ito ang kabisera ng imperyo ng Agni, pare-pareho lang naman ang maaalikabok na guho ng lungsod na \'to.","story.map10-dungeon1.013":"<size=20>Hoy!</size>","story.map10-dungeon1.014":"Tigilan mo ang kalokohan at hanapin mo na ang tamad na Karl na \'yon!","story.map10-dungeon1.015":"Hmm?","story.map10-dungeon1.016":"Saan ka magsisimula?","story.map10-dungeon1.017":"Ang tanga mo talaga!","story.map10-dungeon1.018":"Iniisip ko kung pang-dekorasyon lang ba ang ulo mong \'yan.","story.map10-dungeon1.019":"Pero hinahabol ka pa rin ng disipulong si Mare, hindi ba?","story.map10-dungeon1.020":"Kung manggugulo ka rito, siguradong darating siya at gagamitin si Karl bilang pantawad.","story.map10-dungeon1.021":"Iyon ang pagkakataon nating iligtas ang ungas na si Karl.","story.map10-dungeon1.022":"Kung naiintindihan mo, magkunwari kang nag-iimbestiga gaya ng tangang ikaw at gumawa ka ng pinakamalaking gulo na kaya mo!","story.map10-dungeon2.001":"<size=20>Bwisit! </size><wait=40><size=22>Nakakainis!","story.map10-dungeon2.002":"Ano\'ng akala ng maputlang babaeng \'yon, nagtatago siya sa atin!","story.map10-dungeon2.003":"Hoy! <wait=40><rep_handlename>!","story.map10-dungeon2.004":"Puwede ka bang mag-ingay nang kaunti pa?","story.map10-dungeon2.005":"Tumakbo-takbo ka sa labas gaya ng lagi mong ginagawa para mas madali kang makita!","story.map10-dungeon2.006":"Nakakaawa ka, ni hindi mo kayang maging pain!","story.map10-dungeon2.007":"Nngh! <wait=40>Kahit gaano ako kapasensiyoso, sinasagad mo na ako.","story.map10-dungeon2.008":"Hindi ko na kayang hintayin pa ang disipulong \'yon.","story.map10-dungeon2.009":"Hahabulin ko si Karl nang mag-isa!","story.map10-dungeon2.010":"Hanapin mo rin siya nang mag-isa!","story.map10-dungeon2.011":"Hindi ako ganoon kabait para protektahan ang taong walang silbi sa akin.","story.map10-dungeon2.012":"Kaya huwag mo akong susundan, naintindihan mo?","story.map10-dungeon2.013":"<size=20>Hoy! <rep_handlename>!</size>","story.map10-dungeon2.014":"Muntik ko nang makalimutang sabihin sa \'yo.","story.map10-dungeon2.015":"Huwag na huwag kang magpapahuli sa disipulong \'yon.","story.map10-dungeon2.016":"Sigurado akong kapag nahuli ka, ako na naman ang uutusang magligtas sa \'yo.","story.map10-dungeon2.017":"Hindi ko na kaya ang dagdag pang nakakaabalang utos.","story.map10-dungeon2.018":"Ibig kong sabihin, kung mahuhuli ka rin lang, mas mabuti pang dinurog ka na lang niya.","story.map10-dungeon2.019":"<size=20>Gets mo, \'di ba!?</size>","story.map10-dungeon3.001":"Mukhang nakawala na rin ako sa mga pesteng \'yon.","story.map10-dungeon3.002":"Hmm. <wait=40>Bakit gulat na gulat ka?","story.map10-dungeon3.003":"Mukhang mag-isa ka na rin sa wakas.","story.map10-dungeon3.004":"Kahit ang hangal na tao ay mahuhulaang lilitaw ako sa harap mo, ang aking biktima.","story.map10-dungeon3.005":"O baka sa sobrang hina ng ulo mo, ni hindi mo man lang napansin?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"Hinahanap mo ba ang maliit at berdeng nilalang na halos hindi na matatawag na buhay?","story.map10-dungeon3.008":"Tiyak na naloko siya ng pekeng impormasyong iniwan ko tungkol sa kinaroroonan ni Karl.","story.map10-dungeon3.009":"Malamang ay nagtatatakbo siya ngayon sa buong Agni.","story.map10-dungeon3.010":"Kahit malaki ang bibig niya, tao pa rin lang siya.","story.map10-dungeon3.011":"Medyo nakakaabala ang maliliit mong kaibigan noon, dahil hindi ko pa sila kilala.","story.map10-dungeon3.012":"Pero mukhang wala nang natitirang tutulong sa \'yo ngayon.","story.map10-dungeon3.013":"Gusto kong subukan muling kunin ang buhay mo.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Pero ikaw ang Summoner na nakatalo na sa maraming diyos.","story.map10-dungeon3.016":"Hahayaan muna kitang mapagod nang kaunti pa.","story.map10-dungeon3.017":"Kung gusto mong iligtas si Karl, sundan mo ako.","story.map10-dungeon3.018":"Tapos na ang buhay niya kung hindi.","story.map10-dungeon3.019":"Kahit alam mong puno ng bitag ang daan, susundan mo pa rin kaya ako?","story.map10-dungeon3.020":"Hmph. <wait=40>Ang hahangal talaga ninyong mga tao.","story.map10-dungeon3.021":"Magpakahirap ka sa pag-abante para mas madali kitang tapusin mamaya.","story.map10-dungeon3.022":"Inaabangan ko nang makita kang nanghihina.","story.map10-dungeon4.001":"Kaya mo palang lampasan ang Granasta Plateau.","story.map10-dungeon4.002":"Inaasahan ko na \'yan mula sa tumalo kina Maxwell at Cardes.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"Sa pagtingin sa \'yo, naaalala ko ang digmaan kung saan nalipol ang mga tao.","story.map10-dungeon4.005":"Ang mga taong sapat ang kahangalan para isiping kaya nilang labanan ang mga diyos.","story.map10-dungeon4.006":"Ah oo, noong panahong iyon, may isa pang taong kasingtigas ng ulo mo.","story.map10-dungeon4.007":"Mukhang tinawag siyang bayani ng ibang mga tao.","story.map10-dungeon4.008":"Pero gaya mo ngayon, wala rin siyang nagawa at takot na takot.","story.map10-dungeon4.009":"Gaano man siya kalakas para sa isang tao...","story.map10-dungeon4.010":"...hindi niyon mababago na isa lamang siyang mangmang na tao.","story.map10-dungeon4.011":"Ikaw rin, magkakaroon ka ng ganoong ekspresyon.","story.map10-dungeon4.012":"Inaabangan kong masiyahan doon.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Hmph. <wait=40>Wala akong interes sa tingin mong \'yan.","story.map10-dungeon4.015":"Siguro kailangan ko pang pahirapan ka nang kaunti.","story.map10-dungeon4.016":"Ano\'ng masasabi mo roon?","story.map10-dungeon4.017":"Hayaan mong makita ko kung gaano kalayo ang mararating mo nang mag-isa.","story.map10-dungeon5.001":"<rep_handlename>. Pinipili mo pa ring lumaban.","story.map10-dungeon5.002":"Ayaw ko sa mga mata mong \'yan, <wait=40>na walang bakas ng kawalan ng pag-asa.","story.map10-dungeon5.003":"Paano ka pa nagkakaroon ng pag-asa sa ganitong sitwasyon?","story.map10-dungeon5.004":"Wala na rito ni isa sa mga kakampi mong sumusuporta sa \'yo.","story.map10-dungeon5.005":"Kahit ang kaibigan mo mula pagkabata.","story.map10-dungeon5.006":"O ang babaeng Summoner na laging nang-iinsulto sa \'yo.","story.map10-dungeon5.007":"O ang matandang may katawa-tawang inaasahan sa \'yo.","story.map10-dungeon5.008":"O ang hindi kapani-paniwalang bastos na nilalang na \'yon.","story.map10-dungeon5.009":"Kahit ang mababang diyos na gumagamit sa \'yo sa buong panahong ito.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"O baka sasabihin mong mula pa sa simula ay hindi ka umasa kaninuman?","story.map10-dungeon5.012":"At sa kabila niyon, pinipili mo pa ring desperadong iligtas ang mga kaibigan mo?","story.map10-dungeon5.013":"Isang kaisipang hindi ko maintindihan.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Ah, naaalala ko na.","story.map10-dungeon5.016":"Ngayong nabanggit ko, <wait=20>minsan, noong lubog na lubog sa gulo ang lalaking iyon...","story.map10-dungeon5.017":"...nagising ang isang bagong kapangyarihan sa loob niya.","story.map10-dungeon5.018":"Nagkaroon siya ng malalaking pakpak ng apoy sa likod.","story.map10-dungeon5.019":"Matagal ko nang gustong kalimutan ang kahihiyang dulot ng kapangyarihang iyon.","story.map10-dungeon5.020":"Kung ipapalagay kong taglay mo rin ang kapangyarihang iyon, wala na akong panahong makipaglaro.","story.map10-dungeon5.021":"Hmph...","story.map10-dungeon5.022":"Pero hindi kita puwedeng hayaang tumayo lang diyan at sayangin ang oras ko.","story.map10-dungeon5.023":"Malapit na ang laban nina Lord Zefalhua at Afla Dilith.","story.map10-dungeon5.024":"Kailangan kitang tapusin bago mo pa mapakialaman ang mga hula ko.","story.map10-dungeon5.025":"Handa ka na ba?","story.map10-dungeon5.026":"Ipapakita ko sa \'yo ang mundo ng kawalan ng pag-asa na hindi mo pa nakikita kailanman.","story.map10-dungeon5.027":"Hindi ako magpipigil, kaya ngayon, masdan mo ang tunay kong kapangyarihan!","story.map10-dungeon5.028":"Tanggapin mo ito nang buong lakas mo!","story.map10-dungeon6.001":"Hanggang diyan ka na lang, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Mahusay kang lumaban sa mga diyos hanggang ngayon.","story.map10-dungeon6.003":"Pero sa mga sugat sa buong katawan mo, alam kong hindi ka na makakalaban.","story.map10-dungeon6.004":"Hindi ko hahayaang umusad pa si Lucius at ang mga hula niya!","story.map10-dungeon6.005":"Mamatay ka!","story.map10-dungeon6.006":"<size=18>*Kliiiing*","story.map10-dungeon6.007":"Nngh!","story.map10-dungeon6.008":"Paano mo nahayaang pahirapan ka nang ganito ng babaeng \'yan?","story.map10-dungeon6.009":"Talaga, <wait=20>ang tanga mo.","story.map10-dungeon6.010":"Hoy, magpakatatag ka!","story.map10-dungeon6.011":"Huwag kang magpapatalo bago pa natin mailigtas si Karl!","story.map10-dungeon6.012":"Hangal! <wait=20>Balak mo pang gumalaw kahit sugatan ka?","story.map10-dungeon6.013":"Huwag mo akong pagbibiruin.","story.map10-dungeon6.014":"Akala mo ba talaga matatalo ako ng ganoong atake?","story.map10-dungeon6.015":"Para sa isang disipulo, ang tanga mo pala.","story.map10-dungeon6.016":"Napaka-tao mo naman.","story.map10-dungeon6.017":"<size=18>*Klaaaang*","story.map10-dungeon6.018":"Nngh!","story.map10-dungeon6.019":"Bakit nakatayo ka lang diyan?","story.map10-dungeon6.020":"Napagod ka ba nang husto sa laban mo kay <rep_handlename> kaya hindi ka makagalaw?","story.map10-dungeon6.021":"Tama, <wait=20>tungkol kay Karl, <wait=20>papunta na si Lugina sa Ocean Shrine para iligtas siya.","story.map10-dungeon6.022":"At akala mo pa naman ang galing mong naloko siya. <wait=20>Sayang.","story.map10-dungeon6.023":"Imposible \'yan.","story.map10-dungeon6.024":"Nngh, <rep_handlename>. <wait=20>Mukhang muntik ka nang mamatay ngayon.","story.map10-dungeon6.025":"Kahit ang bumalik lang sa \'yo ay isang Summoner na puno ng sugat.","story.map10-dungeon6.026":"Wawasakin ko kayong dalawa kapag natapos ko na ang bastos na nilalang na \'yon.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Hindi ko na siya nararamdaman.","story.map10-dungeon6.029":"Nngh.","story.map10-dungeon6.030":"*Hingal* <wait=20>*hingal* <wait=20>*Hingal* ","story.map10-dungeon6.031":"A-<wait=20>Ayos lang ako.","story.map10-dungeon6.032":"Bumalik lang ang kaunting sakit nang umalis siya.","story.map10-dungeon6.033":"Pero natutuwa ako\'t naloko natin siya.","story.map10-dungeon6.034":"Tingnan mo...<wait=40>Hindi tayo puwedeng tumayo lang, kailangan nating pumunta sa Ocean Shrine.","story.map10-dungeon6.035":"Sigurado akong doon nakakulong si Karl.","story.map10-dungeon6.036":"Ano\'ng tingin \'yan?","story.map10-dungeon6.037":"Wala akong oras para umupo lang at makipag-usap sa \'yo.","story.map10-dungeon6.038":"Pangako, mag-uusap tayo mamaya, kaya sa ngayon, habulin muna natin si Karl.","story.map10-dungeon7.001":"*Hingal* *hingal* *hingal*","story.map10-dungeon7.002":"Sa wakas, nakarating na tayo sa Ocean Shrine.","story.map10-dungeon7.003":"Mukhang malapit ka na sa hangganan mo.","story.map10-dungeon7.004":"Siya na naman.","story.map10-dungeon7.005":"Kinikilala ko ang tapang na kailangan para humarap sa akin nang bugbog at sira-sira ka nang ganyan.","story.map10-dungeon7.006":"Hmph. <wait=40>Ang yabang mo.","story.map10-dungeon7.007":"Kahit naloko kita para sabihin mo kung saan mo ikinulong si Karl.","story.map10-dungeon7.008":"...Mga hangal.","story.map10-dungeon7.009":"Nakikita kong nagpakahirap kayong makarating sa akin sa Lognea Cove.","story.map10-dungeon7.010":"Sa tingin mo ba makakatakas ka sa akin sa ganyang mga sugat?","story.map10-dungeon7.011":"Nngh...","story.map10-dungeon7.012":"Mga alagad ko!","story.map10-dungeon7.013":"Magtipon kayo rito at puksain ang mga insektong ito!","story.map10-dungeon7.014":"A-Ano \'to? <wait=20>Saan nanggaling ang lahat ng \'to!?","story.map10-dungeon7.015":"Hindi ba nakakahiya para sa isang diyos na tulad mo na tumawag ng ganito karami para lang labanan kaming mga tao?","story.map10-dungeon7.016":"Tumigil ka na sa kahangalan mong pagbubunganga.","story.map10-dungeon7.017":"Dito ko na kayo tuluyang tatapusin.","story.map10-dungeon7.018":"Iyon lang.","story.map10-dungeon7.019":"<rep_handlename>!","story.map10-dungeon7.020":"Pagsisihan mo ang hangal mong paglaban sa mga diyos at mamatay ka!","story.map10-dungeon7.021":"Nngh... <wait=40>Masama \'to, <wait=40>sobrang dami nila.","story.map10-dungeon7.022":"Hindi ka naman ganyan kahina ang loob sa ganitong sitwasyon.","story.map10-dungeon7.023":"Ang boses na \'yon!","story.map10-dungeon7.024":"P-Paano ka...","story.map10-dungeon7.025":"Uy. <wait=40>Pasensiya na\'t pinaghintay ko kayo.","story.map10-dungeon7.026":"Karl!","story.map10-dungeon7.027":"Paano ka...","story.map10-dungeon7.028":"Nakakulong ka pa sa kuwartong \'yon noong huli kong tingnan...","story.map10-dungeon7.029":"Noong dumating ka para tumingin, doon ko nalaman kung nasaan ako.","story.map10-dungeon7.030":"O, diyos na napakababa ng talino.","story.map10-dungeon7.031":"Ang lakas ng loob mo...","story.map10-dungeon7.032":"Lugina! <wait=20>Bakit ang tagal mo!","story.map10-dungeon7.033":"Tumahimik ka!","story.map10-dungeon7.034":"Natagalan ang pagliligtas sa kanya dahil sobrang tamad niya!","story.map10-dungeon7.035":"Sinabi ko na, pasensiya na.","story.map10-dungeon7.036":"Ah oo, at Seria...","story.map10-dungeon7.037":"Paano ka napunta sa ganyang kalagayan?","story.map10-dungeon7.038":"Hindi ko kasalanan, may isang taong nagpapabagal sa akin!","story.map10-dungeon7.039":"Sige na, kalimutan na natin \'yan!","story.map10-dungeon7.040":"May kailangan tayong harapin dito.","story.map10-dungeon7.041":"Tama ba, Mare?","story.map10-dungeon7.042":"Gumuho na ang plano mo.","story.map10-dungeon7.043":"Ano\'ng balak mong gawin ngayon?","story.map10-dungeon7.044":"Tao, naglalakas-loob ka bang isiping mas mataas ka sa mga diyos?","story.map10-dungeon7.045":"Pinupuri kita sa paglampas mo sa inaasahan ko sa \'yo.","story.map10-dungeon7.046":"Pero sa kabila ng paggalang ko sa \'yo, iiwan ko na ang mga plano ko at wawasakin na lang kita.","story.map10-dungeon7.047":"Ako, si Mare, disipulo ni Lord Zevalhua, ay nag-uutos sa inyo!","story.map10-dungeon7.048":"Mga alagad ko!","story.map10-dungeon7.049":"Magtipon kayo sa akin at wasakin ang mga kaaway ko!","story.map10-dungeon7.050":"Patayin ang lahat ng tao sa harap ko!","story.map10-dungeon7.051":"Mukhang marami-rami na sa kanila ang nagtipon dito.","story.map10-dungeon7.052":"Mas marami sila ngayon kaysa dati.","story.map10-dungeon7.053":"Mga tao. <wait=40>Mahusay kayong lumaban.","story.map10-dungeon7.054":"Sisiguraduhin kong maaalala ko kayo...","story.map10-dungeon7.055":"...at ang malagim na wakas na malapit na ninyong sapitin.","story.map10-dungeon7.056":"Saan ka sa tingin mo pupunta!","story.map10-dungeon7.057":"Umalis kayong lahat sa daan ko!","story.map10-dungeon7.058":"Ang dami nila.","story.map10-dungeon7.059":"Karl, <wait=40>sugatan ka...","story.map10-dungeon7.060":"Haha, <wait=20>binugbog lang ako nang kaunti ng disipulong \'yon, \'yon lang...","story.map10-dungeon7.061":"Huwag mo ngang balewalain \'yan!","story.map10-dungeon7.062":"Pero Seria, sugatan ka rin...","story.map10-dungeon7.063":"A-Ano ba \'to...","story.map10-dungeon7.064":"Tingnan mo nga ang lahat ng kaawa-awang nilalang na \'to!","story.map10-dungeon7.065":"Hoy! <wait=40><rep_handlename>!","story.map10-dungeon7.066":"Sawang-sawa na ako sa katatakbo.","story.map10-dungeon7.067":"Habulin mo ang maputlang babaeng \'yon at pabagsakin mo siya!","story.map10-dungeon7.068":"Ako na ang bahala sa dalawang \'to habang wala ka!","story.map10-dungeon7.069":"Hindi namin kailangan ang pag-aalaga mo!","story.map10-dungeon7.070":"Pasensiya na\'t pinag-alala ka namin, <rep_handlename>.","story.map10-dungeon7.071":"Iwan mo na sa amin ang lahat dito at habulin mo ang disipulong \'yon.","story.map10-dungeon7.072":"Babawi talaga ako sa \'yo pagkatapos.","story.map10-dungeon7.073":"Umaasa kami sa \'yo, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzzt* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzt* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>Naririnig mo ba...</size> <wait=20><size=20> *Bzzt...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzzt*</size> <size=18>...Sir...?</size> <wait=20>*Bzzt*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzzt*</size><wait=20><size=20> Ayan, ayos na!</size>","story.map10-dungeon_ex_clear.005":"Ang hirap makakuha ng signal sa loob ng mga dungeon na \'yan.","story.map10-dungeon_ex_clear.006":"Anyway, <wait=20>sasabihin ko sa \'yo ang nalaman ko.","story.map10-dungeon_ex_clear.007":"Ayon sa mga sinaunang kasulatan...","story.map10-dungeon_ex_clear.008":"...selyado na ang lugar na \'yon mula pa noong huling bahagi ng Agni Empire.","story.map10-dungeon_ex_clear.009":"Pero 100 taon bago niyon, may isang emperador na lihim na ikinulong doon.","story.map10-dungeon_ex_clear.010":"Lumipas ang mahabang panahon nang walang nakakaalam na nandoon siya. ","story.map10-dungeon_ex_clear.011":"Kinatatakutan ang emperador na \'yon ng mga nakapaligid sa kanya at itinuring siyang tirano.","story.map10-dungeon_ex_clear.012":"Sa totoo lang, <wait=20>hindi lang ang mga nasasakupan niya ang takot sa kanya kundi pati ang kanilang mga anak.","story.map10-dungeon_ex_clear.013":"Isang araw, nagkasakit at namatay ang isang batang pinahirapan niya.","story.map10-dungeon_ex_clear.014":"Dahil dito, lihim siyang ikinulong.","story.map10-dungeon_ex_clear.015":"Habang lumilipas ang panahon sa napakadilim na dungeon, lumalaki ang galit ng emperador kasabay ng kanyang pag-iisa.","story.map10-dungeon_ex_clear.016":"Isinilang siyang muli bilang napakalakas na multo, at naghiganti sa imperyo sa loob ng 100 taon.","story.map10-dungeon_ex_clear.017":"Kaya naman, <wait=20>ikinulong ang multo ng emperador kasama ng dungeon.","story.map10-dungeon_ex_clear.018":"Nandoon pa rin siya sa ilalim, <wait=20>at lumalaki ang galit niya bawat segundo.","story.map10-dungeon_ex_clear.019":"Nakakatakot isipin pa lang.","story.map10-dungeon_ex_clear.020":"Sir, <wait=20>hindi mo kailangang pilitin ang sarili mong hanapin ang multong \'yan!","story.map10-dungeon_ex_clear.021":"Kailangan mo lang imbestigahang mabuti kung gaano talaga kadelikado ang lugar na \'yon.","story.map10-dungeon_ex_clear.022":"A-<wait=20>Ano \'yon?<wait=40> Ano\'ng sinabi mo?","story.map10-dungeon_ex_clear.023":"Hindi nga!","story.map10-dungeon_ex_clear.024":"Natalo mo na ang multo ng emperador habang nagre-research pa ako!?","story.map10-dungeon_ex_clear.025":"Wow, Sir...<wait=20>ang galing mo.","story.map10-dungeon_ex_clear.026":"Pero teka! <wait=40>Teka lang!","story.map10-dungeon_ex_clear.027":"Gusto ko sanang maghintay ka pa nang kaunti hanggang matapos ang research ko...","story.map10-dungeon_ex_clear.028":"Hmm...<wait=20> Ah basta!","story.map10-dungeon_ex_clear.029":"Sa susunod, gagawin ko ang lahat para maibigay sa \'yo ang impormasyon sa lalong madaling panahon!","story.map10-dungeon_ex_clear.030":"Patutunayan ko sa \'yong hindi lang ikaw ang gumaling!","story.map10-dungeon_ex_clear.031":"Kokontakin kita ulit maya-maya, kaya hintayin mo lang!","story.map10-dungeon_ex_open.001":"<size=18>*Bzzt* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzt* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Si...</size> <wait=20><size=20>*Bzzt...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzzt*</size> <size=18>...naririnig...mo?</size> <wait=20>*Bzzt*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzzt*</size><wait=20><size=20>Sir!</size>","story.map10-dungeon_ex_open.005":"Sa wakas, konektado na tayo!","story.map10-dungeon_ex_open.006":"Mukhang nasa lugar ka na medyo mahina ang signal.","story.map10-dungeon_ex_open.007":"Anyway, <wait=20>uulitin ko mula sa simula.","story.map10-dungeon_ex_open.008":"Ako si Lin Merylham mula sa Logistics Support...","story.map10-dungeon_ex_open.009":"...ng Bureau of Investigation ng Grand Gaia Survey Office, handang tumulong.","story.map10-dungeon_ex_open.010":"Nakumpirma namin noong isang araw ang pagkawala ng isang malaking kapangyarihan sa rehiyon ng Agni. ","story.map10-dungeon_ex_open.011":"Mukhang dahil dito ay bumukas ang isang dating selyadong istruktura sa ilalim ng lupa. ","story.map10-dungeon_ex_open.012":"Ayon sa aming mga tala, <wait=20>may isang bagay na napakasama ang ikinulong doon.","story.map10-dungeon_ex_open.013":"Ang misyon mo ngayon ay pumunta roon at pigilan ito...","story.map10-dungeon_ex_open.014":"...bago pa ito makalabas at makapinsala!","story.map10-dungeon_ex_open.015":"Mukhang isang dungeon ang istrukturang iyon noong napakatagal na panahon.","story.map10-dungeon_ex_open.016":"Ha? <wait=40>Nandiyan ka na?","story.map10-dungeon_ex_open.017":"Hindi na ako nagulat!","story.map10-dungeon_ex_open.018":"Sige, <wait=20>gagawin ko ang makakaya ko para malaman pa ang tungkol sa dungeon.","story.map10-dungeon_ex_open.019":"Magkakaroon ako ng bagong impormasyon para sa \'yo bago mo matapos ang imbestigasyon.","story.map10-dungeon_ex_open.020":"Tiisin mo lang nang kaunti pa!","story.map10-ending.001":"M-<wait=20>Mga hangal...","story.map10-ending.002":"Paanong natalo ng mga tao ang isang diyos na tulad ko...","story.map10-ending.003":"K-Kung gayon, sige!","story.map10-ending.004":"<size=20>Ililibing ko kayong lahat kasama ng shrine na ito!</size>","story.map10-ending.005":"<size=14>*Dagundong* *dagundong*</size>","story.map10-ending.006":"<size=21>Hindi ko hahayaang mangyari \'yan!</size>","story.map10-ending.007":"Nngh, <wait=40>buhay ka rin pala!","story.map10-ending.008":"Tilith, disipulo ni Lucius!","story.map10-ending.009":"Nandito ako, <rep_handlename>!","story.map10-ending.010":"Sige, umalis na tayong lahat dito!","story.map10-ending.011":"Sandali, <rep_handlename>!","story.map10-ending.012":"Huwag mong isiping nanalo ka na!","story.map10-ending.013":"Walang halaga kahit ilan pa kayong magsama-sama.","story.map10-ending.014":"Wala kayong binatbat sa harap ni Lord Zevalhua!","story.map10-ending.015":"At higit pa roon, ang pinakamahalaga sa inyo ay...","story.map10-ending.016":"<size=15>*Dagundong* *dagundong*</size>","story.map10-ending.017":"Mare! <wait=40>Tanggapin mo na, talo ka na!","story.map10-ending.018":"<rep_handlename>! <wait=40>Naghihintay na ang lahat!","story.map10-ending.019":"Tara na!","story.map10-ending.020":"<size=16>*Dagundong* *dagundong*</size>","story.map10-ending.021":"Nngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Dagundong* *dagundong*</size>","story.map10-ending.024":"<rep_handlename>!","story.map10-ending.025":"Nagawa mo!","story.map10-ending.026":"Alam kong kaya mong talunin si Mare, aking <rep_handlename>!","story.map10-ending.027":"A-Aray...","story.map10-ending.028":"Agresibo pa ring lumipad gaya ng dati, <wait=40> Diyosa.","story.map10-ending.029":"Hindi ka ba puwedeng mag-ingat nang kaunti?","story.map10-ending.030":"Hoy, <wait=20>kayong dalawa, tigilan n\'yo ang pagrereklamo!","story.map10-ending.031":"Pero natutuwa akong ayos lang kayong dalawa, Karl at Seria.","story.map10-ending.032":"Alalang-alala ako habang buhat kita, Seria, sa sobrang dami ng sugat mo!","story.map10-ending.033":"Salamat diyan...","story.map10-ending.034":"Oo, <wait=20>nagpapasalamat din ako sa \'yo, Diyosa.","story.map10-ending.035":"At siyempre sa \'yo rin, <rep_handlename>!","story.map10-ending.036":"Pero huwag kang lalaki ang ulo, magmumukha lang kaming masama.","story.map10-ending.037":"Pasensiya na\'t natagalan ang paggaling ko.","story.map10-ending.038":"Anyway, ang galing mo gaya ng dati, <rep_handlename>!","story.map10-ending.039":"Natalo mo si Mare!","story.map10-ending.040":"Oo, <wait=20>tama.","story.map10-ending.041":"<rep_handlename>, <wait=40>talagang ipinagmamalaki kong matawag kang matalik na kaibigan.","story.map10-ending.042":"Tama, Karl.","story.map10-ending.043":"Umm...","story.map10-ending.044":"Ayaw ko sanang sirain ang saya n\'yo, pero hindi ba may nakakalimutan tayo?","story.map10-ending.045":"Tama! <wait=40>Si Lugina!","story.map10-ending.046":"Nasaan kaya siya?","story.map10-ending.047":"Sino si Lugina?","story.map10-ending.048":"Ah, hindi mo pa pala nakikilala nang harapan si Lugina, \'no, Diyosa?","story.map10-ending.049":"Hindi nga, <wait=40>ibig mong sabihin kami lang ang isinama mo?","story.map10-ending.050":"Umm, <wait=40>una sa lahat, hindi ko alam na may iba pa pala.","story.map10-ending.051":"Baka ang tinutukoy n\'yo ay \'yung taong kalahating nakabaon sa lupa?","story.map10-ending.052":"<size=21>Lugina!</size>","story.map10-ending.053":"<size=22>Mga ungas kayo! <wait=40>Babanatan ko kayong lahat!</size>","story.map10-ending.054":"Hoy, at least nakarating ka rito nang buo.","story.map10-ending.055":"Heh... <wait=20>Ang lala ng itsura mo kanina, Lugina.","story.map10-ending.056":"<size=20>Tangang babae! <wait=40>Ikaw ang pinakamalala kong babanatan!","story.map10-ending.057":"Seria, sabi ko tigil na!","story.map10-ending.058":"Lugina, <wait=40>talagang iniligtas mo kami ngayon.","story.map10-ending.059":"Salamat.","story.map10-ending.060":"Heh, <wait=20>tinulungan ko lang kayo dahil iniutos sa akin ng Summoners\' Hall.","story.map10-ending.061":"Sa totoo lang, kahit sino pa \'yon, wala akong pakialam.","story.map10-ending.062":"Pero paano mo nalaman kung saan ako nakakulong?","story.map10-ending.063":"Madali lang.","story.map10-ending.064":"Alam kong susubukan ng babaeng \'yon na ihiwalay ang tangang \'to.","story.map10-ending.065":"Kaya alam kong kapag ginawa ko ang ganoong sitwasyon, siguradong susugod siya.","story.map10-ending.066":"Pero napakaingat niya.","story.map10-ending.067":"Karl, <wait=20>hinulaan kong gagamitin ka niyang pain habang dahan-dahan siyang lumalapit.","story.map10-ending.068":"Naayos na ang lahat bago pa ako umalis ng Elgaia.","story.map10-ending.069":"Ang kailangan ko lang gawin ay sabihan ang tangang babaeng \'to na iligtas ang ungas na \'yon.","story.map10-ending.070":"<size=20>Sino\'ng tinatawag mong tanga!</size>","story.map10-ending.071":"Well, <wait=40>ang suhestiyon mo nga ang nagligtas sa akin.","story.map10-ending.072":"Pagdating na pagdating ko, binanggit ko sa disipulong \'yon ang pangalan ng kalapit na lugar na sinabi mo sa akin.","story.map10-ending.073":"Pagkasabi ko, gaya ng sinabi mo, umalis siya.","story.map10-ending.074":"Heh, <wait=40>madali lang hulaan, dahil alam ko kung kailan ka darating.","story.map10-ending.075":"Wala namang ganoon karaming lugar na mapagtataguan ng tao.","story.map10-ending.076":"Ang tangang disipulong \'yon, <wait=20>ginawa niya mismo ang inakala kong gagawin niya.","story.map10-ending.077":"Pumunta siya sa Ocean Shrine para silipin ang bihag niya.","story.map10-ending.078":"At dahil doon, dinala niya ako mismo sa kanya.","story.map10-ending.079":"Wow, ang galing mo, Lugina.","story.map10-ending.080":"<size=19>Mahirap isiping kayang gawin ng isang tulad mo ang ganoon.</size>","story.map10-ending.081":"<size=21>Ang lakas ng loob mo!<\\\\size>","story.map10-ending.082":"Ikaw pala si Lugina!","story.map10-ending.083":"Ikinagagalak kitang makilala!","story.map10-ending.084":"Ako si Tilith, ang diyosang nagbabantay kay <rep_handlename>.","story.map10-ending.085":"Disipulo ako ni Lucius.","story.map10-ending.086":"Isang diyosang disipulo ni Lucius?","story.map10-ending.087":"Hoy, <rep_handlename>!","story.map10-ending.088":"Baliw ba ang batang \'to o ano?","story.map10-ending.089":"Ang sama mo!","story.map10-ending.090":"At ako pa naman ang nagdala sa \'yo pabalik mula sa Ocean Shrine!","story.map10-ending.091":"Ikaw pala \'yon?","story.map10-ending.092":"Kung gayon, kung ganoon nga...","story.map10-ending.093":"Oo, tunay siyang diyosa.","story.map10-ending.094":"<size=18>Hindi nga...</size>","story.map10-ending.095":"Ang hangal na matandang si Grahdens.","story.map10-ending.096":"Ano ba\'ng pinagsasasabi niya...","story.map10-ending.097":"Ah, at Lugina...","story.map10-ending.098":"Si Grahdens ang nag-utos sa \'yong iligtas kami, hindi ba?","story.map10-ending.099":"Ano\'ng ginagawa ng matanda ngayon?","story.map10-ending.100":"Ano!? <wait=20>Paano ko malalaman?","story.map10-ending.101":"Siguro naggagala lang siya kung saan.","story.map10-ending.102":"Kung si Elder Grahdens ang tinutukoy n\'yo, nahuli siya ni Zevalhua.","story.map10-ending.103":"Ikaw...","story.map10-ending.104":"Matagal tayong hindi nagkita, <rep_handlename>.","story.map10-ending.105":"Pero mukhang hindi ko pa nakikilala ang mga kaibigan mo riyan.","story.map10-ending.106":"Inaabangan ko nang makilala kayong lahat.","story.map10-ending.107":"Ano\'ng ginagawa rito ng hamak na imperial guard na tulad mo?","story.map10-ending.108":"Bago \'yan, ano\'ng ibig mong sabihing nahuli ang matanda?","story.map10-ending.109":"He he he, <wait=20>huwag kang mainip.","story.map10-ending.110":"May mga gusto rin akong itanong.","story.map10-ending.111":"Gaya ng kung bakit buhay ka pa kahit nahuli ka ng disipulong \'yon.","story.map10-ending.112":"Pero puwede nating pag-usapan ang mga detalye sa Milvana.","story.map10-ending.113":"Ayos lang ba \'yon sa inyong dalawa...","story.map10-ending.114":"<rep_handlename> at Tilith, disipulo ni Lord Lucius?","story.map10-ending.115":"Oo, ayos lang sa akin.","story.map10-ending.116":"Tiyak na magbubukas agad si Lord Lucius ng daan para sa atin papuntang Milvana.","story.map10-ending.117":"Nagiging abala na \'to.","story.map10-ending.118":"Karl, <wait=40>ayos ka lang ba?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ako si Lucius...<br><wait=40>Diyos ng Gate na ito...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ikaw, <rep_handlename>,<wait=39> na nagbukas sa Ryvern...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang kapangyarihan ko <wait=40>at maglakbay sa mga bagong lupain...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Upang magdala ng bagong pag-asa sa mundong ito na walang kaayusan...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Manalig ka sa iyong kapangyarihan, <wait=20>at patuloy na sumulong...","story.map10-open.006":"<size=21><rep_handlename>! <wait=40>Bakit ang tagal mo!</size>","story.map10-open.007":"Pinaghihintay mo na naman ang taong nagligtas ng buhay mo gaya ng lagi mong ginagawa, hindi ako makapaniwala sa \'yo.","story.map10-open.008":"Bahala ka.","story.map10-open.009":"Magiging mabait ako at ipapaliwanag ko sa \'yo at sa ungas mong sarili.","story.map10-open.010":"Kung bakit mo ako nakita roon, siyempre!","story.map10-open.011":"Nagkaroon ako ng pangitain.","story.map10-open.012":"Sa henyo kong isip, nakita ko na ang gipit na kalalagyan mo balang araw.","story.map10-open.013":"......","story.map10-open.014":"Hindi ka naniniwala sa akin, <wait=20>\'no?","story.map10-open.015":"Hmph, <wait=20>bahala ka.","story.map10-open.016":"Ang matandang si Grahdens.","story.map10-open.017":"Inutusan niya akong sundan kayong lahat.","story.map10-open.018":"Direktang utos \'yon ng mga Elder Summoner sa akin.","story.map10-open.019":"Patunay \'yon na nagtitiwala ang Summoners\' Hall sa lakas ko!","story.map10-open.020":"<size=21>Ha ha ha ha!</size>","story.map10-open.021":"Anyway, <wait=20>ang talagang gusto nilang ipagawa sa akin ay iligtas ang pabayang si Karl.","story.map10-open.022":"......","story.map10-open.023":"Tutulungan mo ako riyan.","story.map10-open.024":"Hindi ka naman maglalakas-loob na tanggihan ang hiling ng taong may utang ka ng buhay, \'di ba?","story.map10-open.025":"Sige, papunta na ako sa Agni Empire.","story.map10-open.026":"Kung tama ang impormasyong nakuha ko, doon nakakulong si Karl.","story.map10-open.027":"Hindi \'to magiging madali, pero nagsisimula ang lahat sa imperyo.","story.map10-open.028":"Hindi ito ang oras para mag-alinlangan! Naririnig mo ba ako?","story.map10-open.029":"Tama!","story.map10-open.030":"Nakatingin pa rin sa \'yo ang disipulong si Mare, hindi ba?","story.map10-open.031":"Ipagdasal mo nang hindi ka niya maabutan!","story.map10-open.032":"<size=22>Ha ha ha ha!</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>late ka!! ","story.map11-dungeon1.002":"Tigilan mo na ang katamaran!","story.map11-dungeon1.003":"Talaga naman...","story.map11-dungeon1.004":"Bakit mo kami pinaghintay nang ganito katagal sa napakainit na lugar?","story.map11-dungeon1.005":"Aba, aba! <wait=20>Mukhang magkasundong-magkasundo kayong dalawa.","story.map11-dungeon1.006":"<speed=15><size=21>Huwag mo akong pagbibiruin! Tigilan mo ako!</size></speed>","story.map11-dungeon1.007":"Wow...<wait=20>pareho pa kayo ng sinasabi!","story.map11-dungeon1.008":"<speed=15><size=21>Ano\'ng sabi mo?! Ano\'ng sinabi mo?!</size></speed>","story.map11-dungeon1.009":"Diyosa, <wait=40>siya ba si Paris mula sa Imperial Guard?","story.map11-dungeon1.010":"Nakikiusap ako, huwag mo nang dagdagan ang pasanin ko...","story.map11-dungeon1.011":"Sapat na ang gulo ng mga magulang na nagpalaki sa akin...","story.map11-dungeon1.012":"Hehe... <wait=20>Pasensiya na.","story.map11-dungeon1.013":"At<wait=20> sumama rin si <rep_handlename>.","story.map11-dungeon1.014":"Puwede mo bang ikuwento agad ang natitirang bahagi?","story.map11-dungeon1.015":"Totoo bang nahuli ni Zevalhua si Elder Grahdens?","story.map11-dungeon1.016":"Oo, totoo.","story.map11-dungeon1.017":"Hindi ko talaga maibibigay ang mga detalye,","story.map11-dungeon1.018":"pero galing ang impormasyon sa isang mapagkakatiwalaang miyembro ng Imperial Guard, kaya mataas ang kredibilidad nito.","story.map11-dungeon1.019":"Ganoon ba...","story.map11-dungeon1.020":"Tsk.<wait=40> Bakit pa nagpahuli ang matandang Summoner na \'yon? ","story.map11-dungeon1.021":"Nakakainis.","story.map11-dungeon1.022":"Lugy! <wait=40> Huwag kang magsalita nang ganyan!","story.map11-dungeon1.023":"Alam mo namang nagpapakahirap si Elder Grah para sa ating lahat!","story.map11-dungeon1.024":"Lugy?!","story.map11-dungeon1.025":"Lugy... <wait=80> Hehe...","story.map11-dungeon1.026":"Ang pangit na palayaw...","story.map11-dungeon1.027":"May katangian ka talagang hindi maintindihan ng mga tao, Diyosa.","story.map11-dungeon1.028":"Ate na Imperial Guard, mali ka.","story.map11-dungeon1.029":"Medyo baliw lang siya, \'yon lang.","story.map11-dungeon1.030":"Ang sama n\'yong dalawa!!!","story.map11-dungeon1.031":"Seria, <wait=40>tama na, okay?","story.map11-dungeon1.032":"Kung ipagpapatuloy mo \'yan, wala tayong mararating.","story.map11-dungeon1.033":"At ikaw...<wait=20> Puwede ka na lang ba naming tawaging Paris?","story.map11-dungeon1.034":"Hehe.<wait=20> Isang karangalan na tawagin mo lang ang pangalan ko, o tanyag na Summoner Karl.","story.map11-dungeon1.035":"Huwag mo akong kutyain.","story.map11-dungeon1.036":"Anyway, sigurado tayong nandito sa Mirvana ang elder, \'di ba?","story.map11-dungeon1.037":"Oo. <wait=40>Sa kasamaang palad.","story.map11-dungeon1.038":"Sa tingin ko, kung nahuli ni Zevalhua si Elder Grah, malamang nasa Mirvana rin siya.","story.map11-dungeon1.039":"Iyon ay dahil sa lahat ng pagsisikap ni <rep_handlename>, ","story.map11-dungeon1.040":"ito na lang ang lugar na hawak pa ni Zevalhua.","story.map11-dungeon1.041":"At kung ganoon, <wait=40> mas mabilis kung maghihiwa-hiwalay tayo at hahanapin ang mga kahina-hinalang lugar.","story.map11-dungeon1.042":"Mukhang wala talagang magagawa kundi maghiwa-hiwalay, ano?","story.map11-dungeon1.043":"Kung ganoon, huwag kayong haharang sa daan ko!","story.map11-dungeon1.044":"Oo na, oo na. Gets na namin.","story.map11-dungeon1.045":"Galingan mo, Lugy!","story.map11-dungeon1.046":"Tangang babae! <wait=40>Bubugbugin kita!","story.map11-dungeon1.047":"Mukhang magiging masaya ulit ang lahat dahil may gagawin na!","story.map11-dungeon1.048":"Nakakatamad...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>umaasa kami sa \'yo rito.","story.map11-dungeon1.050":"Tulungan mo ang elder gamit ang parehong lakas na ginamit mo para tulungan ako!","story.map11-dungeon2.001":"Hmm...","story.map11-dungeon2.002":"Mukhang walang kahina-hinalang lugar dito...","story.map11-dungeon2.003":"Ha...?","story.map11-dungeon2.004":"Ah, Karl!","story.map11-dungeon2.005":"Hello, Diyosa.","story.map11-dungeon2.006":"May nakita ka bang palatandaan doon?","story.map11-dungeon2.007":"Sa kasamaang palad, wala.","story.map11-dungeon2.008":"Pero talaga, <wait=20>nasaan kaya ang elder...?","story.map11-dungeon2.009":"Kasi gumagawa siya ng ganitong kalokohan sa edad niya kaya siya nahuli sa simula pa lang.","story.map11-dungeon2.011":"Hindi \'no. Halata kong nag-aalala ka lang sa kanya, Karl.","story.map11-dungeon2.012":"Haha. Mukhang hindi ako makakatalo sa isang diyosa.","story.map11-dungeon2.013":"Hindi mo kailangang mag-alala sa kanya!","story.map11-dungeon2.014":"Sigurado akong ayos lang si Elder Grah!","story.map11-dungeon2.015":"Ayos ka lang din noong nahuli ka, \'di ba?","story.map11-dungeon2.016":"Kaya halatang mas magiging ayos ang mas magaling pang tulad ni Elder Grah.","story.map11-dungeon2.017":"May mga bagay sa sinabi mong hindi ko masang-ayunan...","story.map11-dungeon2.018":"Pero kahit mag-alala ako sa kanya, hindi naman siya mamamatay agad-agad.","story.map11-dungeon2.019":"Salamat, Diyosa!","story.map11-dungeon2.020":"Pero medyo kakaiba.","story.map11-dungeon2.021":"Ikaw...","story.map11-dungeon2.022":"Paris-bear.","story.map11-dungeon2.023":"B-Bear?!","story.map11-dungeon2.024":"Mahirap talagang sabihin \'to sa isang diyosa, pero...","story.map11-dungeon2.025":"...puwede bang huwag mo na akong tawaging \\"bear\\"?","story.map11-dungeon2.026":"\\"Paris\\" na lang ang itawag mo sa akin. Ayos lang sa akin \'yon.","story.map11-dungeon2.027":"Sige, okay.","story.map11-dungeon2.028":"Kaya, Paris, bakit ka nga ba nandito?","story.map11-dungeon2.029":"Well, <wait=20>hinahanap ko rin si Elder Grahdens.","story.map11-dungeon2.030":"Kaya hindi na nakakagulat na nagkasalubong tayo.","story.map11-dungeon2.031":"Sige, bahala na.","story.map11-dungeon2.032":"Kaya, ano sa tingin mo ang kakaiba sa lahat ng \'to?","story.map11-dungeon2.033":"Wow, <wait=20>hindi alam ng isang tulad ni Karl ng Nyonne ang tinutukoy ko?","story.map11-dungeon2.034":"Wala akong oras sa mga walang kuwenta mong laro. Sabihin mo na.","story.map11-dungeon2.035":"Hehe, <wait=20>mukhang iba ka nga kay Lugina.","story.map11-dungeon2.036":"Well, sige na nga.","story.map11-dungeon2.037":"Sigurado akong kakaiba rin ito para sa \'yo, \'di ba?","story.map11-dungeon2.038":"Bakit siya huhulihin ng mga diyos at hahayaang mabuhay?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Kung kasama mong lumaban si Elder Grahdens kay Zevalhua, at nahuli siya habang lumalaban,","story.map11-dungeon2.041":"bakit wala silang sapat na dahilan para patayin siya?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"Baka dinadala tayo ng lahat ng ito sa isang bitag?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"Puwede bang mamaya na natin isipin \'yan?! Kailangan nating iligtas si Elder Grah!","story.map11-dungeon2.046":"Tama ka.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"tama ang Diyosa. Ipagpapatuloy ko rin ang paghahanap sa elder.","story.map11-dungeon2.049":"Galingan natin nang magkakasama.","story.map11-dungeon2.050":"Oo, tama ka roon. Salamat sa tulong mo.","story.map11-dungeon2.051":"Hehe, <wait=20>dahil baka masagot naman ni Grahdens ang maliit na palaisipang iyan para sa atin.","story.map11-dungeon2.052":"Oo, baka nga...","story.map11-dungeon2.053":"Hehe...","story.map11-dungeon3.001":"Oh, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"Mag-isa ka ba ngayon?","story.map11-dungeon3.003":"Hehe, <wait=20>naaawa ako sa lahat ng Summoner na pinoprotektahan ng Diyosang \'yon.","story.map11-dungeon3.004":"Hindi ko narinig ang sagot mo noong huli dahil kay Lugina, pero","story.map11-dungeon3.005":"hindi ibig sabihing sumuko na ako sa \'yo.","story.map11-dungeon3.006":"Masaya akong makakalaban ulit kasama mo nang ganito.","story.map11-dungeon3.007":"Kaya naman--","story.map11-dungeon3.008":"<size=23>Hindi puwede!!!</size>","story.map11-dungeon3.009":"<size=21>Paris! <wait=20><br>Tigilan mo \'yan!</size>","story.map11-dungeon3.010":"<size=21>Akin ang Summoner na si <rep_handlename>!</size>","story.map11-dungeon3.011":"Ah, kaya sa \'yo pala ang Summoner na si <rep_handlename>?","story.map11-dungeon3.012":"Well, <wait=20>ano ba talaga ang ibig sabihin niyon?","story.map11-dungeon3.013":"<size=20>Ibig sabihin, eksaktong kung ano ang dating!</size>","story.map11-dungeon3.014":"<size=20>Akin ang Summoner na si <rep_handlename>! <wait=20> Tapos ang usapan!</size>","story.map11-dungeon3.015":"G-<wait=20>Ganoon ba...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>ang <wait=20>dami mong pinagdadaanan ngayon, \'no?","story.map11-dungeon3.017":"Well, <wait=20>anuman, mag-uusap tayo nang kaunti sa ibang pagkakataon.","story.map11-dungeon3.018":"Hahanapin ko muna si Elder Grahdens sa ngayon.","story.map11-dungeon3.019":"May darating ding bagong impormasyon, kaya abangan mo \'yon.","story.map11-dungeon3.020":"Ah! <wait=40>Paris, ang daya mo!","story.map11-dungeon3.021":"Hindi ako magpapatalo sa \'yo, alam mo \'yan!","story.map11-dungeon3.022":"<rep_handlename>!","story.map11-dungeon3.023":"Ipapakita ko sa kanya na ang maganda at walang talong diyosang ito ang makakahanap sa \'yo, Elder Grah!","story.map11-dungeon3.024":"Kaya huwag kang mag-alala, at hintayin mo lang ako!","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>naaawa talaga ako sa \'yo....","story.map11-dungeon4.001":"Tsch, ikaw pala.","story.map11-dungeon4.002":"Kung nandito ka pa rin, ibig sabihin ikaw pa rin ang parehong tanga gaya ng dati.","story.map11-dungeon4.003":"Ha? <wait=40>Sinabi mo bang pareho pa tayong nasa iisang lugar?","story.map11-dungeon4.004":"Tsch, <wait=20>kaya ayaw ko sa mga ungas.","story.map11-dungeon4.005":"May totoong dahilan kung bakit ako nandito.","story.map11-dungeon4.006":"Pero mas mahalaga, <rep_handlename>.","story.map11-dungeon4.007":"Mag-ingat ka talaga sa Imperial Guard na si Paris.","story.map11-dungeon4.008":"Ang babaeng \'yon, <wait=20>siguradong may binabalak siya.","story.map11-dungeon4.009":"Sinasabi niyang nakikipagtulungan ang mga maharlika ng Randall Empire sa Akras Summoner\'s Hall at kung anu-ano pa...","story.map11-dungeon4.010":"imposibleng totoo \'yon.","story.map11-dungeon4.011":"At sigurado akong may dahilan din siya sa sobrang interes niya sa \'yo...","story.map11-dungeon4.012":"<size=23>Hoy, mga ungas!</size>","story.map11-dungeon4.013":"<size=23>Bakit nakatayo lang kayo riyan?!</size>","story.map11-dungeon4.014":"Tsch, pero ngayon may mas nakakainis pang babae na dumating.","story.map11-dungeon4.015":"<size=20>Sino\'ng tinatawag mong nakakainis na babae?!</size>","story.map11-dungeon4.016":"<size=16>Hindi \'to oras para magdaldalan! Kailangan tayo ni Elder Grahdens!</size>","story.map11-dungeon4.017":"Sobrang close n\'yo na kinikilabutan na ako...","story.map11-dungeon4.018":"<size=21>Sino\'ng tinatawag mong close?! <wait=40><br>Ungas!</size>","story.map11-dungeon4.019":"<size=22>Sino\'ng tinatawag mong ungas?!</size>","story.map11-dungeon4.020":"<size=21>Huwag kang magmamataas, eh nakabaon nga ang ulo mo sa lupa kanina!</size>","story.map11-dungeon4.021":"Ghr, <wait=20>kasalanan \'yon ng weirdong Diyosang \'yon...","story.map11-dungeon4.022":"Lugy, dapat magsikap ka pa nang kaunti!","story.map11-dungeon4.023":"<size=23>Bubugbugin ko talaga ang tangang babaeng \'to!</size>","story.map11-dungeon4.024":"<size=21>Hoy, <rep_handlename>!</size>","story.map11-dungeon4.025":"<size=21>Saan ka tatakbo?!</size>","story.map11-dungeon4.026":"<size=18>Teka, <rep_handlename>! Saan ka pupunta?!</size>","story.map11-dungeon4.027":"<size=16>Huwag mo akong iwan sa dalawang weirdong \'to!</size>","story.map11-dungeon4.028":"<size=14>Hindi ko alam kung ano\'ng gagawin nila sa akin!</size>","story.map11-dungeon4.029":"<size=12>Na para bang may gusto akong gawin sa \'yo!</size>","story.map11-dungeon4.030":"<size=10>At ano\'ng ibig sabihin niyan?!</size>","story.map11-dungeon4.031":"<size=9>Hindi mo gets?!</size><wait=20><br><size=9>Ang tanga mo!</size>","story.map11-dungeon4.032":"<size=8>Tumahimik ka!</size><wait=20><br><size=8>Talunan!</size>","story.map11-dungeon5.001":"<rep_handlename>!!<wait=40> Makinig ka, makinig ka!!","story.map11-dungeon5.002":"Alam ko na <wait=20>kung nasaan si Elder Grah!","story.map11-dungeon5.003":"Kasi, umm... <wait=20>Mukhang nasa isang lugar siya na tinatawag na \\"Tower of the Gods.\\"","story.map11-dungeon5.004":"Ginawang base ni Zevalhua ang Tower of the Gods.","story.map11-dungeon5.005":"Kaya, sa madaling salita, <wait=20>kung pupunta tayo sa tower na \'yon","story.map11-dungeon5.006":"matatalo natin si Zevalhua, <wait=20>at maililigtas pa natin si Elder Grah.","story.map11-dungeon5.007":"Kaya sabihan mo sina Karl na pumunta sa Tower of the Gods!","story.map11-dungeon5.008":"Inaasahan ko na \'yan mula sa lingkod ni Lord Lucius, si Lady Tilith.","story.map11-dungeon5.009":"Ah, <wait=20>Paris!","story.map11-dungeon5.010":"Hehehe, <wait=20>magaling ako, \'no?","story.map11-dungeon5.011":"Aba, oo.<wait=20><br>Inaasahan na mula sa isang diyosa.","story.map11-dungeon5.012":"Pero <wait=20>paano mo natuklasan kung nasaan si Elder Grahdens?","story.map11-dungeon5.013":"Kasi...","story.map11-dungeon5.014":"May isa pang lingkod ni Lord Lucius, gaya ko, na nagmamanman kay Zevalhua.","story.map11-dungeon5.015":"Pumunta ang lingkod na iyon sa Tower of the Gods, at nag-ulat na may nakita siyang matandang nakakulong sa isang kuwarto roon.","story.map11-dungeon5.016":"Ganoon ba. <wait=20><br>Naiintindihan ko na...","story.map11-dungeon5.017":"Si Lord Lucius <wait=20>ay patuloy na nagtitipon ng maraming kamangha-manghang banal na lingkod!","story.map11-dungeon5.018":"Siyempre, kasama rin ako roon.","story.map11-dungeon5.019":"Oo, alam na alam kong may kamangha-mangha kang kapangyarihan, Diyosa.","story.map11-dungeon5.020":"Pero, <wait=20>nakapagtataka.","story.map11-dungeon5.021":"Ha? <wait=20>Ang alin?","story.map11-dungeon5.022":"Kung napakarami niyang mahuhusay na banal na nilalang sa panig niya,","story.map11-dungeon5.023":"bakit hindi siya mismo ang humarap sa mga Nahulog na Diyos?","story.map11-dungeon5.024":"Umm, <wait=20>kasi...","story.map11-dungeon5.025":"At saka, <wait=20>ang sugo ng pangunahing diyos,","story.map11-dungeon5.026":"ang Banal na Emperador na si Karna Masta, nakapagtataka rin siya sa akin.","story.map11-dungeon5.027":"Kahit nasa panganib ang Grand Gaia, wala siyang ipinapakitang senyales na may gusto siyang gawin tungkol dito.","story.map11-dungeon5.028":"Kung magkatulong sina Lord Lucius at Karna Masta, wala na silang pakinabang sa aming mga tao.","story.map11-dungeon5.029":"Pakiramdam ko, madali nilang matatalo nang sila lang ang dalawang natitirang Nahulog na Diyos.","story.map11-dungeon5.030":"Kasi... <wait=40><br>Eh, <wait=20>umm...","story.map11-dungeon5.031":"Posible kayang hindi malayang makagalaw nang mag-isa si Lord Lucius at ang iba pa?","story.map11-dungeon5.032":"Halimbawa, <wait=20>baka matapos siyang talunin ng Apat na Nahulog na Diyos noon, siya ay naselyuhan ng kung anong kapangyarihan, o--","story.map11-dungeon5.033":"Hin... <wait=20>Hindi ganoon!","story.map11-dungeon5.034":"Napakaayos ng kalagayan ni Lord Lucius!","story.map11-dungeon5.035":"Hindi ko masasabi sa \'yo ang lahat, pero hindi talaga siya makagalaw ngayon...","story.map11-dungeon5.036":"At...<wait=20>At ganoon din ang problema ni Karna Masta!","story.map11-dungeon5.037":"Pero hindi naman sila naselyuhan kung saan!","story.map11-dungeon5.038":"Paumanhin.","story.map11-dungeon5.039":"Sana\'y mapatawad mo ang hangal at mapaghinalang taong ito.","story.map11-dungeon5.040":"Hindi kayang unawain ng isang tangang tulad ko ang mga dakilang ideya ng mga diyos.","story.map11-dungeon5.041":"Isa lang akong taong laging natatakot.","story.map11-dungeon5.042":"Hindi, <wait=20>ayos lang.","story.map11-dungeon5.043":"Hindi ko inakalang itatanong mo sa akin ang ganoon, kaya nabigla ako.","story.map11-dungeon5.044":"Malaking tulong na sa akin ang mga salita mo.","story.map11-dungeon5.045":"Well, <wait=20>dapat na tayong pumunta para iligtas si Elder Grahdens.","story.map11-dungeon5.046":"Mukhang nauna na sina Karl papunta sa wasak na lungsod ng Mirvana.","story.map11-dungeon5.047":"O-<wait=20>Okay. <wait=40><br>Tama!","story.map11-dungeon5.048":"Kailangan nating sabihin agad kina Karl kung nasaan si Elder Grah!","story.map11-dungeon5.049":"Sige, <rep_handlename>! <wait=40> Tara na!","story.map11-dungeon6.001":"Ah, <wait=20>Karl!","story.map11-dungeon6.002":"Uy, <wait=20>diyosa at <rep_handlename>.","story.map11-dungeon6.003":"Hinihintay namin kayo.","story.map11-dungeon6.004":"Mukhang nalaman n\'yo na kung nasaan si Elder Grahdens, ha?","story.map11-dungeon6.005":"Maraming salamat.","story.map11-dungeon6.006":"Hoy, <wait=20>paano mo nalaman \'yon?","story.map11-dungeon6.007":"Dumaan si Paris kanina <wait=20>at sinabi niya sa amin.","story.map11-dungeon6.008":"Anooo?!<wait=40> Paris, ang bruha mo!!","story.map11-dungeon6.009":"Gusto ko sanang ako ang magbigay ng sorpresa sa kanila!!","story.map11-dungeon6.010":"Pero teka, <wait=20>nasaan na si Paris ngayon?","story.map11-dungeon6.011":"Oo <wait=20>sabi niya may bagay siyang gustong usisain, kaya nauna siya papunta sa Tower of the Gods.","story.map11-dungeon6.012":"Ganoon ba...","story.map11-dungeon6.013":"Ano kaya <wait=20> ang gusto niyang usisain...?","story.map11-dungeon6.014":"Diyosa, <wait=40>ano\'ng problema?","story.map11-dungeon6.015":"Parang hindi maganda ang itsura mo.<wait=20> May nangyari ba?","story.map11-dungeon6.016":"W-<wait=20>Wala, wala \'yon!","story.map11-dungeon6.017":"Lagi akong masigla!","story.map11-dungeon6.018":"Hindi ba, <wait=20><rep_handlename>?","story.map11-dungeon6.019":"Sige.","story.map11-dungeon6.020":"Well, <wait=20>pagkatapos nating iligtas si Elder Grahdens, balak kong ipakuwento sa kanya ang buong istorya.","story.map11-dungeon6.021":"Ang matandang \'yon... <wait=20>Pakiramdam ko, marami pa siyang itinatago sa amin.","story.map11-dungeon6.022":"Baka makatulong din sa atin sa katagalan kung mapapawi natin ang mga alalahanin ng Diyosa.","story.map11-dungeon6.023":"Ang bait talaga ni Karl.","story.map11-dungeon6.024":"Pero siyempre, mga kaibigan \'yan ni <rep_handlename>!","story.map11-dungeon6.025":"Haha. <wait=20>Kapag sinabi mo \'yan sa harap ko, medyo nahihiya ako.","story.map11-dungeon6.026":"Saka, <wait=20>iba ang usapan, pero...","story.map11-dungeon6.027":"Kumusta na \'yung bagay na \'yon?","story.map11-dungeon6.028":"\'Yung bagay na \'yon...?","story.map11-dungeon6.029":"Well, <wait=20>gaya pa rin ng dati. <wait=40><br>Kaya huwag mo nang alalahanin...","story.map11-dungeon6.030":"Ganoon ba! <wait=20><br>Gaya pa rin ng dati, ha?","story.map11-dungeon6.031":"Kung ganoon, <wait=20>hindi ko na aalalahanin.","story.map11-dungeon6.032":"Sinabi ko na sa \'yo! <wait=20>Ako ang unang makakarating sa Tower of the Gods!","story.map11-dungeon6.033":"Hindi mo alam \'yan!","story.map11-dungeon6.034":"Dapat diyan ka na lang sa pasukan at magbantay!","story.map11-dungeon6.035":"<size=18>Bakit ako pa ang kailangang magbantay?!</size>","story.map11-dungeon6.036":"Kasi bagay na bagay \'yon sa tangang babaeng tulad mo.","story.map11-dungeon6.037":"<size=18>Hindi ako tanga!</size>","story.map11-dungeon6.038":"Mahalagang trabaho pa rin naman ang pagbabantay!","story.map11-dungeon6.039":"Kung hindi mo \'yan maintindihan, marami kang mabibigong misyon sa hinaharap!","story.map11-dungeon6.040":"<size=18>Ano\'ng sabi mo sa akin?!</size>","story.map11-dungeon6.041":"Kung napakahalaga pala ng pagbabantay, bakit hindi ikaw ang gumawa?!","story.map11-dungeon6.042":"Magkaibang bagay ang pinag-uusapan mo!","story.map11-dungeon6.043":"Hay naku. <wait=20>Pinapakaba talaga ako ng dalawang \'to...","story.map11-dungeon7.001":"Sa wakas, <wait=40><br><rep_handlename>!","story.map11-dungeon7.002":"Nandito si Elder Grah,","story.map11-dungeon7.003":"at nandito rin ang isa sa Apat na Nahulog na Diyos, \\"Ang Banal na Emperador na si Zevalhua.\\"","story.map11-dungeon7.004":"Nararamdaman ko ang napakalakas na kapangyarihan diyan...","story.map11-dungeon7.005":"Hindi na nakakagulat, galing \'yan sa isa sa mga Nahulog na Diyos.","story.map11-dungeon7.006":"Tsk, <wait=20>wala akong pakialam kung gaano siya kalaki, kapag ininis niya ako, pagpipira-pirasuhin ko siya.","story.map11-dungeon7.007":"Pero teka, <wait=20>nasaan \'yung babaeng taga-Imperial Guard?","story.map11-dungeon7.008":"Mukhang wala siya rito.","story.map11-dungeon7.009":"Hah, <wait=20>mukhang hindi talaga maaasahan ang mga sundalo ng Imperial Army ng Randall.","story.map11-dungeon7.010":"Pero, <wait=20>may sarili rin siyang misyong kailangang asikasuhin.","story.map11-dungeon7.011":"Mukhang abala siya rito at doon.","story.map11-dungeon7.012":"Interesado pa nga siya kung bakit nahuli ang Elder...","story.map11-dungeon7.013":"Karl!","story.map11-dungeon7.014":"Wala tayong oras para isipin \'yan ngayon!","story.map11-dungeon7.015":"Kailangan nating magmadali at iligtas si Elder Grah bago mahuli ang lahat!","story.map11-dungeon7.016":"Tama ka. <wait=40><br>Tama ang sinabi ng Diyosa.","story.map11-dungeon7.017":"Walang silbing isipin \'yan ngayon!","story.map11-dungeon7.018":"Kung ganoon, <wait=20>maghiwa-hiwalay tayo at hanapin ang Elder!","story.map11-dungeon7.019":"Ang totoo, gusto ko sanang magsama-sama ulit tayo bago labanan si Zevalhua, pero","story.map11-dungeon7.020":"depende sa sitwasyon, baka hindi natin magawa \'yon. Baka kailangan natin siyang labanan nang mag-isa, kung kinakailangan.","story.map11-dungeon7.021":"Walang problema.","story.map11-dungeon7.022":"Kahit hindi pala totoo, o kahit bitag pa \'yon, lalaban pa rin ako!","story.map11-dungeon7.023":"Hah! <wait=20>Hindi naman ako umasa nang malaki sa lakas n\'yo.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>umaasa ulit kami sa lakas mo.","story.map11-dungeon7.025":"Sige, <wait=20>huwag kayong magpapapatay diyan!","story.map11-dungeon7.026":"Ito ay...","story.map11-dungeon7.027":"Mukhang wala akong magagawa kundi baguhin ang orihinal kong plano...","story.map11-ending.001":"Nagawa natin, <wait=40><br><rep_handlename>!","story.map11-ending.002":"Natalo mo pa si Zevalhua! Ang galing mo, <rep_handlename>!","story.map11-ending.003":"At sina Karl at ang Elder ay...","story.map11-ending.005":"*Hingal* *hingal* *hingal* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Pff*<wait=40><br>*Hingal*","story.map11-ending.007":"Wow, nagawa mo!","story.map11-ending.008":"Naramdaman kong lalo pang lumakas ang napakalakas na kapangyarihan, kaya nagmadali ako papunta rito,","story.map11-ending.009":"pero mukhang hindi na pala ako kailangang tumakbo...","story.map11-ending.010":"Bwisit, <wait=20>mukhang hindi ako umabot.","story.map11-ending.011":"<rep_handlename>!","story.map11-ending.012":"Ikaw, hayop ka, <wait=20>sinolo mo ang saya, \'no?!","story.map11-ending.013":"Kaya ayaw ko sa \'yo!","story.map11-ending.014":"Oh, <wait=20>mukhang nakaligtas ang lahat nang walang galos!","story.map11-ending.015":"<rep_handlename>!","story.map11-ending.016":"Alam kong matatalo mo si Zevalhua! Kaibigan nga kita, \'di ba?","story.map11-ending.017":"Natutuwa akong ligtas at buo ang lahat.","story.map11-ending.018":"So, <wait=20>nahanap n\'yo ba si Elder Grah?","story.map11-ending.019":"Wala siya rito?","story.map11-ending.020":"Wala siya sa alinman sa ibang mga kuwarto,","story.map11-ending.021":"kaya sigurado akong nandito siya, dahil ito na lang ang kuwartong hindi pa natitingnan. Kaya tumakbo ako papunta rito.","story.map11-ending.022":"Ugh, <wait=20>ngayon may haharapin na naman tayong mas nakakainis na kalokohan.","story.map11-ending.023":"Sana ligtas si Elder Grahdens <wait=20>kung nasaan man siya...","story.map11-ending.024":"Ay, <wait=20>pasensiya na, Karl. <wait=20> Hindi ko sinasadyang sabihin nang ganoon...","story.map11-ending.025":"Hindi, ayos lang.","story.map11-ending.026":"Walang bakas na nagpapakitang <wait=20>pumunta siya rito, kaya","story.map11-ending.027":"malamang nakatakas siya nang mag-isa.","story.map11-ending.028":"Ho ho ho. <wait=40><br>Tamang-tama ka.","story.map11-ending.029":"Ang boses na \'yon!","story.map11-ending.030":"Elder Grah!","story.map11-ending.031":"Ho ho ho.","story.map11-ending.032":"Mukhang binigyan ko kayo ng maraming abala.","story.map11-ending.033":"Elder Grahdens...","story.map11-ending.034":"Huwag kang gumawa ng ganyang mukhang pambata.","story.map11-ending.035":"Baka napag-alala ko kayo, <wait=20><br>pero hindi pa ako nagiging mahina.","story.map11-ending.036":"S-Sino\'ng nag-alala sa \'yo?!","story.map11-ending.037":"At higit sa lahat, <wait=20>ano\'ng ginagawa mo buong panahong ito, at saan?!","story.map11-ending.038":"Ipaliwanag mo sa lahat kung bakit kami nagpaikot-ikot para hanapin ka!","story.map11-ending.039":"Hmph, <wait=20>well, may nagawa akong masama.","story.map11-ending.040":"May bumabagabag sa akin tungkol sa tower na ito, <wait=20>kahit kaunti lang.","story.map11-ending.041":"Nagkunwari akong nahuli ng Nahulog na Diyos na si Mare-kung-sino-man, at pinadala ko ang sarili ko rito sa kanya.","story.map11-ending.042":"Siguro <wait=20>umasa siyang magkakaroon siya ng kalamangan laban sa inyong lahat sa labanan kapag nahuli niya ako.","story.map11-ending.043":"Pero bago pa iyon magamit ni Mare, natalo n\'yo na siya.","story.map11-ending.044":"Dahil may natutunan siya tungkol kina Zevalhua at Afla Dilith matapos niyang makipaglaban sa kanila,","story.map11-ending.045":"ayaw ko siyang labanan nang mag-isa.","story.map11-ending.046":"Pero gaya ng inaasahan, <wait=20>nang hayaan kong hulihin niya ako, dumating ang tulong n\'yo.","story.map11-ending.047":"At dahil doon, nagkaroon ako ng sapat na oras para dahan-dahang magsaliksik.","story.map11-ending.048":"Kung ganoon, <wait=20>sana sinabi mo na lang sa amin.","story.map11-ending.049":"Nakakainis na matanda.","story.map11-ending.050":"Ho ho ho. <wait=40>Pasensiya na, Lugina.","story.map11-ending.051":"May utang na loob ako sa \'yo sa mga ginawa mo.","story.map11-ending.052":"Gagantimpalaan kita nang maayos.","story.map11-ending.053":"Dapat lang.","story.map11-ending.054":"At hindi lang \'yon, <wait=20>kailangan mo ring sabihin sa iba pang mahahalagang tao <wait=20>ang lahat ng ginawa ko.","story.map11-ending.055":"Talaga, <wait=20>walang kaklase-klase ang lalaking \'yan.","story.map11-ending.056":"Tingnan mo nga ang sarili mo!","story.map11-ending.057":"So, <wait=20>Elder.<wait=40> Alam mo naman kung ano ang gusto kong itanong sa \'yo, \'di ba?","story.map11-ending.058":"Hmph. <wait=40>Tungkol sa pinagmulan mo, tama ba?","story.map11-ending.059":"Nakasulat \'yan sa huling habilin ko. Hindi ka ba makapaghintay hanggang doon para basahin?","story.map11-ending.060":"Hindi puwede.","story.map11-ending.061":"Ho ho ho. <wait=40>Biro lang. <wait=20>Hindi mo kailangang magalit nang ganyan.","story.map11-ending.062":"Pero, <wait=20>hindi naman talaga \'yon ganoon kalaking sikreto.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Natagpuan kita noong sanggol ka pa at pinalaki kita. Alam mo naman \'yon, \'di ba?","story.map11-ending.065":"Oo, <wait=20>at nagpapasalamat ako sa \'yo para doon.","story.map11-ending.066":"Pero, <wait=20>may espesyal ba sa lugar kung saan mo ako natagpuan?","story.map11-ending.067":"Hmph. <wait=20><br>Well, oo.","story.map11-ending.068":"Baka bahagya mo na ring naramdaman, <wait=20><br>pero natagpuan kita sa Grand Gaia.","story.map11-ending.069":"Teka, <wait=20>ano?!","story.map11-ending.070":"Tsch, <wait=20>ganoon pala.","story.map11-ending.071":"...","story.map11-ending.072":"Pero, <wait=20>akala ko walang taong nakaligtas sa Grand Gaia...?","story.map11-ending.073":"Kahit ako, hindi ko ito maintindihan.","story.map11-ending.074":"Pumunta lang ako rito kasama ang ibang mga Summoner, at habang sinusuri namin ang paligid,","story.map11-ending.075":"may natagpuan kaming sanggol sa mga guho ng Mistral.","story.map11-ending.076":"Kaya, <wait=40>isinama namin siya pabalik sa Elgaia.","story.map11-ending.077":"\'Yon lang ang lahat.","story.map11-ending.078":"Wala akong ideya kung anong klaseng nilalang talaga ang sanggol na \'yon.","story.map11-ending.079":"Karl.","story.map11-ending.080":"Hindi ko alam kung isa kang naulilang nakaligtas ng Grand Gaia, ","story.map11-ending.081":"o kung anak ka ng mga diyos.","story.map11-ending.082":"Gayunman--","story.map11-ending.083":"Elder. <wait=40><br>Hindi mo na kailangang magsabi ng kahit ano pa.","story.map11-ending.084":"Kasi talagang nagpapasalamat ako sa \'yo, at sa lahat ng iba pang Summoner.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Wow, may ganoon palang sikretong itinatago si Karl, ha?","story.map11-ending.088":"Hmm... <wait=40>Isang sanggol na iniwan sa Grand Gaia.","story.map11-ending.089":"Hindi pa ako nakarinig ng ganoon.","story.map11-ending.090":"May alam kaya si Lord Lucius tungkol dito.","story.map11-ending.091":"Sa tingin ko, <wait=20>pupunta ako at tatanungin ko siya!","story.map11-ending.092":"<rep_handlename>!","story.map11-ending.093":"Well, isa na lang na Nahulog na Diyos ang natitira, at \'yon ang Diyos ng mga Halimaw na si Afla Dilith!","story.map11-ending.094":"Sigurado akong matatalo natin siya kung magtutulungan tayong lahat!","story.map11-ending.095":"At siyempre, <wait=20>aasa rin kami sa kapangyarihan mo bilang Summoner, <rep_handlename>.","story.map11-ending.096":"Kung ganoon, <wait=20>itatanong ko ang tungkol kay Karl at babalikan ko kayo sa susunod!","story.map11-ending.097":"Ay, <wait=20>teka! <wait=20><br>Diyosa!","story.map11-ending.098":"Gusto ko sanang sabihin sa kanya na wala naman talaga akong pakialam...","story.map11-ending.099":"Hindi talaga siya nakikinig, \'no?","story.map11-ending.100":"Ho ho ho. <wait=40><br>Kasi mabait na bata si Tilith.","story.map11-ending.101":"So, <wait=20>ano\'ng gagawin natin sa masamang presensiyang lumitaw pagkaalis ng Diyosa?","story.map11-ending.102":"Malupit talaga ako sa masasamang presensiya.","story.map11-ending.103":"Ikaw ay...","story.map11-ending.104":"Ako si Eriole.","story.map11-ending.105":"Galing ako sa Randall Empire,","story.map11-ending.106":"kung saan ako ang pinunong opisyal ng Imperial Guard, na nagtatanggol sa maharlikang pamilya ng imperyo.","story.map11-ending.107":"Heh, <wait=20>may narinig akong mga tsismis tungkol sa pangalang \'yan.","story.map11-ending.108":"Mga tsismis na nagsasabing masama raw siyang tao na naging pinakabatang humawak ng titulong pinunong opisyal.","story.map11-ending.109":"Ang bastos mo!","story.map11-ending.110":"Oh, <wait=20>bumalik na ang babaeng masyadong natakot humarap sa Apat na Nahulog na Diyos!","story.map11-ending.111":"Ang lalaking ito ay--","story.map11-ending.112":"Paris, umatras ka muna nang kaunti.","story.map11-ending.113":"Ano? <wait=20>P-<wait=20>Pero--","story.map11-ending.114":"Paris.","story.map11-ending.115":"N-<wait=20>Naiintindihan ko...","story.map11-ending.116":"So, <wait=20>ano ba talaga ang kailangan ng pinunong opisyal ng Imperial Guard sa amin?","story.map11-ending.117":"Ikatutuwa ko rin kung maipapaliwanag mo kung sino ang nakakatakot na taong \'yan sa likod mo.","story.map11-ending.118":"...","story.map11-ending.119":"Kasamahan ko ang taong ito. <wait=40><br>Huwag n\'yo siyang alalahanin.","story.map11-ending.120":"Siguradong marami na kayong narinig mula sa nasasakupan kong si Paris.","story.map11-ending.121":"Gusto ko sanang makausap kayong lahat kahit minsan lang,","story.map11-ending.122":"pero bilang sugo ng Emperador ng Randall,","story.map11-ending.123":"pumunta ako ngayon para kausapin mismo ang Summoner na si Grahdens.","story.map11-ending.124":"Ho ho ho.","story.map11-ending.125":"Kung gusto mo lang akong kausapin, <wait=20>hindi mo na kailangang bumiyahe nang ganito kalayo, alam mo.","story.map11-ending.126":"Ha ha ha.","story.map11-ending.127":"May dahilan kami sa paggawa nito.","story.map11-ending.128":"Ipapaliwanag namin nang detalyado mamaya.","story.map11-ending.129":"Balak mo bang isama ang Elder?","story.map11-ending.130":"Sa tingin mo ba sasama siya nang tahimik?","story.map11-ending.131":"Pakiusap, huwag kayong magkamali ng akala.","story.map11-ending.132":"Hindi kami pumunta rito para makipag-away.","story.map11-ending.133":"Alam ko \'yan.","story.map11-ending.134":"Dahil kung may mangyari sa akin, magiging napakaabala niyon para sa inyo.","story.map11-ending.135":"...","story.map11-ending.136":"Kayong lahat, <wait=20>paumanhin. <wait=40><br>Kakausapin ko muna sandali ang mga taong ito.","story.map11-ending.137":"Gusto ko sanang magpasalamat sa inyong lahat nang maayos, pero mukhang kailangan na itong maghintay hanggang sa susunod.","story.map11-ending.138":"Karl.","story.map11-ending.139":"Natuwa akong makita ngayon<wait=20> kung gaano ka na lumaki.","story.map11-ending.140":"Elder Grahdens...","story.map11-ending.141":"At ikaw, <rep_handlename>.","story.map11-ending.142":"Mahusay ang ginawa mo sa pagtalo kay Zevalhua.","story.map11-ending.143":"Gayunman, <wait=20>sa susunod, si Afla Dilith na ang haharapin mo.","story.map11-ending.144":"At hindi tulad ng ibang mga Nahulog na Diyos, sigurado akong handa siyang labanan ka.","story.map11-ending.145":"Wala akong duda na magiging mahirap ang labanang iyon, pero kailangan mong subukin ang sarili mo at ang mga kaibigan mo.","story.map11-ending.146":"Isa pa, <wait=20>ipinagkakatiwala ko sa \'yo si Karl.","story.map11-ending.147":"Baka alam mo na ito, pero","story.map11-ending.148":"may mga kulang pa sa kanya rito at doon, kaya nag-aalala ako sa kanya.","story.map11-ending.149":"Hindi ko kailangan ng mag-aalaga sa akin...","story.map11-ending.150":"Ho ho ho.","story.map11-ending.151":"Kung ganoon, sugo ng Randall Empire, <wait=40><br>tayo na ba?","story.map11-ending.152":"Nagpapasalamat ako<wait=20> sa iyong konsiderasyon at pag-unawa.","story.map11-ending.153":"Paris, <wait=40>tara na.","story.map11-ending.154":"Opo!","story.map11-ending.155":"Umalis lang siya nang ganoon, ha?","story.map11-ending.156":"Dahil si Elder Grahdens \'yon, sigurado akong magiging maayos siya. Pero, gayunman...","story.map11-ending.157":"Hmph. <wait=20>hindi kayang galawin ng mga taga-Randall Empire na \'yon ang matandang Summoner.","story.map11-ending.158":"Tama ka.","story.map11-ending.159":"Si Elder Grahdens ang pinag-uusapan natin, kung tutuusin. <wait=40><br>Magiging maayos lang siya.","story.map11-ending.160":"Higit sa lahat, <wait=20>dapat tayong magtuon sa kung ano ang maitutulong natin mula sa panig natin.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"lalabanan mo si Afla Dilith, <wait=20> ang huli sa Apat na Nahulog na Diyos, <wait=20>hindi ba?","story.map11-ending.163":"Ang totoo, gusto ka sana naming tulungan ni Seria diyan, pero hindi rin namin puwedeng balewalain ang demonyong si Graham.","story.map11-ending.164":"Tama! <wait=40><br>Nakalimutan ko na siya nang tuluyan!","story.map11-ending.165":"Kung hindi natin siya matatalo...","story.map11-ending.166":"<rep_handlename>!","story.map11-ending.167":"Kailangan nating maghiwalay, <wait=20><br>pero magiging okay ka lang, \'di ba?","story.map11-ending.168":"Tatalunin namin si Graham at babalik agad, kaya ingatan mo ang sarili mo!","story.map11-ending.169":"Aba, aba... <wait=20>Mukhang may mabait ding panig ang dakilang demonyong si Seria, ha.","story.map11-ending.170":"Hang-- <wait=20>Gag-- <wait=20>Ganyan talaga ang dapat sabihin sa mga ganitong pagkakataon!","story.map11-ending.171":"Hoy, <rep_handlename>!","story.map11-ending.172":"Huwag mong subukang angkinin ang lahat ng papuri <wait=20>sa pagtalo kay Zevalhua nang mag-isa.","story.map11-ending.173":"Huwag mo ring kalimutan ang lahat ng bagay <wait=40><br>na ginawa ko.","story.map11-ending.174":"Kung ililigtas kita o hindi sa susunod, baka nakadepende \'yon sa kung gaano ka nagpapasalamat sa akin.","story.map11-ending.175":"Haha, <wait=20>si Lugina talaga.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>kailangan na naming umalis.","story.map11-ending.177":"Kung makita mo ulit ang Diyosa, pakisabi sa kanya na lubos akong nagpapasalamat sa tulong niya.","story.map11-ending.178":"At <wait=20>kung may marinig ka tungkol sa akin, at gusto mong pag-usapan natin, ikaw ang bahala.","story.map11-ending.179":"Kasi kung ikaw ang magsasabi sa akin, <wait=20>sigurado akong kakayanin ko ang anumang katotohanang darating.","story.map11-ending.180":"Kung ganoon, <wait=20>inaabangan kong makita ka ulit sa susunod.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ako si Lucius...<wait=40><br>ang diyos na namamahala sa gate na ito...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tagapagpalaya ng Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang aking kapangyarihan...<wait=40><br>at maglakbay patungo sa isang bagong lupain...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>upang dalhin ang aming salita<wait=40><br>sa mundong ito na nalugmok sa kaguluhan...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Manalig ka sa iyong sarili<wait=20><br>at patuloy na sumulong...","story.map11-open.006":"<rep_handlename>! <wait=40><br>Oras na!","story.map11-open.007":"Ito ang Mirvana, ang rehiyong ginawang base ni Zevalhua noong digmaan laban sa mga diyos.","story.map11-open.008":"Mukhang dahil doon, <wait=20>naging pinakamalaking larangan ng digmaan ang rehiyon ng Agni.","story.map11-open.009":"Ang lungkot ng tanawin dito...","story.map11-open.010":"Ay! <wait=20>Sorry, sorry!","story.map11-open.011":"Hindi ito ang oras para maging emosyonal!","story.map11-open.013":"Well, <wait=20>tara na\'t talunin si Zevalhua at iligtas si Elder Grah!","story.map11-open.014":"Alam kong maaasahan ka talaga namin, <rep_handlename>. Naniniwala ako sa \'yo!","story.map2-dungeon1.001":"<size=22>Oy?! <rep_handlename>!!","story.map2-dungeon1.002":"Grabe, <wait=20>hindi ko inakalang dito pa tayo magkikita!","story.map2-dungeon1.003":"Ah, <wait=40>papunta ka rin sa Tore ng Morgan, ano?","story.map2-dungeon1.004":"Kasama ka rin siguro ng Summoner Army na tumutugis sa Apat na Nahulog na Diyos...","story.map2-dungeon1.005":"Hindi? <wait=40>Si Tilith ang nagsabing pumunta ka?","story.map2-dungeon1.006":"Ah, <wait=20>siya siguro \'yung babaeng kinukuwento mo dati.","story.map2-dungeon1.007":"Mukhang inaalagaan ka niyang mabuti.  <wait=20>Dapat magalang akong bumati sa kanya pag nagkita kami. <wait=19>Ipakilala mo kami, ha?","story.map2-dungeon1.008":"Ha? <wait=20>Wala siya rito? <wait=40>Hinahanap mo rin siya?","story.map2-dungeon1.009":"Hmm... <wait=40>Sige, <wait=40>hindi ko na siguro kailangang mag-usisa pa.","story.map2-dungeon1.010":"Kaming mga Demon Slayers ay tumutugis sa demonyong si Graham.","story.map2-dungeon1.011":"Ilang beses na namin siyang nasukol, <wait=20>pero lagi siyang nakakatakas...","story.map2-dungeon1.012":"Tumakbo siya papunta sa disyerto, kaya papasok na kami para hanapin siya.","story.map2-dungeon1.013":"O sige, <wait=20>tara na ba?","story.map2-dungeon1.014":"Siya nga pala, <wait=40>sobrang init sa disyertong \'to, kaya mag-ingat ka nang husto.","story.map2-dungeon1.015":"At magmasid ka rin, may nakakitang hangal daw kamakailan na nagwawasiwas ng nagliliyab na espada!","story.map2-dungeon1.016":"Mag-ingat ka, <wait=20>at magkikita ulit tayo sa lalong madaling panahon!","story.map2-dungeon2.001":"Oy, <rep_handlename>!!","story.map2-dungeon2.002":"Ramdam mo ba? <wait=40>Ang sarap ng simoy ng dagat dito, \'di ba?","story.map2-dungeon2.003":"Eh? <wait=40>Bakit tayo nandito?","story.map2-dungeon2.004":"Kasi sobrang init doon kanina...","story.map2-dungeon2.005":"<size=22>Ah! <wait=40>Bawiin ko \'yon!!","story.map2-dungeon2.006":"Hindi lang tayo nandito dahil sa init...","story.map2-dungeon2.007":"May importante talaga akong gagawin dito! <wait=40>At tigilan mo na \'yang nagdududa mong tingin!","story.map2-dungeon2.008":"Sige na, aalis na \'ko! <wait=40>Hahabol ako sa\'yo pagkatapos ng lakad ko.","story.map2-dungeon2.009":"Mauna ka na, <rep_handlename>!<br><wait=40>Huwag kang tatamad-tamad, ha?","story.map2-dungeon2.010":"Siya nga pala, <wait=40>mukhang may kalabang eskrimadora sa dalampasigang \'to, at kaya raw niyang kontrolin ang malamig na hangin!","story.map2-dungeon2.011":"Maganda rin daw siya, pero alam kong mas cute ako sa kanya!","story.map2-dungeon2.012":"Talunin mo siya, <wait=20>at bilisan mo, ha!","story.map2-dungeon2.013":"Basta, <wait=20>hihintayin kita rito! <wait=40>Good luck!","story.map2-dungeon3.001":"Ikaw ba \'yan, <rep_handlename>?!<br><wait=40>Nakita mo ba si Graham?!","story.map2-dungeon3.002":"Ah, <wait=20>hindi pala... <wait=40>Sayang... <wait=40>Argh...","story.map2-dungeon3.003":"Ah, <wait=20>huwag mo akong alalahanin. <wait=40>Galos lang \'to, walang dapat ikabahala...","story.map2-dungeon3.004":"Pero ang mas malala, <wait=20>halos naubos ang mga kasama ko...","story.map2-dungeon3.005":"Si Graham... <wait=30>Nasa Gubat ng Gabi na siya ngayon.","story.map2-dungeon3.006":"Teritoryo raw ng isa sa mga kabalyero ni Graham ang gubat na \'to.","story.map2-dungeon3.007":"Kabisado ng kabalyerong \'yon ang bawat anino ng gubat, at ginagamit niya ang dilim para makalamang.","story.map2-dungeon3.008":"Isa-isa niyang pinapabagsak ang mga Summoner.","story.map2-dungeon3.009":"Kapag natalo natin ang kabalyerong \'yon, malamang mapalayas natin si Graham sa gubat.","story.map2-dungeon3.010":"Ang alam ko lang, sibat ang gamit ng kabalyerong \'yon.","story.map2-dungeon3.011":"Sa lagay ngayon ng Demon Slayers, wala na kaming magagawa kundi palibutan si Graham...","story.map2-dungeon3.012":"At hindi ako papayag na manood lang habang isa-isang pinapatumba ang mga kasama ko.","story.map2-dungeon3.013":"Kahit ako pa mag-isa, kakaladkarin ko siya palabas ng gubat na \'to!","story.map2-dungeon3.014":"O sige, tara na.<br><wait=40>Inaasahan kong ibibigay mo rin ang lahat mo!","story.map2-dungeon4.001":"Uy, <wait=20><rep_handlename>!<br><wait=40>Buti buo ka pa!","story.map2-dungeon4.002":"Well, <wait=20>hindi ko naman inisip na matatalo ka ng ganoong klase!","story.map2-dungeon4.003":"Papunta ka sa Tore ng Morgan, \'di ba?","story.map2-dungeon4.004":"Kung ganoon, kailangan mong dumaan sa Tiwangwang na Lupain ng Asekutt.","story.map2-dungeon4.005":"Malalakas ang mga halimaw na pagala-gala sa tiwangwang na lupain ng Asekutt.","story.map2-dungeon4.006":"Delikado kung mahina ang elemental affinity ng mga Unit mo laban sa mga halimaw na \'yon, kaya mag-ingat ka.","story.map2-dungeon4.007":"Hmm? <wait=40>Nag-aalala ka sa lagay namin?","story.map2-dungeon4.008":"Well, kahit paano nakaladkad ko si Graham palabas ng gubat.","story.map2-dungeon4.009":"Pero hindi tulad ng Gubat ng Gabi, bukas na parang ang Asekutt.","story.map2-dungeon4.010":"Hindi na siya makakatakbo at makakapagtago gaya ng ginawa niya sa Gubat ng Gabi.","story.map2-dungeon4.011":"Kahit kalahati na lang ang lakas ng grupo naming Demon Slayers...","story.map2-dungeon4.012":"Balak kong tapusin na ang lahat sa Asekutt.","story.map2-dungeon4.013":"Para ito sa mga kasama ko, <wait=40>para sa kanilang sakripisyo.","story.map2-dungeon4.014":"Kaya sa kasamaang palad, <wait=40>hindi kita masasamahan.","story.map2-dungeon4.015":"Pero panatag akong matatalo mo si Maxwell.","story.map2-dungeon4.016":"Paalam!","story.map2-dungeon5.001":"Uy, <rep_handlename>.<br><wait=40>Nakatakas na naman si Graham...","story.map2-dungeon5.002":"Lintik, <wait=40>muntik na namin siyang mahuli!","story.map2-dungeon5.003":"At mas marami pang kasama ang nawala sa\'kin... <wait=40>Isinusumpa ko, dudurugin ko siya pag nahawakan ko siya.","story.map2-dungeon5.004":"...<wait=20>Pero ngayon, kakaunti na lang kaming mga Demon Slayers.","story.map2-dungeon5.005":"Kaya babalik kami sa Summoners\' Hall para humingi ng dagdag na puwersa.","story.map2-dungeon5.006":"Dapat dito ko rin siya kikitain, pero...","story.map2-dungeon5.007":"Oh, <wait=20>ayan na siya!","story.map2-dungeon5.008":"Uy, Seria, <wait=40>mukhang sigla mo ngayon, ah?","story.map2-dungeon5.009":"Karl! <wait=40>Hindi ito ang oras para sa kuwentuhan!","story.map2-dungeon5.010":"Ano\'ng ginagawa ni <rep_handlename> dito?!","story.map2-dungeon5.011":"Hindi ka naman kasapi ng Demon Slayers, \'di ba?!","story.map2-dungeon5.012":"Ah, <wait=40>nagkataon lang na nagkita kami rito ni <rep_handlename>.","story.map2-dungeon5.013":"Ang susunod mong destinasyon <wait=20>ay ang Dambana ni Lystia, tama ba?","story.map2-dungeon5.014":"Kung hindi ka miyembro ng Demon Slayers, wala kang dahilan para nandito.","story.map2-dungeon5.015":"Hoy, <wait=20>Seria. <wait=40>Hindi mo kailangang magsalita nang ganyan kabigat!","story.map2-dungeon5.016":"<size=12>...<wait=40>Bakit ako ang sinisigawan??","story.map2-dungeon5.017":"Mas mahalaga, may balita ako para sa\'yo, Karl.","story.map2-dungeon5.018":"Ayon sa impormasyon mula sa Summoners\' Hall, <wait=20>mukhang isa si Graham sa mga paborito ni Abaddon.","story.map2-dungeon5.019":"Paborito siya ni Abaddon? <wait=40>Ano\'ng ibig sabihin no\'n.","story.map2-dungeon5.020":"Mukhang sikat na sikat siya, kahit sa ibang mga diyos...","story.map2-dungeon5.021":"Kaya kapag nanganib si Graham, siguradong susunod ang mas malaking gulo.","story.map2-dungeon5.022":"Baka si Abaddon mismo ang lumitaw...","story.map2-dungeon5.023":"Kung totoo \'yon, kailangan nating patayin si Graham para mapalabas si Abaddon.","story.map2-dungeon5.024":"Kaya nakatanggap kami ng utos mula sa Summoners\' Hall na sumulong sa Tore ng Morgan. ","story.map2-dungeon5.025":"Ganoon pala.","story.map2-dungeon5.026":"Kaya pala ang bilis tinanggap ng request namin para sa dagdag na puwersa.","story.map2-dungeon5.027":"Basta, hindi ba\'t oras na para tigilan ang daldalan!?","story.map2-dungeon5.028":"Dapat papunta ka na sa Tore ng Morgan, \'di ba?","story.map2-dungeon5.029":"Marami pa kaming kailangang planuhin...","story.map2-dungeon5.030":"...kaya bakit hindi ka na lang umalis nang mag-isa!","story.map2-dungeon5.031":"Eh? <wait=20>T-<wait=20>Teka, Seria! <wait=40><rep_handlename>!!","story.map2-dungeon6.001":"<rep_handlename>! <wait=40>Ayos ka lang ba?!","story.map2-dungeon6.002":"Umalis ka agad matapos kang sigawan ni Seria. <wait=20>Akala ko nagalit ka.","story.map2-dungeon6.003":"Well, <wait=20>buti naman at ayos ka lang.","story.map2-dungeon6.004":"Kakalampas lang din namin sa Dambana ni Lystia.","story.map2-dungeon6.005":"Hoy, <wait=40>bakit ka laging sumusulpot kahit saan kami pumunta?!","story.map2-dungeon6.006":"Hindi mo naman kami sinusundan, \'di ba?!","story.map2-dungeon6.007":"Puwede bang tigilan mo na \'yang walang-kuwentang pagsusungit?!","story.map2-dungeon6.008":"Bakit lagi kang naghahanap ng away.","story.map2-dungeon6.009":"H-<wait=20>Hindi ako naghahanap ng away!","story.map2-dungeon6.010":"Hindi naman siya ganoon kalakas...","story.map2-dungeon6.011":"Nakakainis talaga kung paano mo pinupuri ang ganyang klase. Talaga, tingnan mo nga siya!","story.map2-dungeon6.012":"*Buntong-hininga* <wait=40>Kung hindi \'yan paghahanap ng away, <wait=20>ewan ko na lang...","story.map2-dungeon6.013":"Ewan kung hindi mo napansin, <wait=20>pero nakarating dito si <rep_handlename> nang mag-isa.","story.map2-dungeon6.014":"Tinulungan kami ni <rep_handlename> nang talunin niya ang alagad ni Graham sa Gubat ng Gabi.","story.map2-dungeon6.015":"Siguradong hindi mahina si <rep_handlename>.","story.map2-dungeon6.016":"Hmph. <wait=40>Wala naman akong pakialam kahit ano pa.","story.map2-dungeon6.017":"Sige, magpakasasa ka sa lahat ng maling papuri nila, wala akong pakialam!","story.map2-dungeon6.018":"...<wait=40>Hindi ko talaga maintindihan ang mga babae.","story.map2-dungeon6.019":"Well, <wait=20>anyway...","story.map2-dungeon6.020":"Dadaan kami sa wasak na katedral na \'to para makarating sa Tore ng Morgan...","story.map2-dungeon6.021":"<rep_handlename>, gusto mo bang sumama?","story.map2-dungeon6.022":"<size=24>Tutol ako!","story.map2-dungeon6.023":"Heh, <wait=20>alam kong sasabihin mo \'yan.","story.map2-dungeon6.024":"Well, <wait=20>hindi tayo puwedeng sumabak sa laban nang nag-aaway-away. Huwag na nating pilitin.","story.map2-dungeon6.025":"Kami sa daan namin, ikaw sa daan mo.","story.map2-dungeon6.026":"Kita tayo sa Tore ng Morgan!","story.map2-dungeon7.001":"<rep_handlename>!! <wait=40>Ang bilis mo, <wait=20>hindi ko akalaing nandito ka na.","story.map2-dungeon7.002":"Heh, <wait=40>\'yon lang naman ang kaya niya...","story.map2-dungeon7.003":"Gaya ng dati, away agad...","story.map2-dungeon7.004":"So, <wait=20>anyway... <wait=40>Ito ang kuta ni Abaddon, <wait=20>ang Tore ng Morgan.","story.map2-dungeon7.005":"Malamang nandito sina Abaddon at Graham.","story.map2-dungeon7.006":"Ito na lang ang lugar na puwedeng takbuhan ni Graham.","story.map2-dungeon7.007":"Kami ang bahala kay Graham. <wait=40><br>At <rep_handlename>, ikaw ang humarap kay Abaddon.","story.map2-dungeon7.008":"Malayo na ang narating natin, <wait=40>durugin na natin sila!","story.map2-dungeon7.009":"Pero baka matalo namin si Abaddon bago ka pa magkaroon ng pagkakataon!","story.map2-dungeon7.010":"Ano\'ng sasabihin mo kung matalo ni <rep_handlename> si Graham bago tayo?","story.map2-dungeon7.011":"Well, <wait=40>natural lang na gusto mong ikaw mismo ang humarap sa mga kaaway ng kaibigan mo...","story.map2-dungeon7.012":"Pero sa tingin ko mas mabuting magtulungan tayo sa kanya-kanyang laban at ibigay ang lahat!","story.map2-dungeon7.013":"Uy... <wait=20>uy! <wait=40>Parang may yanig, naririnig mo ba?","story.map2-dungeon7.014":"Doon!!","story.map2-dungeon7.015":"A-<wait=20>Ano \'yon!? <wait=40>Kawan ng... <wait=20>mga halimaw?!","story.map2-dungeon7.016":"...Si Maxwell. <wait=40>Balak niya tayong pigilan dito...","story.map2-dungeon7.017":"Wala nang atrasan... <wait=40>Wala tayong choice kundi lumaban... <wait=40>Dito mismo, ngayon na...","story.map2-dungeon7.018":"...<wait=40>Teka, <wait=40>baka may iba pang paraan.","story.map2-dungeon7.019":"Kailangan lang nating umakyat sa tuktok ng Tore ng Morgan, <wait=40>at talunin si Abaddon doon.","story.map2-dungeon7.020":"Imposible \'yan!","story.map2-dungeon7.021":"Hindi natin kayang labanan ang lahat ng halimaw na \'yon at si Abaddon...","story.map2-dungeon7.022":"Huwag mo nang isipin. <wait=40>Malamang hindi pa nga tayo makakalapit para masilip man lang si Abaddon.","story.map2-dungeon7.023":"Tama ka. <wait=40>Pero <wait=20>hindi na makakausad pa ang mga halimaw na \'to.","story.map2-dungeon7.024":"Dito ko sila pipigilan!","story.map2-dungeon7.025":"Karl!? <wait=40>Ano\'ng sinasabi mo!?","story.map2-dungeon7.026":"Balak mo ba talagang pigilan sila rito habang hinaharap namin si Abaddon?!","story.map2-dungeon7.027":"Tama. <wait=40>Ito na lang ang paraan...","story.map2-dungeon7.028":"Pero tingnan mo sila. <wait=40>Walang makakakaya sa kanilang lahat nang mag-isa!","story.map2-dungeon7.029":"Oo... <wait=40>Alam ko \'yon.","story.map2-dungeon7.030":"Pero kung dito na talaga matatapos ang lahat, itataya ko na sa kung ano ang may pinakamalaking tsansang tumalo kay Abaddon.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>sumama ka na kay Seria.","story.map2-dungeon7.033":"Pipigilan ko ang mga halimaw na \'to. <wait=40>Kailangan mong puksain si Abaddon.","story.map2-dungeon7.034":"...<wait=40>Hindi ako aalis.","story.map2-dungeon7.035":"Seria!!","story.map2-dungeon7.036":"Ang kawang \'to, <wait=20>sobra \'to para kayanin mo nang mag-isa, Karl.","story.map2-dungeon7.037":"Kung tutulungan kitang pigilan sila <wait=20>nang kaunti pang oras...","story.map2-dungeon7.038":"Baka \'yon na ang dagdag na oras na kailangan natin <wait=20>para talunin si Abaddon.","story.map2-dungeon7.039":"Seria, <wait=40>ikaw...","story.map2-dungeon7.040":"<rep_handlename>!","story.map2-dungeon7.041":"Ikaw, <wait=40>kinilala na ng mga Sinaunang Summoner ang lakas mo bilang Summoner, \'di ba?","story.map2-dungeon7.042":"Kung gano\'n, patunayan mo sa\'kin.","story.map2-dungeon7.043":"Bubugbugin kita kapag hindi mo natalo si Abaddon!!","story.map2-dungeon7.044":"...<wait=40>O sige, <wait=20>gawin na natin \'to!!","story.map2-dungeon7.045":"Tsk... <wait=20>Ang babaeng \'yon...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>ibibigay namin ang lahat para mapigilan sila.","story.map2-dungeon7.047":"Kailangan mong talunin si Abaddon.","story.map2-dungeon7.048":"Umaasa kami sa\'yo, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"Ngayon, <wait=40>sa laban!!","story.map2-ending.001":"<size=20><rep_handlename>! Ayos ka lang ba?!</size>","story.map2-ending.002":"Oh, <wait=20>natalo mo ba... <wait=40>si Abaddon?","story.map2-ending.003":"Wow... <wait=40>Ang lakas mo talaga.","story.map2-ending.004":"Hindi ako makapaniwalang natalo mo si Abaddon nang mag-isa...","story.map2-ending.005":"Ako? <wait=20>Ayos lang ako.","story.map2-ending.006":"Pagkatapos nating maghiwalay, <wait=20>ibinuhos ko ang lahat sa pagbabantay sa pasukan ng tore.","story.map2-ending.007":"Itinulak namin ni Seria ang sarili namin hanggang sa sukdulan, muntik na kaming bumigay...","story.map2-ending.008":"Pero buti na lang, dumating sa tamang oras ang dagdag na puwersa mula sa Summoners\' Hall.","story.map2-ending.009":"Ibinigay nila ang lahat para tulungan kami...","story.map2-ending.010":"Hmm? <wait=20>Si Seria? <wait=40>Nandoon siya... <wait=40>Ha? <wait=20>Seria?","story.map2-ending.011":"Saan siya nagpunta? <wait=40>...<wait=40>Hmm, <wait=20>bahala na.","story.map2-ending.012":"Siya nga pala, <wait=20>nag-alala siya nang husto sa\'yo.","story.map2-ending.013":"Gutay-gutay at pagod na pagod na siya, pero ipinilit niyang tulungan ka at dumiretso paakyat ng tore...","story.map2-ending.014":"Hehe, <wait=20>ewan ko kung ano\'ng gagawin niya pag nalaman niyang sinabi ko sa\'yo lahat \'yan...","story.map2-ending.015":"Kaya huwag mong sasabihin sa kanya na sinabi ko, ha?","story.map2-ending.016":"Pero seryoso, <wait=40>lumakas ka na talaga.","story.map2-ending.017":"Nagmadali kaming tulungan ka, <wait=40>pero mukhang hindi mo na kailangan ng tulong.","story.map2-ending.018":"Para sa\'kin, isa ka nang top class na Summoner.","story.map2-ending.019":"Ah, <wait=20>oo nga pala...","story.map2-ending.020":"Hindi rin namin napabagsak si Graham sa huli.","story.map2-ending.021":"Pero nakahuli kami ng ilang halimaw at napaamin namin kung saan nagtatago si Graham.","story.map2-ending.022":"Pero tumakas siya sa lugar na hindi namin maabot... <wait=20>Pesteng halimaw talaga... ","story.map2-ending.023":"Hindi magiging madali ang paghahanap sa kanya.","story.map2-ending.024":"Kailangan kong mag-ulat sa Akras Summoners\' Hall...","story.map2-ending.025":"Ikaw... <wait=40>Well, <wait=40>may sarili ka rin sigurong lakad.","story.map2-ending.026":"...<wait=20>Mabuti pang umalis na ako.","story.map2-ending.027":"Magkaiba man ang layunin natin, <wait=40>pero lagi akong nasa panig mo.","story.map2-ending.028":"Siguraduhin mong mananatili kang buhay! <wait=40>Paalam!","story.map2-ending.029":"Uy! <wait=40><rep_handlename>!!","story.map2-ending.030":"Sa wakas, naabutan din kita!","story.map2-ending.031":"Ang galing mo talaga!!","story.map2-ending.032":"Habang nasa Dalampasigan ng Simoy ako, nakikipagpaligsahan kay Ice Queen Selena kung sino ang mas cute...","story.map2-ending.033":"...mukhang natalo mo na si Abaddon! Hindi kapani-paniwala!","story.map2-ending.034":"...Ha?!","story.map2-ending.035":"H-<wait=20>Huwag mo akong mamasamain! <wait=40>Hindi naman kami nag-beauty contest o kung ano pa man...","story.map2-ending.036":"Ibig kong sabihin, hindi man lang sumipot si Selena!","story.map2-ending.037":"Saka <rep_handlename>, wala ka naman doon kaya walang huhusga sa paligsahan, \'di ba?!","story.map2-ending.038":"...<wait=40>Ano \'yang mukha mong \'yan!","story.map2-ending.039":"May importante talaga akong lakad sa Dalampasigan ng Simoy!","story.map2-ending.040":"Ah! <wait=20>Naririnig mo ba \'yon?<br><wait=40>Parang tinatawag ka ni Lord Lucius?","story.map2-ending.041":"<speed=12>Mag-<wait=10>ingat <wait=20>ka<wait=30>...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ako si Lucius...<br><wait=40>Diyos ng Pintuan...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Tagapagligtas ng Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang aking kapangyarihan <wait=40>at maglakbay sa mga bagong lupain...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Humayo ka <wait=20>at gamitin ang iyong lakas upang magdala ng kapayapaan sa mundong ito...","story.map2-ending.046":"Oh, <wait=20>gising ka na.","story.map2-ending.047":"Magandang umaga, <wait=20> <rep_handlename>.","story.map2-ending.048":"Tingnan mo... <wait=40>Sa wakas, nakarating na tayo sa St. Lamia.","story.map2-ending.049":"Ito... <wait=40>ang teritoryo ni Maxwell.","story.map2-ending.050":"...<wait=40><rep_handlename>, ramdam mo rin ba?","story.map2-ending.051":"Ramdam ko ang alon ng isang makapangyarihang lakas...","story.map2-ending.052":"Mas malakas na rin ang mga halimaw kaysa dati. <wait=40>Kailangan nating mag-focus...","story.map2-ending.053":"Nasa Palasyo ng St. Lamia si Maxwell.","story.map2-ending.054":"Mabibigat na laban ang naghihintay sa\'tin, <wait=40>magsikap tayo nang magkasama!","story.map2-ending.055":"Ano? <wait=40>Nasaan daw ako habang lumalaban ka sa Morgan?","story.map2-ending.056":"Huwag ka ngang maliit mag-isip...","story.map2-ending.057":"Pangako, gagalingan ko sa St. Lamia, <wait=40>OK?","story.map2-ending.058":"Sige, <wait=20>tara na!!","story.map3-dungeon1.001":"<size=13>Ang init-init dito! <wait=40>Gusto ko nang umuwi... <wait=40>Hindi na kaya ng kawawa kong balat...","story.map3-dungeon1.002":"<size=20>Uy! <wait=20><rep_handlename>!","story.map3-dungeon1.003":"Ikaw! <wait=20>Late ka na naman!!","story.map3-dungeon1.004":"Huwag mong sabihing nagpapalamig ka lang sa kung saan!?","story.map3-dungeon1.005":"Hindi ito ang oras para maglaro! <wait=40>Ano\'ng masasabi mo para sa sarili mo?","story.map3-dungeon1.006":"Ha? <wait=20>Paano naman ako?","story.map3-dungeon1.007":"<size=15>Hindi <size=14>naman <size=13>ako <size=12>nagpapalamig <size=11>lang <size=10>kung <size=9>saan-<size=8>saan<size=7>...<size=6>","story.map3-dungeon1.008":"Basta, <wait=40>simula ngayon, aakyatin natin ang Bulkang Eldent.","story.map3-dungeon1.009":"Aktibong bulkan ang Bulkang Eldent, kaya sobrang delikado.","story.map3-dungeon1.010":"Mag-ingat ka sa agos ng lava!","story.map3-dungeon1.011":"O sige, <wait=20>bon voyage!","story.map3-dungeon1.012":"Ano? <wait=40>Gusto mo ng mas praktikal na payo?","story.map3-dungeon1.013":"Sobrang init... Hindi ko na kaya!","story.map3-dungeon1.014":"<size=20>Ah! <wait=40>Suko na ako!","story.map3-dungeon1.015":"Uuwi muna ako para maligo,<wait=20> huwag kang mamamatay bago ako bumalik!","story.map3-dungeon2.001":"<size=12>Brr...","story.map3-dungeon2.002":"Oy, <wait=20><rep_handlename>! <wait=40>Hay naku, <wait=20>bakit ang tagal mo!","story.map3-dungeon2.003":"Eh? <wait=40>Ano\'ng problema sa\'kin?","story.map3-dungeon2.004":"Walang problema. <wait=40>Ako pa rin ang masiglang Tilith gaya ng dati!","story.map3-dungeon2.005":"Oo na, <wait=20>aaminin ko, medyo lumalamig na nga dito.","story.map3-dungeon2.006":"Pero \'yon ay dahil pinaghintay mo ako nang matagal, <rep_handlename>!","story.map3-dungeon2.007":"Bukod do\'n, <wait=20>dapat siguro ikuwento ko pa sa\'yo ang tungkol sa Banal na Bundok Craylia.","story.map3-dungeon2.008":"Ang banal na bundok na \'to, ang Bundok Craylia, ang pinakamataas na bundok sa St. Lamia.","story.map3-dungeon2.009":"May pinagmumulan daw ng espirituwal na kapangyarihan sa tuktok nito, na mukhang sanhi ng walang-tigil na snowstorm na \'to.","story.map3-dungeon2.010":"Bukod pa do\'n, <wait=40>doon din daw nakatira ang Hari ng Dagat na si Leviathan.","story.map3-dungeon2.011":"Bakit kaya niya iniwan ang dagat para tumira sa tuktok ng bundok...","story.map3-dungeon2.012":"Hmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Uh... <wait=20>Brr...","story.map3-dungeon2.014":"Ano? <wait=40>Hindi, talaga, <wait=20>ayos na ayos lang ako!","story.map3-dungeon2.015":"Pero mukhang sa tagal kong nakatayo sa napakalamig na lugar na \'to, nagkasipon ako...","story.map3-dungeon2.016":"Mauna na siguro ako. <wait=40>Good luck sa pag-akyat sa bundok ng niyebe!","story.map3-dungeon3.001":"*Buntong-hininga* <wait=20>Hmph... <wait=40>Kaunti na lang...","story.map3-dungeon3.002":"Oy, <wait=20><rep_handlename>! <wait=40>Kanina pa kita hinihintay.","story.map3-dungeon3.003":"Para makarating kay Maxwell, kailangan nating dumaan dito, <wait=40>sa Gubat ng Dugo.","story.map3-dungeon3.004":"Gubat ng Dugo, nakakakilabot na pangalan...","story.map3-dungeon3.005":"Usap-usapan na ang mga sumusubok tumawid sa gubat na \'to ay natatagpuang balot ng dugo...","story.map3-dungeon3.006":"<size=20><size=18>Sobrang <size=20>sobra, <size=16>sobra, <size=19><size=17>sobra, <size=18>talagang, <size=15>talagang <size=17>nakakakilabot<size=19>!","story.map3-dungeon3.007":"Ano? <wait=40>Sa tingin mo kakaiba ang kilos ko?","story.map3-dungeon3.008":"Hindi ako kakaiba kumilos! <wait=40>Kasing-elegante pa rin ako ng dati, \'di ba?","story.map3-dungeon3.009":"Nag-aalala ka... <wait=20>sa\'kin?","story.map3-dungeon3.010":"Ganoon ba, <wait=20>pero kung may oras ka pang magsabi ng mga kalokohan, bakit hindi ka na lang kumilos at harapin ang gubat na \'to!","story.map3-dungeon3.011":"Good luck!!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Ubo* <wait=20>*Ubo*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Oh, <wait=40><rep_handlename>... <wait=40>Nandito ka na...","story.map3-dungeon4.003":"Hindi ko na... <wait=40>kayang <wait=40>itago sa\'yo...","story.map3-dungeon4.004":"Ang kalagayan ko, <wait=20>hindi ito sakit. <wait=40>Wala akong sakit.","story.map3-dungeon4.005":"Si Maxwell... <wait=40>Sinumpa niya ako.","story.map3-dungeon4.006":"Mula noong... <wait=20>tumapak tayo sa St. Lamia.","story.map3-dungeon4.007":"Ngayong papalapit na tayo sa Palasyo ng St. Lamia, <wait=40>lalo itong lumalala...","story.map3-dungeon4.008":"Siguro <wait=40>nakita ako ni Maxwell bilang isang istorbo...","story.map3-dungeon4.009":"Hmm? <wait=40>Hindi ka tinatablan kasi...","story.map3-dungeon4.010":"Ako... <wait=40>ang nagpoprotekta sa\'yo mula rito.","story.map3-dungeon4.011":"...<wait=40>Okay lang. <wait=40>Hindi ko alintana.","story.map3-dungeon4.012":"Salamat sa pag-aalala... <wait=40>pero magiging okay ako.","story.map3-dungeon4.013":"Isa akong diyosa, <wait=40>ang gabay mo...","story.map3-dungeon4.014":"Siguradong <wait=40>poprotektahan kita...","story.map3-dungeon4.015":"Malapit na... <wait=40>matatalo natin si Maxwell.","story.map3-dungeon4.016":"<wait=20>Gawin natin \'to, <rep_handlename>!!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Ubo* <wait=20>*Hingal*... <wait=40>*Hingal*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Patawad... <wait=40>Ako...","story.map3-dungeon5.003":"<speed=12>Hindi na ako... <wait=40>makakapagpatuloy<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>ako...","story.map3-dungeon5.005":"<speed=12>Hindi ko \'to ginagawa dahil inutusan ako ni Lord Lucius...","story.map3-dungeon5.006":"<speed=12>Ginagawa ko \'to dahil ikaw si <rep_handlename>... <wait=40>G-<wait=20>Gusto lang kitang protektahan.","story.map3-dungeon5.007":"<speed=12>Ako ang humiling kay Lord Lucius na payagan ako... <wait=40>*Ubo* <wait=20>*Ubo*","story.map3-dungeon5.008":"<speed=12>Marami pang ibang lugar <wait=40>na gusto kong puntahan kasama ka...","story.map3-dungeon5.009":"<speed=12>Gusto ko pa <wait=40>sanang maglakbay...","story.map3-dungeon5.010":"<speed=12>Pero... <wait=40>mukhang nauubusan na ako ng oras...","story.map3-dungeon5.011":"<speed=12>Kahit bumagsak ako... <wait=40>patuloy kang poprotektahan ng mahika ko.","story.map3-dungeon5.012":"<speed=12>Mangako ka<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...na <wait=40>siguradong <wait=40>matatalo <wait=12>mo <wait=10>si Max<wait=7>well<wait=5>...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(Nahimatay)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"Uy! <wait=40>Ikaw ba talaga \'yan, <rep_handlename>!?","story.map3-dungeon5.018":"Matibay ka siguro, <wait=40>nakarating ka rito nang mag-isa...","story.map3-dungeon5.019":"So, kumusta ang laban kay Abaddon??<wait=40>","story.map3-dungeon5.020":"<size=18>Teka, <wait=20>ano\'ng nangyari sa babaeng \'yan?! <wait=40>Nangangasul na siya!!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>Huwag mong sabihing<wait=20>...","story.map3-dungeon5.022":"Huwag mong sabihing hindi ka pa rin marunong gumawa ng antidote?!","story.map3-dungeon5.023":"Oo na, oo na. <wait=40>Biro lang.","story.map3-dungeon5.024":"...Sumpa? <wait=40>Ano\'ng ibig mong sabihin?","story.map3-dungeon5.025":"Ano ba, ano\'ng sinasabi mo!?","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60>!","story.map3-dungeon5.027":"Teka... <wait=40>sinasabi mo bang, <wait=20>diyosa ang babaeng \'to?","story.map3-dungeon5.028":"Hindi mo...<wait=40> ako niloloko, <wait=20>\'di ba, <wait=40>ha?","story.map3-dungeon5.029":"At?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Kung gano\'n... <wait=40>si Maxwell pala, ha...","story.map3-dungeon5.032":"Gusto ko sanang tumulong, <wait=40>pero hindi ko na \'to kaya...","story.map3-dungeon5.033":"Hindi ito magagamot ng paggawa lang ng mga potion...","story.map3-dungeon5.034":"Pero teka, <wait=40>si Maxwell ang nagbigay ng sumpang \'to, tama?","story.map3-dungeon5.035":"Kung gano\'n, mawawala ang sumpa kapag natalo si Maxwell, \'di ba?","story.map3-dungeon5.036":"Kung hindi pa rin mawala kahit matalo si Maxwell, bugbugin mo lang siya hanggang ilabas niya ang lunas!","story.map3-dungeon5.037":"\'Yan lang ang ibang paraang naiisip ko ngayon.","story.map3-dungeon5.038":"...<wait=20>Sige. <wait=40>Ako na ang bahala sa kanya.","story.map3-dungeon5.039":"May kampo ang grupo ko malapit dito, dadalhin ko siya do\'n.","story.map3-dungeon5.040":"Bilisan mo.","story.map3-dungeon5.041":"<size=22>Huwag ka lang tumunganga riyan!!","story.map3-dungeon5.042":"Naghihirap siya dahil sa\'yo!","story.map3-dungeon5.043":"Hindi ito ang oras para magpalaboy-laboy, dapat sumusugod ka na sa Palasyo ng St. Lamia!","story.map3-dungeon5.044":"<size=14>...<wait=20>Ang tanga talaga.","story.map3-dungeon7.001":"<size=20><rep_handlename>! <wait=40>Buti buhay ka pa!!","story.map3-dungeon7.002":"Bakit ako nandito? <wait=40>Aba, nandito ako para tulungan ka!","story.map3-dungeon7.003":"<size=20>Lintik!","story.map3-dungeon7.004":"<size=24>*Slash*","story.map3-dungeon7.005":"<size=24>*Slash*","story.map3-dungeon7.006":"...Hay naku, <wait=40>ang dami nila, ano?","story.map3-dungeon7.007":"Narinig ko na ang lahat mula kay Seria.","story.map3-dungeon7.008":"Ako na ang bahala rito.","story.map3-dungeon7.009":"Nauubusan ka na ng oras, \'di ba? <wait=40>Bilisan mo na!","story.map3-dungeon7.010":"<size=20>Ugh!","story.map3-dungeon7.011":"<size=24>*Slash*","story.map3-dungeon7.012":"<size=20>Umalis ka na rito!!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>umaasa kami sa\'yo...","story.map3-ending.001":"<size=20><rep_handlename>!!","story.map3-ending.002":"*Hingal*... <wait=40>hmph...","story.map3-ending.003":"Grabe, <wait=40>nagtagumpay ang Summoner...","story.map3-ending.004":"Natalo na si Maxwell, isa sa Apat na Nahulog na Diyos!!","story.map3-ending.005":"Hay... <wait=40>Pero muntik na talaga...","story.map3-ending.006":"<size=20><rep_handlename>, magaling!!","story.map3-ending.007":"Mukhang naalis nga ang sumpa nang matalo si Maxwell.","story.map3-ending.008":"Tama ka, <wait=40>buti na lang at nakaligtas ang batang diyosang \'to...","story.map3-ending.009":"Siya nga pala, <wait=20>paano ka nakarating dito nang mas maaga sa\'kin?!","story.map3-ending.010":"...<wait=20>Diyosa nga talaga siguro siya. <wait=40>Siguro bumalik ang kapangyarihan niya nang maalis ang sumpa.","story.map3-ending.011":"Hindi ako makapaniwalang may tulong pala ng diyosa si <rep_handlename> mula pa noong una<wait=40>...","story.map3-ending.012":"At Seria, nagulat din ako sa\'yo. Talagang ibinigay mo ang lahat para sa dalawang \'yon, \'no?","story.map3-ending.013":"H-<wait=30>Hindi ko \'yon ginawa para ipagtanggol si <rep_handlename>.","story.map3-ending.014":"Ginawa ko \'yon para sa diyosa, at para sa mundo.","story.map3-ending.015":"Oo na, oo na... <wait=40>Tama na.","story.map3-ending.016":"<size=18>Natalo mo si Maxwell! \'Yan ang <rep_handlename> ko!!","story.map3-ending.017":"...<wait=40>Well, <wait=20>sige na nga.","story.map3-ending.018":"Anyway, <wait=40>para sa isang baguhan na gumaling nang ganoon kabilis...","story.map3-ending.019":"Well, <wait=40>kahanga-hanga talaga.","story.map3-ending.020":"<rep_handlename>! <wait=40>Kikilalanin kitang isang ganap na...","story.map3-ending.021":"Nagawa ni <rep_handlename>!! <wait=40>Nanalo si <rep_handlename>!!","story.map3-ending.022":"Si Abaddon, at pati si Maxwell, natalo na silang lahat!!","story.map3-ending.023":"Medyo nag-alala ako noong una tayong nagkita...","story.map3-ending.024":"...pero ngayon, <wait=20>walang duda, ikaw na ang pinakamalakas na Summoner!!","story.map3-ending.025":"<size=18>T-<wait=20>Teka nga! <wait=40>Ang ingay mo na, bakit hindi ka muna kumalma!","story.map3-ending.026":"Hindi mo ako masisisi. <wait=40>Natalo ng Summoner ko ang isa sa Apat na Nahulog na Diyos!","story.map3-ending.027":"Ngayon lang ako naging ganito kasaya!","story.map3-ending.028":"Tumahimik ka nga! <wait=40>Huwag kang sumasabat kapag may nagsasalita!!","story.map3-ending.029":"At ano \'yang pa-sweet na <wait=40>\\"<rep_handlename> ko\\" na \'yan!?","story.map3-ending.030":"Hindi naman kayo magjowa, \'di ba?!","story.map3-ending.031":"Ang <rep_handlename> ko ay <rep_handlename> ko!","story.map3-ending.032":"Itinaya ko ang buhay ko para mabuhay si <rep_handlename>.","story.map3-ending.033":"Bukod pa do\'n, <wait=20>nagsikap nang husto si <rep_handlename> para iligtas ako...","story.map3-ending.034":"Kami ni <rep_handlename> ay itinadhana!","story.map3-ending.035":"So ano\'ng problema? <wait=40>Nagseselos ka ba?","story.map3-ending.036":"<size=20>S-Si-Sino\'ng magseselos sa isang bubuwit!?","story.map3-ending.037":"<size=18>At ano\'ng tadhana ang sinasabi mo? <wait=40><size=24>Tanga ka ba!?","story.map3-ending.038":"...Uy, <wait=20>kumalma kayong dalawa...","story.map3-ending.039":"Tanga lang ang sasalo ng sumpa para sa isang tulad ni <rep_handlename>. <wait=20>Ang tanga!","story.map3-ending.040":"Ayos lang naman sana si <rep_handlename> kahit pinabayaan mo na lang siya!!","story.map3-ending.041":"Saka, <wait=20>hindi ba\'t diyosa ka raw?!","story.map3-ending.042":"Hindi mo ba kayang basagin ang sumpa nang mag-isa?!","story.map3-ending.043":"Ano\'ng ibig mong sabihin!? <wait=40>Sinasabi mo bang hindi ko ginawa ang lahat!?","story.map3-ending.044":"Nag-aagaw-buhay ka na sa Liblib na Santuwaryo!","story.map3-ending.045":"Kung wala ako roon, nilamon ka na sana ng mga Halimaw na \'yon!!","story.map3-ending.046":"Kalokohan! <wait=40>Poprotektahan ako ni <rep_handlename> kahit wala ka!","story.map3-ending.047":"Puro ka salita, wala ka rin namang nagawa!","story.map3-ending.048":"T-<wait=10>Teka lang!! <wait=40>Sino sa tingin mo ang nag-alaga sa\'yo!","story.map3-ending.049":"Wala akong malay, wala akong maalala...","story.map3-ending.050":"Aba\'t ikaw!!","story.map3-ending.051":"Hoy kayong dalawa... <wait=40>Tigilan n\'yo na \'yan.","story.map3-ending.052":"<size=24>Tumahimik ka!!","story.map3-ending.053":"Whoa...","story.map3-ending.054":"Sa simula pa lang, bakit laging nagmamarunong si Seria kay <rep_handlename>!?","story.map3-ending.055":"Ni hindi nga niya natalo si Graham, lalo na si Abaddon!","story.map3-ending.056":"<size=12>Aray... <wait=40>Kasali rin ako sa labang \'yon, alam n\'yo...","story.map3-ending.057":"Tigilan mo ang pang-iinsulto sa <rep_handlename> ko!!","story.map3-ending.058":"S-<wait=20>Sasabihin ko kung ano\'ng gusto ko! <wait=40>Naghahanap ka ba ng away!?","story.map3-ending.059":"Ikaw ang nagsimula!","story.map3-ending.060":"At alam mo, malakas ako kapag wala akong sumpa!","story.map3-ending.061":"<size=24>Diyos ko naman! <wait=40>Tama na \'yan!!","story.map3-ending.062":"Natalo ni <rep_handlename> si Maxwell!","story.map3-ending.063":"Hindi ito ang oras para magtalo.","story.map3-ending.064":"...Hmph.","story.map3-ending.065":"Hmph.","story.map3-ending.066":"Kayong mga babae, <wait=20>mas malala pa kayo kay Maxwell mismo...","story.map3-ending.067":"Pero anyway, <wait=20>saludo talaga ako sa\'yo, <wait=20><rep_handlename>.","story.map3-ending.068":"Proud akong maging kaibigan mo.","story.map3-ending.069":"...<wait=40>Ayoko mang sabihin, <wait=40>pero hindi ko maikakailang natalo mo nga si Maxwell.","story.map3-ending.070":"<wait=40>Magaling ang ginawa mo.","story.map3-ending.071":"Hay.","story.map3-ending.072":"Sige, <wait=20>kailangan na naming umalis ni Seria.","story.map3-ending.073":"...Ha? <wait=40>Hindi mo na kailangang magpasalamat.","story.map3-ending.074":"Mangako ka lang na tutulong ka sa susunod na kailanganin namin!","story.map3-ending.075":"Kita tayo ulit, kaibigan.","story.map3-ending.076":"Hmph, <wait=20>paalam.","story.map3-ending.077":"...Well, <wait=40>uulitin ko.","story.map3-ending.078":"Congratulations! <wait=40><rep_handlename>.","story.map3-ending.079":"May tiwala akong siguradong matatalo mo si Maxwell.","story.map3-ending.080":"Pero imbes na ako ang tumulong sa\'yo... <wait=40>ikaw pa ang tumulong sa\'kin.","story.map3-ending.081":"Ang saya ko talaga. <wait=40>Salamat.","story.map3-ending.082":"Hehe. <wait=40>Hay naku, nakakahiya.","story.map3-ending.083":"Ah, <wait=20>oo nga. Nangako tayong pupuntahan natin ang maraming lugar nang magkasama, \'di ba?","story.map3-ending.084":"Akala ko mamamatay na ako, <wait=40>kaya hiningi ko sa\'yo ang pangakong \'yon.","story.map3-ending.085":"Pero ngayong natalo mo si Maxwell, malamang lalo pang magiging abala ang lahat.","story.map3-ending.086":"Kahit natalo na si Maxwell, <wait=40>apat ang Nahulog na Diyos sa kabuuan.","story.map3-ending.087":"Tatlo pa sa kanila ang nasa labas.","story.map3-ending.088":"Hangga\'t hindi mo natatalo ang lahat ng Nahulog na Diyos, <wait=40>hindi magkakaroon ng kapayapaan sa Grand Gaia.","story.map3-ending.089":"Kaya naman, <wait=40>kailangan muna nating ipagpaliban ang paglalakbay na ipinangako natin sa isa\'t isa.","story.map3-ending.090":"Sorry talaga, <wait=40>pero sobrang busy ng mga diyosa, alam mo \'yon.","story.map3-ending.091":"Well, <wait=40>oras na para mag-ulat ako kay Lord Lucius.","story.map3-ending.092":"Patuloy mong hasain ang galing mo, <wait=20>kailangan mo pang lumakas kung balak mong talunin ang iba pang Nahulog na Diyos.","story.map3-ending.093":"Ah, <wait=40>at isa pa...","story.map3-ending.094":"Kung magkita kayo ulit ng dalawang \'yon, sabihin mong nagpapasalamat ako.","story.map3-ending.095":"Sabihin mong talagang nagpapasalamat ako sa lahat ng ginawa nila para sa\'tin.","story.map3-ending.096":"O sige, <wait=20>aalis na ako!","story.map3-ending.097":"Magkikita ulit tayo, <wait=20>sigurado ako!","story.map3-ending.098":"Bye!!!","story.map4-dungeon1.001":"Pfft... Wala pa akong nakakasalubong<br>ni isang halimaw mula nang dumating ako rito!","story.map4-dungeon1.002":"Hindi ako makapaniwala... <wait=40> Bakit ako, ang makapangyarihang Lugina, ang naiipit sa ganitong walang kuwentang trabaho...","story.map4-dungeon1.003":"Hm?<wait=40><br>Hoy, ikaw diyan! <wait=20>Magpakilala ka!","story.map4-dungeon1.004":"Aha! <wait=20>Miyembro ka pala ng Akras Army, ha?<br>Ano\'ng pangalan mo?","story.map4-dungeon1.005":"<rep_handlename>?<wait=40><br>Pfft... <wait=40>Ang weird ng pangalan mo, kung ako ang tatanungin.","story.map4-dungeon1.006":"Ano \'yon?<wait=40><br>Gusto mong malaman ang pangalan ko?","story.map4-dungeon1.007":"Hindi naman ako obligadong magpakilala<br>sa isang miyembro ng regular army, pero...","story.map4-dungeon1.008":"<wait=20>...Sige na nga, kung gusto mo talagang malaman, wala namang masama kung sasabihin ko.","story.map4-dungeon1.009":"Ako ang makapangyarihang Summoner na si Lugina,<wait=40><br>kagalang-galang na pinuno ng ika-23 Dibisyon ng Demon Slayers,<wait=40>","story.map4-dungeon1.010":"na kilala rin bilang Sky Garden!<br>Tandaan mo \'yan!","story.map4-dungeon1.011":"So,<wait=40> may hinahanap ka ba rito o ano?","story.map4-dungeon1.012":"Ha?<wait=40> Nasa misyon ka para talunin ang Apat na Nahulog na Diyos?","story.map4-dungeon1.013":"Pft... Hehe... <size=24>Bwahaha!","story.map4-dungeon1.014":"Mukhang nababaliw na talaga<br>ang mga matatanda sa Akras!","story.map4-dungeon1.015":"Hindi mo naman talaga iniisip na may laban ang regular army<br>sa Apat na Nahulog na Diyos, \'di ba?","story.map4-dungeon1.016":"Panahon na para magretiro ang mga gurang na \'yon<br>at iwan ang pagpatay ng demonyo sa mga propesyonal na tulad ko.","story.map4-dungeon1.017":"Hmm? <wait=40>Sa isang diyosa ka kumukuha ng utos, kamo?<br>Hindi sa Summoners\' Hall?","story.map4-dungeon1.018":"...Biro ba \'to?<wait=40><br>O talagang ganyan ka lang katanga?","story.map4-dungeon1.019":"Alam mo ba kung ano\'ng ginagawa ko<br>dito sa napakalayong lugar na \'to?","story.map4-dungeon1.020":"Hindi kapani-paniwala... <wait=40>Kita mo, kaya lagi kong sinasabi","story.map4-dungeon1.021":"na hindi mapagkakatiwalaan ang miyembro ng regular army.","story.map4-dungeon1.022":"Alam mo bang bagong tuklas lang ng Akras Summoners\' Hall<br>ang teritoryong kinatatayuan natin?","story.map4-dungeon1.023":"Hindi pa ito naiimbestigahan nang maayos,<br>kaya mag-ingat ka sa bawat hakbang mo.","story.map4-dungeon1.024":"Alam mo na, mga halimaw at kung anu-ano pa.","story.map4-dungeon1.025":"Anyway, nasa mga makapangyarihan at<br>malalakas na Summoner na tulad ko ang tungkulin","story.map4-dungeon1.026":"na siguraduhing ligtas na ang mga<br>delikadong lugar na tulad nito para sa","story.map4-dungeon1.027":"mga baguhang Summoner<br>na tulad mo na tumapak dito.","story.map4-dungeon1.028":"Kung may utak ka,<br>maghanap ka muna ng mas ligtas na lugar hangga\'t hindi pa ako tapos dito!","story.map4-dungeon1.029":"Napakaraming lugar sa Grand Gaia<br>ang hindi pa naiimbestigahan nang maayos.","story.map4-dungeon1.030":"Ano? Nauutal ba ako?<wait=40><br>Grabe, kasing-tanga mo ang itsura mo.","story.map4-dungeon1.031":"Heto, lilinawin ko pa...<br><wait=40>Umalis ka sa daan ko at hayaan mo akong magtrabaho nang tahimik!<wait=40>","story.map4-dungeon1.032":"Tigilan mo na ang pag-aaksaya ng oras sa mga mahihinang kalabang \'to at maghanap ka sa ibang lugar!","story.map4-dungeon1.033":"Tsk... Sa dami ng tangang tulad mo sa regular army, hindi nakapagtatakang nagkakaproblema ang Summoners\' Hall...","story.map4-dungeon2.001":"Ikaw na naman?!<wait=40><br>Sabi ko umalis ka na rito!","story.map4-dungeon2.002":"Ang kapal ng mukha mo<br>para balewalain ako nang ganyan!","story.map4-dungeon2.003":"O kailangan mo ng hahawak sa<br>kamay mo para ihatid ka pauwi?","story.map4-dungeon2.004":"Grabe... <wait=40>Kahit ang mga miyembro ng Imperial Army ay hindi ganito kawalang-silbi.","story.map4-dungeon2.005":"Ha?<wait=40><br>Ano\'ng ibig sabihin ng walang-kamuwang-muwang mong mukha?","story.map4-dungeon2.006":"Teka lang... <wait=40>Huwag mong sabihing <br>hindi mo pa naririnig ang Randall Imperial Army?","story.map4-dungeon2.007":"Wow. Grabe talaga...","story.map4-dungeon2.008":"Seryoso, halos naaawa<br>na ako sa\'yo.","story.map4-dungeon2.009":"Kung ganoon, wala na akong magagawa.","story.map4-dungeon2.010":"Ako, si Lugina na may dalisay at mabuting puso, ang magtuturo sa\'yo ng lahat ng kailangan mong malaman!","story.map4-dungeon2.011":"Punasan mo ang mga luha mo ng pasasalamat<br>at tandaan mo ang sasabihin ko!","story.map4-dungeon2.012":"Magsimula tayo sa madali. <wait=40>Alam mo naman na nahiwalay ang lupain nating Elgaia sa Grand Gaia.","story.map4-dungeon2.013":"Alam mo \'yon, ang Lupain ng mga Diyos,<br>\'di ba?","story.map4-dungeon2.014":"Ayos,<wait=40> may alam ka rin pala kahit papaano!","story.map4-dungeon2.015":"Ewan ko kung bakit ka mukhang proud!<wait=40> Pinakasimpleng kaalaman na \'yan.","story.map4-dungeon2.016":"Grabe...","story.map4-dungeon2.017":"OK, ituloy natin. <wait=40>Binubuo ang Elgaia ng dalawang malalaking bansa.","story.map4-dungeon2.018":"Ang isa rito, ang Imperyo ng Randall, ang kinaroroonan ng Akras Summoners\' Hall.","story.map4-dungeon2.019":"Ang Akras Summoners\' Hall ang humahawak sa ekonomiya","story.map4-dungeon2.020":"at militar ng bansa, kaya pakitang-tao lang talaga ang pagiging imperyo nito.","story.map4-dungeon2.021":"Nagmula ang mga elite ng Randall<br>sa mga muling nagtayo ng bansa matapos itong","story.map4-dungeon2.022":"mahiwalay sa Grand Gaia, kaya siguro ganoon sila kayabang.","story.map4-dungeon2.023":"Ngayon, isa na lang silang grupo ng mga gurang na nagpapasarap sa marangyang buhay.","story.map4-dungeon2.024":"Siyempre, pakitang-tao lang ang hukbo nila, pagpapakita ng awtoridad, kumbaga.","story.map4-dungeon2.025":"Pero siguro may isa o dalawang magaling na sundalong dumaan sa hanay nila paminsan-minsan.","story.map4-dungeon2.026":"Anyway, <wait=40>ang isa pang bansa ay ang Elgaia Federation,","story.map4-dungeon2.027":"pero halos pareho lang ang kuwento nila.","story.map4-dungeon2.028":"Walang bansang may kakayahang lumaban sa Akras Summoners\' Hall,","story.map4-dungeon2.029":"kaya ang Hall talaga ang namumuno<br>sa buong Elgaia.","story.map4-dungeon2.030":"At dahil ako ang pinakamakapangyarihang Summoner<br>sa Akras Summoners\' Hall,","story.map4-dungeon2.031":"ibig sabihin, ako ang pinakamakapangyarihan sa buong Elgaia!","story.map4-dungeon2.032":"Ano?<wait=40><br>Siguro gusto mo ng autograph ko, \'no?","story.map4-dungeon2.033":"<size=14>(Dagundong, dagundong)","story.map4-dungeon2.034":"A-<wait=20>Aba!","story.map4-dungeon2.035":"L-<wait=20>Lindol ba \'yon?!","story.map4-dungeon2.036":"Pero parang hindi \'yon ordinaryong<br>lindol...","story.map4-dungeon2.037":"Ngayon, naiintindihan mo na ba ang ibig kong sabihin?!","story.map4-dungeon2.038":"Hindi magiging ligtas ang Cordelica hangga\'t hindi natin nalalaman kung ano\'ng nangyayari.","story.map4-dungeon2.039":"Ngayon, pakinggan mo ang matalino kong payo, at umalis ka na rito habang may pagkakataon ka pa!","story.map4-dungeon2.040":"Pagsisisihan mo kapag nagkita pa tayo ulit!","story.map4-dungeon3.001":"<size=20>Ikaw na naman?!<wait=40> <rep_handlename>!","story.map4-dungeon3.002":"Bakit nandito ka pa rin!?","story.map4-dungeon3.003":"Sige, sobra na \'to!","story.map4-dungeon3.004":"Kung ayaw mong makinig sa payo ko,<wait=40> tuturuan na lang kita ng leksyon sa pamamagitan ng bugbog!","story.map4-dungeon3.005":"Ngayon, huwag kang gagalaw!","story.map4-dungeon3.006":"<size=14>(Dagundong, dagundong)","story.map4-dungeon3.007":"H-Hindi na naman!<wait=40><br>Ano ba \'tong sunod-sunod na lindol nitong mga nakaraan?","story.map4-dungeon3.008":"Hoy!<wait=40> <rep_handlename>!","story.map4-dungeon3.009":"Nakikita mo na ba ang sinasabi<br>ko?","story.map4-dungeon3.010":"Hindi \'to lugar para tambayan ng isang baguhang Summoner na tulad mo.","story.map4-dungeon3.011":"Ngayon, umuwi ka na at siguraduhin mong<br>hindi lang ang Imperial Army ang may binabalak!","story.map4-dungeon3.012":"...<wait=20>Ano\'ng ibig sabihin ng tingin na \'yan?","story.map4-dungeon3.013":"Bakit pakiramdam ko hindi mo pa rin naiintindihan kung gaano ako kagaling...","story.map4-dungeon3.014":"Sige, makinig ka.<wait=40><br>Sinabi ko na \'to kanina,","story.map4-dungeon3.015":"pero dito sa Elgaia, may iba\'t ibang pangkat,<br>at bawat isa ay may sariling hukbo.","story.map4-dungeon3.016":"Ang pinakamalakas sa mga hukbong ito ay ang sa Akras Summoners\' Hall.","story.map4-dungeon3.017":"Makatuwiran naman, \'di ba?<br>Kasi nasa kanila ang halos lahat ng","story.map4-dungeon3.018":"Summoner sa Elgaia...","story.map4-dungeon3.019":"Anyway, binubuo ang hukbo ng Akras<br>ng tatlong uri ng puwersa.","story.map4-dungeon3.020":"Una, <wait=40>nandiyan ang Summoner Army, a.k.a. ang Regular Army, kung saan nagsisimula","story.map4-dungeon3.021":"ang bawat baguhang Summoner. \'Yan ang regimyento mo, by the way.","story.map4-dungeon3.022":"Ang opisyal na misyon n\'yo ay talunin ang Apat na Nahulog na Diyos, pero... paano ko ba sasabihin \'to?","story.map4-dungeon3.023":"Sa totoo lang, walang umaasang may<br>magagawa ang Regular Army.","story.map4-dungeon3.024":"Kung sino ang inaasahang gagawa ng trabaho, tanong mo?<br>Siyempre, kami, ang Demon Slayers!","story.map4-dungeon3.025":"Kami ang piling grupo ng mga elite na Summoner<br>na espesyal na pinili mula sa Regular Army.","story.map4-dungeon3.026":"Ang pinakamalalakas, gaya ko, ay binibigyan ng pamumuno sa mas maliliit na pangkat.","story.map4-dungeon3.027":"Siyempre, ang pinakamalakas sa lahat ay ang pinamumunuan ko:","story.map4-dungeon3.028":"Ang ika-23 Dibisyon ng Demon Slayers, ang Sky Garden!","story.map4-dungeon3.029":"At akala mo hindi ko na kayang<br>higitan ang sarili ko, \'no?","story.map4-dungeon3.030":"Hmm? <wait=40>Paano naman ang mga hukbo ng Randall<br>at ng Elgaia Federation, kamo?","story.map4-dungeon3.031":"Hah! Halos iilan lang ang Summoner nila. Mas wala pa silang silbi kaysa sa Regular Army namin.","story.map4-dungeon3.032":"Ngayon, tigilan mo na ang kakatanong at umuwi ka na kung saan ka nababagay!","story.map4-dungeon3.033":"Hindi lampa ang mga halimaw dito<br>tulad ng mga nakakalaban mo dati!","story.map4-dungeon3.034":"Narinig mo ba ako? Alis!","story.map4-dungeon3.035":"*Buntong-hininga* <wait=40>Ano ba\'ng ginawa ko<br>para madestino sa napakalayong lugar na \'to?","story.map4-dungeon3.036":"Kaya pala ipinadala nila ang Demon Slayer na si Lugina ng Sky Garden...","story.map4-dungeon3.037":"Heh. Siguro gusto lang nilang<br>tumigil muna siya sa pang-iistorbo sa kanila...","story.map4-dungeon3.038":"Gayunpaman, mukhang madali siyang gamitin para sa mga layunin ko.","story.map4-dungeon3.039":"Ngayon, ang natitira na lang ay bumuo ng plano...","story.map4-dungeon4.001":"<size=20>Ikaw na naman?! <rep_handlename>!","story.map4-dungeon4.002":"Sobra na \'to! Wala nang Mr. Nice Guy!","story.map4-dungeon4.003":"Sana gusto mo \'yang kinatatayuan mo, kasi diyan kita ililibing pagkatapos ko!","story.map4-dungeon4.004":"<size=18>(Dagundong, dagundong)","story.map4-dungeon4.005":"Isa na naman...?<br>Siguradong hindi normal ang mga lindol na \'to.","story.map4-dungeon4.006":"Mga hangal na matatanda sa Summoners\' Hall...<br>Sumpain silang lahat!","story.map4-dungeon4.007":"Makinig ka, <rep_handlename>!","story.map4-dungeon4.008":"Masyadong delikado ang lugar na \'to<br>para tumambay pa tayo.","story.map4-dungeon4.009":"Isusulat ko na ang mga natuklasan ko at<br>babalik agad sa Elgaia. <wait=40>Ikaw ang magiging saksi ko, ha?","story.map4-dungeon4.010":"Isipin mo lahat ng itinuro ko sa\'yo!<br>Hindi mo naman pababayaan ang matalik mong kaibigan, \'di ba?","story.map4-dungeon4.011":"Medyo duwag na pananalita \'yan para sa isang nagpapakilalang opisyal ng Demon Slayers, hindi ba?","story.map4-dungeon4.012":"...?!<br><wait=40>Sino ka?","story.map4-dungeon4.013":"A-Ang sagisag na \'yan...","story.map4-dungeon4.014":"Hindi puwede!<br>Miyembro ng Imperial Guard?!","story.map4-dungeon4.015":"Tama ka.<br>Mukhang bagay ka nga sa pagtuturo.","story.map4-dungeon4.016":"Ako si Paris. Kabilang ako sa isa<br>sa mga “walang silbing” puwersang inilarawan mo kanina.","story.map4-dungeon4.017":"Nakikinig ka pala buong oras?<br>Walang nagturo sa\'yo ng tamang asal?","story.map4-dungeon4.018":"Ganyan din ang maitatanong ko sa\'yo.","story.map4-dungeon4.019":"O itinuturing mo bang marangal na<br>asal ang pagsuway sa utos ng bansa mo, at ang pagmamaliit","story.map4-dungeon4.020":"sa Imperial Army na nagpapagal<br>para sa kasaganaan ng ating kaharian?","story.map4-dungeon4.021":"Pfft...<br><wait=40>Ay, sorry na sorry po! Patawarin n\'yo po ako!","story.map4-dungeon4.022":"Gaya ng inaasahan ko, pare-parehong<br>bastos ang mga miyembro ng Summoners\' Hall...","story.map4-dungeon4.023":"Sabihin mo \'yan sa may pakialam,<br>ale!","story.map4-dungeon4.024":"Isa pa, kayong mga Imperial Guard<br>ang nagbabantay sa Pamilyang Imperyal, \'di ba?","story.map4-dungeon4.025":"Ano\'ng ginagawa mo sa napakalayong lugar na \'to?","story.map4-dungeon4.026":"Wala akong buong araw,<br>kaya bilisan mo nang magsalita!","story.map4-dungeon4.027":"Heh...<br>Masigla ka para sa isang alalay.","story.map4-dungeon4.028":"Sino\'ng tinatawag mong alalay?!","story.map4-dungeon4.029":"Akala mo magkasama kami ng tangang \'to? Hah!","story.map4-dungeon4.030":"Bahala ka, ale.<br>Marami akong mas mahalagang gagawin","story.map4-dungeon4.031":"kaysa makipag-away sa<br>Imperial Guard dito sa liblib na lugar.","story.map4-dungeon4.032":"Ah, ang tanyag na diplomasya ng Demon Slayers.<br>At least alam na natin kung saan tayo nakatayo.","story.map4-dungeon4.033":"Sa totoo lang, pumunta ako rito para humingi ng pabor sa inyo.","story.map4-dungeon4.034":"Gusto naming hingin ang tulong n\'yo<br>sa pag-iimbestiga sa Cordelica.","story.map4-dungeon4.035":"Hah!<wait=40><br>Tama ba ang narinig ko?","story.map4-dungeon4.036":"Ayokong maghanap ng gulo, <wait=40>pero hindi rin ako susunod sa mga utos mo!","story.map4-dungeon4.037":"Hindi ligtas para sa atin ang manatili rito,<br>kung hindi mo pa napapansin.","story.map4-dungeon4.038":"Nakikita kong alam mo ang panganib<br>na dala ng rehiyong ito.","story.map4-dungeon4.039":"Siyempre, wala akong inaasahang<br>mas mababa mula sa isang nagpapakilalang pinuno ng Demon Slayers.","story.map4-dungeon4.040":"Ano\'ng ipinahihiwatig mo, ha?","story.map4-dungeon4.041":"Ipinahihiwatig?<wait=40> Hindi, sinasabi ko lang ang totoo.","story.map4-dungeon4.042":"Ang taong natatakot sa<br>ilang maliliit na lindol ay hindi","story.map4-dungeon4.043":"makakapamuno ng isang mahusay na pangkat gaya ng sinasabi mo, \'di ba?","story.map4-dungeon4.044":"Ikaw talaga!<wait=40><br>Ingatan mo \'yang dila mo!","story.map4-dungeon4.045":"Tinatawag mo akong duwag?!","story.map4-dungeon4.046":"Huwag mo akong patawanin!<wait=40><br>Ipapakita ko sa\'yo ang tunay na takot!","story.map4-dungeon4.047":"Hoy!<wait=40> <rep_handlename>!","story.map4-dungeon4.048":"Panahon na para may maitulong ka naman dito!","story.map4-dungeon4.049":"Hanggang ngayon, binalewala mo lahat<br>ng sinabi ko sa\'yo.","story.map4-dungeon4.050":"Siguro akala mo ang galing-galing mo, \'no?","story.map4-dungeon4.051":"Kung ganoon ka kagaling, bakit hindi mo patunayan sa pamamagitan ng pagdispatsa sa bubwit na nagtatago sa kutang \'yon!","story.map4-dungeon4.052":"Mas lalakas pa ang mga halimaw na<br>makakaharap natin mula ngayon,","story.map4-dungeon4.053":"pero kahit ikaw, hindi dapat mahirapan<br>sa mga \'yon doon.","story.map4-dungeon4.054":"Hehe... <wait=40>Mukhang magiging kawili-wili \'to.","story.map4-dungeon4.055":"...Ano?! Huwag ka lang tumunganga diyan!<wait=40><br>Lumabas ka at bugbugin mo sila!","story.map4-dungeon4.056":"Narinig mo ang lalaki,<br><rep_handlename>... Hehe.","story.map4-dungeon5.001":"Hmph! <wait=40>Ang tagal mo naman<br>bago nakarating dito.","story.map4-dungeon5.002":"At nagtataka pa ang mga tao kung bakit wala<br>akong respeto sa inyong mga taga-Regular Army.","story.map4-dungeon5.003":"Pero nauna ka naman dito kaysa sa mapagmagaling na Imperial Guard na \'yon, kahit papaano.","story.map4-dungeon5.004":"At sino naman kaya \'yon?","story.map4-dungeon5.005":"Ano-? <wait=20>Ikaw?!<wait=40><br>Gaano ka na katagal nakatayo diyan!","story.map4-dungeon5.006":"Mula bago ka dumating at<br>nagsimulang magpakatanga.","story.map4-dungeon5.007":"Ikaw talaga! <wait=40>Pinapanood mo<br>pala ako buong oras!","story.map4-dungeon5.008":"Ay, kumalma ka nga.","story.map4-dungeon5.009":"Marami akong mas mahalagang gagawin<br>kaysa suriin ang bawat galaw mo.","story.map4-dungeon5.010":"Argh, hayaan n\'yo akong sugurin siya!","story.map4-dungeon5.011":"Kaya ayoko sa inyong mga Imperial Guard,<br>lagi kayong napakayabang!","story.map4-dungeon5.012":"Mamaya mo na ilabas ang mga reklamo mo.<wait=40><br>Una, sabihin mo kung ano\'ng ginagawa mo rito.","story.map4-dungeon5.013":"Ha?<wait=40> <br>Biro ba \'yan?","story.map4-dungeon5.014":"Nandito ako para imbestigahan ang mga guho, siyempre.","story.map4-dungeon5.015":"Tingnan mo sila! Siguradong<br>nandito na sila bago pa ang Malaking Pagbagsak.","story.map4-dungeon5.016":"May nakita ka na bang lugar<br>na ganito kasarap imbestigahan?","story.map4-dungeon5.017":"Anyway, pumunta ako rito para tingnan<br>sila, at sumusunod-sunod naman \'tong isa \'to.","story.map4-dungeon5.018":"Ganoon ba...<wait=40><br>So marunong kang magbasa ng sinaunang sulat?","story.map4-dungeon5.019":"Akala ko ako ang dapat<br>na nag-iimbestiga...","story.map4-dungeon5.020":"Ano \'yon? Akala mo hindi ko kaya ang trabahong \'to, ha!?","story.map4-dungeon5.021":"Ikaw lang ba ang may kakayahang<br>mag-isip nang matalino, ganoon ba?","story.map4-dungeon5.022":"Hindi, <wait=40>sa totoo lang, humahanga ako.","story.map4-dungeon5.023":"Baka hindi ka kasing-tanga ng<br>ipinapahiwatig ng magaspang mong anyo.","story.map4-dungeon5.024":"...<wait=40>Binabalaan kita,<br>ale.","story.map4-dungeon5.025":"Huwag mong isiping hindi ako papalag kapag patuloy mo akong ginalit.","story.map4-dungeon5.026":"At maniwala ka, kapag nagalit ako,<br>kaya kong durugin ang kahit ano!","story.map4-dungeon5.027":"Imperial Guard man o hindi.","story.map4-dungeon5.028":"Naku, nakakatakot naman \'yan.<br>Mabuti pang manatili ako sa mabuting panig mo.","story.map4-dungeon5.029":"Grrr...<wait=40><br>Sabi ko na nga ba! Pinagtatawanan mo ako!","story.map4-dungeon5.030":"Hehe...<wait=40><br>Sa tingin mo ba ganoon ako kalupit?","story.map4-dungeon5.031":"Sa totoo lang, mabuti pang mag-ingat ka rin na huwag galitin si Lugina, naiintindihan mo?","story.map4-dungeon5.032":"Hindi ko naman maisip na<br>ang isang kaibigan ni Karl ay","story.map4-dungeon5.033":"matatakot sa isang miyembro ng Sky Garden...","story.map4-dungeon5.034":"Ha?<wait=40><br>Itong Karl na sinasabi mo... <wait=40>Siya ba ang Karl ng Nyonne?","story.map4-dungeon5.035":"<size=20>Bwahaha!","story.map4-dungeon5.036":"Ay, ang tagal ko nang hindi natawa nang ganoon.<wait=40><br>Ang ideyang magkaibigan ang tangang \'to at si Karl!","story.map4-dungeon5.037":"Ngayon, narinig ko na talaga ang lahat...","story.map4-dungeon5.038":"Hoy, saan ka pupunta!","story.map4-dungeon5.039":"Mag-iimbestiga.<wait=40><br>Mas malawak ang masusuyod natin kung maghihiwalay tayo, hindi ba?","story.map4-dungeon5.040":"Lugina,<wait=40><br>doon ka tumingin.","story.map4-dungeon5.041":"T-Teka!<wait=40><br>Paano ko malalaman kung saan...","story.map4-dungeon5.042":"...Hmph.","story.map4-dungeon5.043":"Kung magsisinungaling din lang siya sa harap ko,<br>sana man lang ginawa niyang kapani-paniwala nang kaunti.","story.map4-dungeon5.044":"Heh, na parang kilala talaga ni Karl<br>ang tanga\'t mangmang na \'to...","story.map4-dungeon5.045":"Grr... <wait=40>Isipin ko lang ang mukhang-babaeng<br>pretty boy na \'yon, kumukulo na ang dugo ko!","story.map4-dungeon5.046":"Hoy, ikaw! <wait=40>Huwag ka lang tumayo diyan na mukhang tanga! Lumabas ka at asikasuhin mo ang mga halimaw na \'yon!","story.map4-dungeon6.001":"<size=20>Argh, <wait=40>sobra na \'to!","story.map4-dungeon6.002":"Sawang-sawa na ako!<br>Ano ba\'ng ginawa ko para mangyari \'to, ha?!","story.map4-dungeon6.003":"Bakit ako pa ang kailangang humarap<br>sa ganitong nakakatakot na mga halimaw!","story.map4-dungeon6.004":"Hindi patas!<wait=40><br>Wala akong ginawa para danasin \'to!","story.map4-dungeon6.005":"Yikes!!<wait=40><br>...Ay, ikaw lang pala, <rep_handlename>.","story.map4-dungeon6.006":"Tsk... Puro gulo na lang ang dinanas ko<br>mula nang makasalubong kita.","story.map4-dungeon6.007":"Nagrereklamo ka na naman, ha?<br>Talaga, Lugina, hindi \'yan bagay sa isang lalaking may katayuan na tulad mo.","story.map4-dungeon6.008":"Tumahimik ka!<wait=40><br>Ano ba\'ng problema mo, lagi mo na lang akong ginugulat nang ganyan!","story.map4-dungeon6.009":"Isa ka sa mga dahilan kung bakit ako<br>nadamay sa kalokohang \'to sa simula pa lang!","story.map4-dungeon6.010":"Malayo sa ideal ang kalagayan natin ngayon,<br>aaminin ko \'yan.","story.map4-dungeon6.011":"Pero hindi mababago ng panlalait at pagrereklamo ang sitwasyon.","story.map4-dungeon6.012":"Akala mo hindi ko pa alam<br>\'yan?!","story.map4-dungeon6.013":"May balita ako para sa\'yo, hindi ako naglalakad sa maruruming lagusang \'to para lang magsaya, okay!","story.map4-dungeon6.014":"Hehe...<wait=40><br>Hindi nga, kita ko.","story.map4-dungeon6.015":"Gayunpaman, mukhang alam mo<br>kung ano\'ng kailangang gawin.","story.map4-dungeon6.016":"Tama. <wait=40>At \'yan nga ang inirereklamo ko.","story.map4-dungeon6.017":"Sige! Lampasan na natin ang<br>lagusang \'to at magmadali tayo sa Guho ng Higante.","story.map4-dungeon6.018":"Naku, mukhang nagmamadali ang isa diyan...<wait=40> Bilisan mo na rin.","story.map4-dungeon6.019":"Kapag hindi tayo nagmadali, gigising ang<br>mga dakilang diyos at wawasakin ang buong kontinenteng \'to.","story.map4-dungeon6.020":"Wala nang oras para magpaliwanag pa sa tangang \'yan!","story.map4-dungeon6.021":"Ako ang mangunguna.","story.map4-dungeon6.022":"Ikaw ang tumapos sa mga matitirang<br>makakalusot sa akin!","story.map4-dungeon6.023":"Heh...<wait=40><br>Pananalita ng isang tunay na mandirigma, Lugina.","story.map4-dungeon6.024":"Pero nagkakamali ka sa isang bagay.","story.map4-dungeon6.025":"May karapatan si <rep_handlename> na malaman<br>ang panganib ng kalagayan natin.","story.map4-dungeon6.026":"Nakita mo nang lumaban si <rep_handlename>,<br>hindi ba?","story.map4-dungeon6.027":"Dapat nating gamitin ang lahat ng<br>lakas militar na nasa ating mga kamay.","story.map4-dungeon6.028":"Hmph! <wait=40>Bahala ka.<br>Pero ikaw na ang bahala sa pagpapaliwanag!","story.map4-dungeon6.029":"Sawang-sawa na ako sa<br>pag-aalaga sa malaking batang \'to.","story.map4-dungeon6.030":"Mukhang nagpasya siyang umalis<br>nang mag-isa, sa huli.","story.map4-dungeon6.031":"Tsk... Hindi siya magkakaroon ng kaibigan<br>sa ganyang kasungit na ugali.","story.map4-dungeon6.032":"Well,<wait=40><br>mukhang tayong dalawa na lang sa wakas!","story.map4-dungeon6.033":"Kaya ikaw pala ang binabanggit ng mga Elder, ang kaibigan ni Karl,","story.map4-dungeon6.034":"ang pinuno ng makapangyarihang ika-24 na Demon Slayers, ang Rebluens.","story.map4-dungeon6.035":"Marami akong narinig na magagandang kuwento tungkol sa\'yo,<br><rep_handlename>.","story.map4-dungeon6.036":"Hindi mo kailangang magmukhang<br>gulat na gulat.","story.map4-dungeon6.037":"Kumalma ka.<wait=40><br>Kakampi mo ako, alam mo \'yon.","story.map4-dungeon6.038":"Sa itsura ng mukha mo, mukhang malayo pa bago ko makuha ang tiwala mo.","story.map4-dungeon6.039":"Saan na nga ba ako?<wait=40><br>Ah oo, ang mga higante.","story.map4-dungeon6.040":"Hindi naman talaga ito komplikado.","story.map4-dungeon6.041":"Noong unang panahon, may lahi ng mga higanteng<br>nanirahan dito sa Cordelica.","story.map4-dungeon6.042":"Gayunpaman, nalipol ang buong lahi nila<br>ng mga puwersang hindi natin maunawaan.","story.map4-dungeon6.043":"Lahat, maliban sa isa:<br>ang kilala ngayon bilang Higanteng Diyos.","story.map4-dungeon6.044":"Dahil nilamon ng galit at kawalan ng pag-asa<br>para sa mga nasawi niyang kasama, ","story.map4-dungeon6.045":"ikinulong ng higante ang sarili niya sa lupaing ito.","story.map4-dungeon6.046":"Ito ang alamat na nakaukit sa<br>Tore ng Liwanag. <wait=40>Kung sino ang sumulat nito, hindi namin alam.","story.map4-dungeon6.047":"Siguradong nakita rin ni Lugina<br>ang parehong inskripsyon.","story.map4-dungeon6.048":"Matapos itong basahin, <wait=40>siguradong<br>pareho kami ng naging konklusyon...","story.map4-dungeon6.049":"Na malapit nang lumitaw ang Higanteng Diyos<br>mula sa kanyang pagkakatulog, nag-aapoy sa galit.","story.map4-dungeon6.050":"Heh...<wait=40> <br>Mukhang nakuha ko na rin ang buong atensyon mo.","story.map4-dungeon6.051":"Kumalma ka.<wait=40><br>Batay sa laki ng mga pagyanig,","story.map4-dungeon6.052":"hindi pa tuluyang nagigising ang Higanteng Diyos.","story.map4-dungeon6.053":"Ayon sa inskripsyon sa mga guho,<br>kapag tuluyan nang nagising ang higante,","story.map4-dungeon6.054":"lalamunin ang buong islang ito<br>sa isang iglap.","story.map4-dungeon6.055":"Halika.<wait=40><br>Kailangan na nating umalis ngayon din.","story.map4-dungeon6.056":"Nasa kabila lang ng lagusang ito ang mga guho kung saan nakahimlay ang Higanteng Diyos.","story.map4-dungeon7.001":"...Oo. <wait=40>Inaantok pa si Grantos,<br>pero gising na siya ngayon.","story.map4-dungeon7.002":"Hindi po, <wait=40>hindi \'yon magiging<br>problema.","story.map4-dungeon7.003":"Siyempre po.<wait=40><br>Ipapaalam ko agad ang anumang bagong mangyayari.","story.map4-dungeon7.004":"Hoy, <wait=40>babae!","story.map4-dungeon7.005":"Tapos ka na bang makipagtsismisan<br>diyan?","story.map4-dungeon7.006":"Isinusumbong mo ba ako sa isa sa mga<br>Imperial na kaibigan mo, o ano?","story.map4-dungeon7.007":"Heh. Walang nakakalusot sa\'yo, \'no?","story.map4-dungeon7.008":"May malaking interes ang Imperyo sa<br>mga mahuhusay na batang Summoner.","story.map4-dungeon7.009":"Bah!<wait=40><br>Well, hindi ako interesado sa inyo!","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"Hoy, <rep_handlename>!<br>Puwede mo bang bilisan nang kaunti?","story.map4-dungeon7.012":"Kung hindi mo pa napapansin, nasa gitna<br>tayo ng isang emergency dito!","story.map4-dungeon7.013":"Kung nagmamadali ka pala,<br>bakit hindi ka na lang nauna nang wala kami?","story.map4-dungeon7.014":"Hindi kayo kapantay ng dakilang Lugina, pero kahit kayong mga baguhan ay may silbi rin!","story.map4-dungeon7.015":"Heh...","story.map4-dungeon7.016":"Sige, makinig kayo.<wait=40><br>Papatayin ko na si Grantos,","story.map4-dungeon7.017":"ang Higanteng Diyos na natulog<br>nang daan-daang taon.","story.map4-dungeon7.018":"Dahil makapangyarihan ako,<br>ako ang gagawa ng mabigat na trabaho.","story.map4-dungeon7.019":"Pero ayokong maistorbo<br>ng mga nakakainis na alipores habang ginagawa ko \'yon.","story.map4-dungeon7.020":"Diyan kayo papasok.<wait=40> kayo ang aagaw sa atensyon nila habang hinaharap ko ang malaki!","story.map4-dungeon7.021":"Haharapin mo nang mag-isa ang ganoon<br>kalaking halimaw? Napaka-gentleman mo naman...","story.map4-dungeon7.022":"Sarkastiko ka, ha?","story.map4-dungeon7.023":"Na parang may kakayahan kayong<br>makipagsabayan sa ganoong kalaking higante!","story.map4-dungeon7.024":"Mas gugustuhin ko pang harapin siya nang mag-isa kaysa iligtas pa kayong dalawa kapag pumalpak ang lahat.","story.map4-dungeon7.025":"Makikita n\'yo, <wait=40>ipapakita ko sa inyo ang tunay na kapangyarihan.","story.map4-dungeon7.026":"Malinaw na ba? <wait=40>Kayo ang bahala sa mga alipores habang inililigtas ko ang mundo!","story.map4-dungeon7.027":"At tandaan n\'yo, kapag pumalpak kayo,<br>tutuhugin ko kayo gamit ang sarili n\'yong mga espada!","story.map4-dungeon7.028":"Talagang sapat ang pagka-bossy niya para pamunuan<br>ang isang regimyento ng Demon Slayers...","story.map4-dungeon7.029":"Marami pang kulang sa tono niya,","story.map4-dungeon7.030":"pero mukhang may kakayahan at<br>sapat na kaalaman naman siya, kahit papaano.","story.map4-dungeon7.031":"Bukod pa roon, mas marami siyang nakalap<br>na datos kaysa inaasahan ko.","story.map4-dungeon7.032":"Gayunpaman, batay sa mga natuklasan ko,","story.map4-dungeon7.033":"imposibleng kaya niyang harapin<br>si Grantos nang mag-isa.","story.map4-dungeon7.034":"Mukhang kailangan ko siyang tulungan.","story.map4-dungeon7.035":"Siyempre,<wait=40><br>kakailanganin din niya ang tulong mo.","story.map4-dungeon7.036":"Panahon na para makita kung ano talaga<br>ang kaya mo.","story.map4-dungeon_ex_clear.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"Nagawa mo, <rep_handlename>!","story.map4-dungeon_ex_clear.003":"Maraming salamat!","story.map4-dungeon_ex_clear.004":"Alam kong kaya mo!","story.map4-dungeon_ex_clear.005":"Ikaw ang pinakamagaling!","story.map4-dungeon_ex_clear.006":"Hehe, <wait=20>sorry, medyo nadala ako.","story.map4-dungeon_ex_clear.007":"Anyway, nalaman na namin kung ano ang halimaw na \'yon.","story.map4-dungeon_ex_clear.008":"Mukhang inaalagaan pala ito noon ng mga higante para magligpit ng basura.","story.map4-dungeon_ex_clear.009":"Pero lumaki ito nang husto kaya kahit sila ay hindi na ito makontrol. ","story.map4-dungeon_ex_clear.010":"Sa huli, ikinulong ito sa lugar na \'yon ng isang bayani.","story.map4-dungeon_ex_clear.011":"Siguradong napakalakas ng bayaning \'yon para mapasuko ang halimaw na hindi kinaya kahit ng mga higante.","story.map4-dungeon_ex_clear.012":"Ay, <wait=20>pero siyempre malakas ka rin!","story.map4-dungeon_ex_clear.013":"Kasi, natalo mo nang mag-isa ang napakalaking halimaw na \'yon!","story.map4-dungeon_ex_clear.014":"At ang lagkit-lagkit pa at nakakadiri...","story.map4-dungeon_ex_clear.015":"Hangang-hanga talaga ako sa\'yo, <rep_handlename>!","story.map4-dungeon_ex_clear.016":"Ay, ano \'yan?","story.map4-dungeon_ex_clear.017":"May kung ano sa balikat mo. <wait=20>Hindi kaya...","story.map4-dungeon_ex_clear.018":"<size=21>Kyaaaaahh!</size>","story.map4-dungeon_ex_clear.019":"<size=21>Yuck, ang lagkit!!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"Sir, <wait=20>may problema tayo! <wait=40>Malaking problema!","story.map4-dungeon_ex_open.003":"Sorry! Hindi ko sinasadyang magdulot ng gulat...","story.map4-dungeon_ex_open.004":"Ako si Lin Merylham mula sa Logistics Support...","story.map4-dungeon_ex_open.005":"...ng Grand Gaia Survey Office Bureau of Investigation, handang maglingkod sa inyo.","story.map4-dungeon_ex_open.006":"P-<wait=20>Paano ka nakakakalma sa ganitong oras!?","story.map4-dungeon_ex_open.007":"<rep_handlename>, bilang miyembro ng Summoner Army ng Akras Summoners\' Hall...","story.map4-dungeon_ex_open.008":"...hinihiling naming imbestigahan mo ang Yungib ng Ignia!","story.map4-dungeon_ex_open.009":"Mukhang may halimaw na natutulog sa likod ng Talon ng Ignia.","story.map4-dungeon_ex_open.010":"Pero mukhang nagising ito dahil sa lindol sa Cordelica noong isang araw.","story.map4-dungeon_ex_open.011":"At tungkol sa halimaw mismo...","story.map4-dungeon_ex_open.012":"Basa at malagkit ito, at kinakain nito ang lahat!","story.map4-dungeon_ex_open.013":"Isipin ko lang ang ganoon kalaki at nakakadiring halimaw, kinikilabutan na ako.","story.map4-dungeon_ex_open.014":"<size=21>Kyaaaaaahh! Kadiri!!</size>","story.map4-ending.001":"Heh, <wait=40>gaya ng inaasahan ko.","story.map4-ending.002":"Hindi nakapagtatakang mataas ang tingin sa\'yo ni Karl.","story.map4-ending.003":"(Hingal... <wait=40>hingal...)","story.map4-ending.004":"Well, <wait=40>tingnan mo kung sino ang nakarating din sa wakas!","story.map4-ending.005":"...<wait=40>Ugh, heto na naman.","story.map4-ending.006":"Narinig mo na siguro ang balita?","story.map4-ending.007":"Natalo na ni <rep_handlename><br>si Grantos.","story.map4-ending.008":"Hindi na pala kailangan ang serbisyo mo.<br>Pagkatapos ng lahat ng pagyayabang mo kanina...","story.map4-ending.009":"I-Ikaw talaga...<wait=40><br>Kung pagyayabang ang hanap mo, lalabanan kita dito mismo!","story.map4-ending.010":"Puwede mo nang itigil ang pekeng tapang.<wait=40><br>Nagkaroon ka ng pagkakataon, at sinayang mo.","story.map4-ending.011":"T-Tumahimik ka!<wait=40><br>Walang mali sa impormasyong natuklasan ko!","story.map4-ending.012":"Siguro lumipat ng puwesto ang lintik na higanteng \'yon o ano...","story.map4-ending.013":"Aaminin ko ito, pareho tayo ng naging konklusyon,","story.map4-ending.014":"at nagawa mo ring talunin ang ilang malalakas na halimaw papunta rito.","story.map4-ending.015":"Gayunpaman, hindi mo natapos ang misyon mo.","story.map4-ending.016":"Ano\'ng silbi ng galing mo kung papalpak ka naman kapag talagang mahalaga na?","story.map4-ending.017":"Grr...<wait=40> Ipapakita ko sa\'yo!<br>Ano ba\'ng alam mo, ha?!","story.map4-ending.018":"Sobra na \'to! Tapos na ako!","story.map4-ending.019":"Hindi ko naman hiniling na alagaan kayo sa simula pa lang, at tingnan mo kung saan ako napunta!","story.map4-ending.020":"Babalik na ako sa Elgaia!","story.map4-ending.021":"Isa pa, kailangan kong ihatid ang ulat ko<br>sa mga gurang na \'yon sa Summoners\' Hall.","story.map4-ending.022":"......","story.map4-ending.023":"Hoy!<wait=40> <rep_handlename>!","story.map4-ending.024":"Huwag mong isiping ang galing-galing mo na dahil sinuwerte kang matalo si Grantos!","story.map4-ending.025":"Kaya ko siyang talunin nang nakapikit<br>at nakatali ang isang kamay sa likod!","story.map4-ending.026":"Sa totoo lang, dapat magpasalamat ka pa sa akin!","story.map4-ending.027":"Tama! <wait=40>Magpasalamat ka sa pinakamakapangyarihang Summoner ng buong Akras Summoners\' Hall sa pag-aalaga sa\'yo!","story.map4-ending.028":"Ehem.<wait=40> Hindi ba si Karl ng pangkat na Rebluens ang pinakamakapangyarihan sa Summoners\' Hall?","story.map4-ending.029":"Naghahanap ka ba ng black eye<br>o ano?","story.map4-ending.030":"Tigilan mo ang pagbanggit sa pangalang \'yan!","story.map4-ending.031":"Mas marami pang talento ang hinliliit ko kaysa sa buong katawan ng pakitang-taong \'yon!","story.map4-ending.032":"Nagkataon lang na nasa tamang lugar at tamang oras ang KJ na \'yon, \'yon lang!","story.map4-ending.033":"Sa Randall, sinasabing mag-isa niyang natalo si Sagamur, ang Dragon ng Impiyerno.","story.map4-ending.034":"Pagkatapos noon, personal daw siyang kinuha para sa Imperial Guard.","story.map4-ending.035":"Hah! Siya?!<wait=40><br>Siya man ang nagbigay ng huling dagok,","story.map4-ending.036":"pero ibang regimyento ang talagang<br>nagpaluhod doon!","story.map4-ending.037":"At oo,<wait=40> kung nagtataka ka,<wait=40>","story.map4-ending.038":"ang regimyentong \'yon ay ang Sky Garden, salamat na lang!","story.map4-ending.039":"Ah oo, <wait=40>naaalala ko na.","story.map4-ending.040":"May kinalaman sa pinuno ng Sky Garden na nawalan ng malay nang makarinig ng mga alulong sa dilim...","story.map4-ending.041":"Ano?!","story.map4-ending.042":"H-Hindi \'yan ang nangyari!","story.map4-ending.043":"Itinaya ko ang buhay ko para protektahan ang mahihinang \'yon mula sa kung anumang nag-aabang doon!","story.map4-ending.044":"Dahil sa akin kaya nakalaban pa<br>sila sa simula pa lang!","story.map4-ending.045":"Kung wala ako roon, wala silang kahit katiting na pag-asang manalo!","story.map4-ending.046":"Hehe. <wait=40>Kung ganoon, dapat<br>akong humingi ng tawad sa pagdududa sa dakilang pinuno ng Sky Garden.","story.map4-ending.047":"Dapat lang talaga!","story.map4-ending.048":"Tsk... <wait=40>Kita mo, kaya hindi<br>ko matiis ang manlolokong Karl na \'yon.","story.map4-ending.049":"Nasaan ang respeto niya?<br>Nakatataas ako sa kanya, Diyos ko naman!","story.map4-ending.050":"Wala akong pakialam kung ikaw man<br>o ang tangang Imperial na babaeng \'yon,","story.map4-ending.051":"sinumang kumakampi kay Karl ay tinik lang sa lalamunan ko!","story.map4-ending.052":"Makinig ka <rep_handlename>, dahil isang beses ko lang \'to sasabihin!","story.map4-ending.053":"Sa susunod na humarang ka sa daan ko,","story.map4-ending.054":"bubugbugin kita nang husto na isang linggo kang mamimitas ng tinik sa puwit mo!","story.map4-ending.055":"Kung ayaw mo noon, simulan mo nang magpakita ng respeto sa akin!","story.map4-ending.056":"Ako ang dakila at makapangyarihang Lugina, at huwag mong kalimutan \'yan!","story.map4-ending.057":"Heh...<wait=40> <br>Well, puwede sanang mas maganda ang kinalabasan noon.","story.map4-ending.058":"Siyanga pala,<wait=40><br>oras na rin para umalis ako.","story.map4-ending.059":"Kung itutuloy mo pa rin ang pagtugis sa Apat na Nahulog na Diyos,<wait=40> baka magkrus muli ang ating mga landas balang araw.","story.map4-ending.060":"Inaasahan kong makipaglaban kasama<br>mo sa hinaharap.","story.map4-ending.061":"Good luck sa\'yo,<br>matapang na mandirigma.","story.map4-ending.062":"––Ganoon ba.<wait=40><br>Hindi pala ito sa Cordelica, sa huli...","story.map4-ending.063":"––Pinaghinalaan ko na rin \'yon,<wait=40><br>pero hindi ko maiwasang madismaya nang kaunti.","story.map4-ending.064":"––Hmm?<wait=40><br>Hindi mo kailangang humingi ng tawad sa kahit ano.","story.map4-ending.065":"––Kung tutuusin, ako ang dapat<br>humingi ng tawad sa pagpapadala sa\'yo sa walang saysay na paghahanap.","story.map4-ending.066":"––Oo, siyempre.<wait=40><br>Ipagpatuloy mo ang mabuting trabaho.","story.map4-ending.067":"––Tandaan mo, umaasa ako sa\'yo.","story.map4-ending.068":"Hehe...","story.map4-ending.069":"Kaya, <wait=40>natalo pala ng batang<br>Summoner si Grantos...","story.map4-ending.070":"Gaya ng inaasahan ko.","story.map4-ending.071":"Mukhang patungo nga ang mundo<br>sa tamang direksyon.","story.map4-ending.072":"Ngayon, kailangan na lang magmadali si Paris<br>na hanapin ang tunay na natutulog sa Grand Gaia.","story.map4-ending.073":"......","story.map4-ending.074":"Nakikinig ka, hindi ba?","story.map4-ending.075":"Nagsimula nang tumakbo ang orasan.<wait=40><br>Wala nang atrasan ngayon.","story.map4-ending.076":"Mabuti pang ihanda na ng amo mo<br>ang sarili niya sa paparating.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Hehe.","story.map4-ending.079":"<size=20>Mwahaha!","story.map4-open.001":"(Tok, <wait=20>tok.)","story.map4-open.002":"Paumanhin po, sir.","story.map4-open.003":"Ayon sa ating mga mapagkukunan sa pamahalaan,","story.map4-open.004":"nakontrol na ng Akras Summoners\' Hall<br>ang katimugang rehiyon ng Mistral.","story.map4-open.005":"...<wait=40>Oo, <wait=40>narinig ko nga.","story.map4-open.006":"Nagiging malakas na puwersa na<br>rin sila sa Grand Gaia.","story.map4-open.007":"Mukhang ganoon nga...","story.map4-open.008":"Paris,<wait=40><br>gusto kong pumunta ka sa Cordelica.","story.map4-open.009":"Kailangan kong malaman ang anumang<br>bagong mangyayari sa hangganan.","story.map4-open.010":"...<wait=40>Siyempre po, sir.<wait=40><br>...<wait=40>At paano po ang mga karaniwan kong tungkulin?","story.map4-open.011":"Ako na ang magpapaliwanag ng sitwasyon sa Emperador.","story.map4-open.012":"Salamat po, sir.<wait=40><br>Kung ganoon, paalam na po.","story.map4-open.013":"......","story.map4-open.014":"...Oh,<wait=40><br>hindi kita napansin diyan.","story.map4-open.015":"Hindi ka talaga marunong kumatok, \'no?","story.map4-open.016":"......","story.map4-open.017":"Ang Akras Summoners\' Hall <wait=40>at ang Pamahalaan ng Elgaia Federation...<wait=60><br>Kumikilos na ang Paksyon ni Abel...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Hehe.","story.map4-open.020":"<size=20>Mwahaha!","story.map4-open.021":"Mukhang magiging kawili-wili na<br>ang mga mangyayari...","story.map5-dungeon1.001":"...<wait=40>Nakakalungkot naman dito. ","story.map5-dungeon1.002":"Mukhang umabot din dito ang labanan.","story.map5-dungeon1.003":"Nakakaawa...","story.map5-dungeon1.004":"Kailangan nating gawin ang lahat para hindi na ito maulit.","story.map5-dungeon1.005":"Aba, <wait=40><rep_handlename>,<wait=40> ang kumpiyansa naman ng mukha mo!","story.map5-dungeon1.006":"Tama, <wait=40>talunin natin ang pasaway na si Cardes!","story.map5-dungeon1.007":"Ha? <wait=40>Sino si Cardes, tanong mo?","story.map5-dungeon1.008":"Ay, sorry!<wait=40> <br>Hindi ko pa pala nakukuwento sa\'yo ang tungkol sa kanya, \'no!?","story.map5-dungeon1.009":"Ehem, <wait=40>o sige, <wait=40>oras na para sa kuwentuhan ni Tilith!","story.map5-dungeon1.010":"Itong Kapuluan ng Palmyna ay pinamumunuan ni \\"Cardes the Malevolent,\\" isa sa Apat na Nahulog na Diyos. ","story.map5-dungeon1.011":"Ang layunin natin ngayon, <rep_handlename>, ay talunin siya!","story.map5-dungeon1.012":"At kailangan mong mag-ingat dahil mas malakas pa siya kaysa kay Maxwell! ","story.map5-dungeon1.013":"Pero walang dapat ikabahala!","story.map5-dungeon1.014":"Sa katunayan, <wait=20>nakakulong pa ngayon ang malaking bahagi ng kapangyarihan ni Cardes.","story.map5-dungeon1.015":"Sabi nila, ikinulong ito noong malaking digmaan sa kailaliman ng Palmyna, sa lugar na tinatawag na \\"Daigdig ng Espiritu\\"...","story.map5-dungeon1.016":"Siguradong may mga kahanga-hangang tao rin dito bukod sa\'yo, <rep_handlename>.","story.map5-dungeon1.017":"Teka,<wait=40> sandali lang...","story.map5-dungeon1.018":"Ibig sabihin, pinamunuan pa rin ni Cardes ang lupaing ito kahit nakakulong na ang kapangyarihan niya, \'di ba? ","story.map5-dungeon1.019":"Baka mas malakas pa siya kaysa sa inakala ko...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"Anyway, <wait=40>kailangan pa rin natin siyang talunin!","story.map5-dungeon1.022":"Pero walang problema \'yan para sa\'yo, <rep_handlename>!","story.map5-dungeon1.023":"Aalis na ako. <wait=20>Kailangan ko pang mag-research tungkol kay Cardes!","story.map5-dungeon1.024":"Good luck!!","story.map5-dungeon2.001":"<size=14><rep_handlename>!","story.map5-dungeon2.002":"<size=14>N-<wait=20>Nasaan ka?","story.map5-dungeon2.003":"<size=20>Ahhhh!!","story.map5-dungeon2.004":"...H-<wait=40>Huwag mo akong gugulatin nang ganyan!","story.map5-dungeon2.005":"Ha?<wait=40><br>Ano\'ng kinatatakutan ko?","story.map5-dungeon2.006":"W-<wait=40>Wala!","story.map5-dungeon2.007":"W-<wait=41>Wala akong kinatatakutan!","story.map5-dungeon2.008":"Walang nakakatakot sa mga barkong multo o kung ano pa man!","story.map5-dungeon2.009":"Ibig kong sabihin, <wait=40>kaya ko pa ngang tumira dito, alam mo ba!","story.map5-dungeon2.010":"Ah!<wait=40> Gets ko na!","story.map5-dungeon2.011":"Sinasabi mo lang \'yan kasi natatakot ka rin, <wait=40>\'di ba <rep_handlename>!?","story.map5-dungeon2.012":"Hehe, <wait=40>duwag pala si <rep_handlename>!","story.map5-dungeon2.013":"Dapat sinabi mo sa akin, <wait=40>pinrotektahan sana kita.","story.map5-dungeon2.014":"Kasi naman, <wait=20>bilang diyosa, hindi lang ako maganda, matapang pa!","story.map5-dungeon2.015":"Oo, <wait=20>tama \'yan!","story.map5-dungeon2.016":"Mukhang may halimaw dito na lumalamon ng kaluluwa ng tao, kaya mag-ingat ka!","story.map5-dungeon2.017":"<size=18>*Splosh*","story.map5-dungeon2.018":"<size=20>Ha?<wait=40> A-Ano \'yon!","story.map5-dungeon2.019":"N-Narinig mo ba, <wait=20>\'yung kakaibang tunog kanina!?","story.map5-dungeon2.020":"Ha?<wait=40> Yabag mo lang pala \'yon?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20><rep_handlename>, ang tanga mo!","story.map5-dungeon2.023":"May dala akong mahalagang impormasyon para sa\'yo, <wait=40>pero ngayon ayoko nang sabihin!","story.map5-dungeon2.024":"Uuwi na ako!","story.map5-dungeon2.025":"Hehe, <wait=40>naniwala ka ba talaga?","story.map5-dungeon2.026":"Natakot ka ba?","story.map5-dungeon2.027":"Hindi naman magagalit nang ganoon ang isang diyosa. ","story.map5-dungeon2.028":"Anyway, <wait=40>ayon sa research ko, ang Palmyna, ang lugar kung saan nakakulong si Cardes...","story.map5-dungeon2.029":"...ay lampas ng Encervis, <wait=40>na nasa kabila lang ng Amdahl.","story.map5-dungeon2.030":"Kailangan muna nating malampasan ang Kastilyo ng Amdahl, <wait=40>saka tayo makakadaan sa Encervis!","story.map5-dungeon2.031":"Kaya bilisan na nating daanan ang lugar na \'to, <wait=40>kinikilabutan talaga ako dito...","story.map5-dungeon2.032":"<size=18>*Splosh* *Splosh*","story.map5-dungeon2.033":"Ha?","story.map5-dungeon2.034":"*Squish* *Squish*","story.map5-dungeon2.035":"<size=20>Ahhh!!","story.map5-dungeon3.001":"<speed=10>Ano\'ng mayroon tayo rito...<wait=40><br>Kakaiba nga ang isang ito sa ibang mga Summoner.","story.map5-dungeon3.002":"Nakapagpasya na ako, <wait=20>tatapusin kita rito.","story.map5-dungeon3.003":"Wala kang dapat ikabahala.<wait=50><br>Matatapos din ang lahat sa lalong madaling panahon.","story.map5-dungeon3.004":"Ang presensyang ito...<wait=20>...","story.map5-dungeon3.005":"Ah, ganoon pala...","story.map5-dungeon3.006":"Nandiyan ka pala!","story.map5-dungeon3.007":"Uy, <wait=40>may problema ba?<wait=40> Mukhang balisa ka.","story.map5-dungeon3.008":"Dapat mas masaya ka sa ganito kagandang panahon! Sige na, ngumiti ka naman!","story.map5-dungeon3.009":"Nandito rin naman ako, <wait=40>kaya umayos ka na!","story.map5-dungeon3.010":"At saka, <wait=40>tingnan mo kung gaano kapayapa ang lugar na \'to.","story.map5-dungeon3.011":"Gusto ko talagang magpahinga kasama ka sa mga ganitong lugar, <rep_handlename>.","story.map5-dungeon3.012":"Hehe, <wait=40>joke lang!","story.map5-dungeon3.013":"May mahalaga kang misyon na talunin ang Apat na Nahulog na Diyos, <rep_handlename>.","story.map5-dungeon3.014":"Wala kang oras para magpalamig-lamig lang!","story.map5-dungeon3.015":"Ha? <wait=40>Paano naman ako?","story.map5-dungeon3.016":"Siyempre wala rin akong ganoong oras...<wait=40> Ibig sabihin...","story.map5-dungeon3.017":"Mukha bang, baka sakali,<wait=40> naglalaro lang ako rito!?","story.map5-dungeon3.018":"Ang kapal ng mukha mo!!","story.map5-dungeon3.019":"Ginagawa ko ang lahat para matulungan ka, <rep_handlename>!","story.map5-dungeon3.020":"Ha? <wait=40>Halimbawa?","story.map5-dungeon3.021":"A-<wait=40>Ang dami kasing hindi ko maipaliwanag...<wait=40> *B<size=15>u<size=14>b<size=13>u<size=12>l<size=11>ong* <size=12>*B<size=11>u<size=10>b<size=9>u<size=8>l<size=7>o<size=6>ng*","story.map5-dungeon3.022":"Anyway, <wait=40>tama na ang tungkol sa akin!","story.map5-dungeon3.023":"Ang mahalaga ngayon ay ang daan sa unahan!","story.map5-dungeon3.024":"O sige, <wait=40>tumungo na tayo sa Kastilyo ng Amdahl!","story.map5-dungeon4.001":"Yuck, <wait=20>ang pangit! <wait=40>Ang dumi-dumi ng lugar na \'to!","story.map5-dungeon4.002":"Kahit si Graham hindi tatapak sa ganitong lugar!","story.map5-dungeon4.003":"Naipaliwanag ko na \'to sa\'yo, \'di ba?","story.map5-dungeon4.004":"Malamang nasa Edila si Graham, ang bayang multo na nasa kabila lang ng mga minahang ito.","story.map5-dungeon4.005":"Tigilan mo na nga ang kakareklamo! <wait=40> Kailangan nating magpatuloy!","story.map5-dungeon4.006":"Kahit ano pa man, <wait=40>puro palpak na impormasyon lang ang nakukuha natin sa Summoners\' Hall!","story.map5-dungeon4.007":"Grabe ka, Seria, <wait=40>ikaw ang pinakamalupit na babaeng kilala ko...","story.map5-dungeon4.008":"Hmm?<wait=40> Oh!<wait=40> <rep_handlename>!","story.map5-dungeon4.009":"Hmph...","story.map5-dungeon4.010":"Nakarating ka rin pala sa Kapuluan ng Palmyna!","story.map5-dungeon4.011":"Sabi ko na, kung may makakarating man, ikaw \'yon, <rep_handlename>.","story.map5-dungeon4.012":"Si Cardes ba ang hinahabol mo?","story.map5-dungeon4.013":"Haha, <wait=40>pakiramdam ko wala siyang laban sa\'yo matapos ang ginawa mo kay Maxwell. ","story.map5-dungeon4.014":"Hmph! <wait=40>Huwag kang masyadong mayabang, <wait=40>baka may masamang mangyari sa\'yo.","story.map5-dungeon4.015":"Ano na naman ba \'yang sinasabi mo? <wait=50> Bakit hindi mo bigyan ng kaunting respeto si <rep_handlename>?<wait=40>","story.map5-dungeon4.016":"*Bonk*","story.map5-dungeon4.017":"<size=18>W-<wait=20>Wala \'yon! <wait=40>Promise, titigil na ako!","story.map5-dungeon4.018":"Anyway, <wait=40>may tauhan si Cardes sa Kapuluan ng Palmyna na kinatatakutan kahit ng pinakamalalakas na puwersa...","story.map5-dungeon4.019":"Mag-alinlangan ka kahit kaunti at tapos ka na!","story.map5-dungeon4.020":"Naku, Seria...","story.map5-dungeon4.021":"Pero sa totoo lang, <wait=40>may katotohanan ang sinasabi niya. ","story.map5-dungeon4.022":"Ang totoo, <wait=40>bukod kay Graham na hinahabol namin ngayon...","story.map5-dungeon4.023":"...May bali-balita ng isang halimaw dito na kasinlakas o mas malakas pa, na kilala bilang Zebra. ","story.map5-dungeon4.024":"Hindi tayo puwedeng magpabaya, <wait=40>kaya mag-ingat tayong lahat sa pagsulong. ","story.map5-dungeon4.025":"Siyanga pala, <wait=40>ano\'ng nangyari sa diyosang \'yon?","story.map5-dungeon4.026":"Para kayong kambal-tuko na hindi mapaghiwalay...","story.map5-dungeon4.027":"Ah, gets ko na!<wait=40> Sawa na ba siya sa pagiging boring mo!?","story.map5-dungeon4.028":"Seria, <wait=40>tama na \'yan.","story.map5-dungeon4.029":"...<wait=40>Biro lang naman \'yon.","story.map5-dungeon4.030":"Papunta kami sa Edila na nasa unahan lang, para habulin si Graham. ","story.map5-dungeon4.031":"Gusto ko sanang lumaban tayo nang magkakasama, <wait=40>pero sa nakakainis na kasamang tulad mo...","story.map5-dungeon4.032":"Hindi naman ako nakakainis...","story.map5-dungeon4.033":"Haha... <wait=40>So, balak mo bang magpatuloy nang mag-isa?","story.map5-dungeon4.034":"May mababangis na kalaban sa unahan,<wait=40> pero naniniwala akong makakaligtas tayo at magkikita ulit!","story.map5-dungeon4.035":"Karl! <wait=40>Wala tayong oras para magpalaboy-laboy, tara na!","story.map5-dungeon4.036":"Galingan mo para hindi ka maging biktima ng mga demonyong \'yon!","story.map5-dungeon4.037":"T-<wait=40>Teka, <wait=40>hintay!","story.map5-dungeon4.038":"Hay naku... <wait=40>O sige, <wait=20>hanggang sa muli, <rep_handlename>!","story.map5-dungeon5.001":"Ah, <wait=40>ang sarap dito!","story.map5-dungeon5.002":"Oh, <wait=40><rep_handlename>!","story.map5-dungeon5.003":"Nakarating ka nang buo. <wait=40>Alam kong kaya mo!","story.map5-dungeon5.004":"Kahit naniniwala ako sa\'yo, nakahinga pa rin ako nang maluwag nang makita kita.","story.map5-dungeon5.005":"Ha? <wait=40>Ano\'ng ginagawa ko?","story.map5-dungeon5.006":"Hehe, <wait=40>siyempre nag-eenjoy ako sa santuwaryo!","story.map5-dungeon5.007":"Bawat sulok ay puno ng liwanag, <wait=20>walang tatalo sa isang magandang santuwaryo.","story.map5-dungeon5.008":"Hindi kayang tanggihan ng isang diyosang tulad ko ang solemne nitong kapaligiran at ang magandang liwanag.","story.map5-dungeon5.009":"At walang mga kakaibang tunog tulad ng narinig natin sa barkong multo!","story.map5-dungeon5.010":"<size=18>*Kaluskos* *Kaluskos*","story.map5-dungeon5.011":"Ano \'yon!?<wait=40> Sino \'yan!?","story.map5-dungeon5.012":"Ho ho ho. <wait=40><br>Nagulat ba kita?","story.map5-dungeon5.013":"Patawarin mo ako, <wait=20>binibini.","story.map5-dungeon5.014":"Hindi ko sinadyang takutin ka, <wait=40>napakaganda lang kasi ng boses mo. ","story.map5-dungeon5.015":"Ah, <wait=40>e-<wait=40>ehh...","story.map5-dungeon5.016":"Sino ka, lolo?","story.map5-dungeon5.017":"Ho ho ho. <wait=40><br>Paumanhin.","story.map5-dungeon5.018":"Ako si Grah. <wait=40><br>Pakitawag mo akong Elder Grah.","story.map5-dungeon5.019":"Elder Grah, ha...","story.map5-dungeon5.020":"Ho ho ho. <wait=40><br>Magandang pangalan, hindi ba?","story.map5-dungeon5.021":"Sinabi ko na ang pangalan ko, <wait=40>hindi mo ba sasabihin ang sa\'yo?","story.map5-dungeon5.022":"Ehh, <wait=40>ako si Tilith! <wait=40>Isa lang akong normal na babae, walang pinagkaiba sa iba.","story.map5-dungeon5.023":"At itong kaibig-ibig na tao rito ay si <rep_handlename>!","story.map5-dungeon5.024":"Napakalakas na Summoner ni <rep_handlename>!","story.map5-dungeon5.025":"Napakatapang.","story.map5-dungeon5.026":"So, Elder Grah, <wait=40>ano\'ng ginagawa mo sa ganitong lugar?","story.map5-dungeon5.027":"Aba, <wait=40>maglalakad-lakad lang sana ako roon.","story.map5-dungeon5.028":"Maglalakad-lakad, kamo...","story.map5-dungeon5.029":"Akala ko puno ng mga halimaw ang lugar na \'to...","story.map5-dungeon5.030":"Hmm, <wait=20>mukhang hindi nila ako pinansin. ","story.map5-dungeon5.031":"Hmm...<wait=40> Medyo kahina-hinala ka pa rin para sa akin...","story.map5-dungeon5.032":"Tingnan mo lang \'yang malalakas na sandatang dala mo...","story.map5-dungeon5.033":"He he he...","story.map5-dungeon5.034":"Mukhang nabisto na ako!","story.map5-dungeon5.035":"Ako, sa totoo lang, <wait=20>si Grah, ang diyos na namumuno sa lupaing ito!","story.map5-dungeon5.036":"At ngayon, sisiguraduhin kong maglalaho kayong dalawa rito agad-agad!","story.map5-dungeon5.037":"Ano!?","story.map5-dungeon5.038":"Binibiro lang kita.","story.map5-dungeon5.039":"Ho ho ho. <wait=40><br>Natakot ba kita?","story.map5-dungeon5.040":"Ang cute-cute mo kapag nagugulat ka, binibini.","story.map5-dungeon5.041":"Pfffft!","story.map5-dungeon5.042":"Patawarin mo ako, pakiusap.","story.map5-dungeon5.043":"Noong unang panahon, nagkaroon ako ng isang uri ng pakikipagsapalaran. ","story.map5-dungeon5.044":"Ginamit ko ang sibat na ito noon, <wait=40>pero halos palamuti na lang ito ngayon.","story.map5-dungeon5.045":"Nandito ako ngayon para siyasatin ang alamat ng Apat na Sinaunang Bayani, <wait=40>pero mukhang wala akong mahahanap na mahalaga rito.","story.map5-dungeon5.046":"O sige, <wait=40>sa tingin ko oras na para umalis ako.","story.map5-dungeon5.047":"Dahil nakilala ko ang isang kawili-wiling Summoner, <wait=40>masasabi kong magandang araw ito. ","story.map5-dungeon5.048":"O sige, <wait=40>inaabangan ko ang muli nating pagkikita.","story.map5-dungeon5.049":"\'Yung matandang \'yon, <wait=40>medyo weird siya, \'no?","story.map5-dungeon5.050":"Hindi naman basta-basta makakagala ang normal na tao rito.","story.map5-dungeon5.051":"Siguradong may itinatago siya<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"Anyway, <wait=40>walang silbing mag-alala diyan ngayon.","story.map5-dungeon5.053":"Wala rin naman itong epekto sa layunin natin!","story.map5-dungeon5.054":"O sige, <wait=40>bilisan nating daanan \'to tapos tumungo sa Kastilyo ng Amdahl!","story.map5-dungeon6.001":"Seria!<wait=40> Kumusta riyan!?","story.map5-dungeon6.002":"Wala!<wait=40> Walang bakas niya kahit saan...","story.map5-dungeon6.003":"Bwisit! <wait=40>Nakatakas na naman siya!","story.map5-dungeon6.004":"Sa ganitong takbo, <wait=40>hindi natin sila maipaghihiganti kailanman...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>Ha!?<wait=40> <size=16>Saan ka nanggaling?","story.map5-dungeon6.007":"Si <rep_handlename> pala...","story.map5-dungeon6.008":"Hehe, <wait=40>mukhang naabutan mo kami sa masamang pagkakataon.","story.map5-dungeon6.009":"Muli, <wait=20>nakawala na naman sa amin si Graham.","story.map5-dungeon6.010":"Kumpara sa\'yo na matapang na lumaban sa Apat na Nahulog na Diyos, <wait=20>siguro nakakaawa kaming tingnan...","story.map5-dungeon6.011":"Ano ba\'ng sinasabi mo!","story.map5-dungeon6.012":"Sinuwerte lang si <rep_handlename>!<wait=40> Karl, nakatalo ka na ng mga kalabang daan-daang beses na mas malakas kaysa sa natalo niya!","story.map5-dungeon6.013":"Haha, <wait=40>maraming salamat, Seria.","story.map5-dungeon6.014":"Talagang espesyal na mapuri mo.","story.map5-dungeon6.015":"Wala na siguro akong dahilan para malungkot, \'no!","story.map5-dungeon6.016":"Ano\'ng ibig mong sabihin sa \\"espesyal?\\"","story.map5-dungeon6.017":"Haha, <wait=40>nagpapasalamat lang ako, \'yon lang. ","story.map5-dungeon6.018":"Ah, at <rep_handlename>...","story.map5-dungeon6.019":"Hindi lang dahil malakas si Graham kaya nakawala na naman siya sa amin...","story.map5-dungeon6.020":"Nang maabutan namin siya ngayon, <wait=40>may kasama siyang isa pang napakalakas na halimaw.","story.map5-dungeon6.021":"Pasensya na kung malabo ang paliwanag ko.","story.map5-dungeon6.022":"Sa totoo lang, <wait=40>hindi talaga namin nakita ang isa pang halimaw.","story.map5-dungeon6.023":"Nang maramdaman pa lang namin ang matindi nitong kapangyarihan, <wait=40>literal kaming tumilapon.","story.map5-dungeon6.024":"Pagkagising namin, <wait=40>naglaho na si Graham kung saan.","story.map5-dungeon6.025":"Nahuli sana natin siya kung hindi tayo inatake nang ganoon...","story.map5-dungeon6.026":"Siguro tama ka...","story.map5-dungeon6.027":"Pero, <wait=40>ang tanging sigurado lang tayo ay walang normal na nilalang ang may ganoong kapangyarihan...","story.map5-dungeon6.028":"Tama ka diyan...","story.map5-dungeon6.029":"Anyway, <wait=40>suwerte tayo at hindi gaanong marami ang nasawi.","story.map5-dungeon6.030":"Ipagpapatuloy namin ang paghahanap kay Graham.","story.map5-dungeon6.031":"Papunta ka sa Kastilyo ng Amdahl sa unahan, tama ba?","story.map5-dungeon6.032":"Nararamdaman ko rin ang isang malakas at mapanganib na presensya mula roon.","story.map5-dungeon6.033":"Siguraduhin mong mag-ingat nang husto.","story.map5-dungeon6.034":"Kapag nakasalubong mo ang halimaw na \'yon, tapos ka!","story.map5-dungeon6.035":"Haha, <wait=40>mahigpit ka pa rin kay <rep_handlename>, gaya ng dati.","story.map5-dungeon6.036":"H-<wait=40>Hindi lang naman si <rep_handlename> ang hinihigpitan ko...","story.map5-dungeon6.037":"Nandiyan ka pala!","story.map5-dungeon6.038":"Saan ka ba nanggaling! <wait=40>Kanina pa kita hinahanap kung saan-saan!","story.map5-dungeon6.039":"Ha?<wait=40> Ano \'to?<wait=40><br>Nakita ko na kayong lahat dati, \'di ba?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Kumusta, diyosa.<wait=40> Matagal tayong hindi nagkita.","story.map5-dungeon6.042":"Ang tagal nga!<wait=40> Malakas ka pa rin gaya ng dati, Karl!","story.map5-dungeon6.043":"At ikaw, <wait=40>ginugulo mo na naman ba ang mahal kong <rep_handlename> gaya ng lagi mong ginagawa?","story.map5-dungeon6.044":"<size=18>Ano\'ng ibig mong sabihin sa \\"ginugulo!\\"","story.map5-dungeon6.045":"At gaya ng sinabi ko dati, <wait=40>hindi sa\'yo si <rep_handlename>!","story.map5-dungeon6.046":"Bakit ka ba nagagalit?<wait=40> Baka <wait=20>nagseselos ka? ","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Klang*","story.map5-dungeon6.049":"<size=18>S-Sandali lang!","story.map5-dungeon6.050":"Kumalma ka, Seria!","story.map5-dungeon6.051":"T-<wait=20>Tara na, <wait=40>kailangan nating balikan ang bakas ni Graham!","story.map5-dungeon6.052":"T-<wait=40>Tama!?","story.map5-dungeon6.053":"<speed=14>O sige, <wait=20><rep_handlename>!","story.map5-dungeon6.054":"<speed=14>Mangako tayong dalawa na gagawin natin ang lahat sa daan sa unahan!","story.map5-dungeon6.055":"<speed=14>Sige, aalis na kami! Ikaw rin, Seria!","story.map5-dungeon6.056":"Karl! <wait=20> Teka!<wait=40> Naiintindihan ko, <wait=40>huwag mo naman akong hilahin nang ganyan kalakas!","story.map5-dungeon6.057":"Diyosa! <wait=40>Umayos ka, ha!","story.map5-dungeon6.058":"Pfft!!","story.map5-dungeon6.059":"Hay, <wait=40>sa wakas umalis na rin siya.","story.map5-dungeon6.060":"Pero, <wait=40>sana matalo nila si Graham!","story.map5-dungeon6.061":"Malapit na tayo. <wait=40>Pagkalampas natin dito, nasa tarangkahan na tayo ng Kastilyo ng Amdahl!","story.map5-dungeon6.062":"Umaasa ako sa\'yo!","story.map5-dungeon7.001":"Sa wakas, nakarating din tayo.","story.map5-dungeon7.002":"Malampasan lang natin ang Kastilyo ng Amdahl, diretso na ang daan papuntang Encervis.","story.map5-dungeon7.003":"Saka tayo isang hakbang na mas malapit kay Cardes at sa lupaing kinakulungan niya.","story.map5-dungeon7.004":"Hehe, <wait=40>huwag kang masyadong kabahan.","story.map5-dungeon7.005":"Alam kong kaya mo, <rep_handlename>!","story.map5-dungeon7.006":"Bilisan na nating lampasan ang kastilyong ito!","story.map5-dungeon7.007":"Akala mo ba talaga ganoon lang kadali?","story.map5-dungeon7.008":"Ha-!!","story.map5-dungeon7.009":"Nagulat na naman ba kita?","story.map5-dungeon7.010":"Ang kapal mo! <wait=40>Huwag mo akong gugulatin nang ganyan!!","story.map5-dungeon7.011":"Ho ho ho.","story.map5-dungeon7.012":"Kasing-cute ka pa rin ng naaalala ko, binibini.","story.map5-dungeon7.013":"Hmph, <wait=40>ang sama mo...","story.map5-dungeon7.014":"Ho ho ho.","story.map5-dungeon7.015":"Anyway, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Napansin mo rin, hindi ba? <wait=40>Ang masamang presensya sa unahan...","story.map5-dungeon7.017":"Oo, <wait=40>kita ko sa mukha mo.","story.map5-dungeon7.018":"O sige, <wait=40>sasabihin ko na sa\'yo kung ano ang aasahan mo.","story.map5-dungeon7.019":"Sa unahan lang, naghihintay sa\'yo ang dating amo ng kastilyong ito.","story.map5-dungeon7.020":"Ang huling emperador ng Imperyo ng Amdahl na winasak ng Palmyna. ","story.map5-dungeon7.021":"Multo na siya ngayon, at may matindi siyang galit sa mga tao.","story.map5-dungeon7.022":"Isang multong galit sa mga tao...","story.map5-dungeon7.023":"Ho ho ho.","story.map5-dungeon7.024":"Ano ba\'ng inaasahan mo?","story.map5-dungeon7.025":"Hindi lahat ng umiiral dito sa Grand Gaia ay may kinalaman sa mga diyos.","story.map5-dungeon7.026":"Madali itong makita kapag tiningnan mo ang kasaysayan ng tao...","story.map5-dungeon7.027":"Mas marami pang tao ang pinatay ng kapwa nila tao kaysa sa winasak ng mga diyos.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Ho ho ho.","story.map5-dungeon7.030":"Anyway, <wait=40>medyo matanda na ako para dito, <wait=40>sa tingin ko dapat na akong umalis.","story.map5-dungeon7.031":"Pero bago ako umalis, <wait=40>kahit diyosa siya, may mga kahinaan pa rin siya.","story.map5-dungeon7.032":"Gawin mo ang lahat para protektahan siya.","story.map5-dungeon7.033":"Ha?<wait=40> Sandali lang!","story.map5-dungeon7.034":"Ho ho ho.","story.map5-dungeon7.035":"Wala na siya...","story.map5-dungeon7.036":"Kailan ko sinabi kay Elder Grah na diyosa ako?","story.map5-dungeon7.037":"Ang dami niyang alam, <wait=40>sino ba talaga siya?","story.map5-dungeon7.038":"Ah, <wait=40>bahala na!","story.map5-dungeon7.039":"Walang silbing mag-alala diyan ngayon! <wait=40>","story.map5-dungeon7.040":"Kailangan nating malampasan \'to bago natin harapin si Cardes!","story.map5-dungeon7.041":"Hay <rep_handlename>, hindi ko alam ang iisipin ko sa usapang multo na \'to...","story.map5-dungeon7.042":"...pero kahit ano pa \'yan, patumbahin natin! <wait=40>Siguradong magugulat si Elder Grah!","story.map5-ending.001":"Nagawa mo, <rep_handlename>!","story.map5-ending.002":"Ang hina naman ng lalaking \'yon!","story.map5-ending.003":"Kahit ang mga multo ng mga sinaunang emperador ay walang laban sa\'yo, <rep_handlename>!","story.map5-ending.004":"<size=18>Wow!","story.map5-ending.005":"Ha-!!","story.map5-ending.006":"Uy, <wait=40>bakit lagi mo na lang akong ginugulat...","story.map5-ending.007":"Pasensya na, <wait=40>pareho lang kasi tayo ng nararamdaman, Tilith...","story.map5-ending.008":"Nagulat din ako sa ginawa ni <rep_handlename> sa multong \'yon.","story.map5-ending.009":"Hmph.","story.map5-ending.010":"Ho ho ho.","story.map5-ending.011":"Pero, <wait=40>para matalo ni <rep_handlename> ang multo ng isang emperador nang ganoon...","story.map5-ending.012":"Hehe, <wait=40>ano?","story.map5-ending.013":"Ibig sabihin, talagang kahanga-hangang Summoner si <rep_handlename>, \'di ba?","story.map5-ending.014":"Hmm, <wait=40>talagang napakagandang salpukan ng mga espada iyon.","story.map5-ending.015":"Masasabi ko, <wait=40>magaling.","story.map5-ending.016":"<size=18><rep_handlename>!<wait=40> Buhay ka pa!!","story.map5-ending.017":"Hingal... <wait=40>hingal...","story.map5-ending.018":"T-<wait=40>Teka lang...","story.map5-ending.019":"A-<wait=40>Ano\'ng nangyari sa multong \'yon?","story.map5-ending.020":"Tinalo \'yon ni <rep_handlename>!","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Hmph...<wait=40><br>Karrrrrrll!!","story.map5-ending.023":"So nag-alala ka rin pala kay <rep_handlename>, \'di ba Seria!?","story.map5-ending.024":"Mukhang may maalalahanin ka rin palang side.","story.map5-ending.025":"H-<wait=40>Hindi gano\'n!<wait=40> Nabalitaan ko lang na may nagpakitang Graham sa paligid dito...","story.map5-ending.026":"Sige na, <wait=20>hindi mo kailangang magtago sa ganyang halatang kasinungalingan.","story.map5-ending.027":"Grr...","story.map5-ending.028":"Ho ho ho.","story.map5-ending.029":"<size=20>!?","story.map5-ending.030":"Mukhang hindi pa tayo nagkakakilala.","story.map5-ending.031":"Bb. Seria, <wait=40>pakitawag mo akong Elder Grah.","story.map5-ending.032":"Ha!?<wait=40> E-<wait=40>Elder Grah?","story.map5-ending.033":"Tama.","story.map5-ending.034":"Ha, <wait=40>pero... <wait=40>I-<wait=40>ibig kong sabihin...","story.map5-ending.035":"Elder Grah.","story.map5-ending.036":"Tandaan mo \'yan, <wait=40>Bb. Seria.","story.map5-ending.037":"Elder Grah, <wait=40>ang weird mo talagang matanda, \'no!","story.map5-ending.038":"Lagi kang biglang sumusulpot sa mga kakaibang lugar, <wait=40>at alam mo ang mga pinakamalabong bagay.","story.map5-ending.039":"At lagi mo pa akong ginugulat!","story.map5-ending.040":"A-<wait=40>A-<wait=40>Ano\'ng sinasabi mo!?<wait=40> Ang taong ito ay...","story.map5-ending.041":"...si Elder Grah, isang mapagbirong matanda lang.","story.map5-ending.042":"Tama, <wait=40>Bb. Seria?","story.map5-ending.043":"Ha?<wait=40> O-<wait=40>Oo, <wait=20>tama...","story.map5-ending.044":"Ho ho ho.","story.map5-ending.045":"Hmph, <wait=40>may kakaiba sa\'yo, Seria!","story.map5-ending.046":"B-<wait=40>Bahala ka! <wait=40>May iniisip lang ako!","story.map5-ending.047":"Tulad ng ano?","story.map5-ending.048":"W-<wait=40>Wala kang pakialam!","story.map5-ending.049":"Hmph, <wait=40>ano ba\'ng nangyayari sa\'yo!","story.map5-ending.050":"Baka naiinis ka kasi niloko ka ni Karl para habulin kami?","story.map5-ending.051":"H-<wait=40>Ha? <wait=20>Paano mo nalaman \'yon!?","story.map5-ending.052":"Alam ng diyosa ang lahat!","story.map5-ending.053":"At anong klaseng diyosa ka!?<wait=40> Wala kang magawa nang mag-isa!","story.map5-ending.054":"Ang sama mo!","story.map5-ending.055":"Uy <rep_handlename>, <wait=40>tulungan mo naman ako at magsalita ka!","story.map5-ending.056":"Bakit?<wait=40> Alam mo na naman ang sasabihin ni <rep_handlename>, \'di ba?","story.map5-ending.057":"Ho ho ho.","story.map5-ending.058":"Puno talaga ng sigla ang mga kabataan.","story.map5-ending.059":"Anyway, <rep_handlename>...","story.map5-ending.060":"Sa pagtalo mo sa multong iyon, <wait=40>nasira mo ang harang na bumabalot sa rehiyong ito.","story.map5-ending.061":"Di magtatagal, bubukas na ang daan patungong Encervis.","story.map5-ending.062":"Malamang naghihintay sa\'yo si Zebra...","story.map5-ending.063":"...ang demonyong kasalukuyang namumuno sa Kapuluan ng Palmyna kapalit ni Cardes.","story.map5-ending.064":"Magsanay ka nang mabuti, at huwag mong hayaang humarang ang yabang mo.","story.map5-ending.065":"Ah!<wait=40> Sasabihin ko sana \'yan!","story.map5-ending.066":"Puro kahangalan ang sinasabi mo, <wait=40>ipaubaya mo na lang \'to kay Grahde...","story.map5-ending.067":"Kay Elder Grah! Ipaubaya mo kay Elder Grah!","story.map5-ending.068":"Kahangalan, kamo!?","story.map5-ending.069":"Ano\'ng masama sa pagsasabi kung ano ka talaga?","story.map5-ending.070":"\'Yan na!<wait=40> Ipapakita ko sa\'yo ang tunay na kapangyarihan ng isang diyosa!","story.map5-ending.071":"Sige, labanan mo ako!<wait=50> Ipapakita ko sa\'yo kung gaano ako kalakas kaysa sa\'yo!","story.map5-ending.072":"<size=20>Humanda ka!!","story.map5-ending.073":"Ho ho ho.","story.map5-ending.074":"Ang iinit ng dugo ninyong dalawang dalaga, \'no.","story.map5-ending.075":"Anyway, <wait=40><rep_handlename>...","story.map5-ending.076":"Dapat na tayong bumalik sa Elgaia.","story.map5-ending.077":"<rep_handlename>! <wait=40>Sandali lang!","story.map5-ending.078":"May mensahe ako mula kay Karl!","story.map5-ending.079":"Sabi niya, \\"Naniniwala ako sa lakas mo.\\"","story.map5-ending.080":"Ito ba talaga ang tamang oras para diyan!?","story.map5-ending.081":"<rep_handlename>!","story.map5-ending.082":"Tumungo tayo sa Encervis pagkatapos kong turuan si Seria ng kaunting respeto!","story.map5-ending.083":"Kung sa tingin mo kaya mo akong talunin, <wait=40>subukan mo!","story.map5-ending.084":"\'Yan na!!<wait=40> Oras na para ipakita ko sa\'yo ang napakalakas kong mahika!","story.map5-ending.085":"Hmph, <wait=40>mukhang seryoso ka. <wait=40>OK, <wait=40>sige na!","story.map5-ending.086":"<size=20>Heto!!","story.map5-ending.087":"O sige, <wait=40>aalis na siguro tayo...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ikaw, <rep_handlename>,<wait=40> na tumalo kay Maxwell, ang Diyosa ng Paglikha…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ang krisis na dulot ng Apat na Nahulog na Diyos,<wait=40> nagpapatuloy pa rin…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Upang magdala ng bagong pag-asa sa mundong ito na puno ng kalungkutan…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kailangan mong manalig sa iyong kapangyarihan, <wait=20>at magpatuloy sa pagsulong…","story.map5-open.005":"<size=22>Late ka!","story.map5-open.006":"Bakit ang tagal mo!?","story.map5-open.007":"Ang tagal-tagal na kitang hinihintay, <rep_handlename>!","story.map5-open.008":"Hindi mo ba naiisip na masyado ka nang nagpabaya mula nang talunin mo si Maxwell?","story.map5-open.009":"<size=20>Hehe, <wait=20>huli ka!!","story.map5-open.010":"Kausap ko si Lucius, <wait=40>kararating ko lang din. ","story.map5-open.011":"Anyway, <wait=40>susunod na ang Kapuluan ng Palmyna!","story.map5-open.012":"Matapos makita kung gaano ka talaga kalakas sa St. Lamia...","story.map5-open.013":"...malaki ang inaasahan ko sa\'yo ngayon!","story.map5-open.014":"Galingan natin！","story.map5-open.015":"*Tok* <wait=20>*Tok*","story.map5-open.016":"Paumanhin sa abala. ","story.map5-open.017":"May bagong impormasyon ako mula sa departamento ng intelligence.","story.map5-open.018":"Mukhang nasira na ang harang na nagpoprotekta sa Kapuluan ng Palmyna. ","story.map5-open.019":"...<wait=40>Oo, <wait=40>natanggap ko ang ulat kanina lang. ","story.map5-open.020":"Mukhang lalo silang nagiging ambisyoso. ","story.map5-open.021":"Iimbestigahan ko agad.","story.map5-open.022":"Hindi, <wait=40>ipagpatuloy mo ang kasalukuyan mong tungkulin. ","story.map5-open.023":"Hindi ko hahayaang madamay ang mahalaga kong tauhan sa kung ano mang binabalak ng grupong iyon. ","story.map5-open.024":"S-<wait=20>Salamat po...<br>O sige, <wait=20>babalik na ako sa trabaho ko. ","story.map5-open.025":"Ang Apat na Nahulog na Diyos...","story.map5-open.026":"Sinasabing may kapangyarihan silang wasakin ang buong Grand Gaia. ","story.map5-open.027":"Gusto kong makita kung gaano talaga sila kalakas...","story.map6-dungeon1.001":"Ang init, init, init!!","story.map6-dungeon1.002":"Bakit ba ang tindi ng init dito!","story.map6-dungeon1.003":"Sana man lang may malamig na hangin paminsan-minsan!","story.map6-dungeon1.004":"Tingnan mo nga kung gaano ako pinagpapawisan!","story.map6-dungeon1.005":"Sinabi ko na sa\'yo minsan, <wait=40>ayoko sa mainit na lugar!","story.map6-dungeon1.006":"Tandaan mo \'yan sa susunod na pipili ka ng tagpuan, <rep_handlename>!","story.map6-dungeon1.007":"Hmm, <wait=40>pero kahit ano pa, umaasa talaga sa\'yo si Lord Lucius, <rep_handlename>...","story.map6-dungeon1.008":"Siguro kailangan ko ring magsikap nang mas higit kaysa dati...","story.map6-dungeon1.009":"A-<wait=20>Ano\'ng itsura \'yan!?","story.map6-dungeon1.010":"A-<wait=40>Ano\'ng ibig mong sabihin na hindi raw ako nagsisikap!?","story.map6-dungeon1.011":"Grr, <wait=40>ang sama mo talaga.","story.map6-dungeon1.012":"Kaya ka lang hindi madalas inaatake ay dahil nasa tabi mo ako!","story.map6-dungeon1.013":"Walang maglalakas-loob na lumapit sa akin, <wait=40>takot silang lahat sa astig kong kapangyarihan!","story.map6-dungeon1.014":"Siguradong kahit ngayon, may mga masasamang nilalang na nakatutok sa\'yo, <rep_handlename>.","story.map6-dungeon1.015":"Hehe, <wait=40>joke lang!","story.map6-dungeon1.016":"Imposibleng hindi ko mapansin kung may ganoong nilalang talaga sa paligid!","story.map6-dungeon1.017":"May makikita kang lawa paglabas mo sa sobrang init na lugar na \'to...","story.map6-dungeon1.018":"Sa kabila lang nito ay may magandang kastilyo, <wait=40>doon tayo magkita sa susunod!","story.map6-dungeon1.019":"Mag-ingat ka hanggang doon, ha.","story.map6-dungeon1.020":"At kung magkaproblema ka, puwede ka namang magdasal sa maganda mong diyosa!","story.map6-dungeon2.001":"<size=18>*Klang*","story.map6-dungeon2.002":"<speed=10>He he he...<wait=40> Hindi ko akalaing kakailanganin kong gamitin nang ganoon ang kapangyarihan ko.","story.map6-dungeon2.003":"Mukhang mapanganib ka nga talaga.","story.map6-dungeon2.004":"Gayunpaman, agad kong tatapusin ang sinumang humarang sa mga plano ko.","story.map6-dungeon2.005":"Buburahin kita sa mundong ito bago mo pa mamalayan.","story.map6-dungeon2.006":"Akala mo ba ganoon lang kadali \'yon?","story.map6-dungeon2.007":"!?","story.map6-dungeon2.008":"Kahit diyos ka, <wait=40>balak mo pa ring magyabang nang ganyan sa isang nag-iisang Summoner?","story.map6-dungeon2.009":"Ahh...<wait=40> Mukhang kilala mo kung sino ako.","story.map6-dungeon2.010":"Tila may nakasalubong na naman akong hindi inaasahang salik.","story.map6-dungeon2.011":"Pero hindi na \'yon mahalaga. <wait=40>Anuman ang mangyari ngayon, iisa pa rin ang kahihinatnan.","story.map6-dungeon2.012":"Ang sinimulan ko ang tuluyang wawakas sa buong sangkatauhan.","story.map6-dungeon2.013":"Ano!? <wait=40>Ibig mo bang sabihin napalipad mo na ang Kuta sa Langit?","story.map6-dungeon2.014":"...<wait=40>Sino ka ba talaga?","story.map6-dungeon2.015":"Mabuti pang tapusin na kita rito mismo...","story.map6-dungeon2.016":"Ho ho ho.<wait=40> Uulitin ko ba?","story.map6-dungeon2.017":"Akala mo ba ganoon lang kadali \'yon?","story.map6-dungeon2.018":"Ang kapangyarihang ito...<wait=40>...","story.map6-dungeon2.019":"Ganoon pala. <wait=40>Kung gayon, ikaw pala si... ","story.map6-dungeon2.020":"Summoner, <wait=40>napukaw mo ang interes ko.","story.map6-dungeon2.021":"Mukhang marami-rami ring diyos ang nasa panig mo. ","story.map6-dungeon2.022":"Babantayan ko pa ang mga kilos mo nang kaunting panahon...","story.map6-dungeon2.023":"Ho ho ho.<wait=40> Mukhang nakaligtas tayo sa gulo.","story.map6-dungeon2.024":"Pero <wait=40>mabigat pa rin ang sitwasyon. ","story.map6-dungeon2.025":"Si Zebra \'yon, <wait=20>lingkod ni Cardes na Malupit, <wait=40>isa sa Apat na Nahulog na Diyos.","story.map6-dungeon2.026":"Mukhang sa paanuman ay nabuhay niyang muli ang maalamat na Kuta sa Langit ng Imperyo ng Amdahl.","story.map6-dungeon2.027":"Hindi kailangan ng mundong ito ang ganoong bagay.","story.map6-dungeon2.028":"Ang paglabas ng ganoong bagay ay hahantong lang sa mas maraming labanan.","story.map6-dungeon2.029":"Papunta ka sa Palmyna, hindi ba?","story.map6-dungeon2.030":"Habang hinahabol mo si Zebra, <wait=40>bakit hindi mo na rin pabagsakin ang Kuta sa Langit?","story.map6-dungeon2.031":"Ho ho ho.","story.map6-dungeon2.032":"Ano\'ng problema?<wait=40> Wala kang dapat ikabahala.","story.map6-dungeon2.033":"Kasama mo naman ang binibini, hindi ba?","story.map6-dungeon2.034":"Basta\'t nasa proteksyon ka ng diyosa, <wait=40>magiging ayos ka lang.","story.map6-dungeon2.035":"Pakinggan mo lang ang sinasabi niya!","story.map6-dungeon2.036":"Hmph<wait=40>...","story.map6-dungeon2.037":"Sa totoo lang,<wait=40> mukhang hindi na malinaw kung sino ang nagliligtas kanino sa inyong dalawa.","story.map6-dungeon2.038":"Ho ho ho.","story.map6-dungeon2.039":"Aalis na ako.<wait=40> Pakikumusta mo ako sa binibini.","story.map6-dungeon3.001":"Hoy, <wait=40><rep_handlename>!","story.map6-dungeon3.002":"Kanina pa ako naghihintay.","story.map6-dungeon3.003":"Ha? <wait=40>Ano\'ng nangyari?<wait=40> Bakit ang seryoso ng mukha mo?","story.map6-dungeon3.004":"Ano\'ng sabi mo!?<wait=40> Binuhay ni Zebra ang Kuta sa Langit!?","story.map6-dungeon3.005":"Paano niya nagawa...","story.map6-dungeon3.006":"Pero teka, <wait=40>ano ba ang Kuta sa Langit? Importante ba \'yon?","story.map6-dungeon3.007":"A-<wait=20>Ano\'ng itsura \'yan!? <wait=40>May mga bagay talagang hindi alam kahit ng mga diyosa!","story.map6-dungeon3.008":"Ho ho ho.","story.map6-dungeon3.009":"Tama, para sa isang diyosa, walang kuwenta ang ganyang mga sandata ng tao.","story.map6-dungeon3.010":"Oh, <wait=40>Elder Grah.","story.map6-dungeon3.011":"Ha? <wait=40>Hindi mo ako tatakutin ngayon?","story.map6-dungeon3.012":"Ay, <wait=40>paumanhin.","story.map6-dungeon3.013":"Mukhang nabigo ko ang inaasahan ng binibini.","story.map6-dungeon3.014":"Kung gayon, <wait=40>hayaan mong ulitin ko mula sa simula.","story.map6-dungeon3.015":"Hindi na kailangan!","story.map6-dungeon3.016":"Ho ho ho.","story.map6-dungeon3.017":"Siyanga pala, <wait=40>may sasabihin ako sa inyo, puwede bang makinig kayo sandali?","story.map6-dungeon3.018":"Ito ang kuwento ng maalamat na \\"Kuta sa Langit\\" ng Imperyo ng Amdahl.","story.map6-dungeon3.019":"\'Yan ang sinasabi ni <rep_handlename>, <wait=40>ang binuhay ni Zebra, \'di ba?","story.map6-dungeon3.020":"Oo, <wait=40>tama ka.","story.map6-dungeon3.021":"Sinubukan din itong buhayin ng mga tao noong unang panahon.","story.map6-dungeon3.022":"Hindi alam kung sino ang gumawa nito, kailan ito ginawa, o kahit paano ito ginawa...","story.map6-dungeon3.023":"Mukhang ang tanging naiwan sa Imperyo ng Amdahl ay mga tagubilin kung paano ito gamitin at paliwanag ng mga kakayahan nito.","story.map6-dungeon3.024":"Matagal itong ipinagbawal ng pamilya ng emperador... ","story.map6-dungeon3.025":"...pero may isang emperador na nagpasyang suwayin iyon.","story.map6-dungeon3.026":"Matagal itong ikinandado ng Imperyo ng Amdahl, sa sali\'t saling lahi...","story.map6-dungeon3.027":"...binasag ng huling emperador ng Imperyo ng Amdahl, si Myzelion the Fourth, ang selyo...","story.map6-dungeon3.028":"...at ginamit ang kapangyarihan ng Kuta sa Langit para salakayin ang mga karatig-bansa at sakupin ang mga ito. ","story.map6-dungeon3.029":"Habang nangyayari ang lahat ng ito, <wait=20>nabalitaan ng hari ng Palmyna ang mga plano ng emperador.","story.map6-dungeon3.030":"Nakiusap siya kay Myzelion the Fourth, pero matigas ang ulo nito at ayaw sumuko. ","story.map6-dungeon3.031":"Sa huli, <wait=20>ginamit ng hari ng Palmyna ang lakas niya para supilin ang Amdahl...","story.map6-dungeon3.032":"...at dinurog sila bago pa nila mabuhay muli ang Kuta sa Langit. ","story.map6-dungeon3.033":"Umm, <wait=40>so ibig sabihin...","story.map6-dungeon3.034":"Sobrang delikado ng Kuta sa Langit na sulit pang wasakin ang isang buong bansa para lang hindi ito mabuhay muli?","story.map6-dungeon3.035":"Oo, <wait=40>ganoon nga.","story.map6-dungeon3.036":"Hindi nga!?<wait=40> At \'yon ang binuhay ni Zebra!?","story.map6-dungeon3.037":"Mismo.","story.map6-dungeon3.038":"Malaking problema \'to!!","story.map6-dungeon3.039":"Pero <wait=40>wala naman \'yong kinalaman sa layunin natin!","story.map6-dungeon3.040":"<rep_handlename>!<wait=40> Ituloy natin ang paghabol kay Cardes!","story.map6-dungeon3.041":"At ikaw, Elder Grah, <wait=40>ikaw na ang bahalang magpabagsak sa Kuta sa Langit!","story.map6-dungeon3.042":"Ha!?<wait=40> Binibini, imposible \'yan para sa akin.","story.map6-dungeon3.043":"Hindi ba\'t ikaw ang dapat humarap sa hamong ito?","story.map6-dungeon3.044":"Ehhh, <wait=40>pero mapapagalitan ako kung lilihis tayo sa landas namin...","story.map6-dungeon3.045":"Huwag kang mag-alala!","story.map6-dungeon3.046":"Nadadaanan ang Kuta sa Langit papuntang Palmyna, <wait=40>dumiretso lang kayo!","story.map6-dungeon3.047":"Kaya puwede bang kayo na ang bahala rito?<wait=40> Isipin n\'yo na lang na hiling ito ng isang matandang malapit nang pumanaw.","story.map6-dungeon3.048":"Hoy, <wait=40><rep_handlename>!","story.map6-dungeon3.049":"Puwede mo ba akong tulungan dito?","story.map6-dungeon3.050":"Sige na nga, <wait=40>wala na yata akong magagawa.","story.map6-dungeon3.051":"Kung ganyan kalaki ang paghingi mo, susubukan namin...","story.map6-dungeon3.052":"...pero tutulungan mo pa rin kami, \'di ba, Elder Grah?","story.map6-dungeon3.053":"Ho ho ho,<wait=40> sigurado ka bang gusto mo akong isama?","story.map6-dungeon3.054":"Hehe, <wait=40>siyempre naman!","story.map6-dungeon3.055":"Isa pa, ako lang ang may karapatang humingi ng kahit ano kay <rep_handlename>!","story.map6-dungeon3.056":"Ahh, <wait=40>ganoon pala.","story.map6-dungeon3.057":"Ho ho ho. <wait=40>Paumanhin kung ako\'y nagkulang sa paggalang.","story.map6-dungeon3.058":"Gagawin ko ang makakaya ko, bilang matandang ganito.","story.map6-dungeon3.059":"Paalam, <rep_handlename>!<wait=40> Aasahan kitang makita sa Kuta sa Langit!","story.map6-dungeon3.060":"Hmm, <wait=40>sa tingin ko mas malakas si Elder Grah kaysa sa ipinapakita niya. <wait=20>Ano sa tingin mo?","story.map6-dungeon3.061":"Eh, <wait=40>wala naman \'yong kinalaman sa atin!","story.map6-dungeon3.062":"O sige!<wait=40> Tumungo na tayo sa Kuta sa Langit!","story.map6-dungeon4.001":"......<wait=40>Paliko-liko pa rin ang paraan mo gaya ng dati.","story.map6-dungeon4.002":"Teritoryo ito ni Cardes.<wait=40> Kikilos ako ayon sa gusto ko.","story.map6-dungeon4.003":"Heh, <wait=40>ayos lang sa akin \'yan. <wait=40>Gusto kong makita kung ano talaga ang kaya mo, Zebra.","story.map6-dungeon4.004":"Kawawa naman ang Summoner na \'yon at ang mga kasama niya...","story.map6-dungeon4.005":"Hindi nila alam na ang diyos na tinutugis nila ay minsang naglibing ng sampu-sampung libong tao.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Ang presensyang ito.","story.map6-dungeon4.007":"Mukhang dumating na sila.","story.map6-dungeon4.008":"Hmph...","story.map6-dungeon4.009":"Mukhang malas ka rin.","story.map6-dungeon4.010":"Ipagtatanggol ko ang dangal mo,<wait=40> at sisiguraduhin kong aalis sila rito.","story.map6-dungeon4.011":"Tara na, <rep_handlename>!<wait=40> Bilisan mo!","story.map6-dungeon4.012":"Ha? <wait=40>Saan na napunta?","story.map6-dungeon4.013":"Sigurado akong dito nanggagaling ang nakakakilabot na presensyang \'yon...","story.map6-dungeon4.014":"<rep_handlename>!<wait=40> Kasalanan mo \'to kasi ang bagal-bagal mo papunta rito.","story.map6-dungeon4.015":"Pero hindi ba parang kakaiba rito?<wait=40> Wala na akong maramdamang kahit sino...","story.map6-dungeon4.016":"Sigurado akong naramdaman ko ang presensya ng isang diyos kanina...","story.map6-dungeon4.017":"Guni-guni ko lang kaya?","story.map6-dungeon4.018":"Hmm, <wait=40>anyway, kailangan na nating tumungo sa Kuta sa Langit!","story.map6-dungeon4.019":"Tara sa Bangin ng Gadillian!","story.map6-dungeon5.001":"<size=18>Hoy!<wait=40> <rep_handlename>!","story.map6-dungeon5.002":"Hah, hah, hah.<wait=40> Nahanap din kita sa wakas...","story.map6-dungeon5.003":"Seria!<wait=40> Dito!","story.map6-dungeon5.004":"Hah, hah, hah, hah.<wait=40> Sino\'ng mag-aakalang aabot ka hanggang dito...","story.map6-dungeon5.005":"Ikaw na tanga!<wait=40> Sa susunod, pumunta ka sa lugar na madaling mahanap!","story.map6-dungeon5.006":"Imposible naman \'yan...","story.map6-dungeon5.007":"Hay. <wait=40>Pero sa totoo lang, hinanap ka namin kung saan-saan.","story.map6-dungeon5.008":"Akala namin nasa paligid ka pa ng Kastilyo ng Avenia...","story.map6-dungeon5.009":"...pero mukhang nakarating ka na rin pala sa Encervis.","story.map6-dungeon5.010":"Ang laki mong abala.","story.map6-dungeon5.011":"Bakit ba kailangang hanapin ng Demon Slayers ang isang tangang tulad mo.","story.map6-dungeon5.012":"Kaming mga taga-Summoners\' Hall ay dapat nakatuon sa mga gawain ng Summoners\' Hall.","story.map6-dungeon5.013":"Biglang inutusan kaming suportahan si <rep_handlename>, ano kaya ang iniisip nila?","story.map6-dungeon5.014":"Tama na \'yan.","story.map6-dungeon5.015":"Wala tayong magagawa sa sitwasyong kinalalagyan natin.","story.map6-dungeon5.016":"Mas mahalaga ang pagpigil sa Kuta sa Langit kaysa kay Graham. <wait=20>Alam mo naman \'yan, \'di ba, Seria?","story.map6-dungeon5.017":"Alam ko, alam ko!","story.map6-dungeon5.018":"Ayoko lang na kasali si <rep_handlename> sa planong \'to!","story.map6-dungeon5.019":"Haha, <wait=40>ikaw talaga \'yan, Seria.","story.map6-dungeon5.020":"Pero uulitin ko, <wait=40>nandito kami para pigilan si Zebra. ","story.map6-dungeon5.021":"Hindi natin siya puwedeng hayaang gamitin ang Kuta sa Langit para salakayin ang Elgaia.","story.map6-dungeon5.022":"Alam kong mahirap ang laban hanggang ngayon, <wait=40>pero kailangan pa nating magsikap nang kaunti mula rito!","story.map6-dungeon5.023":"...Ano \'yon?","story.map6-dungeon5.024":"Ha? <wait=40>Hindi mo pa raw naririnig ang tungkol doon? <wait=50>Seryoso ka ba??","story.map6-dungeon5.025":"*Buntong-hininga* <wait=40>Nakakahiya naman...","story.map6-dungeon5.026":"Mukha akong tanga, ako lang mag-isa ang excited!","story.map6-dungeon5.027":"Mukhang may pumalpak talaga sa Summoners\' Hall!","story.map6-dungeon5.028":"Nakakalungkot. <wait=40>Dapat nasa mataas na alerto tayo ngayon.","story.map6-dungeon5.029":"Akala ko natanggap mo rin ang parehong impormasyong natanggap namin...","story.map6-dungeon5.030":"Baka mali lang ang impormasyong natanggap niya?","story.map6-dungeon5.031":"Hindi \'yan karaniwan sa Summoners\' Hall.","story.map6-dungeon5.032":"Siguro tama ka...","story.map6-dungeon5.033":"Anyway, <wait=40>mukhang ako na lang ang magsasabi sa\'yo.","story.map6-dungeon5.034":"Hinahabol mo si Zebra, ang bumuhay sa Kuta sa Langit, <wait=40>tama ba?","story.map6-dungeon5.035":"Sige, <wait=40>at least alam mo \'yon.","story.map6-dungeon5.036":"Tungkol sa Kuta sa Langit, <wait=40>masama talaga \'yon. ","story.map6-dungeon5.037":"Kapag tuluyan na itong gumana...","story.map6-dungeon5.038":"...<wait=40>magagamit ito ni Zebra para dumaan sa Pintuan ni Lucius at salakayin ang Elgaia.","story.map6-dungeon5.039":"Dahil dito, pati ang mga nakatataas sa Summoners\' Hall ay kinilala nang nasa estado tayo ng emerhensiya...","story.map6-dungeon5.040":"At humingi sila ng tulong sa lahat ng Summoner na malapit sa Kuta sa Langit...","story.map6-dungeon5.041":"Kasama ka na roon, <rep_handlename>.","story.map6-dungeon5.042":"Kahit kaya naman naming mga Demon Slayers na asikasuhin ang lahat ng \'to nang kami lang...","story.map6-dungeon5.043":"...mula nang talunin mo si Maxwell, ipinipilit ni Karl na kilalanin ko rin ang kakayahan mo...","story.map6-dungeon5.044":"Tutulungan ka namin ngayon, <wait=40>kaya magpasalamat ka!","story.map6-dungeon5.045":"Ha ha ha.","story.map6-dungeon5.046":"Sa madaling salita, <wait=40>ang kailangan mo lang gawin ay ipagpatuloy ang paghabol sa Kuta sa Langit gaya ng dati. ","story.map6-dungeon5.047":"Tutulungan ka naming sumulong sa pamamagitan ng pag-aasikaso sa anumang balakid na lilitaw. ","story.map6-dungeon5.048":"Sa totoo lang, <wait=40>kami ang lugi rito.","story.map6-dungeon5.049":"Kailangan mong suklian ang pabor na \'to pagkatapos!","story.map6-dungeon5.050":"Ayon sa impormasyon mula sa Akras Summoners\' Hall...","story.map6-dungeon5.051":"...mukhang mararating natin ang Kuta sa Langit kapag nadaanan natin ang Lupain ng mga Patay sa unahan. ","story.map6-dungeon5.052":"Kami na ang maglilinis ng daan para sa\'yo.","story.map6-dungeon5.053":"Ituloy mo lang ang pagsulong at ituon ang mata mo sa Kuta sa Langit!","story.map6-dungeon5.054":"Simulan na natin, Seria!","story.map6-dungeon5.055":"Hoy, <wait=40>Karl, <wait=20>hintayin mo ako!","story.map6-dungeon5.056":"<rep_handlename>!","story.map6-dungeon5.057":"Siguraduhin mong tutulong din ang diyosang \'yan! <wait=40>Naiintindihan mo?","story.map6-dungeon5.058":"Hay naku, <wait=40>bakit ko pa ba inaalala ang batang tulad mo...","story.map6-dungeon6.001":"Ah! <wait=40>Nandiyan ka pala!","story.map6-dungeon6.002":"<rep_handlename>!<wait=40> Dito!","story.map6-dungeon6.003":"Kinikilabutan ako sa lugar na \'to...","story.map6-dungeon6.004":"Bakit ba ang nakakatakot ng mga lugar na pinamumunuan ng Apat na Nahulog na Diyos...","story.map6-dungeon6.005":"Kailangan mong magdala ng liwanag sa mga lugar na \'to, <rep_handlename>!","story.map6-dungeon6.006":"Oh, <wait=40>may espesyal akong impormasyon para sa\'yo ngayon!","story.map6-dungeon6.007":"Sasabihin ko sa\'yo kung paano tayo makakarating sa Kuta sa Langit. ","story.map6-dungeon6.008":"Makinig kang mabuti habang nagpapaliwanag ang maganda mong diyosa!","story.map6-dungeon6.009":"Una, <wait=40>ang tunay na pangalan ng Kuta sa Langit ay Solaris. ","story.map6-dungeon6.010":"Hindi ko nalaman kung gaano na katagal itong nasa lugar na \'to...","story.map6-dungeon6.011":"...pero mukhang makikita itong lumulutang sa langit lampas lang ng Lupain ng mga Patay.","story.map6-dungeon6.012":"Haha, <wait=40>sabi ko na nga ba magugulat ka. ","story.map6-dungeon6.013":"Siguro iniisip mo, \\"Paano tayo aakyat sa langit?\\", tama ba ako?","story.map6-dungeon6.014":"Ipaubaya mo na \'yan sa diyosa!","story.map6-dungeon6.015":"Kapag nakalampas ka rito at papunta ka na sa Kuta sa Langit...","story.map6-dungeon6.016":"Ipapadala kita paitaas gamit ang espesyal kong kapangyarihan!","story.map6-dungeon6.017":"Hehe, <wait=40>ano\'ng gagawin mo kung wala ako?","story.map6-dungeon6.018":"Magpasalamat ka sa akin hangga\'t gusto mo!","story.map6-dungeon6.019":"Pero huwag kang magpabaya!","story.map6-dungeon6.020":"Mukhang may sobrang nakakatakot na babae sa unahan na mahilig sa masaker...","story.map6-dungeon6.021":"Mauuna na ako sa Kuta sa Langit, <rep_handlename>, <wait=40>kaya huwag kang magtagal!","story.map6-dungeon6.022":"A-<wait=40>At huwag mong isiping nauuna ako dahil natatakot ako, gets mo!?","story.map6-dungeon7.001":"Nakarating na tayo!","story.map6-dungeon7.002":"Mukhang naipadala kita mismo sa gitna ng Kuta sa Langit!","story.map6-dungeon7.003":"Ang galing ko, \'no?","story.map6-dungeon7.004":"Aray... <wait=40>Nasaan ba tayo?","story.map6-dungeon7.005":"Nahihilo <wait=40>ako...","story.map6-dungeon7.006":"Nakikipaglaban lang tayo sa mga demonyo sa Lupain ng mga Patay kanina, \'di ba?","story.map6-dungeon7.007":"Ah! <wait=40>Karl!","story.map6-dungeon7.008":"At ang maliit mong kaibigang si Seria!","story.map6-dungeon7.009":"Ano\'ng ibig mong sabihin sa \\"maliit na kaibigan!?\\"","story.map6-dungeon7.010":"Si <rep_handlename> pala!","story.map6-dungeon7.011":"Pero kung nandito ka, <wait=40>ibig sabihin...","story.map6-dungeon7.012":"Nasa loob tayo ng Kuta sa Langit!","story.map6-dungeon7.013":"...<wait=40>Mukhang ganoon nga.","story.map6-dungeon7.014":"<size=18>Gaano ka ba katanga!?","story.map6-dungeon7.015":"Kasalanan mo talagang nandito tayo, \'di ba!?","story.map6-dungeon7.016":"Hindi mo ba nakikitang lumalaban pa ang lahat sa ibaba?","story.map6-dungeon7.017":"Dapat inintindi mo muna ang sitwasyon bago ka kumilos, diyosa!","story.map6-dungeon7.018":"A-<wait=40>Ano\'ng sinasabi mo? <wait=40>Wala naman akong ginawang mali...","story.map6-dungeon7.019":"Ang taas siguro ng tingin mo sa sarili mo para masabi \'yan!","story.map6-dungeon7.020":"Puwede bang hayaan na lang natin \'yan? Mas marami tayong mas mahalagang problema, hindi ba?","story.map6-dungeon7.021":"Isa pa, mas madali na nating masusuportahan si <rep_handlename> ngayon.","story.map6-dungeon7.022":"At saka, <wait=40>hindi naman makakaapekto ang pagkawala nating dalawa sa mga lumalaban pa sa ibaba.","story.map6-dungeon7.023":"Siguro tama ka, pero...","story.map6-dungeon7.024":"Anyway, <wait=40>kahanga-hanga ka pa ring diyosa gaya ng dati.","story.map6-dungeon7.025":"Napadali mo nang kaunti ang mga bagay kahit nasa mapanganib tayong sitwasyon. ","story.map6-dungeon7.026":"Kung may makakagawa nito kapag pinagtuunan ng isip, <wait=40>alam kong ikaw \'yon.","story.map6-dungeon7.027":"Mali ang akala mo, Karl!<wait=40> Masyado kang madaling magtiwala!","story.map6-dungeon7.028":"Haha...","story.map6-dungeon7.029":"<size=18>!?<wait=40> Sino \'yan!?","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Mukhang kahit kayong mga tao ay nararamdaman ang presensya ko.","story.map6-dungeon7.032":"Zebra!!","story.map6-dungeon7.033":"Si Zebra \'yan, ang baliw na diyos... <wait=40>Mag-ingat kayo, kasing-delikado siya ng itsura niya...","story.map6-dungeon7.034":"Pagbabayaran mo ang ginawa mo sa Edila!","story.map6-dungeon7.035":"Humanda ka!","story.map6-dungeon7.036":"Wala akong pakinabang sa inyong mga kawawang uod.","story.map6-dungeon7.037":"Ang hinahanap ko <wait=40>ay si Tilith, ang disipulo ni Lucius.","story.map6-dungeon7.038":"<size=18>Nandiyan ka pala!","story.map6-dungeon7.039":"<size=18>*Bok*","story.map6-dungeon7.040":"Kyaahh!!","story.map6-dungeon7.041":"Mukhang pagod ka na.<wait=40> Inaasahan na \'yan dahil sa dami ng kapangyarihang ginamit mo para dalhin sila rito.","story.map6-dungeon7.042":"Ang dami mong tiniis para sa mga kawawang uod na \'to.","story.map6-dungeon7.043":"Kung labanan sa mga diyos ang gusto mo, sigurado akong pipigilan ka ni Lucius...","story.map6-dungeon7.044":"...pero kung balak mo kaming atakihin ngayon, hindi kita pagbibigyan!","story.map6-dungeon7.045":"<size=18>Lahat kayo, umatras kayo!","story.map6-dungeon7.046":"Ano\'ng kapangyarihan \'to...<wait=40> Ugh...<wait=40>Hindi ako makagalaw...","story.map6-dungeon7.047":"Gyah...<wait=40> Paano ka pa nagkaroon ng ganitong lakas pagkatapos ng lahat ng \'yon...<wait=40> Hindi kaya...","story.map6-dungeon7.048":"Hah... hah... ","story.map6-dungeon7.049":"Baka mahina ako nang kaunti ngayon...<wait=40> pero hindi ako matatalo sa\'yo...","story.map6-dungeon7.050":"<size=18>Huwag mo akong lokohin! <wait=40>Isa ka lang maliit na aso ni Lucius!!","story.map6-dungeon7.051":"<size=18>Kyaaahh!!","story.map6-dungeon7.052":"<size=20>Tilith!!","story.map6-dungeon7.053":"Nngh... <wait=40>Mas lumaban siya kaysa sa inaasahan ko...","story.map6-dungeon7.054":"Pero hindi na \'yon mahalaga ngayon. <wait=40>Naalis ko na ang nakaharang sa daan ko. ","story.map6-dungeon7.055":"Wala nang diyos na magtatanggol sa inyo.","story.map6-dungeon7.056":"Magiging magandang pagsasanay kayong lahat para sa mga tauhan ko. ","story.map6-dungeon7.057":"Akala mo ba hahayaan ka lang naming makatakas?","story.map6-dungeon7.058":"Wala akong pakialam sa balak ninyo.","story.map6-dungeon7.059":"Kayong mga kawawang uod ay ni hindi makahakbang kahit isang beses sa harap ko.","story.map6-dungeon7.060":"Ginagamit ko ang Kuta sa Langit na ito para lang palayain si Lord Cardes mula sa kanyang pagkakagapos.","story.map6-dungeon7.061":"Kung talagang determinado kayong harapin ako, <wait=40>naghihintay ako sa kailaliman nito. ","story.map6-dungeon7.062":"Ipaparamdam ko sa inyong lahat ang takot sa mga diyos!","story.map6-dungeon7.063":"<size=18>Tigil!!","story.map6-dungeon7.064":"Lintik! <wait=40>Nakatakas siya!","story.map6-dungeon7.065":"<size=18>Karl!!","story.map6-dungeon7.066":"<size=18>Ano ba \'to!?<wait=40> Saan galing ang lahat ng halimaw na \'to!?","story.map6-dungeon7.067":"N-<wait=40>Nngh...","story.map6-dungeon7.068":"P-<wait=40>Patawad...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"Huwag ka nang magsalita!<wait=40> Kailangan mong magtipid ng lakas!","story.map6-dungeon7.070":"Karl, <wait=40>alam mo na ang dapat nating gawin!","story.map6-dungeon7.071":"Oo! <wait=40><rep_handlename>!","story.map6-dungeon7.072":"Habulin mo si Zebra. <wait=20>Kami na ni Seria ang bahala rito!","story.map6-dungeon7.073":"Hindi ko alam kung paano niya balak gamitin ang kutang ito...","story.map6-dungeon7.074":"...pero kapag napalaya niya si Cardes, malaking problema tayo!","story.map6-dungeon7.075":"Huwag ka lang tumayo diyan, <wait=40>kumilos ka na!","story.map6-dungeon7.076":"Akala mo ba hamon sa amin ang mga halimaw na ganito?","story.map6-dungeon7.077":"Ang lakas ng loob mong pagdudahan ang pinuno ng Demon Slayers!","story.map6-dungeon7.078":"Kung may oras ka sa walang kuwentang pag-aalala, <wait=40>tigilan mo na ang pagpapaliban at habulin mo siya!","story.map6-dungeon7.079":"Isa pa, <wait=40>sa lahat ng tao, alam mong may laban pa ang diyosang \'to, \'di ba?","story.map6-dungeon7.080":"Tama ka, Seria.","story.map6-dungeon7.081":"Walang banta sa amin ang mga halimaw na \'to.","story.map6-dungeon7.082":"At huwag kang mag-alala sa diyosa, nasa proteksyon na namin siya.","story.map6-dungeon7.083":"Kaya humayo ka na, <wait=40>at talunin ang masamang si Zebra!","story.map6-dungeon7.084":"Umaasa kami sa\'yo, <rep_handlename>!","story.map6-dungeon7.085":"Ipakita mo sa amin kung anong klaseng Summoner ka talaga!","story.map6-dungeon7.086":"Seria!!","story.map6-dungeon7.087":"Sige!","story.map6-dungeon7.088":"<speed=20><size=20>Heto na!!","story.map6-dungeon_ex_clear.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"Nagawa mo, <rep_handlename>!","story.map6-dungeon_ex_clear.003":"Natalo mo ang nilalang bago pa man makarating doon ang mga logistics officer namin.","story.map6-dungeon_ex_clear.004":"Alam kong kaya mo, sir!","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>pero mukhang pupunta pa rin sila sa mga guhong \'yon.","story.map6-dungeon_ex_clear.006":"Mukhang may napakalaking bagay na dating nakatago sa mga guhong ito.","story.map6-dungeon_ex_clear.007":"Parang shipyard o ganoon ang dating nito, pero siguro ito lang ang naging opsyon.","story.map6-dungeon_ex_clear.008":"Hmm? <wait=40>May napansin ka ba mula nang pumasok ka sa loob, sir?","story.map6-dungeon_ex_clear.009":"Siyanga pala, may mga tala raw na nagsasabing lumitaw rin si Valmodora noong digmaan ng mga diyos.","story.map6-dungeon_ex_clear.010":"Mukhang kahit noon ay nanirahan din ito sa ilang guho sa kung saan.","story.map6-dungeon_ex_clear.011":"Pero sinasabing nalipol din ito ng isang mandirigma.","story.map6-dungeon_ex_clear.012":"Sigurado akong maitatala ka rin sa kasaysayan dahil sa ginawa mo.","story.map6-dungeon_ex_clear.013":"Pero <wait=20>subukan mong huwag maging padalos-dalos sa susunod!","story.map6-dungeon_ex_clear.014":"Pero kahit ano pa\'ng sabihin ko, pupunta ka pa rin, \'di ba?","story.map6-dungeon_ex_clear.015":"Alalang-alala talaga ako sa\'yo, alam mo ba!","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Hehe, <wait=20>ang tagal ko nang hindi nakikita \'yang problemadong mukha mo.","story.map6-dungeon_ex_clear.018":"Anyway, pakituloy ang imbestigasyon mo sa ibang lugar!","story.map6-dungeon_ex_open.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"Naririnig mo ba ako, <wait=40>sir?","story.map6-dungeon_ex_open.003":"<size=20><rep_handlename>!</size>","story.map6-dungeon_ex_open.004":"Naririnig mo ba ako?","story.map6-dungeon_ex_open.005":"Ako si Lin Merylham mula sa Logistics Support...","story.map6-dungeon_ex_open.006":"...ng Grand Gaia Survey Office Bureau of Investigation, handang maglingkod sa inyo.","story.map6-dungeon_ex_open.007":"Kinokontak kita ngayon dahil may bagong impormasyon.","story.map6-dungeon_ex_open.008":"May nakakatakot na natuklasan ang Summoners\' Hall sa mga sinaunang guho sa Encervis.","story.map6-dungeon_ex_open.009":"Mukhang may napakadelikadong nilalang na ginawang tahanan ang mga ito.","story.map6-dungeon_ex_open.010":"Sa ngayon, <wait=20>mukhang tahimik pa naman.","story.map6-dungeon_ex_open.011":"Pero mukhang humihigop ito ng lakas mula sa mga guho sa paligid nito para palawakin ang teritoryo nito.","story.map6-dungeon_ex_open.012":"Magpapadala ulit kami ng mga logistics officer doon, kaya bago \'yon, pakiusap, lumayo ka muna!","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"A-<wait=20>Ano \'yon, sir? <wait=40>Nandoon ka na?","story.map6-dungeon_ex_open.015":"Hmph, <wait=40>sir, masyado kang padalos-dalos!","story.map6-dungeon_ex_open.016":"Pero kahit ano pa\'ng sabihin ko, pupunta ka pa rin, \'di ba?","story.map6-dungeon_ex_open.017":"Naiintindihan ko!","story.map6-dungeon_ex_open.018":"Hindi na kita pipigilan!","story.map6-dungeon_ex_open.019":"Ang halimaw na naghihintay sa\'yo sa loob ay kilala bilang Valmodora.","story.map6-dungeon_ex_open.020":"Mukhang medyo malaking halimaw ito, kaya mag-ingat ka nang husto.","story.map6-dungeon_ex_open.021":"Lagi akong alalang-alala sa\'yo, <wait=20>alam mo ba...","story.map6-ending.001":"<speed=10>I-<wait=40>Ikaw na hangal...","story.map6-ending.002":"<speed=10>T-<wait=40>Tipikal na tao...","story.map6-ending.003":"Gyah!<wait=40> <speed=10>Bilang disipulo...<wait=40> ni Lord Cardes...","story.map6-ending.004":"<speed=10>H-<wait=40>Hindi ako p-puwedeng..<wait=40> matalo...<wait=40> nang ganito kadali...","story.map6-ending.005":"<speed=10>Nngh...<wait=40> Wala na akong magagawa...","story.map6-ending.006":"<speed=10>Pababagsakin ko ang Kuta sa Langit, <wait=40>at isasama ko kayong lahat!!","story.map6-ending.007":"<size=18>*Klang*","story.map6-ending.008":"<size=18>I-<wait=40>Ikaaawwww!!","story.map6-ending.009":"Kahit ang diyos ay dapat marunong tumigil.","story.map6-ending.010":"Kung hindi mo alam \'yon, para ka lang pangalawang-klaseng demonyo, sa tingin ko.","story.map6-ending.011":"Pagnilayan mo \'yan nang mabuti. ","story.map6-ending.012":"<size=18>Gwaaaahhh!!","story.map6-ending.013":"Hmm!?","story.map6-ending.014":"Bakit gulat na gulat ka?","story.map6-ending.015":"Hindi bale, <wait=40>bilisan mo at tawagin ang binibini.","story.map6-ending.016":"Ngayong wala na si Zebra, <wait=40>malamang ikakandado ulit ang Kuta sa Langit.","story.map6-ending.017":"Hmm!? <wait=40>Ang liwanag na ito...","story.map6-ending.018":"<speed=10>Hindi kaya... <wait=40>galing ito sa Lawa ng Aldela?","story.map6-ending.019":"<size=18><rep_handlename>!!","story.map6-ending.020":"Arayyy...<wait=40> Saan na naman kami napadpad ngayon?","story.map6-ending.021":"<rep_handlename>!!","story.map6-ending.022":"...<wait=40>...<wait=40>Nagawa mo!","story.map6-ending.023":"Ang galing-galing mo talaga!","story.map6-ending.024":"Nngh, <wait=40>ang sakit ng puwet ko...","story.map6-ending.025":"Hoy ikaw!<wait=40> Puwede bang mas maingat ang paglapag sa susunod!","story.map6-ending.026":"Ho ho ho.","story.map6-ending.027":"Hindi naman siguro problema \'yan sa puwet na kasinlaki ng sa\'yo, \'di ba, Seria?","story.map6-ending.028":"Gr-<wait=40>Grahde...<wait=40> Elder Grah!<wait=40> Bakit ka ba nandito!?","story.map6-ending.029":"Elder Grah?<wait=40> Ano\'ng klaseng pangalan \'yan?","story.map6-ending.030":"Sandali lang, <wait=40>hindi ba\'t ikaw si Grahdens?","story.map6-ending.031":"Ano\'ng ginagawa ng isang Elder Summoner na tulad mo sa ganitong lugar?","story.map6-ending.032":"Ang lakas ng loob mo, <wait=40>hangal ka!","story.map6-ending.033":"At isipin mo, <wait=40>sa wakas ay nakikita na ako ni Tilith bilang isang mabait na matanda lang...","story.map6-ending.034":"Tapos dumating ka at sinira mo ang lahat!","story.map6-ending.035":"Ha?<wait=40> Ano\'ng ibig mong sabihin sa \\"mabait na matanda?\\"","story.map6-ending.036":"Bilang isa sa mga pinuno ng Summoners\' Hall,<wait=40> hindi ba\'t dapat nagtatrabaho ka roon!?","story.map6-ending.037":"Hmm, <wait=40>hindi ko masyadong gets ang nangyayari, <wait=40>pero mukhang importante pala talaga si Elder Grah.","story.map6-ending.038":"Hindi lang pala siya ang kakaibang matandang nakilala namin...","story.map6-ending.039":"Hoy, <wait=40>ngayong alam mo na kung sino si Lord Grahdens, dapat mas igalang mo siya!","story.map6-ending.040":"Pero wala naman \'yong kinalaman sa akin...","story.map6-ending.041":"At saka, hindi ko alam kung paano ninyo tinitingnan ang mga bagay dito sa mundo ng tao...","story.map6-ending.042":"...pero kung pipili ka, hindi ba\'t mas importante ako, bilang diyosa?","story.map6-ending.043":"Ikaw dapat ang mas gumalang sa akin, Seria!","story.map6-ending.044":"Kung ganyan ang tingin mo, bakit hindi mo subukang umasta nang mas parang diyosa?","story.map6-ending.045":"Ano\'ng gusto mong palabasin!?","story.map6-ending.046":"Kumalma kayo, <wait=40>balak n\'yo ba talagang mag-away sa kabila ng tagumpay ni <rep_handlename> laban kay Zebra?","story.map6-ending.047":"Ho ho ho.","story.map6-ending.048":"Seria, <wait=40>tama ang sinasabi ni Tilith.","story.map6-ending.049":"Kung ikukumpara sa mga diyos, <wait=40>maliit lang ang halaga ng pag-iral ko. ","story.map6-ending.050":"Tilith, <wait=40>gusto kong patuloy mo akong tawaging simpleng Elder Grah.","story.map6-ending.051":"\'Yan naman talaga ang balak ko.","story.map6-ending.052":"Alam ko na kung sino ka talaga, Elder Grah.<wait=40> Iba ka sa isa pang weirdong kakilala ko!","story.map6-ending.053":"Sino\'ng tinutukoy mo!?","story.map6-ending.054":"Hmm, ewan ko...","story.map6-ending.055":"Hay naku, <wait=40>magbabago pa kaya kayong dalawa?","story.map6-ending.056":"Anyway, <wait=40>Grahdens...","story.map6-ending.057":"Balik tayo sa tanong ko kanina, <wait=40>bakit ka nandito?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Summoner ka rin, <wait=40>bakit hindi mo ako igalang nang kaunti pa?","story.map6-ending.060":"Tigilan mo na \'yan. <wait=40>Hindi kita hahayaang ibahin ulit ang usapan.","story.map6-ending.061":"Matagal na kitang kilala at sanay na ako sa mga gawi mo.","story.map6-ending.062":"Ho ho ho.<wait=40> Prangka ka pa rin gaya ng dati.","story.map6-ending.063":"Karl, <wait=40>hayaan mong ipaliwanag ko ang detalye mamaya.","story.map6-ending.064":"May kailangan muna akong pag-usapan kasama si <rep_handlename>.","story.map6-ending.065":"<rep_handlename>, <wait=40>sa pagtalo mo kay Zebra gaya ng hiniling ko...","story.map6-ending.066":"Ipinapaabot ko ang pasasalamat ko bilang Elder Summoner ng Defense Department ng Akras Summoners\' Hall.","story.map6-ending.067":"Hehe, <wait=40>may iba ka pa bang inaasahan sa mabuting kaibigan ko?","story.map6-ending.068":"Alam kong kaya mo, <rep_handlename> ko!","story.map6-ending.069":"Hoy, <wait=20>tigilan mo ang pagtawag sa kanya na sa\'yo!","story.map6-ending.070":"A-<wait=40>Anyway, dahil tinupad ni <rep_handlename> ang hiling ni Lord Grahdens...","story.map6-ending.071":"Siguro may dahilan na akong purihin ka bilang kapwa Summoner.","story.map6-ending.072":"Ang prangka mo naman!","story.map6-ending.073":"A-<wait=40>Ano\'ng sinasabi mo!?","story.map6-ending.074":"Ho ho ho.<wait=40> Mukhang lahat ay nagpapasalamat sa ginawa mo.","story.map6-ending.075":"Pero <wait=40>kahit gaano pa siya kalakas, <wait=40>huwag mong kalimutang disipulo lang ni Cardes si Zebra.","story.map6-ending.076":"Walang-wala ang kapangyarihan ni Zebra kumpara sa nahulog na diyos na hinahabol mo ngayon. ","story.map6-ending.077":"Tiyak <wait=40>na naghihintay sa\'yo sa Palmyna ang mga labanang walang kapantay ang bangis.","story.map6-ending.078":"Ngayon, higit kailanman, <wait=40>kailangan mong mag-ingat.","story.map6-ending.079":"Huwag kang mag-alala sa kanya. <wait=40>Nasa proteksyon ko siya.","story.map6-ending.080":"Ano\'ng ibig mong sabihin sa \\"proteksyon ko?\\" <wait=40>Muntik ka nang mamatay kani-kanina lang, hindi mo ba naaalala?","story.map6-ending.081":"Seria!","story.map6-ending.082":"A-<wait=40>Ano!?","story.map6-ending.083":"Salamat...<wait=40> sa pagprotekta sa akin kanina.","story.map6-ending.084":"A-<wait=20>A-<wait=10>Ano\'ng n-<wait=10>nangyari sa\'yo bigla?","story.map6-ending.085":"H-<wait=40>Hindi naman sa naghihintay ako ng pasasalamat o ano...","story.map6-ending.086":"A-<wait=40>Ako lang naman ay... <wait=20>*Bulong* <size=14>*Bulong* <size=12>*Bulong*","story.map6-ending.087":"Haha, <wait=40>nahihiya ka ba?","story.map6-ending.088":"Ho ho ho.","story.map6-ending.089":"<rep_handlename>!","story.map6-ending.090":"Papunta na rin tayo sa wakas sa Palmyna, ang lupaing kinakukulungan ni Cardes!","story.map6-ending.091":"Naniniwala ako sa\'yo...","story.map6-ending.092":"<rep_handlename>, <wait=40>ikaw ang Summoner na magliligtas sa mundo!","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ikaw, <rep_handlename>,<wait=39> na nagbukas ng Amdahl...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang aking kapangyarihan sa pagsisimula ng iyong paglalakbay sa bagong lupaing ito...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Upang magdala ng bagong pag-asa sa mundong ito na puno ng kalungkutan…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kailangan mong manalig sa iyong kapangyarihan, <wait=20>at patuloy na sumulong…","story.map6-open.005":"Oh, <wait=40>gising ka na!","story.map6-open.006":"Tingnan mo! <wait=40>Nasa Encervis na tayo.","story.map6-open.007":"Sa malalalim nitong tubig at matataas na bulkan, <wait=40>kilala ang lugar na \'to sa matitinding kapaligiran.","story.map6-open.008":"Noong unang panahon, <wait=40>may naganap na labanan ng mga tao rito...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"Pero hindi naman ito masyadong interesante kaya kalimutan na lang natin!","story.map6-open.011":"Isa pa, <wait=40>marami ka pang ibang kailangang matutunan!","story.map6-open.012":"At wala naman talaga \'yong kinalaman sa atin.","story.map6-open.013":"Nandito tayo sa gitna ng Kapuluan ng Palmyna, pero malayo pa tayo sa mismong Palmyna...","story.map6-open.014":"Pero huwag kang magpabaya, <wait=20>at laging mag-focus!","story.map6-open.015":"Malaki rin ang inaasahan ko sa\'yo rito!","story.map6-open.016":"O sige, <wait=20>galingan natin at magsikap tayong talunin si Cardes!!","story.map7-dungeon1.001":"<rep_handlename>!","story.map7-dungeon1.002":"Lagot tayo!<wait=40> Malaking gulo \'to!!","story.map7-dungeon1.003":"Kyahh!","story.map7-dungeon1.004":"<size=18>*Blag*","story.map7-dungeon1.005":"Aray kooo...","story.map7-dungeon1.006":"Hoy!<wait=40> <rep_handlename>! <wait=40>\'Wag ka lang diyan nakatayo!","story.map7-dungeon1.007":"Ha? <wait=40>Akala mo hihintayin kita sa Kastilyo ng Obselion?","story.map7-dungeon1.008":"Wala nang oras para intindihin ang mga ganyang detalye!","story.map7-dungeon1.009":"Malaking gulo talaga \'to!","story.map7-dungeon1.010":"Nagsisimula nang matunaw ang selyong nakakulong kay Cardes!!","story.map7-dungeon1.011":"Hindi ko alam kung bakit bigla na lang itong natunaw...","story.map7-dungeon1.012":"...pero siguradong naghahanda na siyang makatakas!","story.map7-dungeon1.013":"Pero sa tingin ko, walang kinalaman dito ang kahit sinong taga-labas.","story.map7-dungeon1.014":"Hay naku!","story.map7-dungeon1.015":"Akala ko madali na lang natin siyang matatalo, matapos mong pabagsakin si Zebra.","story.map7-dungeon1.016":"Hmph, <wait=40>mukhang magiging busy na naman tayo...","story.map7-dungeon1.017":"Ang dami ko pang kailangang gawin para kay Lord Lucius...","story.map7-dungeon1.018":"Tapos ngayon, aasikasuhin ko pa kung anuman ang binabalak ni Cardes...","story.map7-dungeon1.019":"Bakit hindi man lang ako makapagpahinga!","story.map7-dungeon1.020":"Ay, <wait=40>muntik ko nang makalimutan!","story.map7-dungeon1.021":"Hindi ko pa rin nahahanap ang daan papunta sa Daigdig ng Espiritu!","story.map7-dungeon1.022":"Pero pangako, malalaman ko \'yon bago ka makarating sa Kastilyo ng Obselion, <rep_handlename>.","story.map7-dungeon1.023":"Good luck, <wait=40>at ngayon, siguradong magkikita na tayo sa Kastilyo ng Obselion!","story.map7-dungeon2.001":"Ho ho ho. <wait=40>Hindi ba\'t si <rep_handlename> ito?","story.map7-dungeon2.002":"Papunta ka ba sa lupaing pinagkukulungan kay Cardes?","story.map7-dungeon2.003":"Hmm? <wait=40>Anong problema?<wait=40> Mukhang balisa ka.","story.map7-dungeon2.004":"Kung si Tilith ang hinahanap mo, hindi ko siya nakita rito. ","story.map7-dungeon2.005":"Bakit ganyan ang mukha mo, parang problemado? <wait=40>Hindi mo siya kailangang alalahanin, alam mo ba?","story.map7-dungeon2.006":"Lampas na siya sa kayang alalahanin ng mga hamak na Summoner na tulad natin. ","story.map7-dungeon2.007":"Pero kung ganoon kaganda ang tingin niya sa\'yo, kakabahan din siguro ako. ","story.map7-dungeon2.008":"Ho ho ho.","story.map7-dungeon2.009":"Hmph. <wait=40>Mukhang matagal-tagal na rin mula nang tayong dalawa lang ang magkasama. ","story.map7-dungeon2.010":"Dahil may oras pa tayo, <wait=40>bakit hindi kita kuwentuhan nang kaunti?","story.map7-dungeon2.011":"Isang kuwento tungkol sa malagim na labanan ng mga tao at ng mga diyos.","story.map7-dungeon2.012":"Noong unang panahon, <wait=40>tahanan ng Maharlikang Pamilya ng Palmyna ang Kastilyo ng Obselion. ","story.map7-dungeon2.013":"Isa itong magandang kastilyo noon, <wait=40>napapaligiran ng luntiang kalikasan. ","story.map7-dungeon2.014":"Pero ganito na ang sinapit nito matapos ang labanan sa mga diyos. ","story.map7-dungeon2.015":"Kilala mo ba ang Apat na Bayani ng Palmyna?","story.map7-dungeon2.016":"May alamat na nagsasabing lumaban ang apat na mandirigma kay Cardes para iligtas ang lupaing ito.","story.map7-dungeon2.017":"Sinasabi pa nga na kasama nila si Edea, ang Prinsesa ng Palmyna.","story.map7-dungeon2.018":"Kung totoo ang alamat, ang Apat na Bayani ang nagkulong kay Cardes. ","story.map7-dungeon2.019":"Pero sinasabi rin na kapalit ng pagkulong kay Cardes...","story.map7-dungeon2.020":"...kinailangang isakripisyo ng Apat na Bayani ang sarili nilang buhay. ","story.map7-dungeon2.021":"Ano kaya ang nasa isip nila sa huli? ","story.map7-dungeon2.022":"Masaya ba sila sa paniniwalang maililigtas ng pagkulong kay Cardes ang Palmyna? ","story.map7-dungeon2.023":"Iyon ba ang dahilan kung bakit hinarap nila nang walang takot ang kamatayan?","story.map7-dungeon2.024":"Kahit gaano sila kagiting sa pagbubuwis ng buhay para protektahan ang lugar na ito...","story.map7-dungeon2.025":"...nang magsimula silang lumaban, nawala na ito.","story.map7-dungeon2.026":"Isang tunay na malungkot na kuwento...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>naiintindihan mo ba ang gusto kong sabihin?","story.map7-dungeon2.028":"Ho ho ho. <wait=40>Huwag kang mag-alala.","story.map7-dungeon2.029":"Tiyak, <wait=40>balang araw ay mapapasok ka rin sa isang sitwasyong hindi mo maisip. ","story.map7-dungeon2.030":"Hanggang doon, <wait=40>bantayan mong mabuti ang paligid mo habang patuloy itong nagbabago. ","story.map7-dungeon2.031":"Ang matutuklasan mo ang magsisilbing gatong sa landas mo. ","story.map7-dungeon2.032":"Ho ho ho.<wait=40> Pasensya na sa mahabang sermon. ","story.map7-dungeon2.033":"Pagkakita mo ulit kay Tilith, pakisabi sa kanya ang mensaheng ito.","story.map7-dungeon2.034":"Malapit nang tuluyang masira ang selyo ni Cardes.","story.map7-dungeon2.035":"Paalam, at mag-ingat ka.","story.map7-dungeon3.001":"<size=18>*Hiwa*","story.map7-dungeon3.002":"Phew. <wait=40>Mukhang halos ubos na natin ang mga halimaw sa lugar na \'to. ","story.map7-dungeon3.003":"Pero aaminin ko, <wait=40>mas malakas sila kaysa sa inaasahan ko.","story.map7-dungeon3.004":"Hmm?","story.map7-dungeon3.005":"Uy! <wait=40><rep_handlename>!","story.map7-dungeon3.006":"Maligayang pagdating sa Palmyna!","story.map7-dungeon3.007":"Malapit na tayo sa pinagkukulungan kay Cardes. <wait=40>Ibuhos na natin ang lahat sa huling tulak na \'to!","story.map7-dungeon3.008":"Uy! <wait=40>Seria!<wait=40> Nakarating din si <rep_handlename>!","story.map7-dungeon3.009":"Hindi mo na kailangang sabihin sa\'kin tuwing darating siya. <wait=40>Saka, dinededma ko lang si <rep_handlename>.","story.map7-dungeon3.010":"Haha. <wait=40>Ganoon ka pa rin, ano Seria?","story.map7-dungeon3.011":"Anyway, <wait=40>nasaan na \'yung diyosang laging nakasunod sa\'yo?","story.map7-dungeon3.012":"...Hmm, kaya pala hinahanap niya ang daan papunta sa Daigdig ng Espiritu.","story.map7-dungeon3.013":"Mukhang wala tayong choice kundi pumunta roon kung gusto nating harapin si Cardes...","story.map7-dungeon3.014":"Anong problema?<wait=40> Medyo namumutla ka.","story.map7-dungeon3.015":"W-<wait=40>Wala \'to!","story.map7-dungeon3.016":"Medyo naiinis lang ako!","story.map7-dungeon3.017":"Kasi naman, <wait=40>hindi mo ba nakikita ang nangyayari, Karl!?","story.map7-dungeon3.018":"Mula pa noon, ang layunin natin ay pabagsakin si Graham!","story.map7-dungeon3.019":"Bakit kailangan nating sayangin ang oras sa pagtulong kay <rep_handlename>!?","story.map7-dungeon3.020":"Halika na, <wait=40>tiyak na mas mahalaga ang pagtalo sa Apat na Nahulog na Diyos kaysa kay Graham. ","story.map7-dungeon3.021":"Alam ko, alam ko!","story.map7-dungeon3.022":"Pero alam mo naman ang nararamdaman ko, \'di ba Karl?","story.map7-dungeon3.023":"Higit sa lahat, gusto kong pabagsakin si Graham!","story.map7-dungeon3.024":"Oo, <wait=40>naiintindihan ko ang nararamdaman mo. <wait=50>Patawarin mo ako, <wait=40>Seria...","story.map7-dungeon3.025":"Hindi naman kita sinisisi o ano, Karl...","story.map7-dungeon3.026":"Grrr!!<wait=40> Kasalanan mo \'tong lahat!","story.map7-dungeon3.027":"Bakit hindi mo na lang harapin si Cardes nang mag-isa!","story.map7-dungeon3.028":"Medyo kalokohan na \'yan,<wait=40> hindi ba?","story.map7-dungeon3.029":"Sabi ko nga, alam ko!","story.map7-dungeon3.030":"Karl, <wait=40>ang hirap mo nang kontrahin nitong mga nakaraan!","story.map7-dungeon3.031":"Hindi, <wait=40>ikaw lang ang puro kalokohan ang sinasabi nitong mga nakaraan...","story.map7-dungeon3.032":"Hindi ko alam ang sinasabi mo!","story.map7-dungeon3.033":"<rep_handlename>! <wait=40>Bilisan mo\'t hanapin ang diyosang \'yon...","story.map7-dungeon3.034":"...at alamin kung paano tayo makakapunta sa Daigdig ng Espiritu!","story.map7-dungeon3.035":"U-<wait=20>Uy!<wait=40> Hintayin mo ako!","story.map7-dungeon3.036":"<rep_handlename>! Kami na ang maglilinis ng daan sa unahan.","story.map7-dungeon3.037":"Siguraduhin mo lang na handa ka nang harapin si Cardes!","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Masaya akong makita ka... <wait=40>Mukhang ayos ka naman...","story.map7-dungeon4.003":"Hah...<wait=40> hah...","story.map7-dungeon4.004":"A-<wait=40>Ayos lang ako...","story.map7-dungeon4.005":"Nngh...<wait=40> Mukhang medyo pumalpak ako...","story.map7-dungeon4.006":"Habang inaalam ko kung paano pumunta sa Daigdig ng Espiritu, <wait=40>may hindi inaasahang nangyari...","story.map7-dungeon4.007":"Sorry kung pinag-alala kita.","story.map7-dungeon4.008":"Magiging okay ako, <wait=20>kailangan ko lang ng kaunting pahinga.","story.map7-dungeon4.009":"Pero mas mahalaga, <wait=40>may kailangan akong sabihin sa\'yo...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"Ang selyo kay Cardes...<wait=40> hindi lang ito basta nagkakalamat...","story.map7-dungeon4.012":"Si Cardes... <wait=40>ang sumisira nito... <wait=40>mula sa loob...","story.map7-dungeon4.013":"Mahina pa siya ngayon dahil matagal siyang nakakulong...","story.map7-dungeon4.014":"Pero napakalakas pa rin ng kapangyarihan niya bilang diyos...","story.map7-dungeon4.015":"Umaapaw na ito mula sa Daigdig ng Espiritu, <wait=40>winawasak ang lahat ng madaanan...","story.map7-dungeon4.016":"Sinubukan kong ayusin ang selyo, pero nabigo ako...","story.map7-dungeon4.017":"Hah...<wait=40> hah...","story.map7-dungeon4.018":"P-<wait=40>Pero... <wait=40>may pag-asa pa tayo.","story.map7-dungeon4.019":"Bukas na ngayon ang daan papunta sa Daigdig ng Espiritu.","story.map7-dungeon4.020":"Pumunta ka sa Larangan ng Noera. <wait=40>Nasa kabila lang niyon ang pasukan sa Daigdig ng Espiritu...","story.map7-dungeon4.021":"Mauna ka na, <wait=40>at \'wag mo akong alalahanin!","story.map7-dungeon4.022":"Humingi ka na rin ng tulong kina Karl, Seria, at Elder Grah. ","story.map7-dungeon4.023":"Magpapahinga muna ako bago ako sumunod sa inyo...","story.map7-dungeon4.024":"\'Wag mo akong alalahanin...","story.map7-dungeon4.025":"Ako ang maganda at walang-talong diyosa!","story.map7-dungeon4.026":"Kaso lang, <wait=40>medyo pagod lang ako ngayon...","story.map7-dungeon4.027":"Pero \'wag kang mag-alala... <wait=50>Magkikita tayo sa harap ng labanan...","story.map7-dungeon5.001":"Hindi ba\'t si <rep_handlename> ito?","story.map7-dungeon5.002":"Bakit ang seryoso ng mukha mo?","story.map7-dungeon5.003":"Ano\'ng sabi mo!?<wait=40> Ano\'ng nangyari kay Tilith!?","story.map7-dungeon5.004":"Hmph. <wait=40>Mukhang mas malala ang sitwasyon kaysa sa inakala ko. ","story.map7-dungeon5.005":"Pasensya na, pero may kailangan akong asikasuhin dito, <wait=40>kaya hindi kita matutulungan. ","story.map7-dungeon5.006":"Hiniling ko na kina Karl at Seria na tulungan ka. ","story.map7-dungeon5.007":"Magtulungan kayo para talunin si Cardes.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"May sasabihin ako sa\'yo bago mo harapin ang Nahulog na Diyos.","story.map7-dungeon5.010":"Nagtrabaho rito sa Seminaryo ng Arlind ang isa sa Apat na Bayani ng Palmyna.","story.map7-dungeon5.011":"Lorand ang pangalan niya, at isa siyang guro. ","story.map7-dungeon5.012":"Kahit nagretiro na siya sa buhay-sundalo...","story.map7-dungeon5.013":"...nakumbinsi siya ni Edea, ang Prinsesa ng Palmyna, <wait=40>na lumaban sa mga sumasalakay na diyos. ","story.map7-dungeon5.014":"Nagtapos ito gaya ng ikinuwento ko sa\'yo noon. ","story.map7-dungeon5.015":"Isinakripisyo ng Apat na Bayani ang buhay nila para ikulong si Cardes. ","story.map7-dungeon5.016":"Pero, <wait=40>marami pang ibang kuwento ng mga taong lumaban gaya ng Apat na Bayani. ","story.map7-dungeon5.017":"Noong unang panahon, <wait=40>maraming tao ang lumaban sa mga diyos dito.","story.map7-dungeon5.018":"Karamihan sa kanila ay nasawi.","story.map7-dungeon5.019":"Ayon sa alamat, <wait=40>pinahintulutan ni Lucius ang ilang nakaligtas na tumakas papuntang Elgaia. ","story.map7-dungeon5.020":"Nasawi ang lahat ng naiwan sa Grand Gaia. ","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> Sa tingin mo, bakit nilipol ng mga diyos ang mga tao?","story.map7-dungeon5.022":"Napakaraming teorya, <wait=40>pero wala pang nahahanap na sagot.","story.map7-dungeon5.023":"Pero matapos ang mahabang panahon, <wait=40>muling binuksan ni Lucius ang daan papuntang Grand Gaia.","story.map7-dungeon5.024":"Siguro kailangan din niya ang lakas ng mga tao para talunin ang Apat na Nahulog na Diyos. ","story.map7-dungeon5.025":"Gayunpaman, bakit nga ba nagwawala ang Apat na Nahulog na Diyos?","story.map7-dungeon5.026":"At bakit walang ginagawa ang Banal na Emperador na si Karna Masta, ang panginoon ng mga diyos, sa sitwasyong ito?","story.map7-dungeon5.027":"Napakaraming bagay na hindi talaga maiintindihan nating mga tao.","story.map7-dungeon5.028":"Pero tiyak na naiintindihan ito ni Tilith, bilang alagad ni Lucius, hindi ba?","story.map7-dungeon5.029":"Sigurado ka bang hindi niya alam? <wait=40>Baka may itinatago lang siyang impormasyon sa\'yo.","story.map7-dungeon5.030":"O baka naman, <wait=40>hindi lang talaga siya nag-iisip. ","story.map7-dungeon5.031":"Ho ho ho.","story.map7-dungeon5.032":"Napakabait at napakagandang bata ni Tilith, sana iyon lang ang dahilan. ","story.map7-dungeon5.033":"Anyway, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Pasensya na sa mahabang daldal ko, <wait=40>pero sigurado akong naiintindihan mo ang ibig kong sabihin.","story.map7-dungeon5.035":"\'Wag kang magpatangay sa lahat ng nangyayari, <wait=40>kumilos ka ayon sa sarili mong isip at kalooban. ","story.map7-dungeon5.036":"Ang papel mo rito ay higit na sa kayang pasanin ng isang Summoner. ","story.map7-dungeon5.037":"Dapat lumakad ka na.","story.map7-dungeon5.038":"Nasa kabila ng Larangan ng Noera sa unahan ang pasukan sa Daigdig ng Espiritu.","story.map7-dungeon5.039":"At \'wag mong kalimutan, <wait=20>hindi lang si Tilith at ang mga diyos ang umaasa sa\'yo.","story.map7-dungeon6.001":"Yo, <rep_handlename>!<wait=40> Nandito ka na pala.","story.map7-dungeon6.002":"Tingnan mo!<wait=40> Nasa harap na natin ang pasukan sa Daigdig ng Espiritu.","story.map7-dungeon6.003":"Uy, <wait=40>sinabi na sa\'yo ng diyosang \'yon kung paano tayo makakapasok sa Daigdig ng Espiritu, \'di ba?","story.map7-dungeon6.004":"At nasaan siya? <wait=40>Paano siya nakakapaglakwatsa sa ganitong kritikal na oras!?","story.map7-dungeon6.005":"Ah......<wait=50> Ganoon pala......","story.map7-dungeon6.006":"P-<wait=40>Pero walang dapat ipag-alala, \'di ba?<wait=40> Diyosa naman siya, hindi ba!?","story.map7-dungeon6.007":"Sigurado akong susulpot din siya nang may mayabang na ngiti sa mukha niya!","story.map7-dungeon6.008":"Kaya burahin mo na \'yang malungkot na mukha mo at gawin mo ang trabaho mo!","story.map7-dungeon6.009":"Ginawa niya ang lahat ng \'yon dahil naniniwala siyang kaya mong talunin si Cardes!","story.map7-dungeon6.010":"Kailangan mong ibigay ang lahat ngayon! <wait=40>Hindi mo puwedeng sayangin ang lahat ng ginawa niya!","story.map7-dungeon6.011":"Tama siya.","story.map7-dungeon6.012":"Alam kong nag-aalala ka, <rep_handlename>, <wait=40>pero kailangan muna nating talunin si Cardes bago ang lahat.","story.map7-dungeon6.013":"Kung talagang bukas ang pasukan sa Daigdig ng Espiritu...","story.map7-dungeon6.014":"...wala nang pumipigil sa amin na tulungan ka rin.","story.map7-dungeon6.015":"Para sa diyosa, <wait=40>gagawin namin ang lahat para tumulong!","story.map7-dungeon6.016":"S-<wait=40>Sinusunod ko lang ang utos ng Summoners\' Hall!","story.map7-dungeon6.017":"Walang kinalaman ang ginagawa ko sa tangang diyosang \'yon!","story.map7-dungeon6.018":"Anyway, <wait=40>maganda rin kung siya naman ang magkakautang sa atin. ","story.map7-dungeon6.019":"Siguro gagalingan ko nang kaunti ngayon.","story.map7-dungeon6.020":"Heh, <wait=40>sigurado akong mapapanatag kahit siya kapag nakita niya kung gaano ka ka-motivated, Seria.","story.map7-dungeon6.021":"A-<wait=40>Ano\'ng pinagsasasabi mo!?","story.map7-dungeon6.022":"Sinasabi ko lang na mukhang maaasahan ka namin, Seria. <wait=40>Tama, <rep_handlename>?","story.map7-dungeon6.023":"\'Wag mo siyang sang-ayunan!","story.map7-dungeon6.024":"Sige na, <wait=40>pasukin na natin ang Daigdig ng Espiritu!","story.map7-dungeon6.025":"<rep_handlename>!<wait=40> Seria!<wait=40> Tara na!","story.map7-dungeon7.001":"Kaya ito pala ang Daigdig ng Espiritu Palmyna...<wait=40> Nakakakilabot, totoo lang.","story.map7-dungeon7.002":"Buti na lang mas maluwag ito kaysa sa inakala ko.","story.map7-dungeon7.003":"Ha?<wait=40> Hindi ba mas mahihirapan tayong hanapin si Cardes kung mas maluwag?","story.map7-dungeon7.004":"A-<wait=20>Ah, ibig kong sabihin...<wait=40> Hindi \'yon ang ibig kong sabihin...","story.map7-dungeon7.005":"Iniisip ko lang na mahirap labanan si Cardes sa masikip na lugar. ","story.map7-dungeon7.006":"Oo, <wait=40>tama ka riyan.","story.map7-dungeon7.007":"Sa ganito kalawak na espasyo, <wait=40>walang limitasyon ang mga paraan natin para harapin si Cardes. ","story.map7-dungeon7.008":"Oo, <wait=40>mukhang ganoon nga.","story.map7-dungeon7.009":"<size=16>*Dagundong*","story.map7-dungeon7.010":"A-<wait=20>Ano \'yon!<wait=20> Bakit yumayanig ang lahat?","story.map7-dungeon7.011":"Lintik! <wait=40>Mukhang hindi pala ganoon katahimik dito gaya ng inakala natin!","story.map7-dungeon7.012":"Umaasa pa naman akong mas mahaba ang oras natin para hanapin si Cardes...","story.map7-dungeon7.013":"<rep_handlename>!<wait=40> Seria!","story.map7-dungeon7.014":"Maghiwa-hiwalay tayo para hanapin si Cardes!","story.map7-dungeon7.015":"Sa tingin mo ba magandang ideya \'yan sa ganitong sitwasyon!?","story.map7-dungeon7.016":"Nauubusan na tayo ng oras.","story.map7-dungeon7.017":"Kung hindi natin matatalo si Cardes bago siya makawala...","story.map7-dungeon7.018":"...malaki ang tsansang maglaho tayo kasama ng Daigdig ng Espiritu.","story.map7-dungeon7.019":"......<wait=40>Naiintindihan ko.","story.map7-dungeon7.020":"Kapag nakarinig kayo ng nagbabanggaang espada, <wait=40>tiyak na doon nagsimula ang labanan. ","story.map7-dungeon7.021":"Makinig kayong mabuti at bantayan ninyo ang paligid!","story.map7-dungeon7.022":"<rep_handlename>!","story.map7-dungeon7.023":"Baguhan ka pa lang, <wait=40>kaya kapag nakita mo si Cardes, umupo ka lang at hintayin kami!","story.map7-dungeon7.024":"Tama siya. <wait=40>Anuman ang mangyari, walang dapat humarap sa kanya nang mag-isa!","story.map7-dungeon7.025":"Gusto kong mabuhay tayong lahat at sabay-sabay na bumalik sa Elgaia!","story.map7-ending.001":"Hah...<wait=40> hah...<wait=40> Nahuli kami!","story.map7-ending.002":"<size=20>*Dagundong*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Hawakan mo ang kamay ko......","story.map7-ending.004":"Hello sa inyong lahat! <wait=40>Sorry, nahuli ako!!","story.map7-ending.005":"<rep_handlename>! <wait=40>Alam kong kaya mo!","story.map7-ending.006":"I-<wait=20>Ikaw! <wait=40>Bakit ka nandito!?","story.map7-ending.007":"Akala ko malubha ang sugat mo...","story.map7-ending.008":"Kinutuban akong nasa panganib si <rep_handlename>, <wait=40>kaya ipinagpaliban ko muna ang pagpapagaling para tumulong.","story.map7-ending.009":"Medyo masakit pa rin nga, eh.","story.map7-ending.010":"Ang tanga mo para gawin \'yon dahil lang sa kutob!","story.map7-ending.011":"Buti na lang umabot ako para matulungan ka rin, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"S-<wait=40>Salamat diyan...","story.map7-ending.014":"Wala \'yon! <wait=40>Masaya lang ako na ligtas kayong lahat!","story.map7-ending.015":"Oo, <wait=40>salamat sa pagliligtas sa amin!","story.map7-ending.016":"Sayang naman kung dito lang tayo natapos, <wait=40> matapos nating pabagsakin si Cardes. ","story.map7-ending.017":"Salamat, <wait=40>diyosa.","story.map7-ending.018":"\'Yan ang Karl na kilala ko! <wait=40>Puwede mo rin akong pasalamatan pa, Seria!","story.map7-ending.019":"H-<wait=40>Huwag kang abusado!","story.map7-ending.020":"Kasi naman, <wait=40>kung diyosa ka, bakit lagi kang dumarating sa pinakahuling minuto!","story.map7-ending.021":"A-<wait=40>Ano\'ng problema mo!","story.map7-ending.022":"At isa pa, bakit hindi mo sinabi sa amin kung paano lumabas sa Daigdig ng Espiritu!?","story.map7-ending.023":"A-<wait=40>Ay, <wait=20>siguro nakalimutan...","story.map7-ending.024":"Hayaan na lang natin.","story.map7-ending.025":"At kahit hindi halata, talagang nagpapasalamat si Seria sa ginawa mo para sa kanya.","story.map7-ending.026":"Oo, <wait=40>alam ko.","story.map7-ending.027":"Halata naman sa pamumula ng pisngi niya!","story.map7-ending.028":"Mahal ko rin si Seria!","story.map7-ending.029":"Tumigil ka na! <wait=40>Nakakasuka ka!!","story.map7-ending.030":"<size=12>Ang tanga mo talaga...","story.map7-ending.031":"Karl! <wait=40>Aalis na ako!","story.map7-ending.032":"Nagawa na natin ang ipinagawa ng Summoners\' Hall!","story.map7-ending.033":"Panahon na para tugisin si Graham!","story.map7-ending.034":"T-<wait=20>Teka lang!","story.map7-ending.035":"<rep_handlename>!","story.map7-ending.036":"Hindi pa ako naging ganito kaproud na tawagin kang kaibigan!","story.map7-ending.037":"Pagkatapos ng lahat ng \'to, <wait=20>sabay tayong mag-adventure sa Grand Gaia!","story.map7-ending.038":"\'Wag kang magyabang dahil lang natalo mo si Cardes!","story.map7-ending.039":"Mauubos din ang swerte mo, alam mo \'yon.","story.map7-ending.040":"Sa susunod nating pagkikita, ipapakita ko sa\'yo ang tunay na lakas ng Summoner na namumuno sa Demon Slayers. ","story.map7-ending.041":"Pero hanggang doon, <wait=20>siguraduhin mong buo ka pa!","story.map7-ending.042":"Umalis na sila.","story.map7-ending.043":"Sana magkasama tayong lumaban ulit balang araw!","story.map7-ending.044":"<rep_handlename>! <wait=40>Maraming salamat sa pagtalo kay Cardes!","story.map7-ending.045":"Aaminin kong hindi kita masyadong maasahan noong una tayong nagkita, <wait=40>pero natalo mo na ang dalawa sa Apat na Nahulog na Diyos.","story.map7-ending.046":"Ang interesante talaga ninyong mga tao!","story.map7-ending.047":"Mula nang makilala ko sina Karl, Seria,<wait=40> at ikaw...","story.map7-ending.048":"...lalo ko pang nagustuhan kayong mga tao!","story.map7-ending.049":"Excited na ako sa mga susunod pa nating adventure, <wait=40>aking <rep_handlename>.","story.map7-ending.050":"......<wait=40>Mukhang natalo na ang dakilang si Cardes.","story.map7-ending.051":"Ang natitira na lang na mga Nahulog na Diyos ay si Zevalhua the Supreme, <wait=40>at ang Diyos ng Halimaw na si Afla Dilith. ","story.map7-ending.052":"Tiyak na panahon na para kumilos din sila.","story.map7-ending.053":"Kailangan nating bilisan ang paghahanda.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"Inaabangan ko kung aling landas ang tatahakin mo sa susunod na labanan...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ikaw, <rep_handlename>,<wait=39> na nagbukas ng Encervis...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang kapangyarihan ko sa pagtungo mo sa Palmyna, <wait=40>lupain ng nakakulong na Nahulog na Diyos...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Upang magdala ng bagong pag-asa sa mundong ito na puno ng kalungkutan...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Dapat kang magtiwala sa iyong kapangyarihan, <wait=20>at patuloy na sumulong...","story.map7-open.005":"<rep_handlename>!<wait=40> Sa wakas, nakarating ka na sa Palmyna!","story.map7-open.006":"Malapit na ang Daigdig ng Espiritu kung saan nakakulong si Cardes!","story.map7-open.007":"Dahil natalo mo si Zebra, sigurado akong madali kang makakarating doon, <rep_handlename>.","story.map7-open.008":"Pero kahit ganoon, <wait=40>\'wag kang magpabaya!","story.map7-open.009":"Noong unang panahon, may kaharian dito na tinatawag na Palmyna na buong tapang na lumaban sa mga diyos. ","story.map7-open.010":"Makikita pa rin hanggang ngayon ang mga labi ng digmaang iyon...","story.map7-open.011":"...kasama ang lahat ng espiritu at halimaw na pagala-gala pa rin.","story.map7-open.012":"Sige, <wait=40>hahanapin ko na ang daan natin papunta sa Daigdig ng Espiritu. ","story.map7-open.013":"Dahan-dahan ka lang sa pagsulong, <rep_handlename>.","story.map7-open.014":"Hihintayin kita sa unahan sa Kastilyo ng Obselion!","story.map8-dungeon1.001":"Lintik! <wait=40>Ang layo pa rin.","story.map8-dungeon1.002":"Pero sige na nga, <wait=20>wala namang mangyayari kung magrereklamo ako.","story.map8-dungeon1.003":"Hmm? <wait=40>Hoy, ikaw!","story.map8-dungeon1.004":"Tsk, <wait=20>ikaw pala \'yan, mahal naming <rep_handlename>.","story.map8-dungeon1.005":"Bakit ka nandito?","story.map8-dungeon1.006":"Hindi kaya...!?","story.map8-dungeon1.007":"Nandito ka para angkinin ang kredito sa pinaghirapan ko, \'no!?","story.map8-dungeon1.008":"Anyway, <wait=20>ano \'tong naririnig ko tungkol sa Cordelica?","story.map8-dungeon1.009":"May narinig akong tsismis na mag-isa mo raw tinalo ang isa sa Apat na Nahulog na Diyos?","story.map8-dungeon1.010":"Hmph, <wait=40>o baka naman, <wait=20>kinailangan ka pang iligtas nina Karl at Seria, ano?","story.map8-dungeon1.011":"Ewan, <wait=20>wala rin namang pinagkaiba \'yon.","story.map8-dungeon1.012":"Tumahimik ka! <wait=40>Hindi ako humihingi ng paliwanag o kung ano man!","story.map8-dungeon1.013":"Kung may kalahating utak ka man lang, makikinig ka sa sasabihin ko!","story.map8-dungeon1.014":"Ba<wait=20>s<wait=20>ta.","story.map8-dungeon1.015":"Huwag na huwag kang haharang sa daan ko! \'Yon lang!","story.map8-dungeon1.016":"Nasa gitna ako ng pagsasagawa ng napakahalagang misyon para sa Summoners\' Hall.","story.map8-dungeon1.017":"Pero wala namang hindi kayang hawakan ng isang elite na tulad ko.","story.map8-dungeon1.018":"Kung gets mo ang ibig kong sabihin, lumayas ka na lang at pumunta kahit saan!","story.map8-dungeon1.019":"At pangako, kapag nakita kitang tumatambay sa Cordelica, didispatsahin kita agad.","story.map8-dungeon1.020":"Gets mo?","story.map8-dungeon2.001":"Hay, <wait=40>mas delikado pala ang lugar na \'to kaysa inakala ko.","story.map8-dungeon2.002":"Sa ganitong takbo, malayo pa ang lalakbayin ko bago makarating sa tore.","story.map8-dungeon2.003":"Aba, <wait=40>ikaw pala, <rep_handlename>.","story.map8-dungeon2.004":"Ano\'ng ginagawa mo rito?","story.map8-dungeon2.005":"Hehe, <wait=40>hindi ko na pala kailangang itanong.","story.map8-dungeon2.006":"Seryoso talaga siguro ang Summoners\' Hall para ipadala ka hanggang dito.","story.map8-dungeon2.007":"Pero gayunpaman, <wait=20>wala akong balak sumuko.","story.map8-dungeon2.008":"Aangkinin ng Imperial Guard ang kapangyarihang nakatago sa Lizeria.","story.map8-dungeon2.009":"Hehe, <wait=40>hindi mo kailangang tumingin nang ganyan.","story.map8-dungeon2.010":"Nakita ko ang tunay mong kakayahan noong nasa Cordelica tayo.","story.map8-dungeon2.011":"Bakit hindi mo iwan ang grupong \'yon ng Akras at sumama sa amin?","story.map8-dungeon2.012":"Para makabuo ng tunay na kapayapaan, kailangan mong kumawala sa kontrol ng mga Elder!","story.map8-dungeon2.013":"Ano\'ng pinagsasasabi mo, <wait=40>asong imperyal!","story.map8-dungeon2.014":"Walang silbi ang kahit anong sabihin mo kay <rep_handlename>.","story.map8-dungeon2.015":"Ang bastos na boses na \'yan...","story.map8-dungeon2.016":"Matagal na tayong hindi nagkita...","story.map8-dungeon2.017":"Ms. Imperial Guard.","story.map8-dungeon2.018":"Nagulat ako. <wait=40>Paano ka ba nakarating dito?","story.map8-dungeon2.019":"Wala lang \'yon, talaga.","story.map8-dungeon2.020":"Nagkataon lang na ako ang Summoner na espesyal na pinili ng Summoners\' Hall para pumunta rito at mag-imbestiga.","story.map8-dungeon2.021":"\'Yang mukhang tangang Summoner na \'yan ay turista lang na naghahanap ng murang kilig.","story.map8-dungeon2.022":"Walang kaalam-alam si <rep_handlename> sa nangyayari rito.","story.map8-dungeon2.023":"Ibig kong sabihin, hindi ka naman nagbabahagi ng mahalagang impormasyon sa engot na \'to, \'di ba?","story.map8-dungeon2.024":"Nngh...","story.map8-dungeon2.025":"Anyway, <wait=20>ang tunay na mga tanga rito ay ang grupong \'yon sa Summoners\' Hall.","story.map8-dungeon2.026":"Paano nila naipadala ang isang second class na Summoner na tulad mo sa ganitong lugar?","story.map8-dungeon2.027":"Patunay lang \'yon na wala silang kaalam-alam kung gaano kahalaga ang lugar na \'to.","story.map8-dungeon2.028":"At kung ganoon nga talaga, <wait=20>wala akong magiging problema sa pagkuha ng kapangyarihang nakatago rito.","story.map8-dungeon2.029":"Hoy! <wait=40>Ingatan mo ang bibig mo!","story.map8-dungeon2.030":"Wala kang laban sa\'kin kung ibubuhos ko ang buong lakas ko!","story.map8-dungeon2.031":"Hehe, <wait=40>ang tindi ng itsura ng mukha mo.","story.map8-dungeon2.032":"Pero sa totoo lang, <wait=20>hindi mo kailangang magmatapang.","story.map8-dungeon2.033":"Wala rin naman akong oras para makipaglaro sa\'yo.","story.map8-dungeon2.034":"Tatakas ka ba?","story.map8-dungeon2.035":"Hindi, <wait=40>pinipili ko lang na iwasan ang mga walang-saysay na engkuwentro para matupad ang layunin ko.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>pag-isipan mo ang napag-usapan natin kanina.","story.map8-dungeon2.037":"Sigurado akong mas makikinabang ka roon kaysa magkaroon ng mga tangang kakampi na tulad niya.","story.map8-dungeon2.038":"<size=22>Ano\'ng pinagsasasabi mo!</size>","story.map8-dungeon2.039":"Heh, <wait=40>tumakas din pala siya.","story.map8-dungeon2.040":"Uy! <wait=40><rep_handlename>!","story.map8-dungeon2.041":"Bakit lagi na lang kitang nakikita sa mga ganitong lugar?","story.map8-dungeon2.042":"Sinasabi mo bang wala kang balak makinig sa sinasabi ko?","story.map8-dungeon2.043":"O baka naman, <wait=20>balak mong tanggapin ang alok niya at traidurin ang Summoners\' Hall?","story.map8-dungeon2.044":"Wala naman talaga akong pakialam sa gagawin mo.","story.map8-dungeon2.045":"Kapag binalewala mo ulit ang babala ko, <wait=20>sa susunod na makita kita...","story.map8-dungeon2.046":"...wala na akong magagawa kundi gawin kang abo.","story.map8-dungeon2.047":"Heh, <wait=40>ang kulit mo talaga!","story.map8-dungeon2.048":"Pero huwag kang mag-alala, <wait=40>hindi kita tinatakot o kung ano man.","story.map8-dungeon2.049":"Gusto ko lang malaman mo na wala akong pinapayagang humarang sa daan ko!","story.map8-dungeon2.050":"Gets mo?","story.map8-dungeon3.001":"Hoy, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Mukhang maganda ang mood mo.","story.map8-dungeon3.003":"Sandali!","story.map8-dungeon3.004":"Ang pagbalewala mo sa babala ko at pagpunta rito ay nangangahulugan lang na balak mong traidurin ang Summoners\' Hall, tama ba ako?","story.map8-dungeon3.005":"Anong klaseng kondisyon ang inilatag sa\'yo ng babaeng \'yon?","story.map8-dungeon3.006":"Hmm? <wait=40>Sinasabi mong hindi ka traidor?","story.map8-dungeon3.007":"<size=22>Ha ha ha!</size>","story.map8-dungeon3.008":"Interesante ang pinili mo para sa isang tangang tulad mo.","story.map8-dungeon3.009":"Na isa lang ang ibig sabihin...","story.map8-dungeon3.010":"Pumunta ka rito para guluhin ako, \'no?","story.map8-dungeon3.011":"Ha ha ha! <wait=40>Nakakatawa ka!","story.map8-dungeon3.012":"<size=22>Huwag kang masyadong mayabang!</size>","story.map8-dungeon3.013":"Gusto mo bang ipakita ko sa\'yo kung gaano ka kababa kumpara sa\'kin?","story.map8-dungeon3.014":"Ang engot.","story.map8-dungeon3.015":"Hindi talaga kita matiis.","story.map8-dungeon3.016":"Ay oo nga pala, narinig kong kaibigan ka rin pala ng tangang si Karl.","story.map8-dungeon3.017":"Mukhang wala akong magagawa kundi turuan ka ng leksyon at ipakita sa\'yo kung gaano talaga ako kagaling.","story.map8-dungeon3.018":"Ayos ba sa\'yo? <wait=20>Hihintayin kita sa kabila ng nagyelong lawang ito.","story.map8-dungeon3.019":"Ako mismo ang magtuturo sa\'yo, kaya dapat lang na abangan mo \'yan!","story.map8-dungeon4.001":"H-<wait=20>Hindi maaari! <wait=40>Imposible \'yan.","story.map8-dungeon4.002":"Natalo mo rin si Cardes!?","story.map8-dungeon4.003":"H-<wait=20>Hindi po, <wait=40>hindi ako nagdududa sa inyo...","story.map8-dungeon4.004":"Naiintindihan ko. <wait=40>Aasikasuhin ko ito nang buong ingat.","story.map8-dungeon4.005":"Opo. <wait=40>Hindi ninyo kailangang mag-alala tungkol diyan.","story.map8-dungeon4.006":"Gagawin ko ang lahat para hindi kayo mabigo.","story.map8-dungeon4.007":"Hay... <wait=40>Mas mabilis na nagkakagulo ang mga bagay kaysa inaasahan ko.","story.map8-dungeon4.008":"Huh, <wait=20>hindi kaya...","story.map8-dungeon4.009":"Hehe, <wait=40>nagkita na naman tayo.","story.map8-dungeon4.010":"Kung gayon, natalo mo na si Lugina?","story.map8-dungeon4.011":"Siguradong hindi naging problema sa\'yo ang pagtalo sa ganoon kahinang Summoner, lalo na\'t natalo mo na ang dalawa sa Apat na Nahulog na Diyos?","story.map8-dungeon4.012":"Hehe, <wait=20>huwag mo akong tingnan nang ganyan.","story.map8-dungeon4.013":"Naiintindihan ko kung gaano ka talaga kalakas kumpara sa kanya.","story.map8-dungeon4.014":"Kaya, <wait=20>hayaan mong itanong ko ulit.","story.map8-dungeon4.015":"Hindi mo ba iiwan ang Akras Summoners\' Hall at makikipagtulungan sa amin?","story.map8-dungeon4.016":"Hindi tayo nagkaroon ng sapat na oras para mag-usap noong huli dahil bastos tayong naabala.","story.map8-dungeon4.017":"Pero seryoso ako.","story.map8-dungeon4.018":"Hehe, <wait=20>natural lang na malito ka sa ganito kabiglang paanyaya.","story.map8-dungeon4.019":"Hayaan mong sabihin ko sa\'yo ang isang bagay. <wait=40>Sira na ang sistema ng pamamahala sa Elgaia.","story.map8-dungeon4.020":"At kami lang ang makakaayos nito.","story.map8-dungeon4.021":"Nakikita mo rin naman ang nangyayari, \'di ba?","story.map8-dungeon4.022":"Sa halip na isang republika, isang organisasyon ng mga Summoner ang nagpapatakbo sa mundo.","story.map8-dungeon4.023":"Noong unang panahon, <wait=20>may iilang nakatakas sa trahedya ng sagupaan laban sa mga diyos.","story.map8-dungeon4.024":"Pinamunuan nila ang mga tao at itinatag ang Imperyo ng Randall.","story.map8-dungeon4.025":"Pagkatapos, <wait=20>matagal na panahon matapos maitatag ang imperyo...","story.map8-dungeon4.026":"...ilang grupo ang nabuo bilang pagtutol sa may-pribilehiyong uri ng Imperyo ng Randall.","story.map8-dungeon4.027":"Itinatag nila ang Elgaia Federation.","story.map8-dungeon4.028":"Kamakailan lang, ang Elgaia ang unang nagsimulang magbago.","story.map8-dungeon4.029":"Sa panahon ng pagbabagong ito lumitaw ang mga Summoner, <wait=20>pati na ang isang nagnais na pagbuklurin silang lahat.","story.map8-dungeon4.030":"Itinatag nila ang Akras Summoners\' Hall.","story.map8-dungeon4.031":"Ang mga Sinaunang Summoner na bumuo ng Akras Summoners\' Hall...","story.map8-dungeon4.032":"...kilala rin bilang \\"Mga Orihinal na Summoner\\" dahil sila ang unang tumawid sa gate...","story.map8-dungeon4.033":"...gamit ang kahanga-hangang kapangyarihan ng pagsu-summon na nakamit nila...","story.map8-dungeon4.034":"...ay bumuo ng isa sa pinakadakilang organisasyon sa buong Elgaia.","story.map8-dungeon4.035":"Dahil sa napakalaking kapangyarihan ng mga Summoner, unti-unti ring nakuha ng organisasyong ito ang kontrol sa ekonomiya.","story.map8-dungeon4.036":"Bago pa napansin ng sinuman, naging hungkag na anino na lang ng dati nitong sarili ang republika.","story.map8-dungeon4.037":"Ngayon, ang Imperyo ng Randall at ang Elgaia Federation ay mga hungkag na balangkas na lang.","story.map8-dungeon4.038":"Hehe, <wait=40>sinasabi ng mukha mong naiintindihan mo na ito.","story.map8-dungeon4.039":"Pero, <wait=40>mukhang wala kang problema rito.","story.map8-dungeon4.040":"Siyempre, <wait=20>walang kinalaman sa mga ordinaryong tao kung sino ang may kontrol sa ano.","story.map8-dungeon4.041":"Pero hindi dapat basta-basta tinitingnan ang mundo.","story.map8-dungeon4.042":"Iniisip ko kung papanig ka pa rin sa Summoners\' Hall kung alam mo ang madilim nilang panig.","story.map8-dungeon4.043":"Kung mangangako kang makikipag-alyansa sa amin mula ngayon, sasabihin ko sa\'yo ang lahat.","story.map8-dungeon4.044":"Hehe, <wait=20>pero hindi mo kailangang magmadali.","story.map8-dungeon4.045":"Dahil anuman ang mangyari, kapag nakuha ko na ang kapangyarihang nakatago rito...","story.map8-dungeon4.046":"...wala ka nang magagawa kundi sumunod sa amin sa aming makatarungang landas.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Sige, <wait=40>aalis na ako.","story.map8-dungeon4.049":"Inaasahan kong makakausap ka ulit, nang hindi naaabala ng bastos na hangal na \'yon.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"Hoy, <wait=40>ano\'ng nangyari sa\'yo bigla?","story.map8-dungeon5.003":"Iniisip mo bang mas malakas ka sa\'kin sa huling laban natin?","story.map8-dungeon5.004":"Mukhang hindi mo napansin kung gaano kita pinagbigyan.","story.map8-dungeon5.005":"Mukhang kailangan mo ng paalala.","story.map8-dungeon5.006":"Ha? <wait=40>Kung alam ko ba ang madilim na panig ng Summoners\' Hall?","story.map8-dungeon5.007":"Tanga ka, <wait=20>anong kalokohang kuwento ang hinayaan mong ipasok ng babaeng \'yon sa utak mo?","story.map8-dungeon5.008":"Sinabi ko nang huwag kang makinig sa babaeng \'yon!","story.map8-dungeon5.009":"At saka, walang kinalaman sa atin ang ginagawa ng Summoners\' Hall.","story.map8-dungeon5.010":"Sa madaling salita, ang talagang mahalaga lang ay kung sino ang pinakamalakas sa Elgaia.","story.map8-dungeon5.011":"Ang Elgaia Federation ba at ang masisigasig nilang mamamayan?","story.map8-dungeon5.012":"O ang Imperyo ng Randall at ang makaluma nilang militar?","story.map8-dungeon5.013":"O baka wala sa kanila.","story.map8-dungeon5.014":"Pero sa tingin ko, ang Akras Summoners\' Hall ang pinakamalakas.","story.map8-dungeon5.015":"Ang mga elite ng Summoners\' Hall ang mga elite ng Elgaia.","story.map8-dungeon5.016":"\'Yon lang \'yon.","story.map8-dungeon5.017":"At kaya kailangan kong gawin ang lahat para sa Summoners\' Hall.","story.map8-dungeon5.018":"Pero nakakainis na talaga ang pagharang mo sa\'kin habang abala na ako sa pagtatrabaho.","story.map8-dungeon5.019":"Kaya ngayong araw, hindi kita pagbibigyan.","story.map8-dungeon5.020":"Hihintayin kita sa unahan.","story.map8-dungeon5.021":"<size=20>Ipapakita ko sa\'yo kung gaano tayo magkaiba!</size>","story.map8-dungeon5.022":"<size=20>Humanda ka na!</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Dumating ka nga.","story.map8-dungeon6.002":"Tingnan mo. <wait=40>Hindi ba kahanga-hanga?","story.map8-dungeon6.003":"Noong unang panahon, ito ang tahanan ng Republika ng La Veda kung saan nananalangin ang mga tao sa Diyos ng Liwanag.","story.map8-dungeon6.004":"Pero, <wait=20>winasak ang mga taong iyon ng mismong diyos na pinagdarasalan nila.","story.map8-dungeon6.005":"Nakakikilabot na tanawin.","story.map8-dungeon6.006":"Maraming tala tungkol sa labanan laban sa mga diyos.","story.map8-dungeon6.007":"Ang una at pinakatanyag ay ang alamat ng Anim na Bayani.","story.map8-dungeon6.008":"Pero, <wait=20>marami pa ring hindi alam.","story.map8-dungeon6.009":"Lalo na, <wait=20>kaunti lang ang alam tungkol sa nangyari sa Grand Gaia...","story.map8-dungeon6.010":"...matapos iligtas ni Lucius ang mga tao.","story.map8-dungeon6.011":"Ano nga ba talaga ang ginagawa ni Lucius...","story.map8-dungeon6.012":"...habang gumagawa ng napakaraming kalupitan ang Apat na Nahulog na Diyos.","story.map8-dungeon6.013":"At bakit hindi pa kumikilos ang dakilang pinuno ng mga diyos na si Carna Masta?","story.map8-dungeon6.014":"Hehe, <wait=20>kapag iniisip mo \'yan, mapapaisip ka talaga kung gaano tayo kaligtas.","story.map8-dungeon6.015":"Ako...","story.map8-dungeon6.016":"Hindi, <wait=20>kami ay namumuhay sa takot sa kasalukuyang sitwasyon.","story.map8-dungeon6.017":"Sa ganitong panahon ng kawalang-katiyakan...","story.map8-dungeon6.018":"...sino ang nakakaalam kung kailan muling magpapasya ang mga diyos na manira at targetin ang Elgaia?","story.map8-dungeon6.019":"Kaya kailangan naming makuha ang dakilang kapangyarihang nakahimlay rito.","story.map8-dungeon6.020":"Ang kapangyarihang sinasabing nakahimlay sa lupaing dating sinasamba ng mga tao ang Diyos ng Liwanag.","story.map8-dungeon6.021":"Hehe, <wait=40>ayan ka na naman sa nababahalang mukha mo.","story.map8-dungeon6.022":"Hindi mo kailangang magmadali. <wait=40>Maglaan ka ng oras para maintindihan ang lahat ng ito.","story.map8-dungeon6.023":"Pero, <wait=20>gusto ko ring mag-isip ka para sa hinaharap.","story.map8-dungeon6.024":"Alin ang makatarungang landas tungo sa paglikha ng mundong mapayapang matitirhan ng mga tao?","story.map8-dungeon6.025":"Sige, <wait=20>kailangan ko nang umalis.","story.map8-dungeon6.026":"Ay, <wait=20>at isa pa...","story.map8-dungeon6.027":"Kanina lang, nakita ko si Lugina na papunta sa isang itim na tulay sa unahan na may napakabagsik na itsura sa mukha.","story.map8-dungeon6.028":"Mag-ingat ka, ha?","story.map8-dungeon6.029":"Hehehe.","story.map8-dungeon7-2.001":"I-<wait=40>Imposible...","story.map8-dungeon7-2.002":"Paano ako matatalo sa...","story.map8-dungeon7-2.003":"Nngh...","story.map8-dungeon7-2.004":"<size=18>Hindi ito totoo...</size>","story.map8-dungeon7-2.005":"<size=24>Hindi ko ito matatanggap!</size>","story.map8-dungeon7-2.006":"Hindi ako dapat matalo sa\'yo kailanman!","story.map8-dungeon7-2.007":"Imposible...","story.map8-dungeon7-2.008":"<size=20>Hindi! <wait=40>Hindi! <wait=40>Hindi!","story.map8-dungeon7-2.009":"<size=18>Paano ako natalo...</size>","story.map8-dungeon7-2.010":"Hmph, <wait=40>ano\'ng tinititigan mo?","story.map8-dungeon7-2.011":"Umalis ka na rito!","story.map8-dungeon7-2.012":"<size=20>Lintik ka!!</size>","story.map8-dungeon7-2.013":"Bwisit...","story.map8-dungeon7.001":"Sawang-sawa na akong maghintay, <rep_handlename>.","story.map8-dungeon7.002":"Sigurado akong dadaan ka rito.","story.map8-dungeon7.003":"Ang hinahanap namin ng babaeng \'yon ay nasa tore raw sa unahan.","story.map8-dungeon7.004":"<size=20>Argh!</size>","story.map8-dungeon7.005":"Ayan na naman \'yang nakakainis na mukha mo!","story.map8-dungeon7.006":"Kahit mukhang wala kang pakialam, wala kang pinagkaiba sa kanya: humaharang sa daan ko ang pagkausyoso mo.","story.map8-dungeon7.007":"Sa kawalan mo ng alam, balak mo ba talagang agawin ang tropeo ko?","story.map8-dungeon7.008":"Nagsisimula na talaga akong mainis sa\'yo.","story.map8-dungeon7.009":"Ang misyong ito ang pagkakataon kong ipakita sa mga matatandang \'yon ang tunay kong lakas.","story.map8-dungeon7.010":"Hindi ko hahayaang humarang sa\'kin ang isang baguhang tulad mo!","story.map8-dungeon7.011":"Hindi ko hahayaang mapunta sa iba ang tagumpay na ito!","story.map8-dungeon7.012":"Dudurugin ko ang sinumang haharang sa daan ko!","story.map8-dungeon7.013":"Nngh, <wait=20>ano \'yang itsura mo! Huwag kang matakot ngayon!","story.map8-dungeon7.014":"Bahala ka.","story.map8-dungeon7.015":"Ito na ang huli kong babala.","story.map8-dungeon7.016":"Sa susunod na magkasalubong tayo...","story.map8-dungeon7.017":"<size=22>Katapusan mo na!</size>","story.map8-dungeon7.018":"<size=22>Gets mo?</size>","story.map8-dungeon8.001":"Nngh...","story.map8-dungeon8.002":"Hindi ko inaasahan ito, <wait=20>hindi ko akalaing ganito kahirap.","story.map8-dungeon8.003":"Pero gayunpaman, <wait=20>hindi ako susuko dahil lang sa maliliit na sugat na \'to!","story.map8-dungeon8.004":"Kailangan ko talagang mahanap ang gate para kay Eriole.","story.map8-dungeon8.005":"Uy! <wait=40><rep_handlename>!","story.map8-dungeon8.006":"Hindi ako makapaniwalang naabutan mo ako.","story.map8-dungeon8.007":"Dahil nandito ka, ibig sabihin natalo mo si Lugina, tama?","story.map8-dungeon8.008":"Medyo magaspang man siya, <wait=20>pero bilang pinuno ng Demon Slayers, higit pa siya sa mabigat na kalaban.","story.map8-dungeon8.009":"Talagang malakas ka siguro para matalo siya.","story.map8-dungeon8.010":"Nngh...","story.map8-dungeon8.011":"Hehe, <wait=20>wala lang ang mga sugat na \'to, huwag kang mag-alala.","story.map8-dungeon8.012":"May maliit lang na problemang lumitaw.","story.map8-dungeon8.013":"Ngayon higit kailanman, nakatuon ang layunin ko sa pagkuha ng nakatagong kapangyarihang naghihintay rito.","story.map8-dungeon8.014":"Kahit ikaw, hindi kita hahayaang humarang sa daan ko.","story.map8-dungeon8.015":"Haha, <wait=40>nakakatakot na ekspresyon.","story.map8-dungeon8.016":"Pero gayunpaman, <wait=20>seryoso ako.","story.map8-dungeon8.017":"Naniniwala akong kayang ibalik ng kapangyarihang nakahimlay rito ang mundo sa dapat nitong kalagayan.","story.map8-dungeon8.018":"Alam mo ba kung ano ang naghihintay sa atin dito?","story.map8-dungeon8.019":"Isa itong tore na sinasabing umiiral na bago pa man naitatag ang La Veda.","story.map8-dungeon8.020":"Maaaring itinayo pa nga ang La Veda para bantayan ang tore.","story.map8-dungeon8.021":"Sa madaling salita, <wait=40>higit pa sa mahalaga ang naghihintay sa atin dito.","story.map8-dungeon8.022":"Malamang marami ring bitag ang inilagay para protektahan ito.","story.map8-dungeon8.023":"Naiintindihan mo ba ang ibig kong sabihin?","story.map8-dungeon8.024":"Kung oo, <wait=40>huwag ka nang tumuloy pa.","story.map8-dungeon8.025":"Ayaw mo namang mauwi sa pakikipaglaban sa\'kin, \'di ba?","story.map8-dungeon8.026":"He he he.","story.map8-dungeon8.027":"Inaasahan kong susundin mo ang payo ko at babalik ka na.","story.map8-dungeon8.028":"Sige, <wait=40>aalis na ako.","story.map8-dungeon8.029":"Mag-uusap ulit tayo kapag matagumpay kong natapos ang layunin ko.","story.map8-dungeon8.030":"Huwag mong isiping sumuko na ako sa pagkumbinsi sa\'yong pumanig sa amin.","story.map8-dungeon8.031":"He he he.","story.map8-dungeon_ex_clear.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"Sir! <wait=40>Ayos ka lang ba?","story.map8-dungeon_ex_clear.003":"*Buntong-hininga* <wait=20>Nakahinga ako nang maluwag.","story.map8-dungeon_ex_clear.004":"Lalo pang inimbestigahan ng mga opisyal ng Summoners\' Hall ang lawa sa ilalim ng lupa pagkaalis mo.","story.map8-dungeon_ex_clear.005":"Mukhang doon pala nagpapahinga ang diyos na si Lagzal.","story.map8-dungeon_ex_clear.006":"Lumitaw rin siya sa Grand Gaia noong dakilang labanan ng mga diyos at tao.","story.map8-dungeon_ex_clear.007":"Ayon sa mga tala namin, orihinal siyang tinalo ng iisang bayani.","story.map8-dungeon_ex_clear.008":"Pero mukhang hindi siya tuluyang nawasak, at sa halip ay umatras siya rito.","story.map8-dungeon_ex_clear.009":"Halos tumigil ang tibok ng puso ko nang malaman namin ang impormasyong ito.","story.map8-dungeon_ex_clear.010":"Ibig kong sabihin, napakaraming buhay ang kinuha niya sa labanan!","story.map8-dungeon_ex_clear.011":"Sobra akong nag-alala nang malaman kong haharapin mo siya...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"Huli na para humingi ng tawad!","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Buntong-hininga* <wait=40>Pero Summoner ka nga naman.","story.map8-dungeon_ex_clear.016":"Mas marami at mas delikadong lugar pa ang iimbestigahan mo mula ngayon.","story.map8-dungeon_ex_clear.017":"Kung gusto ko talagang suportahan ka, hindi kita dapat pigilan.","story.map8-dungeon_ex_clear.018":"Naiintindihan ko!","story.map8-dungeon_ex_clear.019":"Naniniwala ako sa\'yo, sir!","story.map8-dungeon_ex_clear.020":"At lagi kang makakaasa sa akin, sir!","story.map8-dungeon_ex_clear.021":"He he he.","story.map8-dungeon_ex_clear.022":"Sige, makikipag-ugnayan ako kapag may dumating pang impormasyon!","story.map8-dungeon_ex_clear.023":"Mag-ingat ka hanggang sa susunod!","story.map8-dungeon_ex_open.001":"<size=18>*Buzz* </size><wait=20><size=20>*Buz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Sir, <wait=40>naririnig mo ba ako?","story.map8-dungeon_ex_open.003":"Ayos, <wait=20>nakakonekta ako agad sa\'yo ngayon.","story.map8-dungeon_ex_open.004":"Ako si Lin Merylham mula sa Logistics Support...","story.map8-dungeon_ex_open.005":"...ng Grand Gaia Survey Office Bureau of Investigation, handang maglingkod sa inyo.","story.map8-dungeon_ex_open.006":"<rep_handlename>, bilang miyembro ng Summoner Army ng Akras Summoners\' Hall...","story.map8-dungeon_ex_open.007":"...ngayong araw, hinihiling naming imbestigahan mo ang Lawa sa Ilalim ng Lupa ng Golzo!","story.map8-dungeon_ex_open.008":"Ilang araw na ang nakalipas, natukoy ng Summoners\' Hall ang pagkawala ng isang malaking puwersa sa Lizeria.","story.map8-dungeon_ex_open.009":"Pagkatapos noon, may natukoy kaming mas malaki pang puwersa rito sa lawang ito sa ilalim ng lupa.","story.map8-dungeon_ex_open.010":"Gusto naming imbestigahan mo kung ano talaga ang nangyayari rito.","story.map8-dungeon_ex_open.011":"Sa totoo lang, masama ang kutob ko rito, kaya ayos lang kung ayaw mong tumuloy...","story.map8-dungeon_ex_open.012":"...pero iba ang sinasabi ng tono ng boses mo.","story.map8-dungeon_ex_open.013":"Puno ka ng ambisyon gaya ng dati!","story.map8-dungeon_ex_open.014":"Naiintindihan ko!","story.map8-dungeon_ex_open.015":"Kahit nag-aalala ako, susuportahan kita gaya ng lagi kong ginagawa!","story.map8-dungeon_ex_open.016":"Kaya pakiusap, <wait=40>bumalik ka sa akin nang buo!","story.map8-dungeon_ex_open.017":"Naiintindihan mo?","story.map8-dungeon_ex_open.018":"Hmph...","story.map8-ending.001":"Ang mapabagsak ang ganoong klaseng sistema ng depensa...","story.map8-ending.002":"Ito siguro ang inaasahang lakas ng isang nakatalo ng Nahulog na Diyos.","story.map8-ending.003":"Pero gayunpaman, <wait=20>hindi ko kailanman isusuko ang nakaselyo sa kabila ng gate sa unahan!","story.map8-ending.004":"Tingnan mo nga ang sarili mo, <rep_handlename>.","story.map8-ending.005":"Hindi ka naman gaanong sugatan, pero hindi ka pa rin makagalaw?","story.map8-ending.006":"Tsk, <wait=40>nakakainis talagang isipin na nahirapan ako nang ganoon sa\'yo.","story.map8-ending.007":"Ha? <wait=40>Ano\'ng ibig mong sabihin, magmadali sa unahan?","story.map8-ending.008":"Heh, <wait=20>wala pa silang sinasabi sa\'yo, \'no?","story.map8-ending.009":"Sumama ka sa\'kin.","story.map8-ending.010":"Tingnan natin kung anong nakakatuwang gulo ang pinasok ng babaeng \'yon.","story.map8-ending.011":"S-<wait=20>Sandali. <wait=20>Paanong wala rito?","story.map8-ending.012":"Ibig bang sabihin nito, nilinlang kami?","story.map8-ending.013":"Paano kami nagawang...","story.map8-ending.014":"Ano ang makukuha nila sa panlilinlang sa amin nang ganoon?","story.map8-ending.015":"Hoy, <rep_handlename>! <wait=40>Tingnan mo!","story.map8-ending.016":"Gaya lang ng sinabi ko.","story.map8-ending.017":"Mukhang may kaunting problema si Munting Ms. Imperial Guard.","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Heh he he. <wait=40>Tigilan mo na \'yang nakakatakot na mukha.","story.map8-ending.020":"Wala rito ang kapangyarihang hinahanap mo.","story.map8-ending.021":"Nasa mga guho ito ng gate.","story.map8-ending.022":"Alam ko dahil ipinadala ako ng mga Elder Summoner para imbestigahan ito.","story.map8-ending.023":"Pero nag-enjoy akong makinig sa madamdamin mong daldal.","story.map8-ending.024":"Ikaw na bastos na hangal.","story.map8-ending.025":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.026":"Kahit titigan mo pa ako nang masama hangga\'t gusto mo, hindi pa rin bubukas ang gate.","story.map8-ending.027":"Nngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"Paano mo natitiis na makasama nang ganoon katagal ang ganyang kabastos na lalaki?","story.map8-ending.030":"Alam mo naman ang ibig kong sabihin, \'di ba?","story.map8-ending.031":"Basura talaga ang lalaking \'to!","story.map8-ending.032":"Hinihintay ko lang ang araw na tatanggapin mo ang paanyaya ko.","story.map8-ending.033":"Ooh, <wait=20>naiinggit ako! <wait=40>Gusto ko ring maimbitahan, alam mo ba!","story.map8-ending.034":"Pero sayang lang ang oras ko sa walang-saysay mong layunin.","story.map8-ending.035":"Nngh.","story.map8-ending.036":"Tandaan mo \'to.","story.map8-ending.037":"Balang araw, pagsisisihan mo ang lahat ng ginawa mo.","story.map8-ending.038":"Heh, <wait=20>sa wakas umalis na rin siya.","story.map8-ending.039":"Hoy, <rep_handlename>.","story.map8-ending.040":"Bakit bigla kang mukhang kalmado?","story.map8-ending.041":"Huwag mong sabihing iniisip mong pinatawad na kita?","story.map8-ending.042":"Lalakas pa ako nang higit kaysa dati.","story.map8-ending.043":"At kapag nangyari \'yon, gagamitin kita hangga\'t kaya ko.","story.map8-ending.044":"Huwag mong kalimutan \'yan!","story.map8-ending.045":"Heh.","story.map8-ending.046":"Ay, <wait=20>at isa pa...","story.map8-ending.047":"Mukhang wala ka talagang ideya kung ano ang hinahabol namin ngayon.","story.map8-ending.048":"Noong una, akala ko sinusubukan mo lang akong lokohin para maunahan mo ako.","story.map8-ending.049":"Pero sa huli, mukhang kasingtanga ka lang pala ng itsura mo!","story.map8-ending.050":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.051":"Akin ang susunod na tagumpay.","story.map8-ending.052":"At dapat lang na magpasalamat ka sa lahat ng ginawa ko para sa\'yo, ako, ang pinakamakapangyarihang Summoner sa buong mundo!","story.map8-ending.053":"Ganoon ba, <wait=20>kaya naglaho na ang gate.","story.map8-ending.054":"Ayos lang. <wait=20>Hindi mo kailangang humingi ng tawad.","story.map8-ending.055":"Ginawa mo ang lahat sa isang mahirap na gawain.","story.map8-ending.056":"Oo, <wait=20>mag-ingat ka at bumalik nang ligtas.","story.map8-ending.057":"He he he.","story.map8-ending.058":"Mukhang lahat ay eksaktong gaya ng sinabi mo.","story.map8-ending.059":"Mukhang tapos na ang kontrata.","story.map8-ending.060":"Panahon na rin para kumilos kami.","story.map8-ending.061":"Oo, <wait=40>inaasahan din ng aking panginoon ang paglusob ninyo.","story.map8-ending.062":"He he he.","story.map8-ending.063":"<size=20>Ibalik natin ang mundo sa tunay nitong anyo!</size>","story.map8-ending.064":"<size=20>Masasaksihan natin itong magbago at umunlad sa harap mismo ng ating mga mata!</size>","story.map8-ending.065":"<size=20>Maghintay lang kayo at makikita ninyo!</size>","story.map8-ending.066":"<size=20>Malapit nang isilang ang isang bagong bayani!</size>","story.map8-open.001":"Randall,<wait=40> ang kabiserang lungsod ng Imperyo ng Randall.","story.map8-open.002":"Ang pribadong silid ng mga tagabantay ng pamilyang imperyal, <wait=40>ang Imperial Guard.","story.map8-open.003":"*Tok* <wait=20>*tok*","story.map8-open.004":"Pasok.","story.map8-open.005":"Paumanhin sa pang-aabala.","story.map8-open.006":"Oh, <wait=40> kay gandang ekspresyon sa mukha mo. <wait=20>May magandang balita ka ba para sa akin?","story.map8-open.007":"Opo, <wait=20>at paumanhin at natagalan ito.","story.map8-open.008":"Ayon sa aming imbestigasyon, naniniwala kaming nasa Lizeria ang gate na hinahanap natin.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Kung tama ang pagkakaalala ko, doon dating umiiral ang La Veda.","story.map8-open.011":"Ganoon ba. <wait=20>Mukhang hindi pala tayo nilinlang.","story.map8-open.012":"Tama po.","story.map8-open.013":"Kahit duda ako na tumpak ang lahat ng impormasyong natanggap natin, sa tingin ko ay tumpak ang isang ito.","story.map8-open.014":"......","story.map8-open.015":"Gusto kong pumunta roon para kumpirmahin ito mismo.","story.map8-open.016":"Maaari ba akong mabigyan ng pahintulot?","story.map8-open.017":"Sa pagkakaalam ko, nagsimula na ang Summoner Army ng bagong imbestigasyon sa lugar na iyon.","story.map8-open.018":"Naiintindihan ko. <wait=40>Gagawin ko ang lahat para matapos ito sa lalong madaling panahon.","story.map8-open.019":"Mapanganib na gawain ito, alam mo ba?","story.map8-open.020":"Handa akong isakripisyo ang sarili ko para sa tunay na kapayapaan.","story.map8-open.021":"Umaasa ako sa\'yo.","story.map8-open.022":"Hindi na po ninyo kailangang sabihin iyan.","story.map8-open.023":"Sisiguraduhin kong maaasikaso ang lahat!","story.map8-open.024":"Good luck.","story.map8-open.025":"Sino \'yan!?","story.map8-open.026":"Mukhang may gusto kang sabihin.","story.map8-open.027":"Nakikinig ka ba? <wait=40>Bakit hindi ka lumabas?","story.map8-open.028":"......","story.map8-open.029":"Ganoon ba. <wait=40>Hindi mo na kailangang sabihin.","story.map8-open.030":"Wala nang oras na dapat sayangin. <wait=20>Kailangan nating ibalik ang mundo sa wastong anyo nito.","story.map8-open.031":"Iniisip ko kung maiintindihan kaya ito ng grupong \'yon ng Summoner Army...","story.map8-open.032":"...Kung paano talaga dapat ang mundong ito.","story.map9-dungeon1.001":"Uy, <wait=20><rep_handlename>!","story.map9-dungeon1.002":"Nakarating ka na rin pala sa Ryvern, <wait=20>ang pasukan sa rehiyon ng Agni. ","story.map9-dungeon1.003":"Sa tingin ko hahabulin mo si Zevalhua, <wait=20>ang susunod na Nahulog na Diyos. ","story.map9-dungeon1.004":"Siyempre tutulungan ka ulit namin ngayon kaya walang magiging problema!","story.map9-dungeon1.005":"Karl! <wait=40>May sarili tayong mga layunin, tandaan mo!?","story.map9-dungeon1.006":"Wala akong ganang tulungan si <rep_handlename>, <wait=20>lalo na\'t hindi naman tayo inutusan ng Summoners\' Hall.","story.map9-dungeon1.007":"Haha, <wait=20>ganyan ka pa rin, Seria.","story.map9-dungeon1.008":"Dalawa na sa Apat na Nahulog na Diyos ang natalo ni <rep_handlename>. ","story.map9-dungeon1.009":"Hindi mo ba dapat kilalanin man lang \'yon?","story.map9-dungeon1.010":"Hmph, <wait=20>kinikilala ko ang lakas na kinailangan doon.","story.map9-dungeon1.011":"Pero tingnan mo naman ang mayabang na mukhang \'yan!","story.map9-dungeon1.012":"Patas na babala lang ang binibigay ko, <wait=20>\'yon lang!","story.map9-dungeon1.013":"<rep_handlename>! <wait=20>Dapat magpasalamat ka sa akin!","story.map9-dungeon1.014":"Ah! <wait=20>Nandiyan ka pala!","story.map9-dungeon1.015":"<rep_handlename>! <wait=20>Bakit ang tagal mo?","story.map9-dungeon1.016":"Oh, <wait=20>sina Karl at Seria!","story.map9-dungeon1.017":"Hello, <wait=20>Diyosa.","story.map9-dungeon1.018":"Dumating din siya sa wakas...","story.map9-dungeon1.019":"Hoy, kayong dalawa!","story.map9-dungeon1.020":"Tutulungan n\'yo rin ulit si <rep_handlename> ngayon, \'di ba?","story.map9-dungeon1.021":"Si Graham ang hinahabol namin!","story.map9-dungeon1.022":"Huwag mo munang alalahanin \'yan.","story.map9-dungeon1.023":"Siguradong makakatakas lang ulit siya, <wait=20>kaya bakit hindi na lang kayo tumulong mula sa simula ngayon?","story.map9-dungeon1.024":"Ang sama naman ng sinabi mo.","story.map9-dungeon1.025":"Ikaw talaga!","story.map9-dungeon1.026":"Ang saya-saya talagang makipagsapalaran nang ganito kasama kayong lahat.","story.map9-dungeon1.027":"Pakiramdam ko gaano man kahirap ang laban, malalampasan natin \'yon kahit papaano, \'di ba?","story.map9-dungeon1.028":"Haha, <wait=20>kung \'yan ang sabi ng diyosa, wala na tayong magagawa.","story.map9-dungeon1.029":"\'Di ba, <wait=20>Seria?","story.map9-dungeon1.030":"Ang dali mo talagang mapapayag, Karl...","story.map9-dungeon1.031":"Anyway, <wait=20>sigurado akong uutusan din tayo ni Lord Grahdens kaya siguro puwede na rin tayong tumulong. ","story.map9-dungeon1.032":"Ang bait mo rin pala, Seria!","story.map9-dungeon1.033":"A-<wait=20>Ano ba\'ng problema mo!","story.map9-dungeon1.034":"Tumutulong lang ako kasi wala na tayong ibang pagpipilian.","story.map9-dungeon1.035":"Ha ha ha. <wait=20>Mukhang may desisyon na tayo.","story.map9-dungeon1.036":"Kaya magkakasama tayong lahat dito, <rep_handlename>!","story.map9-dungeon1.037":"Galingan natin at bugbugin si Zevalhua!","story.map9-dungeon1.038":"Ayos! <wait=40>Galingan n\'yo, lahat!","story.map9-dungeon1.039":"*Buntong-hininga* <wait=20>Hindi pa rin ako sigurado rito...","story.map9-dungeon1.040":"Hmm. <wait=40>Nakakaawa...","story.map9-dungeon2.001":"Uy, <rep_handlename>. <wait=40>Medyo nahuli ka. ","story.map9-dungeon2.002":"Nandito lang ang diyosa kanina.","story.map9-dungeon2.003":"Pagkatapos noon, nagkaroon sila ng away ni Seria, <wait=20>tapos pareho silang nauna. ","story.map9-dungeon2.004":"Ha ha ha. <wait=40>Ang dalawang \'yon, <wait=40>naging malapit na talaga sila sa isa\'t isa, \'no?","story.map9-dungeon2.005":"Magtulungan tayo para hindi tayo matalo sa kanila!","story.map9-dungeon2.006":"Kay hahabag na mga nilalang talaga kayong mga tao.","story.map9-dungeon2.007":"Sino \'yan?","story.map9-dungeon2.008":"Hindi n\'yo kailangang matakot.","story.map9-dungeon2.009":"Ako si Mare.","story.map9-dungeon2.010":"Isa akong disipulo ng Kataas-taasang si Zevalhua.","story.map9-dungeon2.011":"Disipulo ni Zevalhua?","story.map9-dungeon2.012":"Kaya pumunta ka rito para patayin kami? ","story.map9-dungeon2.013":"Napakawalang-galang ng pagsasalita mo nang masama tungkol kay Lord Zevalhua nang ganyan...","story.map9-dungeon2.014":"Isa na naman itong tanda ng kamangmangan mo. Nakakalungkot...","story.map9-dungeon2.015":"Gayunman, huwag kang magkamali ng akala.","story.map9-dungeon2.016":"Hindi ko kailangang itaya ang pangalan ko para tapusin kayong dalawa.","story.map9-dungeon2.017":"Hindi ikaw ang pakay ko, Summoner, <wait=40>kundi ang may asul na buhok. <wait=40>Ikaw ang hinahabol ko.","story.map9-dungeon2.018":"Ako ang target mo?","story.map9-dungeon2.019":"Ano\'ng kailangan mo sa akin?","story.map9-dungeon2.020":"Naisip kong gampanan ang papel ng isang diyos at ilantad sa \'yo ang katotohanan. ","story.map9-dungeon2.021":"Ang katotohanan?","story.map9-dungeon2.022":"Hinayaan mong linlangin ka ng hangal na si Grahdens at ngayon ay magulo na ang buhay mo.","story.map9-dungeon2.023":"Ikaw... <wait=60>Ano ba talaga ang balak mo?","story.map9-dungeon2.024":"Hindi mo kailangang mag-ingat. ","story.map9-dungeon2.025":"Ang mga elder mo ang nagbigay sa \'yo sa pangangalaga ng iba di-nagtagal matapos ka nilang matagpuan.","story.map9-dungeon2.026":"Malungkot ang naging paglaki mo, hindi mo kailanman naramdaman ang init ng pagmamahal ng isang magulang.","story.map9-dungeon2.027":"Kaya sa \'yo, na kinupkop ng mga iresponsableng matandang \'yon...","story.map9-dungeon2.028":"...ako, isang maawaing diyos, ang magsasabi sa \'yo ng katotohanan.","story.map9-dungeon2.029":"Tumigil ka sa kalokohan mo!","story.map9-dungeon2.030":"Ano\'ng alam mo tungkol kay Elder Grahdens!","story.map9-dungeon2.031":"Bilang isa sa mga Elder Summoner, lagi siyang abala...","story.map9-dungeon2.032":"...Pero lagi niya akong inaalala!","story.map9-dungeon2.033":"Hindi siya katulad ng taong inilalarawan mo, ikaw na disipulo ng isang Nahulog na Diyos!","story.map9-dungeon2.034":"Kasintuso ka ni Grahdens sa mga salita. ","story.map9-dungeon2.035":"Mukhang lubos kang na-brainwash. ","story.map9-dungeon2.036":"Tumahimik ka! <wait=40>Hindi kita hahayaang magsalita pa ng kahit isang salita laban sa kanya!","story.map9-dungeon2.037":"Isa kang walang-alam at hangal na tanga.","story.map9-dungeon2.038":"Ituturo ko sa \'yo ang daan.","story.map9-dungeon2.039":"Hihintayin kita sa Guho ng Azura sa unahan. ","story.map9-dungeon2.040":"Pumunta kang mag-isa kung gusto mong malaman ang katotohanan.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>utang ko ang lahat kay Elder Grahdens.","story.map9-dungeon2.042":"Medyo kakaiba man siya, pero mapagkakatiwalaan siyang tao at mahalagang-mahalaga siya sa akin!","story.map9-dungeon2.043":"Hindi ko mapapatawad ang sinabi niya tungkol sa kanya. ","story.map9-dungeon2.044":"Pasensiya na, pero kailangan mong mauna nang wala ako.","story.map9-dungeon2.045":"Pupunta ako sa Guho ng Azura para harapin siya.","story.map9-dungeon2.046":"Ikaw na ang bahala kay Zevalhua!","story.map9-dungeon2.047":"Nakikiusap ako, <rep_handlename>, <wait=20>pakiusap!","story.map9-dungeon3.001":"<rep_handlename>!","story.map9-dungeon3.002":"Nakita mo ba si Karl?","story.map9-dungeon3.003":"Sinabi niya sa aking mauna na ako noong nasa Khelne kami, <wait=20>kaya nauna ako, pero...","story.map9-dungeon3.004":"Mukha siyang kalmado, <wait=20>pero sa tingin ko talagang nagagalit siya. ","story.map9-dungeon3.005":"Ang totoo, hindi ko pa siya nakitang ganoon kagalit dati.","story.map9-dungeon3.006":"Ha? <wait=40>May disipulo ni Zevalhua na lumitaw at nagsalita tungkol sa kanya at kay Lord Grahdens?","story.map9-dungeon3.007":"Ganoon ba.","story.map9-dungeon3.008":"Napakahalagang tao ni Lord Grahdens para kay Karl.","story.map9-dungeon3.009":"Magkaibigan na kayo mula pa noong mga bata kayo, \'di ba? <wait=40>Alam mo ang buong kuwento, \'di ba?","story.map9-dungeon3.010":"Pero, <wait=40>ayaw talaga ni Karl na pag-usapan ang sarili niya, \'no...","story.map9-dungeon3.011":"Kung sasabihin lang niya sa amin kung ano\'ng nangyayari, <wait=20>baka makatulong kami.","story.map9-dungeon3.012":"Anyway, <wait=20>magmadali tayo papunta sa Guho ng Azura!","story.map9-dungeon3.013":"Sigurado akong okay lang si Karl, pero hindi ko mapigilang mag-alala.","story.map9-dungeon3.014":"Mapag-isip ka pala <wait=40>para sa isang uod na tulad mo.","story.map9-dungeon3.015":"Amin na siya.","story.map9-dungeon3.016":"Hindi na siya babalik sa inyo. ","story.map9-dungeon3.017":"Ikaw pala si Mare!","story.map9-dungeon3.018":"Mga hangal na tao. <wait=40>Natatakot ba kayong makita ang katotohanan?","story.map9-dungeon3.019":"Kung ganoon, dapat sumama rin kayo.","story.map9-dungeon3.020":"Dapat n\'yo siyang makita ngayong tinanggap na niya ang katotohanan.","story.map9-dungeon3.021":"Tama na!","story.map9-dungeon3.022":"Tilith!","story.map9-dungeon3.023":"Hehe, <wait=20>ngayon mo lang ako tinawag sa pangalan ko.","story.map9-dungeon3.024":"T-<wait=20>Tanga ka! <wait=40>Hindi ito ang oras para diyan!","story.map9-dungeon3.025":"Tama ka. <wait=20>Kailangan nating may gawin kay Mare.","story.map9-dungeon3.026":"Ano\'ng pakay ng isang mababang-uring diyos na tulad mo sa akin?","story.map9-dungeon3.027":"Ang sama mo!","story.map9-dungeon3.028":"Ako ang kahanga-hangang disipulo ni Lord Lucius, alam mo ba!","story.map9-dungeon3.029":"Isa pa, Seria. <wait=20>Huwag kang magpapaloko.","story.map9-dungeon3.030":"Magaling si Mare sa paggulo ng puso ng iba. ","story.map9-dungeon3.031":"Kaunti lang ang katotohanan sa mga sinasabi niya.","story.map9-dungeon3.032":"Kaya mo bang pagpasyahan kung ano ang totoo at hindi?","story.map9-dungeon3.033":"Ikaw, <wait=20>na bulag na sumusunod sa bawat salita ni Lucius, <wait=20>at ipinapahiram ang kapangyarihan mo sa mga tao at kung anu-ano pa.","story.map9-dungeon3.034":"Sinasabi mo bang mali si Lord Lucius?","story.map9-dungeon3.035":"Hindi na mahalaga. <wait=40>Wala nang magagawa kapag ganyang kahangal na mga diyos ang kaharap. ","story.map9-dungeon3.036":"Ikaw ang tinutukoy ko, alam mo.","story.map9-dungeon3.037":"Kung gusto mong malaman ang katotohanan, paniwalaan mo lang ang sinasabi ko.","story.map9-dungeon3.038":"At sa paggawa nito, makikita mo ulit ang lalaking \'yon. ","story.map9-dungeon3.039":"Sandali lang!","story.map9-dungeon3.040":"Grabe! <wait=40>Kasing-sama talaga siya ng narinig ko!","story.map9-dungeon3.041":"Seria! <wait=20>Sigurado akong okay lang si Karl!","story.map9-dungeon3.042":"Kaya huwag kang gagawa ng padalos-dalos!","story.map9-dungeon3.043":"Alam ko. <wait=40>Okay na ako ngayon.","story.map9-dungeon3.044":"Pero gayunman, nag-aalala ako kay Karl.","story.map9-dungeon3.045":"Alam kong baka bitag ito...","story.map9-dungeon3.046":"...pero siguradong papunta na roon si Karl ngayon.","story.map9-dungeon3.047":"<rep_handlename>, gusto kong gumawa ka ng pinakamalaking gulo na kaya mo rito.","story.map9-dungeon3.048":"Kailangan ko ng panggambala kung magmamadali ako papunta kay Karl. ","story.map9-dungeon3.049":"Oo, <wait=20>mukhang okay ka na talaga!","story.map9-dungeon3.050":"Bagay na bagay pa nga sa \'yo ang pagkukunwari mong malupit kay <rep_handlename>!","story.map9-dungeon3.051":"Hindi ako nagkukunwari!","story.map9-dungeon3.052":"*Buntong-hininga* <wait=40>Anyway, tama na \'yan.","story.map9-dungeon3.053":"Tilith, <wait=20>protektahan mo si <rep_handlename> para sa akin.","story.map9-dungeon3.054":"Sino\'ng nakakaalam kung ano ang susubukan ng disipulong si Mare.","story.map9-dungeon3.055":"Hindi ko maisip na hahayaan lang niya ang taong nakatalo na sa dalawa sa Apat na Nahulog na Diyos.","story.map9-dungeon3.056":"Naiintindihan ko. <wait=40>Pero, <wait=20>pakiusap, huwag kang gagawa ng kapabayaan.","story.map9-dungeon3.057":"Huwag mo akong alalahanin.","story.map9-dungeon3.058":"Hindi ako ganoon kahina para kailanganin pa akong alalahanin ng isang hangal na diyosang tulad mo.","story.map9-dungeon3.059":"Kulang ka pa rin sa kababaang-loob gaya ng dati, Seria!","story.map9-dungeon3.060":"Hehe, <wait=40>anyway, aalis na ako.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>ingatan mo rin ang sarili mo, okay?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Pasensiya na...","story.map9-dungeon4.003":"Si Mare...<wait=20> Nilinlang niya kami...","story.map9-dungeon4.004":"Seria! <wait=40>Ayos ka lang ba?","story.map9-dungeon4.005":"Ayos...<wait=40>lang ako...","story.map9-dungeon4.006":"Pero...<wait=20>si Karl ay...","story.map9-dungeon4.007":"Huwag mong pilitin ang sarili mo!","story.map9-dungeon4.008":"Si Mare...<wait=20>at si Karl ay...<wait=20>magkapantay sa laban...","story.map9-dungeon4.009":"Naisip kong subukang tumulong...","story.map9-dungeon4.010":"Pero, <wait=40>mukhang \'yon pala...<wait=20>mismo ang gusto niya...","story.map9-dungeon4.011":"Sa sandaling itinuon ko ang sarili ko sa kanya...","story.map9-dungeon4.012":"Tinawag niya ang mga alipin niyang nagtatago. <wait=20>Sabay-sabay silang sumugod sa akin...","story.map9-dungeon4.013":"Tapos habang sinusubukan kong iwasan ang mga atake nila...<wait=20>inatake ako ni Mare mula sa likod...","story.map9-dungeon4.014":"Si Karl...<wait=20>prinotektahan niya ako <wait=20>mula sa atake niya...","story.map9-dungeon4.015":"Tapos, <wait=20>habang sinusubukan kong protektahan si Karl matapos siyang bumagsak, <wait=20>nangyari ito...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Sinabi niya sa akin...","story.map9-dungeon4.018":"\\"Iiwan kita bilang mensahe para kay <rep_handlename>...","story.map9-dungeon4.019":"...\'Yon lang ang dahilan kung bakit kita hinahayaang mabuhay.\\"","story.map9-dungeon4.020":"Napakahangal ko!","story.map9-dungeon4.021":"Hindi lang ako nahulog sa bitag niya, ngayon pa ito. <wait=20>Paano ako mabubuhay sa ganitong kahihiyan. ","story.map9-dungeon4.022":"Natutuwa pa rin akong marinig \'yan.","story.map9-dungeon4.023":"Natutuwa saan!","story.map9-dungeon4.024":"Buhay ka, \'di ba? <wait=20>Natutuwa lang ako na nandito ka pa.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"At kung nahuli si Karl, <wait=20>ibig sabihin buhay pa rin siya!","story.map9-dungeon4.027":"Siguradong maililigtas siya ng aking <rep_handlename>!","story.map9-dungeon4.028":"Ayaw ko sa pagtawag mo kay <rep_handlename> na sa \'yo, <wait=20>at pati sa bulag mong pagtitiwala...","story.map9-dungeon4.029":"Pero...<wait=20>tama ka...","story.map9-dungeon4.030":"Mukhang nakakulong si Karl sa isang lugar na tinatawag na Puting Tore. ","story.map9-dungeon4.031":"Sinabi ni Mare na hihintayin ka niya roon.","story.map9-dungeon4.032":"Walang duda na bitag ito.","story.map9-dungeon4.033":"Pero gayunman, nakikiusap akong subukan mo.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>iligtas mo si Karl!</size>","story.map9-dungeon4.035":"Hmph, <wait=20>ano\'ng tango-tango at pa-cool mong \'yan?","story.map9-dungeon4.036":"Ililigtas mo naman siya kahit wala akong sabihin, \'di ba?","story.map9-dungeon4.037":"Nngh...","story.map9-dungeon4.038":"Seria! <wait=20>Huwag mong pilitin ang sarili mo!","story.map9-dungeon4.039":"<rep_handlename>! <wait=40>Ako na ang bahala kay Seria!","story.map9-dungeon4.040":"Iuuwi ko siya nang ligtas sa Elgaia. ","story.map9-dungeon4.041":"Kaya pakiusap, <rep_handlename>, <wait=20>iligtas mo si Karl.","story.map9-dungeon4.042":"Kami ni Seria, <wait=20>naniniwala kami sa \'yo, <rep_handlename>.","story.map9-dungeon4.043":"Hindi naman ako talaga naniniwala sa \'yo...","story.map9-dungeon4.044":"Seria, <wait=20>okay lang.","story.map9-dungeon4.045":"Ang aking <rep_handlename> ang pinakamalakas sa lahat!","story.map9-dungeon4.046":"Sino\'ng tinatawag mong sa \'yo?","story.map9-dungeon4.047":"Eh, <wait=40>bahala na...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"Pakiusap...<wait=40>ibalik mo si Karl para sa akin...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Hinihintay kita.","story.map9-dungeon5.002":"Akala ko dadaan ka rito papunta sa Puting Tore.","story.map9-dungeon5.003":"Nasa kabilang panig ng Kabundukan ng Ryvern ang Puting Tore, <wait=20>pagkalabas mo ng kuweba. ","story.map9-dungeon5.004":"Duda akong magiging madali itong lampasan kahit sa galing mo.","story.map9-dungeon5.005":"Gayunman, <wait=20>huwag kang matakot. ","story.map9-dungeon5.006":"Ako ang magliligtas sa batang si Karl.","story.map9-dungeon5.007":"Minamahal kong anak siya, kung tutuusin. ","story.map9-dungeon5.008":"Ho ho ho. <wait=40>Ano\'ng nagdududang tingin \'yan sa mukha mo?","story.map9-dungeon5.009":"Wala akong ideya kung ano ang sinabi ng disipulong si Mare.","story.map9-dungeon5.010":"Pero ako ang kumuha sa inabandonang sanggol na \'yon at nagpalaki sa kanya na parang sarili kong anak.","story.map9-dungeon5.011":"Gayunpaman, <wait=20>totoo na sa huli ay ipinaubaya ko siya sa pangangalaga ng isang mapagkakatiwalaang kakilala. ","story.map9-dungeon5.012":"Masyado lang talagang abala ang buhay ng isang Summoner Elder.","story.map9-dungeon5.013":"Pero alam mo na ang natitirang bahagi ng kuwento, \'di ba?","story.map9-dungeon5.014":"Nagpapasalamat ako sa \'yo dahil lagi mong nakakalaro si Karl noong mga bata pa kayo. ","story.map9-dungeon5.015":"Ho ho ho.","story.map9-dungeon5.016":"Gayunman, gaano man ako naging abala...","story.map9-dungeon5.017":"...hindi ko siya basta iniwan na lang sa iba.","story.map9-dungeon5.018":"Paminsan-minsan, palihim akong umaalis nang walang nakakapansin para silipin siya. ","story.map9-dungeon5.019":"Malaking gulo sana ang kinasangkutan ko kung may nakaalam na ako, isang Summoner Elder, ay may anak.","story.map9-dungeon5.020":"Gayunman, <wait=20>kahit kinailangan kong maging palihim, tinanggap pa rin niya ako.","story.map9-dungeon5.021":"Ho ho ho. <wait=40>Nakakapanariwa ng alaala.","story.map9-dungeon5.022":"Kung ganoon, <wait=20>dapat na siguro akong umalis.","story.map9-dungeon5.023":"Responsibilidad ng mga magulang na ibalik ang nawawala nilang anak.","story.map9-dungeon5.024":"At isa pa, <wait=20>kailangan kong parusahan ang naglakas-loob na linlangin ang mahal kong anak.","story.map9-dungeon5.025":"Ho ho ho. <wait=20>Huwag kang mag-alala.","story.map9-dungeon5.026":"Tumanda man ako, <wait=20>malamang mas malakas pa rin ako nang maraming beses kaysa sa sinuman sa inyo.","story.map9-dungeon5.027":"Bukod pa roon, <wait=20>kahit may mangyari man sa akin...","story.map9-dungeon5.028":"...hiniling ko na sa ibang mga Elder Summoner na bantayan kayong lahat. ","story.map9-dungeon5.029":"Ho ho ho. <wait=40>Masyado ba akong maingat?","story.map9-dungeon5.030":"Huwag kang matakot, at tumuloy ka kay Zevalhua.","story.map9-dungeon5.031":"Sigurado akong ayaw rin ni Karl na maging pabigat sa \'yo.","story.map9-dungeon5.032":"Pero kahit ganoon, balak mo pa ring pumunta sa Puting Tore, \'di ba?","story.map9-dungeon5.033":"May napakabubuting kaibigan si Karl. ","story.map9-dungeon5.034":"Kung ganoon, <wait=20>ililigtas ko si Karl at hihintayin kita sa Puting Tore. ","story.map9-dungeon5.035":"Ho ho ho.","story.map9-dungeon6.001":"Mukhang isa na lang ang natitira. ","story.map9-dungeon6.002":"Mukhang mga hangal na nilalang talaga kayong mga tao. ","story.map9-dungeon6.003":"Wawasakin kita gaya ng ginawa ko sa iba pang mga hangal na mandirigmang \'yon.","story.map9-dungeon6.004":"<size=20>Hindi ko hahayaang mangyari \'yan!</size>","story.map9-dungeon6.005":"Poprotektahan ko si <rep_handlename>!","story.map9-dungeon6.006":"Ikaw pala...","story.map9-dungeon6.007":"Mas maaga kang bumalik kaysa sa inaasahan ko.","story.map9-dungeon6.008":"Tatawagin sana kitang hangal, <wait=20>pero ano pa ba ang aasahan ko sa isang disipulo ni Lucius.","story.map9-dungeon6.009":"Anyway...","story.map9-dungeon6.010":"Summoner, <wait=40>hihintayin kita sa Puting Tore.","story.map9-dungeon6.011":"Kasama ko rin ang kaibigan mo.","story.map9-dungeon6.012":"<rep_handlename>, ayos ka lang ba?","story.map9-dungeon6.013":"Kung nag-aalala ka kay Seria, hindi mo na kailangang mag-alala.","story.map9-dungeon6.014":"Naiuwi ko siya nang ligtas sa Elgaia, at mapayapa na siyang nagpapahinga sa Summoners\' Hall. ","story.map9-dungeon6.015":"So, <wait=20>tara na\'t iligtas natin si Karl nang magkasama!","story.map9-dungeon6.016":"Kaya natin \'to, ikaw at ako, <wait=20>gaano man karaming bitag ang ihanda ni Mare!","story.map9-dungeon6.017":"Walang kaaway na hindi natin matatalo basta magkasama tayo!","story.map9-dungeon6.018":"Karl! Tiisin mo pa nang kaunti!","story.map9-dungeon7.001":"Kahit ang liwanag dito, kinikilabutan pa rin ako sa lugar na \'to.","story.map9-dungeon7.002":"Isa na naman kaya ito sa mga bitag ni Mare?","story.map9-dungeon7.003":"Hindi ko kailangang sayangin ang alinman sa mahahalaga kong bitag sa inyo.","story.map9-dungeon7.004":"Boses \'yan ni Mare!","story.map9-dungeon7.005":"Naghanda ako ng kalaban para sa inyo.","story.map9-dungeon7.006":"Granvalm, Guardian ng tower na ito. <wait=40>Wasakin mo ang mga nanghihimasok na ito!","story.map9-dungeon7.007":"<size=20>Kyaaaahh! <wait=40>Tingnan mo ang dragon na \'yon!</size>","story.map9-dungeon7.008":"Siya ang perpektong katapat para sa mga hangal na tulad n\'yo.","story.map9-dungeon7.009":"Teka!","story.map9-dungeon7.010":"Galit na galit na talaga ako! <wait=40><rep_handlename>, umatras ka!","story.map9-dungeon7.011":"Ha ha ha...","story.map9-dungeon7.012":"Tumakas sila...","story.map9-dungeon7.013":"Pero, <wait=20>mukhang may tumatakbong pabalik ang dragon na \'yon para protektahan ang isang bagay...","story.map9-dungeon7.014":"Baka gusto nitong siguraduhing hindi makatakas si Karl.","story.map9-dungeon7.015":"<rep_handlename>!","story.map9-dungeon7.016":"Siguradong \'yon nga!","story.map9-dungeon7.017":"Habulin mo ang dragon na \'yon, magiging okay lang ako!","story.map9-dungeon7.018":"Kailangan ko lang magpahinga rito sandali!","story.map9-dungeon7.019":"Kailangan nating patunayan ang tiwala ni Seria sa atin.","story.map9-dungeon7.020":"Walang problema \'yan para sa aking <rep_handlename>!","story.map9-dungeon7.021":"Tuparin mo ang pangako mo kay Seria at iligtas si Karl!","story.map9-ending.001":"Summoner. <wait=40>Mukhang nakatayo ka pa rin.","story.map9-ending.002":"Magrelaks ka. <wait=40>Sisiguraduhin kong mabilis at walang sakit ang katapusan mo.","story.map9-ending.003":"Pagkatapos mo, wala nang matitirang magbabanta kay Lord Zevalhua. ","story.map9-ending.004":"Ano\'ng gulat na itsura \'yan sa mukha mo?","story.map9-ending.005":"Ikaw ang pakay ko mula pa sa simula.","story.map9-ending.006":"Ikaw, ang Summoner na pinili ni Lucius.","story.map9-ending.007":"Ngayong napuksa ko na ang lahat ng dating nagpoprotekta sa \'yo...","story.map9-ending.008":"...wala nang matitirang magliligtas sa \'yo.","story.map9-ending.009":"Pati ang matanda ay natalo habang lumalaban para iligtas ang isang taong wala naman pala rito mula sa simula.","story.map9-ending.010":"Bukod pa roon, <wait=20>naubos na rin ang kapangyarihan ng hangal na diyosang nagtiwala sa \'yo.","story.map9-ending.011":"Hindi mahalaga kung ilan pang disipulo ni Lucius ang ipadala niya.","story.map9-ending.012":"Siguradong naiintindihan nila na sa kahinaan nila, hindi sila makakagalaw sa harap ng puting dragon.","story.map9-ending.013":"Naging hangal na siya dahil sa labis na tagal ng pakikisalamuha sa inyong mga tao.","story.map9-ending.014":"Kaawa-awa talaga kayong mga taong uod.","story.map9-ending.015":"Madali kayong masabik at kumikilos nang mag-isa.","story.map9-ending.016":"Kahit alam n\'yong bitag ito, sinasabi n\'yong para iligtas ang mga kaibigan n\'yo habang idinadamay n\'yo ang iba sa gulo. ","story.map9-ending.017":"Ang pagkilos nang mag-isa kapag napakarami mong pananagutan ay humahantong lang sa kabiguan. ","story.map9-ending.018":"Isa pa, <wait=20>ang mga may malalaking layunin na nagtutuon sa maliliit ay nawawalan ng lahat sa huli.","story.map9-ending.019":"Napakahangal na paraan ng pamumuhay.","story.map9-ending.020":"Siguradong hindi ka naiiba.","story.map9-ending.021":"Summoner...","story.map9-ending.022":"Hmph, <wait=40>nabagot na ako.","story.map9-ending.023":"Nagsalita ako sa pag-aakalang lalaban ka kahit kaunti, pero mukhang nasa limitasyon ka na.","story.map9-ending.024":"Ayos lang. <wait=40>Mukhang kailangan na lang kitang tapusin dito!","story.map9-ending.025":"<size=20>Tumigil ka diyan!</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"Mukhang may natitira ka pang mga kakampi.","story.map9-ending.029":"Pero hindi na mahalaga.","story.map9-ending.030":"Nakakulong sa kabisera ng Agni ang lalaking hinahanap mo. ","story.map9-ending.031":"Mabuti pang habulin mo kung gusto mo siyang iligtas.","story.map9-ending.032":"At wala kang oras para hintaying makabawi ang mga kaibigan mo.","story.map9-ending.033":"Kung gagawin mo \'yon, huli na para iligtas siya.","story.map9-ending.034":"......","story.map9-ending.035":"Hoy <rep_handlename>, <wait=20>huwag ka lang tumayo diyan!","story.map9-ending.036":"Mamaya na tayo mag-usap. <wait=40>Sa ngayon, dapat na tayong pumunta sa kabisera ng Agni.","story.map9-ending.037":"May sasabihin ako sa \'yo pagdating natin doon.","story.map9-ending.038":"Dapat magpasalamat ka sa akin!","story.map9-ending.039":"<size=20>Ah ha ha ha!</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ako si Lucius...<br><wait=40>Diyos ng Gate na ito...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ang krisis na dulot ng Apat na Nahulog na Diyos,<wait=40> nagpapatuloy pa rin...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gamitin mo ang kapangyarihan ko <wait=40>at maglakbay sa mga bagong lupain...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Upang magdala ng bagong pag-asa sa mundong ito na walang kaayusan...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Manalig ka sa iyong kapangyarihan, <wait=20>at patuloy na sumulong...","story.map9-open.006":"<rep_handlename>! <wait=40>Sorry at pinaghintay kita!","story.map9-open.007":"Pero dahil lagi na lang akong naghihintay sa \'yo, <rep_handlename>...","story.map9-open.008":"...naisip kong ikaw naman ang paghintayin ko ngayon!","story.map9-open.009":"Ano \'yon? <wait=20>Sabi mo hindi ka naman naghintay nang ganoon katagal?","story.map9-open.010":"Ang daya naman!","story.map9-open.011":"Inaasahan ko pa namang pagpapawisan ka man lang sa paghihintay sa akin!","story.map9-open.012":"Pero bahala na! <wait=40>Ang mahalaga, matalo natin agad ang susunod na Nahulog na Diyos!","story.map9-open.013":"Kalahati na lang ng Apat na Nahulog na Diyos ang natitira!","story.map9-open.014":"At ang susunod mong haharapin ay...","story.map9-open.015":"...ang dakilang emperador na si Zevalhua na kumokontrol sa rehiyon ng Agni. ","story.map9-open.016":"Sinasabing hindi sila magkasundo ni Afla Dilith, isa pa sa mga Nahulog na Diyos...","story.map9-open.017":"...pero siguradong napansin na niya ang pagdating natin dito.","story.map9-open.018":"Malamang susubukan niyang maglagay ng mga bitag para sa atin!","story.map9-open.019":"Pero hindi ka naman mahuhuli sa mga \'yon, \'di ba, <rep_handlename>?","story.map9-open.020":"Sige, <wait=20>pupunta na ako sa Milvana kung saan naghihintay si Zevalhua!","story.map9-open.021":"Randall,<wait=40> ang kabisera ng Randall Empire.","story.map9-open.022":"Sa Randall Castle, sa loob ng pribadong silid ng mga tagapagbantay ng maharlikang pamilya, <wait=40>ang Imperial Guard.","story.map9-open.023":"*Tok* <wait=20>*tok*","story.map9-open.024":"Paumanhin.","story.map9-open.025":"......","story.map9-open.026":"Handa na ang paghahanda para pumunta sa rehiyon ng Agni. ","story.map9-open.027":"Ganoon ba.","story.map9-open.028":"Kung ganoon, tumuloy na rin tayo. ","story.map9-open.029":"Sa Grand Gaia, ang lupaing kontrolado ng mga diyos. ","storylog.category.10000.description":"Habang naglalakbay sa Grand Gaia kasama ang mga kaibigan at isang makapangyarihang diyosa, hinaharap ng isang Summoner ang mga demonyo sa matitinding laban.","storylog.category.10000.name":"Mga Gunita ng Grand Gaia","storylog.category.10100.description":"Sa gabay ni Tilith, na naglilingkod sa diyos na si Lucius, sinimulan ng Summoner ang isang dakilang pakikipagsapalaran. Kailangang talunin ang Apat na Nahulog na Diyos, simula kay Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Mukhang ang islang dating tinitirhan ng mga higante ang susunod na destinasyon ng Summoner. Pero papunta rin sa Cordelica si Paris ng Imperial Guard...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"Dumating ang Summoner sa lupaing gustong wasakin ni Cardes the Malevolent. Isang bagong laban ang nagsisimula kung saan dating nakatayo ang maalamat na 4 na Bayani ng Palmyna.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Dumating si Paris sa isla ng sinaunang Republika ng La Veda para hanapin ang isang usap-usapang gate, pero nagsimula na ng imbestigasyon ang Summoners\' Hall.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Kailangang mapatay si Zevalhua the Supreme bago niya wasakin ang lahat. Sinasabing may alitan siya kay Afla Dilith, isa sa Apat na Nahulog na Diyos.","storylog.category.10104.name":"Rehiyon ng Agni","storylog.category.11001.description":"Habang hinahabol ni Karl ang demonyong si Graham, hahamunin naman ng Summoner ang alagad ni Maxwell na si Abaddon. Pero kaya nga bang talunin si Abaddon?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"Ang lupaing sakop ng Manlilikhang si Maxwell ang bagong destinasyon. Ang layunin: tumungo sa kuta ni Maxwell, ang Palasyo ng St. Lamia, kasama si Tilith.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"Lumapag ang Summoner kung saan dating umunlad ang dakilang Imperyo ng Amdahl. Inaasahan ni Tilith na magtatapos ang paglalakbay na ito sa pagkatalo ni Cardes the Malevolent.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Ayon kay Tilith, minsang nasaksihan ng lupaing ito ang isang digmaang sibil ng mga tao. Sumisiklab ang matitinding laban sa gitna ng ilang.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Si Zevalhua the Supreme ang bagong target. Sabi ni Tilith, natatakot siyang may binabalak na sabwatan.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"Dinadalaw na ngayon ng Summoner ang lupaing dating kinatatayuan ng isang makapangyarihang imperyo. Ipinagkatiwala ni Grahdens sa iyo at kay Lugina ang pagliligtas kay Karl, pero...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Sa wakas, narating na ang kuta ni Zevalhua. Oras na para magbigay-daan ang lumang larangan ng digmaang ito sa bagong laban para iligtas ang nahuling si Grahdens.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"Hiniling sa Summoner na pasukin ang isang bago at misteryosong lupain. Pero mas malalakas pala ang mga kalabang naghihintay roon kaysa inaasahan...","storylog.category.20000.name":"Isang Bagong Rehiyon","storylog.scenario.10001.description":"Ipinaliwanag ni Tilith ang kalagayan ng Grand Gaia sa Kuweba ng Apoy. Kailangang sumabak ang Summoner sa isang malayo at mahabang paglalakbay para talunin ang Apat na Nahulog na Diyos...","storylog.scenario.10001.title":"Simula ng Paglalakbay","storylog.scenario.10002.description":"Sa Niyebeng Parang ng Egor, binanggit ni Tilith ang kahalagahan ng Element ng mga Unit. Talo ng Kidlat ang Tubig, atbp... Magandang isaalang-alang sa mga susunod na laban.","storylog.scenario.10002.title":"Pagkakatugma ng mga Unit","storylog.scenario.10003.description":"Narating ng Summoner ang Gubat ng mga Halimaw, kung saan nangangaso ang mga kalaban ng mababangis na hayop para kainin. Maingat ding ipinaliwanag dito ang paggamit ng Sphere.","storylog.scenario.10003.title":"Mahalaga ang Kagamitan","storylog.scenario.10004.description":"Nainis si Tilith sa alinsangan ng Latian ng Magutagal, pero ipinaliwanag pa rin niya ang mga Spark na nalilikha ng sabay-sabay na pag-atake.","storylog.scenario.10004.title":"Teknik sa Laban","storylog.scenario.10005.description":"Humanga si Tilith na ligtas na narating ng Summoner ang Labi ng Mirza. Bilang gantimpala, ipinaliwanag niya ang mga benepisyo ng paggamit ng Leader Skill.","storylog.scenario.10005.title":"Pamumuno","storylog.scenario.10006.description":"Sabi-sabi, may misteryosong eskrimador na nag-aabang sa Pugad ng Halimaw. Kahit sumusumpa si Tilith na hindi siya natatakot, halatang takot na takot siya...","storylog.scenario.10006.title":"Hindi Ako Takot!","storylog.scenario.10007.description":"Ngayong nasa Tore ng Mistral na, isang hakbang na lang ang pagpapalaya sa buong rehiyon. Pero nakabuo ang Manlilikhang si Maxwell ng nakakatakot na kalaban...","storylog.scenario.10007.title":"Napalaya ang Mistral","storylog.scenario.10008.description":"Matagumpay na natalo ng Summoner ang Juggernaut, at pinuri siya ni Tilith. Bubuksan na ngayon ni Lucius ang daan patungo sa di-kilalang lupain ng Morgan.","storylog.scenario.10008.title":"Tungo sa Bagong Lupain","storylog.scenario.10009.description":"Habang hinahanap si Tilith, pumasok ang ating Summoner sa Disyerto ng Kagan. Sa di-sinasadyang pagkikita nila ni Karl, nalaman na hinahabol niya ang demonyong si Graham.","storylog.scenario.10009.title":"Muling Pagkikita kay Karl","storylog.scenario.10010.description":"Sa Dalampasigan ng Simoy, nabalitaan ni Tilith ang isang maganda pero walang-pakialam na eskrimadora. Pero kumpiyansa siyang mas maganda pa rin siya kaysa sa usap-usapang kagandahang ito.","storylog.scenario.10010.title":"Magandang Eskrimadora","storylog.scenario.10011.description":"Nasaktan si Karl habang hinahabol si Graham. Sinasabing teritoryo ng isa sa mga tauhan ni Graham ang Gubat ng Gabi, na umaatake sa maraming Summoner.","storylog.scenario.10011.title":"Tauhan ni Graham","storylog.scenario.10012.description":"Matagumpay na napalayas ni Karl si Graham mula sa Gubat ng Gabi. Wala na itong matatakbuhan, kaya oras na para tapusin ang lahat sa Tiwangwang na Lupain ng Asekutt.","storylog.scenario.10012.title":"Ang Paghabol ni Karl","storylog.scenario.10013.description":"Nagpakita si Seria, isang miyembro ng Demon Slayers, sa Dambana ni Lystia. Ayon sa kanya, isa si Graham sa pinakamahahalagang tauhan ni Abaddon.","storylog.scenario.10013.title":"Abaddon at Graham","storylog.scenario.10014.description":"Naging palaban si Seria sa Summoner. Kahit gusto ni Karl na magpatuloy sa Wasak na Katedral bilang grupo ng tatlo, pinahihirapan ito ni Seria...","storylog.scenario.10014.title":"Pagtanggi","storylog.scenario.10015.description":"Sa wakas, narating ang kuta ni Abaddon sa Tore ng Morgan; hinarang nina Karl at Seria ang mga sumusugod na kalaban para makasulong ang Summoner.","storylog.scenario.10015.title":"Para sa Aking mga Kasama","storylog.scenario.10016.description":"Natalo na si Abaddon. Matapos makatagpo si Karl at muling maghiwalay, tumungo sina Tilith at ang Summoner sa St. Lamia para hanapin si Maxwell.","storylog.scenario.10016.title":"Patungo sa Base ng Kaaway","storylog.scenario.10017.description":"Sa Bulkang Eldent, nagbabala si Tilith na hindi katanggap-tanggap ang pagpapabaya sa tungkulin. Sabi niya, hindi pa siya kailanman nagpabaya sa trabaho niya, pero...","storylog.scenario.10017.title":"Bawal Magpabaya!","storylog.scenario.10018.description":"Kahit sinusubukan ni Tilith na magkuwento tungkol sa Banal na Bundok Craylia, mukhang hindi maganda ang lagay niya. Sipon daw ang tumama sa kanya...","storylog.scenario.10018.title":"Masamang Pangitain","storylog.scenario.10019.description":"Ginagawa ni Tilith ang lahat para magkunwaring hindi lumalala ang kalagayan niya habang nasa Gubat ng Dugo. Pero halatang nahihirapan na siya...","storylog.scenario.10019.title":"Pagkukunwari","storylog.scenario.10020.description":"Sa wakas, inamin ni Tilith ang masama niyang kalagayan sa Bundok Wistorea. Lalong tumitindi ang epekto ng sumpa ni Maxwell habang papalapit siya sa Palasyo ng St. Lamia.","storylog.scenario.10020.title":"Ang Sumpa","storylog.scenario.10021.description":"Sa Liblib na Santuwaryo, tuluyang bumagsak si Tilith. Ipinagkatiwala siya kay Seria, at mag-isang tumungo ang Summoner sa Palasyo ng St. Lamia para wakasan ang sumpa.","storylog.scenario.10021.title":"Isang Pangako","storylog.scenario.10022.description":"Matapos iligtas ni Karl, hinabol ng Summoner si Maxwell sa Palasyo ng St. Lamia. Maililigtas nga ba si Tilith mula sa kakila-kilabot na sumpang ito?!","storylog.scenario.10022.title":"Isang Dapat Protektahan","storylog.scenario.10023.description":"Nang mabasag ang sumpa, bumalik sa dati si Tilith, pero kung paano man ay nauwi siya sa isang madramang pagtatalo kay Seria...","storylog.scenario.10023.title":"Pagbagsak ng Manlilikha","storylog.scenario.10100.description":"Nang malaman ni Eriole na nabuksan na ng Akras Summoners\' Hall ang katimugang rehiyon ng Mistral, ipinadala niya si Paris sa Cordelica...","storylog.scenario.10100.title":"Nagsisimula ang Balak","storylog.scenario.10101.description":"Nakaharap ang Demon Slayer na si Lugina sa Mga Kuweba ng Greskya. Dahil wala siyang respeto sa Regular Army, iniutos niyang umalis ang Summoner.","storylog.scenario.10101.title":"Demon Slayer Lugina","storylog.scenario.10102.description":"Sa Talon ng Ignia, ipinaliwanag ni Lugina kung paano naiimpluwensyahan ng Imperyo ng Randall at ng Akras Summoners\' Hall ang buhay sa Elgaia.","storylog.scenario.10102.title":"Mga Usapin sa Elgaia","storylog.scenario.10103.description":"Ipinaliwanag ni Lugina kung paano gumagana ang Summoner Army habang nasa Gubat ng Lomass. At bilang isang elite, iginiit niyang igalang ng Summoner ang kanyang awtoridad.","storylog.scenario.10103.title":"Ang Summoner Army","storylog.scenario.10104.description":"Nagpakita si Paris sa Kuta ng Valtan. Humingi siya ng tulong sa Summoner para sa land survey sa Cordelica, pero...","storylog.scenario.10104.title":"Ang Hiling ni Paris","storylog.scenario.10105.description":"Habang papunta sa Tore ng Liwanag, binanggit ni Paris na kaibigan ni Karl ang Summoner, pero hindi naniniwala si Lugina. Mukhang ayaw niya kay Karl.","storylog.scenario.10105.title":"Ang Yabang Niya!","storylog.scenario.10106.description":"Ipinaliwanag ni Paris sa Minahan ng Cordelica na isang lahi ng mga higante ang tumira sa isla noong unang panahon. Mukhang gising na rin ang diyos ng mga higante.","storylog.scenario.10106.title":"Isang Higanteng Diyos","storylog.scenario.10107.description":"Habang nasa misyon si Lugina na talunin ang higanteng diyos na si Grantos sa Guho ng Higante, hiniling ni Paris sa Summoner na ipakita kung ano ang tunay na lakas.","storylog.scenario.10107.title":"Ang Masigasig na si Lugina","storylog.scenario.10108.description":"Nang malamang natalo ng Summoner si Grantos, tumawa si Eriole habang ipinahahayag na patungo na sa tamang direksyon ang mundo...","storylog.scenario.10108.title":"Ang Motibo ni Eriole","storylog.scenario.10200.description":"Ginabayan ni Lucius ang Summoner sa Kapuluan ng Palmyna, habang isang lalaki sa Randall ang nabalitaang naglaho na ang harang sa mga islang iyon.","storylog.scenario.10200.title":"Superbisor ng mga Kabalyero","storylog.scenario.10201.description":"Ang susunod na target ay si Cardes the Malevolent, isa pa sa Apat na Nahulog na Diyos. Sa Nayon ng Julep, nabalitaan mong kalahati ng kapangyarihan niya ay nakakulong pa rin.","storylog.scenario.10201.title":"Cardes the Malevolent","storylog.scenario.10202.description":"Sinasabi ni Tilith na hindi siya takot sakay ng Barkong Multo Legnia. Pero nagbigay pa rin siya ng impormasyon tungkol sa Palmyna, kung saan nakakulong si Cardes...","storylog.scenario.10202.title":"Daan Patungong Palmyna","storylog.scenario.10203.description":"Biglang inatake ang Summoner ng isang kakaibang lalaki sa Kapatagan ng Elios. Pero naglaho ang presensya ng misteryosong lalaking ito nang kasimbilis ng paglitaw niya.","storylog.scenario.10203.title":"Isang Misteryosong Lalaki","storylog.scenario.10204.description":"Sa pakikipagkita kina Seria at Karl sa Mga Minahan ng Saji, nalamang hinahabol pa rin nila si Graham. Binalaan ni Karl ang Summoner tungkol sa isang nagngangalang Zebra.","storylog.scenario.10204.title":"Zebra ang Pangalan Niya","storylog.scenario.10205.description":"Nakasalubong ni Tilith at ng kanyang Summoner si \\"Elder Grah\\" sa Templo ng Lamellia. Sabi ng matanda, iniimbestigahan daw niya ang mga alamat tungkol sa Apat na Nahulog na Diyos.","storylog.scenario.10205.title":"Isang Misteryosong Matanda","storylog.scenario.10206.description":"Nasukol nina Karl at Seria si Graham sa Bayang Multo Edila, pero tinangay sila ng isang di-kilala at makapangyarihang puwersa, kaya nakatakas si Graham.","storylog.scenario.10206.title":"Di-kilalang Puwersa","storylog.scenario.10207.description":"Nagpakita sa Kastilyo ng Amdahl si Elder Grah at ikinuwento ang mapaghiganting espiritu ng huling emperador ng Amdahl, na tila gumagala pa rin sa kastilyo.","storylog.scenario.10207.title":"Ang Huling Emperador ng Amdahl","storylog.scenario.10208.description":"Humanga si Elder Grah sa kakayahan ng Summoner na talunin ang masamang espiritu. Nagmamadaling dumating si Seria, at mukhang kilala niya ang matanda.","storylog.scenario.10208.title":"Seria at Elder Grah","storylog.scenario.10209.description":"Sa gabay ni Lucius, narating ng Summoner ang Encervis. Ayon kay Tilith, isang digmaang sibil ng mga tao ang sumalanta sa lupaing ito noong unang panahon.","storylog.scenario.10209.title":"Mga Guho ng Nakaraan","storylog.scenario.10210.description":"Pagdating sa Bunganga ng Elsta, ikinuwento ni Tilith sa Summoner kung gaano siya nagsipag. Pero parang kaduda-duda ang mga sinasabi niya...","storylog.scenario.10210.title":"Ang Masipag na si Tilith","storylog.scenario.10211.description":"Biglang umatake si Zebra sa Lawa ng Aldela, pero dahil sa tulong ni Elder Grah, walang malubhang pinsala. Mukhang nakatira ang malakas na kalabang ito sa isang lumulutang na kuta.","storylog.scenario.10211.title":"Bumalik ang Kuta sa Langit","storylog.scenario.10212.description":"Ikinuwento ni Elder Grah ang kasaysayan ng Amdahl habang naglilibot sa Kastilyo ng Avenia. Hiniling niya sa Summoner na wasakin ang kuta sa langit, pero walang-gana si Tilith...","storylog.scenario.10212.title":"Kasaysayan ng Amdahl","storylog.scenario.10213.description":"Natagpuan sina Zebra at ang Madilim na Anino sa Bangin ng Gadillian habang pinag-uusapan kung paano haharapin ang Summoner. Ano kaya ang ugnayan nila...?","storylog.scenario.10213.title":"Zebra at ang Madilim na Anino","storylog.scenario.10214.description":"Hinanap nina Seria at Karl ang Summoner sa Mausoleo ng Alman. Pareho nilang sinabing gusto nilang gamitin ang lakas nila para tumulong pabagsakin ang kuta sa langit.","storylog.scenario.10214.title":"Nakakapanatag na Suporta","storylog.scenario.10215.description":"Sa Lupain ng mga Patay, ibinunyag ni Tilith na Solaris ang opisyal na pangalan ng kuta sa langit. Balak niyang gamitin ang kapangyarihan niya para makapasok dito.","storylog.scenario.10215.title":"Paglusob sa Kuta","storylog.scenario.10216.description":"Dahil sa kapangyarihan ni Tilith, matagumpay ang pagpasok sa Kuta sa Langit Solaris. Nakita ito ni Zebra bilang pagkakataon para atakihin ang pagod na diyosa.","storylog.scenario.10216.title":"Zebra vs. Tilith","storylog.scenario.10217.description":"Sa wakas, natalo na si Zebra. Pero winasak niya ang Solaris para isama sa pagbagsak ang Summoner. Sino ang makapipigil sa trahedyang ito...?","storylog.scenario.10217.title":"Zebra at Grahdens","storylog.scenario.10218.description":"Narating ng Summoner ang Palmyna sa gabay ni Lucius. Kitang-kita pa rin dito ang mga bakas ng isang kahariang lumaban sa mga diyos.","storylog.scenario.10218.title":"Ang Larangan ng Digmaan","storylog.scenario.10219.description":"Bagama\'t nasa Kastilyo ng Obselion noong una, nagmamadaling tumungo si Tilith sa Guho ng Dejour para magbabalang nagsisimula nang humina ang selyo kay Cardes.","storylog.scenario.10219.title":"Ang Lumuluwag na Selyo","storylog.scenario.10220.description":"Naiwang mag-isa si Grahdens kasama ang Summoner sa Kastilyo ng Obselion. Ikinuwento niya ang 4 na Bayani ng Palmyna na nagkulong kay Cardes the Malevolent.","storylog.scenario.10220.title":"4 na Bayani ng Palmyna","storylog.scenario.10221.description":"Sa Landas na Esmeralda, nalaman nina Seria at Karl na kailangan nilang pumunta sa daigdig ng mga espiritu para talunin si Cardes. Pero medyo kakaiba ang kilos ni Seria...","storylog.scenario.10221.title":"Ang Kakaibang si Seria","storylog.scenario.10222.description":"Habang dumaraan sa Guho ng Grandelt, ibinunyag ni Tilith na unti-unting nadudurog ang katawan ni Cardes, at nagwawala ang kanyang banal na kapangyarihan.","storylog.scenario.10222.title":"Ang Pagwawala ng mga Diyos","storylog.scenario.10223.description":"Sa Seminaryo ng Arlind, ipinahayag ni Grahdens ang kanyang mga duda tungkol sa nakaraan at sa mga kamakailang kilos ng mga diyos. Mukhang naiimpluwensyahan ng kanyang mga isip ang Summoner.","storylog.scenario.10223.title":"Ang mga Duda ni Grahdens","storylog.scenario.10224.description":"Sinamahan nina Karl at Seria ang Summoner sa mga pintuan ng daigdig sa ilalim sa Larangan ng Noera. Pareho silang nag-aalala kay Tilith.","storylog.scenario.10224.title":"Ang Pasukan sa Hades","storylog.scenario.10225.description":"Naghiwa-hiwalay ang Summoner at ang iba pa para hanapin si Cardes sa Daigdig ng Espiritu Palmyna. Matatalo kaya siya bago niya wasakin ang lahat?","storylog.scenario.10225.title":"Pakikipaglaban kay Cardes","storylog.scenario.10226.description":"Habang sinusubukan ng lahat na tumakas sa gumuguhong daigdig sa ilalim, nasugatan si Seria. Sa desperadong sitwasyong ito, dumating si Tilith para iligtas ang lahat.","storylog.scenario.10226.title":"Muling Isinilang ang Diyosa","storylog.scenario.10300.description":"Matapos marinig ang ulat ni Paris, ipinadala siya ni Eriole sa Lizeria. Ano kaya ang hinahanap niya?","storylog.scenario.10300.title":"Ang Paghahanap","storylog.scenario.10301.description":"Lumitaw si Lugina sa Kapatagan ng Erinecht at iginiit na mas mahalaga ang misyon niya kaysa sa misyon ng Summoner. Hindi pa rin nagbabago ang palaban niyang ugali.","storylog.scenario.10301.title":"Ang Misyon ni Lugina","storylog.scenario.10302.description":"Pagdating sa Kabundukan ng Golzo, nabunyag na naghahanap si Paris ng natutulog na kapangyarihan sa Lizeria. At mukhang iyon din ang hinahabol ni Lugina.","storylog.scenario.10302.title":"Ambisyon ng Dalawa","storylog.scenario.10303.description":"Sa Nagyelong Lawa ng Lodan, maling inakala ni Lugina na tinraidor ni Paris ang Summoner. Nalinawan ang lahat, pero ipinilit ni Lugina ang pagsasanay...","storylog.scenario.10303.title":"Ang Pagsasanay ni Lugina","storylog.scenario.10304.description":"Ikinuwento ni Paris ang istrukturang panlipunan ng Elgaia habang nasa Di-madaanang Latian. Parang hindi siya nagtitiwala sa kapangyarihan ng Summoners\' Hall.","storylog.scenario.10304.title":"Madilim na Panig ng Hall","storylog.scenario.10305.description":"Sa Gubat ng Kidlat Zaljiba, binanggit ni Paris ang madilim na panig ng Summoners\' Hall. Tinanong si Lugina tungkol dito, at sumagot siya nang naaayon.","storylog.scenario.10305.title":"Ang Motibasyon ni Lugina","storylog.scenario.10306.description":"Ibinahagi ni Paris ang kanyang mga duda tungkol sa mga diyos at ang kawalang-katatagan ng mundo sa Nawawalang Lungsod La Veda. Gusto niyang kumilos nang mag-isa.","storylog.scenario.10306.title":"Ang Motibasyon ni Paris","storylog.scenario.10307.description":"Sa ibabaw ng Itim na Tulay, sinabi ni Lugina na dudurugin niya ang sinumang haharang sa kanya, at nagbigay ng isang huling pahayag sa Summoner bago sumulong.","storylog.scenario.10307.title":"Huling Babala","storylog.scenario.10308.description":"Kahit natalo si Lugina sa Summoner, iginiit niyang imposibleng mabigo siya, at patuloy niyang itinatanggi ang sariling pagkatalo.","storylog.scenario.10308.title":"Ang Pagkatalo ni Lugina","storylog.scenario.10309.description":"Sa Tore ng Pagkawasak, ayaw pa ring isuko ng sugatang si Paris ang natutulog na kapangyarihan sa rehiyon. Hindi niya mapapatawad ang panghihimasok ng Summoner.","storylog.scenario.10309.title":"Ang Determinasyon ni Paris","storylog.scenario.10310.description":"Isang sistema ng depensa na kayang wasakin ang mga Summoner. Pero ang hinahanap ni Paris, na dapat ay malapit na, ay hindi makita kahit saan...","storylog.scenario.10310.title":"Mapangwasak na Kapangyarihan","storylog.scenario.10400.description":"Naglakbay sina Tilith at ang Summoner para talunin si Zevalhua the Supreme. Lingid sa kanila, papunta rin sa Agni sina Eriole at Paris...","storylog.scenario.10400.title":"Dalawang Paglalakbay","storylog.scenario.10401.description":"Sa Lungga ng Glomore, sinabi nina Karl at Seria na gusto nilang tumulong talunin si Zevalhua habang may misteryosong babaeng nanonood nang may pang-aalipusta mula sa malayo.","storylog.scenario.10401.title":"Magkakasama","storylog.scenario.10402.description":"Pagdating sa Niyebeng Pook ng Khelne, biglang lumitaw ang Disipulong si Mare at hiniling kay Karl na makipagkita sa kanya nang mag-isa sa Guho ng Azura para ibunyag ang isang sikreto.","storylog.scenario.10402.title":"Ang Nakaraan ni Karl","storylog.scenario.10403.description":"Nag-aalala si Seria kay Karl habang naglalakad sa Gubat ng Stokhelna nang muling magpakita si Mare para sabihing nahulog na si Karl sa kanyang patibong...","storylog.scenario.10403.title":"Disipulong si Mare","storylog.scenario.10404.description":"Nahulog si Seria sa bitag ni Mare sa Guho ng Azura, at nasugatan. Ipinaubaya ni Tilith sa Summoner ang pagliligtas kay Karl habang inaalagaan niya si Seria.","storylog.scenario.10404.title":"Nabitag na Seria","storylog.scenario.10405.description":"Hinihintay ni Grahdens ang Summoner sa Kabundukan ng Ryvern at ibinahagi ang mga alaala niya tungkol kay Karl. Sabi niya, magpapahuli siya kay Mare para mailabas si Karl.","storylog.scenario.10405.title":"Grahdens at Karl","storylog.scenario.10406.description":"Nagpakita si Mare sa harap ng nag-iisang Summoner sa loob ng Kuweba ng Kailaliman. Nang maghahanda na siyang umatake, bumalik si Tilith at pinigilan ito.","storylog.scenario.10406.title":"Palihim na Tilith","storylog.scenario.10407.description":"Pinakawalan ni Mare si Granvalm laban sa Summoner sa Puting Tore, at tumakas. Pero hindi siya hahayaan ni Tilith na makatakas nang ganoon kadali.","storylog.scenario.10407.title":"Granvalm na Puti","storylog.scenario.10408.description":"Muling lumitaw si Mare matapos matalo si Granvalm, at sa gitna ng mapanganib na sitwasyong ito, isang di-inaasahang kakampi ang nagligtas sa lahat...","storylog.scenario.10408.title":"Di-inaasahang Tulong","storylog.scenario.10409.description":"Iniligtas ni Lugina ang Summoner sa Ryvern para tuparin ang hiling ni Grahdens. Iginigiit din niyang hiniling sa kanya na tumulong sa pagliligtas kay Karl.","storylog.scenario.10409.title":"Magpasalamat Ka","storylog.scenario.10410.description":"Sa Imperyo ng Agni, sabik na sabik si Lugina sa misyon ng pagliligtas. Sabi niya, perpektong pagkakataon ito para tapusin ang misyon niya at pagtawanan si Karl.","storylog.scenario.10410.title":"Pinakamahusay na Pagsisikap ni Lugina","storylog.scenario.10411.description":"Sawang maghintay sa paglitaw ni Mare, iniwan ni Lugina ang Summoner sa Baybayin ng Agniria at humayo para hanapin si Karl nang mag-isa...","storylog.scenario.10411.title":"Muling Pagkilos","storylog.scenario.10412.description":"Sa wakas, nagpakita si Mare sa Talampas ng Granasta. Pero ayaw niyang lumaban. Sa halip, iniutos niyang sumunod sa kanya ang Summoner para iligtas si Karl.","storylog.scenario.10412.title":"Mare na Manlilinlang","storylog.scenario.10413.description":"Naaalala ni Mare ang isang taong lumaban sa digmaan laban sa mga diyos habang hinahabol siya ng nababagabag na Summoner papasok sa Taluktok ng Kidlat Navara.","storylog.scenario.10413.title":"Mga Alaala ni Mare","storylog.scenario.10414.description":"Sumulong ang Summoner sa Puntod ng Hari nang hindi nawawalan ng pag-asang mailigtas si Karl. Hindi maintindihan ni Mare ang ganitong katigasan ng ulo, kaya sa wakas ay umatake siya.","storylog.scenario.10414.title":"Magkasalungat na Puwersa","storylog.scenario.10415.description":"Nang ibibigay na ni Mare ang huling atake sa Look ng Lognea, sumugod si Seria, na dapat ay malubhang sugatan, para iligtas ang Summoner.","storylog.scenario.10415.title":"Ganting-salakay","storylog.scenario.10416.description":"Isang pulutong ng kaaway ang lumitaw sa Dambana sa Dagat Albina, kaya naipit sina Seria at ang Summoner. Pero dumating si Lugina kasama ang napalayang si Karl sa tamang oras.","storylog.scenario.10416.title":"Ang Pagliligtas","storylog.scenario.10417.description":"Sa wakas, natalo ng Summoner si Mare, pero biglang lumitaw si Paris para iulat na nabihag si Grahdens.","storylog.scenario.10417.title":"Nabihag na Grahdens","storylog.scenario.10418.description":"Sa wakas, tumapak na ang Summoner sa Mirvana. Ipinaliwanag ni Tilith na ito ang pinangyarihan ng pinakamadugong labanan sa dakilang digmaan laban sa mga diyos.","storylog.scenario.10418.title":"Sinaunang Larangan ng Digmaan","storylog.scenario.10419.description":"Nahuli ni Zevalhua the Supreme si Grahdens. Para iligtas siya, naghiwa-hiwalay sa mga grupo ang Summoner at ang iba pa sa Kuweba ng Kadiliman.","storylog.scenario.10419.title":"Magtipon ang Naghahanap","storylog.scenario.10420.description":"Sa Niyebeng Parang ng Arvest, nagtataka si Paris kung bakit binihag ng mga diyos si Grahdens sa halip na patayin agad...","storylog.scenario.10420.title":"Kahina-hinalang Kilos","storylog.scenario.10421.description":"Habang hinahanap si Grahdens sa Dagat ng mga Puno ng Marleg, muling inanyayahan ni Paris ang Summoner na sumapi sa kanyang layunin. Pero sumingit si Tilith.","storylog.scenario.10421.title":"Kaninong Summoner?","storylog.scenario.10422.description":"Pinagsabihan ni Lugina si Paris sa Latian ng Walang Hanggang Ulan. Pero bago pa lumala ang lahat, sumali si Seria sa gulo at nakipagtalo kay Lugina.","storylog.scenario.10422.title":"Lugina at Seria","storylog.scenario.10423.description":"Nakumpirma ang kinaroroonan ni Grahdens pagdating sa Tangos ng Narasta, at nagtanong si Paris kung bakit hindi mismo si Lucius ang tumalo sa Apat na Nahulog na Diyos.","storylog.scenario.10423.title":"Mga Duda ni Paris","storylog.scenario.10424.description":"Nagpasalamat si Karl kay Tilith nang magbahagi siya ng karagdagang impormasyon tungkol kay Grahdens sa Guho ng Mirvana. Pero tuloy pa rin ang karaniwang away nina Lugina at Seria.","storylog.scenario.10424.title":"Hindi Sila Nagbabago","storylog.scenario.10425.description":"Sa wakas, narating na ng buong grupo ang Tore ng mga Diyos. Magagawa kaya nilang talunin si Zevalhua the Supreme para iligtas si Grahdens?","storylog.scenario.10425.title":"Zevalhua the Supreme","storylog.scenario.10426.description":"Nagpakita si Grahdens at ibinunyag ang sikreto ng pinagmulan ni Karl. Kasabay nito, biglang lumitaw si Eriole at sumingit para kausapin ang elder.","storylog.scenario.10426.title":"Ang Sikreto ng Pinagmulan","storylog.scenario.20000.description":"Hiniling ni Lin mula sa Survey Office Bureau sa Summoner na imbestigahan ang Kabundukan ng Egor. Sabi nila, may natutulog na demonyo ng yelo roon.","storylog.scenario.20000.title":"Demonyo ng Bundok","storylog.scenario.20001.description":"Ikinuwento ni Lin ang nakaraan ni Skramya. Ayon sa alamat, ikinulong ng isang bayani ang demonyo matapos nitong subukang wasakin ang bansang gustong kumontrol dito.","storylog.scenario.20001.title":"Ang Nakaraan ng Demonyo","storylog.scenario.20002.description":"Hiniling ni Lin sa Summoner na suriin ang Yungib ng Ignia. Mukhang may demonyong nagising doon matapos ang mga lindol sa Cordelica...","storylog.scenario.20002.title":"Malagkit at Madulas","storylog.scenario.20003.description":"Natalo ng Summoner ang dambuhala at di-makontrol na demonyo. Pinuri ni Lin ang Summoner, pero biglang nagbago nang husto ang kanyang ugali...","storylog.scenario.20003.title":"Mga Ayaw ni Lin","storylog.scenario.20004.description":"Ipinasa ni Lin sa Summoner ang impormasyong may demonyo sa loob ng Pugad ni Valmodora. Inaasahan niyang mangangalap pa ng detalye ang Summoner.","storylog.scenario.20004.title":"Dambuhalang Demonyo","storylog.scenario.20005.description":"Natalo ng Summoner si Valmodora habang sinusuri ang lugar. Mukhang may itinatago ngang napakalaking bagay ang mga guho.","storylog.scenario.20005.title":"Misteryosong mga Guho","storylog.scenario.20006.description":"Ramdam ng Summoner ang napakalakas na kapangyarihang nagmumula sa kailaliman ng Lawa sa Ilalim ng Lupa ng Golzo. Masama ang kutob ni Lin, pero humiling pa rin siya ng pagsisiyasat.","storylog.scenario.20006.title":"Ang Masamang Kutob ni Lin","storylog.scenario.20007.description":"Si Lagzal, na natutulog sa ilalim ng lupa, ay isang diyos na nagnais wasakin ang mga tao. Mukhang labis na nag-alala si Lin sa Summoner habang nasa ekspedisyon.","storylog.scenario.20007.title":"Ang Nahulog na Diyos na si Lagzal","storylog.scenario.20008.description":"Habang dumaraan sa Dungeon ng Agni, hiniling ni Lin sa Summoner na supilin ang isang \\"masamang nilalang\\" na nakakulong sa loob nito.","storylog.scenario.20008.title":"Nakatago sa Dungeon","storylog.scenario.20009.description":"Ayon kay Lin, ang nakakulong sa loob ay ang multo ng isang kinatatakutang tirano na ipininid ng sarili niyang mga tagapaglingkod.","storylog.scenario.20009.title":"Wakas ng Isang Tirano"}')}]);